CREATE OR REPLACE FUNCTION "public"."adjust_customer_points"("p_customer_id" "uuid", "p_delta" integer, "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_store uuid := public.current_store_id(); r public.customers; v_bal int; v_next int; begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; if p_delta is null or p_delta = 0 then raise exception 'delta_required' using errcode = '22023'; end if; select * into r from public.customers where id = p_customer_id and store_id = v_store; if not found then raise exception 'customer_not_found' using errcode = 'P0001'; end if; v_bal := public.customer_points_balance_internal(v_store, r.id); v_next := v_bal + p_delta; if v_next < 0 then raise exception 'insufficient_points' using errcode = 'P0001'; end if; insert into public.customer_points_ledger (store_id, customer_id, delta, balance_after, reason, actor_id) values (v_store, r.id, p_delta, v_next, 'adjust', auth.uid()); return public.customer_card(v_store, r) || jsonb_build_object('note', nullif(btrim(coalesce(p_note, '')), '')); end; $$;


