                 'deactivated_at', s.deactivated_at,
                 'created_at', s.created_at,
                 'delist_duty', s.delist_duty
               )
               order by s.created_at
             )
        from public.staff s
       where s.store_id = v_store
    ),
    '[]'::jsonb
  );
end;
$$;


