CREATE OR REPLACE FUNCTION "public"."admin_remove_staff"("p_user_id" "uuid", "p_store" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.admin_store(p_store);
  v_target public.staff;
begin
  select * into v_target
    from public.staff
   where user_id = p_user_id and store_id = v_store;
  if not found then
    raise exception 'staff_not_found' using errcode = 'P0001';
  end if;
  if auth.role() <> 'service_role' then
    if p_user_id = auth.uid() then
      raise exception 'cannot_remove_self' using errcode = 'P0001';
    end if;
    if v_target.role = 'owner' and not public.is_owner() then
      raise exception 'owner_only' using errcode = '42501';
    end if;
  end if;
  perform public.assert_admin_survives(v_store, p_user_id);

  delete from public.staff
   where user_id = p_user_id and store_id = v_store;

  insert into public.events (store_id, kind, actor, actor_id, note)
  values (
    v_store, 'staff_removed',
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'service'),
    auth.uid(),
    format('%s (%s)', v_target.display_name, v_target.role)
  );
end;
$$;


ALTER FUNCTION "public"."admin_remove_staff"("p_user_id" "uuid", "p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_staff_active"("p_user_id" "uuid", "p_active" boolean, "p_store" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.admin_store(p_store);
  v_target public.staff;
begin
  select * into v_target
    from public.staff
   where user_id = p_user_id and store_id = v_store;
  if not found then
    raise exception 'staff_not_found' using errcode = 'P0001';
  end if;
  if not p_active then
    if auth.role() <> 'service_role' then
      if p_user_id = auth.uid() then
        raise exception 'cannot_deactivate_self' using errcode = 'P0001';
      end if;
      if v_target.role = 'owner' and not public.is_owner() then
        raise exception 'owner_only' using errcode = '42501';
      end if;
    end if;
    perform public.assert_admin_survives(v_store, p_user_id);
  end if;

  update public.staff
     set deactivated_at = case when p_active then null else now() end
   where user_id = p_user_id and store_id = v_store;

  insert into public.events (store_id, kind, actor, actor_id, note)
  values (
    v_store,
    case when p_active then 'staff_reactivated' else 'staff_deactivated' end,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'service'),
    auth.uid(),
    v_target.display_name
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_staff_active"("p_user_id" "uuid", "p_active" boolean, "p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_staff_role"("p_user_id" "uuid", "p_role" "text", "p_store" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.admin_store(p_store);
  v_role text := lower(btrim(coalesce(p_role, '')));
  v_target public.staff;
begin
  if v_role not in ('owner', 'manager', 'staff') then
    raise exception 'invalid_role' using errcode = '22023';
  end if;
  select * into v_target
    from public.staff
   where user_id = p_user_id and store_id = v_store;
  if not found then
    raise exception 'staff_not_found' using errcode = 'P0001';
  end if;
  if auth.role() <> 'service_role' then
    if p_user_id = auth.uid() then
      raise exception 'cannot_change_self' using errcode = 'P0001';
    end if;
    -- Only an owner may grant owner or change an existing owner.
    if (v_target.role = 'owner' or v_role = 'owner') and not public.is_owner() then
      raise exception 'owner_only' using errcode = '42501';
    end if;
  end if;
  if v_target.role is not distinct from v_role then
    return;
  end if;
  if v_role = 'staff' then
    perform public.assert_admin_survives(v_store, p_user_id);
  end if;

  update public.staff set role = v_role
   where user_id = p_user_id and store_id = v_store;

  insert into public.events (store_id, kind, field, old_value, new_value, actor, actor_id, note)
  values (
    v_store, 'staff_role', 'role', v_target.role, v_role,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'service'),
    auth.uid(),
    v_target.display_name
  );
end;
$$;


ALTER FUNCTION "public"."admin_set_staff_role"("p_user_id" "uuid", "p_role" "text", "p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_store"("p_store" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid;
begin
  if auth.role() = 'service_role' then
    if p_store is null then
      raise exception 'store_required' using errcode = '22023';
    end if;
    return p_store;
  end if;
  perform public.assert_manager();
  v_store := public.current_store_id();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if p_store is not null and p_store is distinct from v_store then
    raise exception 'not_store_staff' using errcode = '42501';
  end if;
  return v_store;
end;
$$;


ALTER FUNCTION "public"."admin_store"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."adopt_orphan_inventory"("p_store" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  n int := 0;
begin
  update public.sku_ledger set store_id = p_store where store_id is null;
  get diagnostics n = row_count;
  update public.units set store_id = p_store where store_id is null;
  update public.sales set store_id = p_store where store_id is null;
  update public.reservations set store_id = p_store where store_id is null;
  update public.events set store_id = p_store where store_id is null;
  update public.photos set store_id = p_store where store_id is null;
  update public.listings set store_id = p_store where store_id is null;
  update public.delist_tasks set store_id = p_store where store_id is null;
  update public.incidents set store_id = p_store where store_id is null;
  perform public.move_unit_photos_to_store_layout(p_store);
  if exists (
    select 1 from public.verify_unit_photos(p_store) v where not v.storage_ok
  ) then
    raise exception 'photo_verify_failed' using errcode = 'P0001';
  end if;
  return n;
end;
$$;


