CREATE OR REPLACE FUNCTION "public"."allocate_line_taxes"("p_prices" integer[], "p_bps" integer) RETURNS integer[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  n int := coalesce(array_length(p_prices, 1), 0);
  v_sum bigint := 0;
  v_ticket int;
  v_lines int[];
  v_acc int := 0;
  i int;
  v_line int;
begin
  if n = 0 then
    return '{}'::int[];
  end if;
  if p_bps is null or p_bps < 0 then
    raise exception 'tax_rate_required' using errcode = 'P0001';
  end if;
  for i in 1..n loop
    if p_prices[i] is null or p_prices[i] < 0 then
      raise exception 'invalid_price' using errcode = '22023';
    end if;
    v_sum := v_sum + p_prices[i];
  end loop;
  v_ticket := round((v_sum::numeric * p_bps::numeric) / 10000.0, 0)::int;
  v_lines := array[]::int[];
  for i in 1..n loop
    if i = n then
      v_line := v_ticket - v_acc;
    else
      v_line := floor((p_prices[i]::numeric * p_bps::numeric) / 10000.0)::int;
      v_acc := v_acc + v_line;
    end if;
    v_lines := v_lines || v_line;
  end loop;
  return v_lines;
end;
$$;


ALTER FUNCTION "public"."allocate_line_taxes"("p_prices" integer[], "p_bps" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."anon_can_read_unit_photo"("object_name" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
  select exists (
    select 1 from public.storefront_items i
    join public.photos p on p.store_id=i.store_id and p.sku=i.sku
    where i.store_id::text=split_part(object_name,'/',1)
      and i.sku=split_part(object_name,'/',2)
      and (object_name=p.path or object_name in (
        i.store_id::text||'/'||i.sku||'/web/400/'||
          regexp_replace(split_part(p.path,'/',3),'\.[^.]+$','')||'.webp',
        i.store_id::text||'/'||i.sku||'/web/1200/'||
          regexp_replace(split_part(p.path,'/',3),'\.[^.]+$','')||'.webp'
      ))
  );
$_$;


