CREATE OR REPLACE FUNCTION "public"."apply_square_webhook"("p_event_id" "text", "p_event_type" "text", "p_kind" "text", "p_payment_id" "text", "p_resource_id" "text", "p_status" "text", "p_amount_cents" integer, "p_merchant_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_pay text := nullif(btrim(coalesce(p_payment_id, '')), '');
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_status text := upper(btrim(coalesce(p_status, '')));
  v_inserted text;
  v_charge integer;
  v_card integer;
  v_web integer;
  v_sale_total integer;
  v_sale_count integer;
  v_action text := 'recorded';
  v_alert boolean := false;
  v_voided integer := 0;
  v_skus text[] := array[]::text[];
  v_sale record;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_only' using errcode = '42501';
  end if;
  if p_event_id is null or length(btrim(p_event_id)) < 1 or length(p_event_id) > 200 then
    raise exception 'bad_event_id' using errcode = '22023';
  end if;
  if v_kind not in ('refund', 'dispute') then
    raise exception 'bad_event_kind' using errcode = '22023';
  end if;
  if v_pay is not null and length(v_pay) > 200 then
    raise exception 'bad_payment_id' using errcode = '22023';
  end if;

  insert into public.square_webhook_events (
    event_id, event_type, merchant_id, payment_id, refund_id, dispute_id, status, amount_cents, action
  ) values (
    btrim(p_event_id),
    left(coalesce(p_event_type, v_kind), 80),
    nullif(left(coalesce(p_merchant_id, ''), 80), ''),
    v_pay,
    case when v_kind = 'refund' then nullif(left(coalesce(p_resource_id, ''), 80), '') else null end,
    case when v_kind = 'dispute' then nullif(left(coalesce(p_resource_id, ''), 80), '') else null end,
    nullif(left(v_status, 40), ''),
    p_amount_cents,
    'received'
  )
  on conflict (event_id) do nothing
  returning event_id into v_inserted;

  if v_inserted is null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'alert', false, 'action', 'duplicate');
  end if;

  if v_pay is not null then
    select max(amount_cents) into v_card
      from public.card_charges
     where payment_id = v_pay or payment_id = 'square:' || v_pay;
    select max(total_cents) into v_web
      from public.web_orders
     where payment_id = v_pay or payment_id = 'square:' || v_pay;
    select coalesce(sum(price_cents + tax_cents + coalesce(shipping_cents, 0) + coalesce(card_fee_cents, 0)), 0),
           count(*)::integer
      into v_sale_total, v_sale_count
      from public.sales
     where payment_id = v_pay or payment_id = 'square:' || v_pay;
    select coalesce(array_agg(distinct sku), array[]::text[]) into v_skus
      from (
        select sku from public.sales where payment_id = v_pay or payment_id = 'square:' || v_pay
        union
        select sku from public.web_orders where payment_id = v_pay or payment_id = 'square:' || v_pay
        union
        select sku from public.card_charges where payment_id = v_pay or payment_id = 'square:' || v_pay
      ) found
     where sku is not null and btrim(sku) <> '';
  end if;

  v_charge := coalesce(v_card, v_web, case when coalesce(v_sale_count, 0) > 0 then v_sale_total else null end);

  if v_kind = 'dispute' then
    v_action := 'dispute';
    v_alert := true;
  elsif v_kind = 'refund' and v_status = 'COMPLETED' and v_charge is not null and p_amount_cents is not null and p_amount_cents > 0 and p_amount_cents >= v_charge then
    for v_sale in
      select id, store_id, sku
        from public.sales
       where voided_at is null
         and (payment_id = v_pay or payment_id = 'square:' || v_pay)
    loop
      begin
        perform set_config('floor.store_id', coalesce(v_sale.store_id::text, ''), true);
        perform public.void_sale(v_sale.id, left('Square refund ' || coalesce(p_resource_id, p_event_id), 200), null);
        v_voided := v_voided + 1;
      exception
        when others then
          if sqlerrm is distinct from 'sale_not_voidable' then
            raise;
          end if;
      end;
    end loop;
    update public.web_orders
       set status = 'refunded',
           refund_id = coalesce(nullif(left(coalesce(p_resource_id, ''), 80), ''), refund_id),
           cancel_source = coalesce(cancel_source, 'square'),
           cancel_reason = coalesce(cancel_reason, 'Square refund'),
           canceled_at = coalesce(canceled_at, now()),
           updated_at = now()
     where status = 'paid'
       and (payment_id = v_pay or payment_id = 'square:' || v_pay);
    update public.card_charges
       set status = 'canceled',
           error = left('square_refund:' || coalesce(p_resource_id, p_event_id), 500),
           updated_at = now()
     where status in ('pending', 'captured', 'finalized', 'finalize_failed')
       and (payment_id = v_pay or payment_id = 'square:' || v_pay);
    v_action := case when v_voided > 0 then 'voided' else 'refunded' end;
    v_alert := true;
  elsif v_kind = 'refund' and v_status = 'COMPLETED' then
    v_action := case when v_charge is null then 'unmatched' else 'partial' end;
    v_alert := true;
  else
    v_action := 'recorded';
    v_alert := false;
  end if;

  update public.square_webhook_events
     set action = v_action,
         detail = left(format('charge=%s voided=%s', coalesce(v_charge::text, 'none'), v_voided), 200)
   where event_id = btrim(p_event_id);

  return jsonb_build_object(
    'ok', true,
    'duplicate', false,
    'alert', v_alert,
    'action', v_action,
    'payment_id', v_pay,
    'amount_cents', p_amount_cents,
    'charge_cents', v_charge,
    'voided_sales', v_voided,
    'skus', to_jsonb(v_skus)
  );
end;
$$;


ALTER FUNCTION "public"."apply_square_webhook"("p_event_id" "text", "p_event_type" "text", "p_kind" "text", "p_payment_id" "text", "p_resource_id" "text", "p_status" "text", "p_amount_cents" integer, "p_merchant_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_with_pin"("p_action" "text", "p_sku" "text", "p_pin" "text", "p_ticket_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_hash text;
  v_fails int;
  v_until timestamptz;
  v_id uuid;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if p_action = 'void_ticket' and p_ticket_id is null then
    raise exception 'ticket_required' using errcode = '22023';
  end if;

  v_until := (public.store_setting(v_store, 'pin_locked_until', 'null'::jsonb) #>> '{}')::timestamptz;
  if v_until is not null and v_until > now() then
    insert into public.pin_attempts (store_id, user_id, ok) values (v_store, auth.uid(), false);
    insert into public.events (store_id, sku, kind, actor, actor_id, note)
    values (v_store, p_sku, 'pin_locked', coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'), auth.uid(), 'attempt while locked');
    raise exception 'pin_locked' using errcode = 'P0001';
  end if;

  v_hash := public.store_setting(v_store, 'manager_pin_hash', 'null'::jsonb) #>> '{}';
  if v_hash is null or v_hash = 'null' then
    raise exception 'pin_not_set' using errcode = 'P0001';
  end if;

  if crypt(p_pin, v_hash) <> v_hash then
    v_fails := coalesce((public.store_setting(v_store, 'pin_failed_count', '0'::jsonb) #>> '{}')::int, 0) + 1;
    insert into public.store_settings (store_id, key, value)
    values (v_store, 'pin_failed_count', to_jsonb(v_fails))
    on conflict (store_id, key) do update set value = to_jsonb(v_fails);
    insert into public.pin_attempts (store_id, user_id, ok) values (v_store, auth.uid(), false);
    insert into public.events (store_id, sku, kind, actor, actor_id, note)
    values (v_store, p_sku, 'pin_failed', coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'), auth.uid(), v_fails::text);
    if v_fails >= 5 then
      insert into public.store_settings (store_id, key, value)
      values (v_store, 'pin_locked_until', to_jsonb(now() + interval '5 minutes'))
      on conflict (store_id, key) do update set value = to_jsonb(now() + interval '5 minutes');
      insert into public.events (store_id, sku, kind, actor, actor_id, note)
      values (v_store, p_sku, 'pin_lockout', coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'), auth.uid(), '5 failures');
    end if;
    raise exception 'pin_wrong' using errcode = 'P0001';
  end if;

  insert into public.store_settings (store_id, key, value)
  values (v_store, 'pin_failed_count', '0'::jsonb)
  on conflict (store_id, key) do update set value = '0'::jsonb;
  delete from public.store_settings where store_id = v_store and key = 'pin_locked_until';
  insert into public.pin_attempts (store_id, user_id, ok) values (v_store, auth.uid(), true);

  insert into public.approvals (store_id, action, sku, ticket_id, requested_by, approved_by)
  values (v_store, p_action, p_sku, p_ticket_id, auth.uid(), auth.uid())
  returning id into v_id;

  insert into public.events (store_id, sku, kind, actor, actor_id, note)
  values (
    v_store,
    p_sku,
    'approval',
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'),
    auth.uid(),
    p_action
  );
  return v_id;
end;
$$;


ALTER FUNCTION "public"."approve_with_pin"("p_action" "text", "p_sku" "text", "p_pin" "text", "p_ticket_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assert_admin_survives"("p_store" "uuid", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if exists (
      select 1 from public.staff
       where store_id = p_store and user_id = p_user_id
         and role in ('owner', 'manager') and deactivated_at is null
    )
    and not exists (
      select 1 from public.staff
       where store_id = p_store and user_id <> p_user_id
         and role in ('owner', 'manager') and deactivated_at is null
    )
  then
    raise exception 'last_admin' using errcode = 'P0001';
  end if;
end;
$$;


