    CONSTRAINT "web_orders_fulfillment_allowed" CHECK (("fulfillment" = ANY (ARRAY['ship'::"text", 'pickup'::"text"]))),
    CONSTRAINT "web_orders_match_status_check" CHECK (("match_status" = ANY (ARRAY['matched'::"text", 'unmatched'::"text", 'already_sold'::"text"]))),
    CONSTRAINT "web_orders_pack_condition_check" CHECK ((("pack_condition" IS NULL) OR ("pack_condition" = ANY (ARRAY['ok'::"text", 'not_as_listed'::"text"])))),
    CONSTRAINT "web_orders_status_check" CHECK (("status" = ANY (ARRAY['claimed'::"text", 'paid'::"text", 'stolen'::"text", 'expired'::"text", 'refunded'::"text", 'canceled'::"text"]))),
    CONSTRAINT "web_orders_tax_remitted_by_check" CHECK ((("tax_remitted_by" IS NULL) OR ("tax_remitted_by" = ANY (ARRAY['marketplace'::"text", 'store'::"text", 'none'::"text"]))))
);


