CREATE OR REPLACE FUNCTION "public"."begin_online_checkout"("p_store" "uuid", "p_sku" "text", "p_buyer" "jsonb", "p_fulfillment" "text", "p_quote" "uuid" DEFAULT NULL::"uuid", "p_rate" "text" DEFAULT NULL::"text", "p_redeem_points" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_unit public.units;
  v_res public.reservations;
  v_order public.web_orders;
  v_rate jsonb := null;
  v_ship int := 0;
  v_ship_tax int := 0;
  v_tax jsonb;
  v_customer jsonb;
  v_cust_id uuid;
  v_redeem int;
  v_quote jsonb;
  v_postal text := left(regexp_replace(coalesce(p_buyer->>'postal',''),'\D','','g'),5);
begin
  perform public.assert_service();
  perform set_config('floor.store_id', p_store::text, true);
  if p_fulfillment not in ('ship','pickup') then raise exception 'fulfillment_required'; end if;
  if coalesce(p_buyer->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
     or coalesce(btrim(p_buyer->>'name'),'') = '' or length(regexp_replace(coalesce(p_buyer->>'phone',''),'\D','','g')) < 10 then
    raise exception 'buyer_contact_required';
  end if;
  if p_fulfillment = 'ship' and (coalesce(btrim(p_buyer->>'line1'),'') = '' or coalesce(btrim(p_buyer->>'city'),'') = ''
     or coalesce(btrim(p_buyer->>'region'),'') = '' or v_postal = '') then
    raise exception 'buyer_address_required';
  end if;
  perform public.release_expired_reservations();

  select * into v_unit from public.units where store_id = p_store and sku = p_sku for update;
  if not found or v_unit.state <> 'available' or coalesce(v_unit.ask_cents,0) <= 0
     or not exists(select 1 from public.storefront_items s where s.store_id = p_store and s.sku = p_sku) then
    raise exception 'held_or_unavailable' using errcode = 'P0001';
  end if;

  if p_fulfillment = 'ship' then
    if not coalesce((public.unit_ship_check(v_unit)->>'ship')::boolean, false) then
      raise exception 'not_shippable' using errcode = 'P0001';
    end if;
    select r.value into v_rate
      from public.shipping_quotes q, jsonb_array_elements(q.rates) as r(value)
     where q.id = p_quote and q.store_id = p_store and q.sku = p_sku and q.expires_at > now()
       and q.postal = v_postal and q.region = upper(btrim(p_buyer->>'region'))
       and r.value->>'id' = p_rate
     limit 1;
    v_ship := coalesce((v_rate->>'amount_cents')::int, 0);
    if v_rate is null or v_ship <= 0 then
      raise exception 'shipping_rate_invalid' using errcode = 'P0001';
    end if;
  end if;

  update public.units set state = 'reserved', updated_at = now()
   where store_id = p_store and sku = p_sku and state = 'available';
  insert into public.reservations (store_id, sku, channel, actor_id, expires_at)
  values (p_store, p_sku, 'website', null, now() + public.web_hold_ttl())
  returning * into v_res;

  v_tax := public.web_tax_decision(p_store, p_fulfillment, p_buyer->>'region');
  perform set_config('floor.tax_bps_override', v_tax->>'bps', true);
  v_customer := public.web_lookup_customer(p_store, p_buyer->>'phone');
  v_cust_id := (v_customer->>'id')::uuid;
  v_redeem := least(greatest(coalesce(p_redeem_points,0),0), coalesce((v_customer->>'points_balance')::int,0));
  v_quote := public.web_quote(p_store, jsonb_build_array(jsonb_build_object('sku',p_sku,'price_cents',v_unit.ask_cents,'qty',1)), v_cust_id, v_redeem);
  if (v_tax->>'tax_shipping')::boolean then
    v_ship_tax := round(v_ship * (v_tax->>'bps')::int / 10000.0);
  end if;

  insert into public.web_orders (
    store_id, sku, reservation_id, status, fulfillment,
    buyer_name, buyer_email, buyer_phone,
    ship_line1, ship_line2, ship_city, ship_region, ship_postal, ship_country,
    item_cents, shipping_cents, tax_cents, total_cents,
    checkout_quote, customer_id, redeem_points, shipping_rate, carrier, service,
    tax_bps, tax_rule, shipping_tax_cents
  ) values (
    p_store, p_sku, v_res.id, 'claimed', p_fulfillment,
    btrim(p_buyer->>'name'), lower(btrim(p_buyer->>'email')), btrim(p_buyer->>'phone'),
    case when p_fulfillment = 'ship' then nullif(btrim(p_buyer->>'line1'),'') end,
    case when p_fulfillment = 'ship' then nullif(btrim(p_buyer->>'line2'),'') end,
    case when p_fulfillment = 'ship' then nullif(btrim(p_buyer->>'city'),'') end,
    case when p_fulfillment = 'ship' then upper(nullif(btrim(p_buyer->>'region'),'')) end,
    case when p_fulfillment = 'ship' then nullif(btrim(p_buyer->>'postal'),'') end,
    'US',
    v_unit.ask_cents, v_ship, (v_quote->>'tax_cents')::int + v_ship_tax,
    (v_quote->>'total_cents')::int + v_ship + v_ship_tax,
    v_quote, v_cust_id, v_redeem, v_rate, v_rate->>'carrier', v_rate->>'service',
    (v_tax->>'bps')::int, v_tax->>'rule', v_ship_tax
  ) returning * into v_order;

  insert into public.events (store_id, sku, kind, actor, note)
  values (p_store, p_sku, 'reserved', 'website', 'web checkout hold (' || p_fulfillment || ', tax ' || (v_tax->>'rule') || ')');

  return jsonb_build_object(
    'order_id', v_order.id, 'reservation_id', v_res.id, 'expires_at', v_res.expires_at,
    'sku', p_sku, 'fulfillment', p_fulfillment,
    'title', coalesce(nullif(btrim(v_unit.title),''), concat_ws(' ', v_unit.brand, v_unit.model)),
    'item_cents', v_unit.ask_cents, 'shipping_cents', v_ship, 'shipping_rate', v_rate,
    'tax_rule', v_tax->>'rule', 'tax_bps', (v_tax->>'bps')::int,
    'customer', v_customer,
    'quote', v_quote || jsonb_build_object('shipping_cents', v_ship,
      'tax_cents', (v_quote->>'tax_cents')::int + v_ship_tax,
      'total_cents', (v_quote->>'total_cents')::int + v_ship + v_ship_tax),
    'store_name', coalesce(public.store_setting(p_store,'display_name','"Store"'::jsonb) #>> '{}','Store'));
end $_$;


ALTER FUNCTION "public"."begin_online_checkout"("p_store" "uuid", "p_sku" "text", "p_buyer" "jsonb", "p_fulfillment" "text", "p_quote" "uuid", "p_rate" "text", "p_redeem_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."bg_db_probe"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select jsonb_build_object('active', (
    select count(*) from pg_stat_activity
     where state = 'active' and datname = current_database() and pid <> pg_backend_pid() and backend_type = 'client backend'))
$$;


ALTER FUNCTION "public"."bg_db_probe"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_register_charge"("p_charge_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_charge public.card_charges;
begin
  perform public.assert_staff_or_service();
  select * into v_charge
    from public.card_charges
   where id = p_charge_id and store_id = v_store
   for update;
  if not found then
    raise exception 'charge_not_found' using errcode = 'P0001';
  end if;
  if v_charge.status = 'finalized' then
    raise exception 'charge_already_finalized' using errcode = 'P0001';
  end if;
  if v_charge.status = 'pending' then
    update public.card_charges
       set status = 'canceled', updated_at = now()
     where id = p_charge_id;
  end if;
  -- captured → leave captured; caller must refund via Netlify then mark canceled/failed
end;
$$;


ALTER FUNCTION "public"."cancel_register_charge"("p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_register_charge"("p_charge_id" "uuid", "p_payment_id" "text", "p_card_brand" "text" DEFAULT NULL::"text", "p_card_last4" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_charge public.card_charges;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if p_payment_id is null or btrim(p_payment_id) = '' then
    raise exception 'payment_id_required' using errcode = '22023';
  end if;

  select * into v_charge
    from public.card_charges
   where id = p_charge_id and store_id = v_store
   for update;
  if not found then
    raise exception 'charge_not_found' using errcode = 'P0001';
  end if;

  -- Duplicate callback: same payment already recorded.
  if v_charge.status in ('captured', 'finalized', 'finalize_failed')
     and v_charge.payment_id is not distinct from btrim(p_payment_id) then
    return jsonb_build_object(
      'id', v_charge.id,
      'status', v_charge.status,
      'payment_id', v_charge.payment_id,
      'duplicate', true
    );
  end if;

  if v_charge.status = 'canceled' then
    raise exception 'charge_canceled' using errcode = 'P0001';
  end if;
  if v_charge.status = 'failed' then
    raise exception 'charge_failed' using errcode = 'P0001';
  end if;
  if v_charge.status is distinct from 'pending' then
    -- Different payment_id on already-captured charge = conflict.
    raise exception 'charge_already_captured' using errcode = 'P0001';
  end if;

  update public.card_charges
     set status = 'captured',
         payment_id = btrim(p_payment_id),
         card_brand = nullif(btrim(coalesce(p_card_brand, '')), ''),
         card_last4 = nullif(btrim(coalesce(p_card_last4, '')), ''),
         updated_at = now()
   where id = p_charge_id;

  return jsonb_build_object(
    'id', p_charge_id,
    'status', 'captured',
    'payment_id', btrim(p_payment_id),
    'duplicate', false
  );
end;
$$;


ALTER FUNCTION "public"."capture_register_charge"("p_charge_id" "uuid", "p_payment_id" "text", "p_card_brand" "text", "p_card_last4" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."capture_sale_price_override"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_ask int;
begin
  if new.ticket_id is null and new.override_price_cents is null then
    select ask_cents into v_ask from public.units where store_id=new.store_id and sku=new.sku;
    if v_ask is not null and new.price_cents is distinct from v_ask then
      new.list_price_cents:=v_ask;
      new.override_price_cents:=new.price_cents;
      new.override_by:=new.actor_id;
      new.override_reason:=coalesce(new.override_reason,'Checkout price override');
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."capture_sale_price_override"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."channel_display_name"("p_channel" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case lower(btrim(coalesce(p_channel, '')))
    when 'depop' then 'Depop'
    when 'ebay' then 'eBay'
    when 'whatnot' then 'Whatnot'
    when 'mercari' then 'Mercari'
    when 'facebook' then 'Facebook'
    when 'amazon' then 'Amazon'
    when 'website' then 'Website'
    when 'tiktok' then 'TikTok Shop'
    when 'vendoo' then 'Vendoo'
    else initcap(replace(coalesce(p_channel, 'Marketplace'), '_', ' '))
  end;
$$;


ALTER FUNCTION "public"."channel_display_name"("p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."channel_fee_estimate"("p_store" "uuid", "p_channel" "text", "p_price_cents" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rates jsonb := coalesce(public.store_setting(p_store, 'channel_fee_rates', '{}'::jsonb), '{}'::jsonb);
  v_r jsonb; v_fee int;
begin
  v_r := v_rates -> lower(btrim(coalesce(p_channel, '')));
  if v_r is null or jsonb_typeof(v_r) <> 'object' then return null; end if;
  v_fee := round(coalesce(p_price_cents, 0) * coalesce((v_r ->> 'pct')::numeric, 0) / 100.0)::int
         + coalesce((v_r ->> 'fixed_cents')::int, 0);
  v_fee := greatest(v_fee, coalesce((v_r ->> 'min_fee_cents')::int, 0), 0);
  return jsonb_build_object('fee_cents', v_fee, 'source', 'estimated');
end $$;


ALTER FUNCTION "public"."channel_fee_estimate"("p_store" "uuid", "p_channel" "text", "p_price_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."channel_order_update"("p_store" "uuid", "p_provider" "text", "p_order_id" "text", "p_fee_cents" integer DEFAULT NULL::integer, "p_fee_source" "text" DEFAULT NULL::"text", "p_ship_label_cents" integer DEFAULT NULL::integer, "p_tax_cents" integer DEFAULT NULL::integer, "p_tax_remitted" boolean DEFAULT NULL::boolean, "p_payout_cents" integer DEFAULT NULL::integer, "p_ship_label_source" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sale bigint;
  v_sku text;
  v_item int;
  v_fee_source text;
  v_ship_source text;
begin
  perform public.assert_service();
  select s.id, s.sku into v_sale, v_sku from public.sales s
   where s.store_id = p_store and s.payment_id = lower(p_provider) || ':' || p_order_id
   order by s.id desc limit 1;
  if v_sale is null then
    select o.sale_id, o.sku into v_sale, v_sku from public.web_orders o
     where o.store_id = p_store and o.payment_id = lower(p_provider) || ':' || p_order_id
     limit 1;
  end if;
  select coalesce(item_cents, 0), fee_source, ship_label_source
    into v_item, v_fee_source, v_ship_source
  from public.channel_orders
   where store_id = p_store and provider = lower(p_provider) and order_id = p_order_id;
  if v_item is null or v_item = 0 then
    select coalesce(s.price_cents, 0) into v_item from public.sales s where s.id = v_sale;
    if v_item > 0 then
      update public.channel_orders set item_cents = v_item
       where store_id = p_store and provider = lower(p_provider) and order_id = p_order_id
         and coalesce(item_cents, 0) = 0;
    end if;
  end if;

  if v_fee_source = 'manual' and coalesce(p_fee_source, '') <> 'manual' then
    p_fee_cents := null;
    p_fee_source := null;
  end if;
  if v_ship_source = 'manual' and coalesce(p_ship_label_source, '') <> 'manual' then
    p_ship_label_cents := null;
    p_ship_label_source := null;
  end if;

  if p_ship_label_cents is not null
     and p_ship_label_cents > 50000
     and v_item > 0
     and p_ship_label_cents > (v_item * 3) then
    p_ship_label_cents := null;
    p_ship_label_source := null;
  end if;
  update public.channel_orders set
    sale_id = coalesce(sale_id, v_sale), sku = coalesce(sku, v_sku),
    fee_cents = coalesce(p_fee_cents, fee_cents),
    fee_source = coalesce(p_fee_source, fee_source),
    ship_label_cents = case when p_ship_label_cents is not null then p_ship_label_cents else ship_label_cents end,
    ship_label_source = case
      when p_ship_label_cents is not null then coalesce(p_ship_label_source, 'marketplace')
      else ship_label_source end,
    tax_cents = coalesce(p_tax_cents, tax_cents),
    tax_remitted = coalesce(p_tax_remitted, tax_remitted),
    payout_cents = coalesce(p_payout_cents, payout_cents)
  where store_id = p_store and provider = lower(p_provider) and order_id = p_order_id;
  if not found and v_sale is not null then
    insert into public.channel_orders(store_id, provider, order_id, sku, sale_id, fee_cents, fee_source,
      ship_label_cents, ship_label_source, tax_cents, tax_remitted, payout_cents, item_cents)
    values (p_store, lower(p_provider), p_order_id, v_sku, v_sale, p_fee_cents, coalesce(p_fee_source, 'actual'),
      p_ship_label_cents, coalesce(p_ship_label_source, case when p_ship_label_cents is not null then 'marketplace' end),
      p_tax_cents, p_tax_remitted, p_payout_cents, nullif(v_item, 0));
  end if;
end $$;


ALTER FUNCTION "public"."channel_order_update"("p_store" "uuid", "p_provider" "text", "p_order_id" "text", "p_fee_cents" integer, "p_fee_source" "text", "p_ship_label_cents" integer, "p_tax_cents" integer, "p_tax_remitted" boolean, "p_payout_cents" integer, "p_ship_label_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."channel_return_reserve_pct"("p_store" "uuid", "p_channel" "text") RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v jsonb := public.return_settings(p_store);
  v_ch text := lower(btrim(coalesce(p_channel, '')));
  v_pct numeric;
begin
  v_pct := nullif(v #>> array['reserve_pct', v_ch], '')::numeric;
  if v_pct is null then
    v_pct := nullif(v #>> array['reserve_pct', 'other'], '')::numeric;
  end if;
  return coalesce(v_pct, 0);
end $$;


ALTER FUNCTION "public"."channel_return_reserve_pct"("p_store" "uuid", "p_channel" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."alert_outbox" (
    "id" bigint NOT NULL,
    "store_id" "uuid" NOT NULL,
    "kind" "text" NOT NULL,
    "sku" "text",
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sent_at" timestamp with time zone,
    "error" "text",
    CONSTRAINT "alert_outbox_kind_check" CHECK (("kind" = ANY (ARRAY['sale_delist'::"text", 'delist_nag'::"text", 'double_sell'::"text", 'sale_relist'::"text", 'web_order'::"text", 'web_shipped'::"text", 'web_apology'::"text", 'pack_condition'::"text", 'return_decision'::"text"])))
);


ALTER TABLE "public"."alert_outbox" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_alerts"("p_limit" integer DEFAULT 50) RETURNS SETOF "public"."alert_outbox"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'not_service' using errcode = '42501';
  end if;
  return query
    update public.alert_outbox o
       set sent_at = now()
     where o.id in (
       select id from public.alert_outbox
        where sent_at is null
        order by created_at
        limit p_limit
       for update skip locked
     )
    returning *;
end;
$$;


ALTER FUNCTION "public"."claim_alerts"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_email_outbox"("p_limit" integer DEFAULT 40) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_n int := greatest(1, least(coalesce(p_limit, 40), 80)); v_rows jsonb; begin perform public.assert_service(); with picked as (select id from public.email_outbox where status = 'queued' order by created_at limit v_n for update skip locked), marked as (update public.email_outbox o set status = 'sending' from picked where o.id = picked.id returning o.id, o.store_id, o.customer_id, o.campaign_id, o.kind, o.to_email, o.subject, o.body_text, o.payload) select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'store_id', m.store_id, 'customer_id', m.customer_id, 'campaign_id', m.campaign_id, 'kind', m.kind, 'to_email', m.to_email, 'subject', m.subject, 'body_text', m.body_text, 'payload', m.payload, 'name', c.name, 'signup_code', c.signup_code, 'unsub_token', c.unsub_token, 'points', public.customer_points_balance_internal(m.store_id, m.customer_id), 'credit_cents', public.customer_credit_cents(m.store_id, public.customer_points_balance_internal(m.store_id, m.customer_id)))), '[]'::jsonb) into v_rows from marked m left join public.customers c on c.id = m.customer_id; return coalesce(v_rows, '[]'::jsonb); end; $$;


ALTER FUNCTION "public"."claim_email_outbox"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_delist_task"("p_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_staff_or_service();
  update public.delist_tasks
     set completed_at = now(), completed_by = auth.uid()
   where id = p_id
     and store_id = public.current_store_id()
     and completed_at is null;
  update public.listings l
     set status = 'delisted', delisted_at = now()
    from public.delist_tasks t
   where t.id = p_id
     and l.store_id = t.store_id
     and l.sku = t.sku
     and l.channel = t.channel;
end;
$$;


ALTER FUNCTION "public"."complete_delist_task"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_shipping_checkout"("p_store" "uuid", "p_order" "uuid", "p_payment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare o public.web_orders; r public.reservations; v_quote jsonb; v_lines jsonb; v_summary jsonb; v_sale bigint; v_no text;
begin
  perform public.assert_service();
  perform set_config('floor.store_id',p_store::text,true);
  perform 1 from public.units where store_id=p_store and sku=(select sku from public.web_orders where id=p_order and store_id=p_store) for update;
  select * into o from public.web_orders where id=p_order and store_id=p_store for update;
  if not found then raise exception 'order_not_found'; end if;
  if o.status='paid' and o.payment_id=p_payment then return public.ticket_summary(p_store,o.reservation_id) || jsonb_build_object('total_cents',o.total_cents,'shipping_cents',o.shipping_cents,'order_no',o.order_no,'pickup_deadline',o.pickup_deadline); end if;
  if o.status <> 'claimed' or o.checkout_quote is null or nullif(p_payment,'') is null then raise exception 'order_not_payable'; end if;
  select * into r from public.reservations where id=o.reservation_id for update;
  if r.released_at is not null or r.finalized_at is not null or r.expires_at <= now() then raise exception 'reservation_expired'; end if;
  if o.customer_id is not null then perform 1 from public.customers where id=o.customer_id for update; end if;
  -- Charge with the exact rate frozen at checkout, even if settings changed while the customer paid.
  perform set_config('floor.tax_bps_override', coalesce(o.tax_bps, public.store_tax_rate_bps())::text, true);
  v_lines:=jsonb_build_array(jsonb_build_object('sku',o.sku,'price_cents',o.item_cents,'qty',1));
  v_quote:=public.web_quote(p_store,v_lines,o.customer_id,o.redeem_points);
  if v_quote is distinct from o.checkout_quote then raise exception 'quote_changed'; end if;
  v_no := 'OB-' || nextval('public.web_order_no_seq');
  v_summary:=public.web_finalize_ticket(p_store,o.reservation_id,v_lines,p_payment,o.customer_id,o.redeem_points,
    'Online ' || case when o.fulfillment='pickup' then 'pickup' else 'shipping' end || ' order ' || v_no);
  v_sale:=(v_summary->'lines'->0->>'sale_id')::bigint;
  if v_sale is null then raise exception 'sale_missing'; end if;
  update public.sales set shipping_cents=o.shipping_cents,tax_cents=o.tax_cents,
    customer_name=o.buyer_name,customer_email=o.buyer_email,customer_phone=o.buyer_phone where id=v_sale;
  update public.ticket_extras set card_cents=o.total_cents where store_id=p_store and ticket_id=o.reservation_id;
  update public.reservations set finalized_at=now(),sale_id=v_sale,payment_id=p_payment where id=o.reservation_id;
  update public.web_orders set status='paid',sale_id=v_sale,payment_id=p_payment,payment_source_id=null,
    order_no=v_no, paid_at=now(),
    pickup_deadline=case when fulfillment='pickup' then public.pickup_deadline_from(p_store, now()) end,
    updated_at=now() where id=o.id returning * into o;
  return public.ticket_summary(p_store,o.reservation_id) || jsonb_build_object('total_cents',o.total_cents,
    'shipping_cents',o.shipping_cents,'order_no',o.order_no,'fulfillment',o.fulfillment,'pickup_deadline',o.pickup_deadline);
end $$;


ALTER FUNCTION "public"."complete_shipping_checkout"("p_store" "uuid", "p_order" "uuid", "p_payment" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."consume_public_rate"("p_id" "text", "p_limit" integer, "p_window_seconds" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_start timestamptz;
  v_count integer;
  v_reset integer;
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service_only' using errcode = '42501';
  end if;
  if p_id is null or length(btrim(p_id)) < 1 or length(p_id) > 200 then
    raise exception 'bad_rate_id' using errcode = '22023';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 10000 then
    raise exception 'bad_rate_limit' using errcode = '22023';
  end if;
  if p_window_seconds is null or p_window_seconds < 1 or p_window_seconds > 86400 then
    raise exception 'bad_rate_window' using errcode = '22023';
  end if;

  insert into public.public_rate_buckets as b (bucket_id, window_start, hits)
  values (p_id, clock_timestamp(), 1)
  on conflict (bucket_id) do update
    set hits = case
          when b.window_start + make_interval(secs => p_window_seconds) <= clock_timestamp() then 1
          else b.hits + 1
        end,
        window_start = case
          when b.window_start + make_interval(secs => p_window_seconds) <= clock_timestamp() then clock_timestamp()
          else b.window_start
        end,
        updated_at = clock_timestamp()
  returning window_start, hits into v_start, v_count;

  v_reset := greatest(1, ceil(extract(epoch from (v_start + make_interval(secs => p_window_seconds) - clock_timestamp())))::int);
  return jsonb_build_object(
    'ok', v_count <= p_limit,
    'limit', p_limit,
    'remaining', greatest(0, p_limit - v_count),
    'reset', v_reset
  );
end;
$$;


ALTER FUNCTION "public"."consume_public_rate"("p_id" "text", "p_limit" integer, "p_window_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_register_charge"("p_ticket_id" "uuid", "p_device_id" "uuid", "p_lines" "jsonb", "p_charge_cents" integer DEFAULT NULL::integer, "p_discount_bps" integer DEFAULT 0, "p_discount_approval_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_redeem_points" integer DEFAULT 0, "p_cash_cents" integer DEFAULT NULL::integer, "p_card_cents" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text", "p_payment_method" "text" DEFAULT 'card'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_quote jsonb;
  v_n int;
  v_i int;
  v_line jsonb;
  v_sku text;
  v_unit int;
  v_qty int;
  v_seen text[] := '{}';
  v_id uuid;
  v_existing public.card_charges;
  v_device public.pos_devices;
  v_amount int;
  v_card_base int;
  v_fee int;
  v_tax int;
  v_pay text := lower(btrim(coalesce(p_payment_method, 'card')));
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if p_ticket_id is null then
    raise exception 'ticket_required' using errcode = '22023';
  end if;
  if v_pay not in ('card', 'split') then
    v_pay := 'card';
  end if;

  select * into v_existing
    from public.card_charges
   where store_id = v_store and ticket_id = p_ticket_id
   order by created_at desc
   limit 1
   for update;
  if found then
    if v_existing.status = 'finalized' then
      return jsonb_build_object(
        'id', v_existing.id,
        'ticket_id', v_existing.ticket_id,
        'amount_cents', v_existing.amount_cents,
        'tax_cents', v_existing.tax_cents,
        'card_fee_cents', v_existing.card_fee_cents,
        'status', v_existing.status,
        'summary', public.ticket_summary(v_store, p_ticket_id)
      );
    end if;
    if v_existing.status in ('pending', 'captured') then
      return jsonb_build_object(
        'id', v_existing.id,
        'ticket_id', v_existing.ticket_id,
        'amount_cents', v_existing.amount_cents,
        'tax_cents', v_existing.tax_cents,
        'card_fee_cents', v_existing.card_fee_cents,
        'status', v_existing.status
      );
    end if;
  end if;

  select * into v_device
    from public.pos_devices
   where id = p_device_id and store_id = v_store and kind = 'phone_reader';
  if not found then
    raise exception 'reader_not_paired' using errcode = 'P0001';
  end if;
  if v_device.last_seen is null or v_device.last_seen < now() - interval '45 seconds' then
    raise exception 'reader_offline' using errcode = 'P0001';
  end if;
  if not coalesce(v_device.square_authorized, false) then
    raise exception 'reader_not_authorized' using errcode = 'P0001';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) < 1 then
    raise exception 'empty_ticket' using errcode = '22023';
  end if;

  v_n := jsonb_array_length(p_lines);
  for v_i in 0..v_n - 1 loop
    v_line := p_lines->v_i;
    v_sku := btrim(coalesce(v_line->>'sku', ''));
    if v_sku = '' then
      raise exception 'invalid_sku' using errcode = '22023';
    end if;
    if v_sku = any (v_seen) then
      raise exception 'duplicate_sku' using errcode = 'P0001', message = format('duplicate_sku %s', v_sku);
    end if;
    v_seen := v_seen || v_sku;
    v_unit := (v_line->>'price_cents')::int;
    v_qty := coalesce(nullif(v_line->>'qty', '')::int, 1);
    if v_unit is null or v_unit < 0 or v_qty is null or v_qty < 1 then
      raise exception 'invalid_price' using errcode = '22023', message = format('invalid_price %s', v_sku);
    end if;
    if not exists (
      select 1 from public.units u
       where u.store_id = v_store and u.sku = v_sku
         and u.state in ('available', 'reserved')
         and u.qty_on_hand >= v_qty
    ) then
      raise exception 'unit_not_sellable' using errcode = 'P0001', message = format('unit_not_sellable %s', v_sku);
    end if;
  end loop;

  v_quote := public.quote_ticket_totals(
    p_lines, coalesce(p_discount_bps, 0), p_customer_id, coalesce(p_redeem_points, 0),
    'floor', v_pay, case when v_pay = 'split' then p_cash_cents else null end
  );
  v_tax := (v_quote->>'tax_cents')::int;
  v_fee := coalesce((v_quote->>'card_fee_cents')::int, 0);
  v_card_base := coalesce((v_quote->>'card_base_cents')::int, 0);
  v_amount := (v_quote->>'card_charge_cents')::int;

  if p_charge_cents is not null then
    if p_charge_cents < 0 then
      raise exception 'invalid_charge_cents' using errcode = '22023';
    end if;
    if p_charge_cents is distinct from v_amount then
      raise exception using
        errcode = 'P0001',
        message = format('charge_amount_mismatch expected %s got %s', v_amount, p_charge_cents);
    end if;
  end if;

  insert into public.card_charges (
    store_id, device_id, ticket_id, lines, sku, title,
    amount_cents, tax_cents, card_fee_cents, actor_id, status,
    discount_bps, discount_approval_id, customer_id, redeem_points,
    cash_cents, card_cents, note, charge_cents, payment_method
  ) values (
    v_store, p_device_id, p_ticket_id, p_lines,
    btrim(coalesce((p_lines->0)->>'sku', '')),
    format('%s item(s)', v_n),
    v_amount, v_tax, v_fee, auth.uid(), 'pending',
    coalesce(p_discount_bps, 0), p_discount_approval_id, p_customer_id, coalesce(p_redeem_points, 0),
    case when v_pay = 'split' then p_cash_cents else null end,
    case when v_pay = 'split' then v_card_base else null end,
    nullif(btrim(coalesce(p_note, '')), ''),
    p_charge_cents,
    v_pay
  )
  returning id into v_id;

  return jsonb_build_object(
    'id', v_id,
    'ticket_id', p_ticket_id,
    'amount_cents', v_amount,
    'tax_cents', v_tax,
    'card_fee_cents', v_fee,
    'card_base_cents', v_card_base,
    'status', 'pending',
    'quote', v_quote
  );
end;
$$;


ALTER FUNCTION "public"."create_register_charge"("p_ticket_id" "uuid", "p_device_id" "uuid", "p_lines" "jsonb", "p_charge_cents" integer, "p_discount_bps" integer, "p_discount_approval_id" "uuid", "p_customer_id" "uuid", "p_redeem_points" integer, "p_cash_cents" integer, "p_card_cents" integer, "p_note" "text", "p_payment_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."current_store_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(
    (select store_id from public.staff
      where user_id = auth.uid() and deactivated_at is null),
    case
      when auth.role() = 'service_role'
        then nullif(current_setting('floor.store_id', true), '')::uuid
      else null
    end
  );
$$;


ALTER FUNCTION "public"."current_store_id"() OWNER TO "postgres";


