    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_bal int; begin v_bal := public.customer_points_balance_internal(p_store, r.id); return jsonb_build_object('id', r.id, 'store_id', r.store_id, 'phone', r.phone, 'name', r.name, 'email', r.email, 'marketing_opt_in', r.marketing_opt_in, 'first_purchase_discount_used', r.first_purchase_discount_used, 'created_at', r.created_at, 'signup_code', r.signup_code, 'balance', v_bal, 'credit_cents', public.customer_credit_cents(p_store, v_bal)); end; $$;


