CREATE OR REPLACE FUNCTION "public"."customer_credit_cents"("p_store" "uuid", "p_points" integer) RETURNS integer
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ select greatest(coalesce(p_points, 0), 0) * greatest(public.store_setting_int(p_store, 'rewards_point_value_cents', 1), 0); $$;


