CREATE OR REPLACE FUNCTION "public"."delete_manufacturer_photo"("p_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_path text;
begin
  perform public.assert_staff_or_service();
  select path into v_path from public.manufacturer_photos where id = p_id;
  if v_path is null then
    raise exception 'Photo not found.' using errcode = 'P0001';
  end if;
  delete from public.manufacturer_photos where id = p_id;
  delete from storage.objects
   where bucket_id = 'manufacturer-photos' and name = v_path;
  insert into public.events (store_id, sku, kind, field, old_value, actor, actor_id)
  values (
    public.current_store_id(), null, 'manufacturer_photo_removed', 'manufacturer_photo', v_path,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'),
    auth.uid()
  );
end;
$$;


ALTER FUNCTION "public"."delete_manufacturer_photo"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_unit"("p_sku" "text", "p_approval_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
begin
  perform public.assert_staff_or_service();
  if v_store is null and auth.role() = 'service_role' then
    select store_id into v_store from public.units where sku = p_sku limit 1;
  end if;
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;

  if not public.is_manager() and auth.role() <> 'service_role' then
    if p_approval_id is null or not exists (
      select 1 from public.approvals a
       where a.id = p_approval_id and a.store_id = v_store
         and a.action = 'delete_unit' and a.sku = p_sku
         and a.consumed_at is null and a.created_at > now() - interval '10 minutes'
    ) then
      raise exception 'manager_approval_required' using errcode = 'P0001';
    end if;
    update public.approvals set consumed_at = now() where id = p_approval_id;
  end if;

  if exists (select 1 from public.sales where sku = p_sku and store_id = v_store and voided_at is null) then
    raise exception 'void_the_sale_first' using errcode = 'P0001';
  end if;

  delete from public.photos where sku = p_sku and store_id = v_store;
  delete from public.units where sku = p_sku and store_id = v_store;
  update public.sku_ledger set fate = 'hard-deleted' where sku = p_sku and store_id = v_store;
  insert into public.events (store_id, sku, kind, actor, actor_id)
  values (
    v_store, p_sku, 'deleted',
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'),
    auth.uid()
  );
end;
$$;


ALTER FUNCTION "public"."delete_unit"("p_sku" "text", "p_approval_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_unit_photo"("p_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_sku text;
  v_path text;
  v_primary boolean;
  v_next bigint;
begin
  perform public.assert_staff_or_service();
  select sku, path, is_primary into v_sku, v_path, v_primary
    from public.photos
   where id = p_id and store_id is not distinct from v_store;
  if v_sku is null then
    raise exception 'Photo not found.' using errcode = 'P0001';
  end if;

  delete from public.photos where id = p_id and store_id is not distinct from v_store;

  if v_primary then
    select id into v_next
      from public.photos
     where store_id is not distinct from v_store and sku = v_sku
     order by id
     limit 1;
    if v_next is not null then
      update public.photos set is_primary = true where id = v_next;
    end if;
  end if;

  insert into public.events (store_id, sku, kind, old_value, actor, actor_id)
  values (
    v_store, v_sku, 'photo_removed', v_path,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'),
    auth.uid()
  );
end;
$$;


ALTER FUNCTION "public"."delete_unit_photo"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disconnect_provider"("p_provider" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_owner();
  update public.connections
     set status = 'disconnected',
         token_ciphertext = null,
         refresh_ciphertext = null,
         last_error = null,
         updated_at = now()
   where store_id = public.current_store_id()
     and provider = p_provider;
  if p_provider = 'square' then
    insert into public.store_settings (store_id, key, value)
    values (public.current_store_id(), 'card_payments_enabled', 'false'::jsonb)
    on conflict (store_id, key) do update set value = 'false'::jsonb;
  end if;
  -- eBay/Amazon auto stays as-is until owner flips mode. Square never touches channels.
end;
$$;


ALTER FUNCTION "public"."disconnect_provider"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_delist_nags"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  n int;
begin
  insert into public.alert_outbox (store_id, kind, sku, payload)
  select t.store_id, 'delist_nag', t.sku,
         jsonb_build_object('channel', t.channel, 'task_id', t.id, 'nag_after', t.nag_after)
    from public.delist_tasks t
   where t.completed_at is null
     and t.nag_after <= now()
     and not exists (
       select 1 from public.alert_outbox o
        where o.kind = 'delist_nag'
          and o.sku = t.sku
          and o.store_id = t.store_id
          and o.payload->>'task_id' = t.id::text
          and o.created_at > t.nag_after
     );
  get diagnostics n = row_count;
  return n;
end;
$$;


ALTER FUNCTION "public"."enqueue_delist_nags"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_double_sell_alert"("p_store" "uuid", "p_sku" "text", "p_detail" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.alert_outbox (store_id, kind, sku, payload)
  values (
    p_store,
    'double_sell',
    p_sku,
    coalesce(p_detail, '{}'::jsonb)
  );
end;
$$;


