CREATE OR REPLACE FUNCTION "public"."enqueue_eligibility_review"("p_store" "uuid", "p_sku" "text", "p_channel" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if exists (
    select 1 from public.marketplace_eligibility_review
    where store_id = p_store and sku = p_sku and channel = lower(p_channel) and status = 'pending'
  ) then return; end if;
  insert into public.marketplace_eligibility_review(store_id, sku, channel, reason)
  values (p_store, p_sku, lower(p_channel), p_reason);
end $$;


ALTER FUNCTION "public"."enqueue_eligibility_review"("p_store" "uuid", "p_sku" "text", "p_channel" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_pending_photo_enrichment"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_count int;
begin
  insert into public.photo_enrichment_queue(store_id,sku,identity_key)
  select u.store_id,u.sku,public.photo_enrichment_identity(u.brand,u.model,u.title)
  from public.units u
  where u.store_id is not null
    and lower(coalesce(u.category,'')) <> 'refrigerator'
    and exists(select 1 from public.photos p where p.store_id=u.store_id and p.sku=u.sku)
    and not exists(select 1 from public.manufacturer_photos mp
      where lower(mp.brand)=lower(u.brand)
        and lower(mp.model)=lower(coalesce(u.listing_specs->>'matched_model',u.model)))
    and not exists(select 1 from public.photo_enrichment_suggestions s
      where s.store_id=u.store_id and s.sku=u.sku and s.status='approved')
  on conflict (store_id,sku) do nothing;
  get diagnostics v_count = row_count;
  return v_count;
end $$;


ALTER FUNCTION "public"."enqueue_pending_photo_enrichment"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."returns" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "sku" "text" NOT NULL,
    "sale_id" bigint,
    "web_order_id" "uuid",
    "channel" "text" NOT NULL,
    "external_order_id" "text",
    "external_return_id" "text",
    "reason" "text" DEFAULT 'buyer_remorse'::"text" NOT NULL,
    "fault" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "status" "text" DEFAULT 'requested'::"text" NOT NULL,
    "refund_cents" integer DEFAULT 0 NOT NULL,
    "return_label_cents" integer DEFAULT 0 NOT NULL,
    "label_paid_by" "text" DEFAULT 'unknown'::"text" NOT NULL,
    "unrecovered_fees_cents" integer DEFAULT 0 NOT NULL,
    "regrade_loss_cents" integer DEFAULT 0 NOT NULL,
    "decision_deadline_at" timestamp with time zone,
    "approved_at" timestamp with time zone,
    "in_transit_at" timestamp with time zone,
    "received_at" timestamp with time zone,
    "inspected_at" timestamp with time zone,
    "dispositioned_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "refunded_at" timestamp with time zone,
    "condition_before" "text",
    "condition_after" "text",
    "inspection_notes" "text",
    "disposition" "text",
    "route_to" "text" DEFAULT 'garage'::"text" NOT NULL,
    "supplier_id" "uuid",
    "supplier_credit_cents" integer DEFAULT 0 NOT NULL,
    "supplier_credit_received" boolean DEFAULT false NOT NULL,
    "tracking_number" "text",
    "carrier" "text",
    "needs_decision" boolean DEFAULT false NOT NULL,
    "ledger_posted_at" timestamp with time zone,
    "raw" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by" "uuid",
    "closed_by" "uuid",
    CONSTRAINT "returns_channel_ok" CHECK (("channel" = "lower"("btrim"("channel")))),
    CONSTRAINT "returns_disposition_check" CHECK ((("disposition" IS NULL) OR ("disposition" = ANY (ARRAY['relist'::"text", 'downgrade_channel'::"text", 'bundle_lot'::"text", 'write_off'::"text", 'supplier_credit'::"text", 'keep_buyer'::"text"])))),
    CONSTRAINT "returns_fault_check" CHECK (("fault" = ANY (ARRAY['seller'::"text", 'buyer'::"text", 'unknown'::"text", 'carrier'::"text"]))),
    CONSTRAINT "returns_label_paid_by_check" CHECK (("label_paid_by" = ANY (ARRAY['seller'::"text", 'buyer'::"text", 'channel'::"text", 'unknown'::"text"]))),
    CONSTRAINT "returns_reason_check" CHECK (("reason" = ANY (ARRAY['buyer_remorse'::"text", 'defective'::"text", 'not_as_described'::"text", 'wrong_item'::"text", 'damaged_in_transit'::"text", 'other'::"text"]))),
    CONSTRAINT "returns_refund_cents_check" CHECK (("refund_cents" >= 0)),
    CONSTRAINT "returns_regrade_loss_cents_check" CHECK (("regrade_loss_cents" >= 0)),
    CONSTRAINT "returns_return_label_cents_check" CHECK (("return_label_cents" >= 0)),
    CONSTRAINT "returns_route_to_check" CHECK (("route_to" = ANY (ARRAY['garage'::"text", 'supplier'::"text", 'buyer_keeps'::"text"]))),
    CONSTRAINT "returns_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'approved'::"text", 'in_transit'::"text", 'received'::"text", 'inspected'::"text", 'dispositioned'::"text", 'closed'::"text", 'refunded_no_return'::"text", 'denied'::"text", 'canceled'::"text"]))),
    CONSTRAINT "returns_supplier_credit_cents_check" CHECK (("supplier_credit_cents" >= 0)),
    CONSTRAINT "returns_unrecovered_fees_cents_check" CHECK (("unrecovered_fees_cents" >= 0))
);


ALTER TABLE "public"."returns" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_return_decision_alert"("p_return" "public"."returns") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not coalesce(p_return.needs_decision, false) then return; end if;
  if exists (
    select 1 from public.alert_outbox a
     where a.store_id = p_return.store_id
       and a.kind = 'return_decision'
       and a.sku = p_return.sku
       and a.sent_at is null
       and a.payload->>'return_id' = p_return.id::text
  ) then return; end if;

  insert into public.alert_outbox (store_id, kind, sku, payload)
  values (
    p_return.store_id,
    'return_decision',
    p_return.sku,
    jsonb_build_object(
      'return_id', p_return.id,
      'channel', p_return.channel,
      'order_id', p_return.external_order_id,
      'deadline_at', p_return.decision_deadline_at,
      'reason', p_return.reason,
      'status', p_return.status
    )
  );
end $$;


ALTER FUNCTION "public"."enqueue_return_decision_alert"("p_return" "public"."returns") OWNER TO "postgres";


