CREATE OR REPLACE FUNCTION "public"."enqueue_sale_alerts"("p_sale" "public"."sales") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_manual text[];
begin
  select coalesce(array_agg(l.channel order by l.channel), '{}')
    into v_manual
    from public.listings l
    left join public.channel_config c
      on c.store_id = l.store_id and c.channel = l.channel
   where l.store_id = p_sale.store_id
     and l.sku = p_sale.sku
     and l.status = 'listed'
     and l.channel is distinct from p_sale.channel
     and coalesce(c.mode, 'manual') = 'manual';

  insert into public.alert_outbox (store_id, kind, sku, payload)
  values (
    p_sale.store_id,
    'sale_delist',
    p_sale.sku,
    jsonb_build_object(
      'channel', p_sale.channel,
      'price_cents', p_sale.price_cents,
      'receipt_no', p_sale.receipt_no,
      'pull_from', to_jsonb(v_manual)
    )
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_sale_alerts"("p_sale" "public"."sales") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enqueue_sale_relist_alerts"("p_sale" "public"."sales") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_channels text[];
begin
  select coalesce(array_agg(distinct x.channel order by x.channel), '{}')
    into v_channels
    from (
      select l.channel
        from public.listings l
       where l.store_id = p_sale.store_id
         and l.sku = p_sale.sku
         and l.status = 'listed'
         and l.channel is distinct from 'floor'
      union
      select t.channel
        from public.delist_tasks t
       where t.store_id = p_sale.store_id
         and t.sku = p_sale.sku
         and t.sale_id = p_sale.id
    ) x;

  if coalesce(array_length(v_channels, 1), 0) = 0 then
    return;
  end if;

  insert into public.alert_outbox (store_id, kind, sku, payload)
  values (
    p_sale.store_id,
    'sale_relist',
    p_sale.sku,
    jsonb_build_object(
      'receipt_no', p_sale.receipt_no,
      'ticket_id', p_sale.ticket_id,
      'relist_on', to_jsonb(v_channels)
    )
  );
end;
$$;


ALTER FUNCTION "public"."enqueue_sale_relist_alerts"("p_sale" "public"."sales") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_marketplace_eligibility"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS TABLE("status" "text", "reason" "text", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_status text;
  v_reason text;
  v_source text;
  g_status text;
  g_reason text;
  g_source text;
begin
  select e.status, e.reason, e.source into v_status, v_reason, v_source
    from public.evaluate_marketplace_eligibility_core(p_store, p_sku, p_channel) e;

  if v_status = 'allow' then
    select g.status, g.reason, g.source into g_status, g_reason, g_source
      from public.return_risk_channel_gate(p_store, p_sku, p_channel) g;
    if g_status = 'block' then
      return query select g_status, g_reason, g_source;
      return;
    end if;
  end if;

  return query select v_status, v_reason, v_source;
end $$;


ALTER FUNCTION "public"."evaluate_marketplace_eligibility"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."evaluate_marketplace_eligibility_core"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS TABLE("status" "text", "reason" "text", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  u public.units;
  v_channel text := lower(btrim(coalesce(p_channel, '')));
  v_label text;
  v_rules public.marketplace_policy_rules;
  r jsonb;
  v_text text;
  v_category text;
  v_is_camera boolean;
  v_power boolean;
  v_charger text;
  v_word text;
  v_cat text;
  v_override public.unit_marketplace_overrides;
  v_strike boolean;
begin
  if p_store is null or coalesce(p_sku, '') = '' or v_channel = '' then
    return query select 'block'::text, 'Missing store, SKU, or channel'::text, 'rules'::text;
    return;
  end if;
  v_label := public.channel_display_name(v_channel);

  select * into u from public.units where store_id = p_store and sku = p_sku;
  if not found then
    return query select 'block'::text, v_label || ': unit not found'::text, 'rules'::text;
    return;
  end if;

  select exists(
    select 1 from public.marketplace_policy_strikes s
    where s.store_id = p_store and s.sku = p_sku and s.channel = v_channel
  ) into v_strike;
  if v_strike then
    return query select 'block'::text,
      v_label || ': permanently blocked  -  policy strike on this SKU'::text, 'strike'::text;
    return;
  end if;

  select * into v_override from public.unit_marketplace_overrides
   where store_id = p_store and sku = p_sku and channel = v_channel;
  if found then
    if v_override.decision = 'block' then
      return query select 'block'::text,
        v_label || ': blocked by override  -  ' || v_override.note, 'override'::text;
      return;
    end if;
    return query select 'allow'::text,
      v_label || ': allowed by override  -  ' || v_override.note, 'override'::text;
    return;
  end if;

  select * into v_rules from public.marketplace_policy_rules
   where store_id = p_store and channel = v_channel;
  if not found then
    return query select 'review'::text,
      v_label || ': needs review  -  no policy rules configured'::text, 'rules'::text;
    return;
  end if;
  if not v_rules.enabled then
    return query select 'allow'::text, v_label || ': rules disabled'::text, 'rules'::text;
    return;
  end if;

  r := coalesce(v_rules.rules, '{}'::jsonb);
  v_text := public.unit_policy_text(u);
  v_category := lower(btrim(coalesce(u.category, '')));

  v_is_camera := coalesce(u.is_camera, false)
    or v_category like '%camera%'
    or public.policy_has_word(v_text, 'camera')
    or public.policy_has_word(v_text, 'dslr')
    or public.policy_has_word(v_text, 'mirrorless')
    or public.policy_has_word(v_text, 'camcorder')
    or public.policy_has_word(v_text, 'gopro')
    or public.policy_has_word(v_text, 'webcam');

  v_charger := null;
  foreach v_word in array array[
    'charger','charging cable','usb cable','power cable','power cord','ac adapter',
    'power adapter','wall adapter','charging dock','extension cord','hdmi cable','lightning cable'
  ] loop
    if public.policy_has_word(v_text, v_word) then v_charger := v_word; exit; end if;
  end loop;

  if u.requires_power is true or u.is_electrical is true then
    v_power := true;
  elsif u.requires_power is false and coalesce(u.is_electrical, false) is not true then
    v_power := false;
  elsif v_category in ('appliances','electronics','electric toothbrushes','power tools','small appliances',
      'kitchen appliances','audio','computers','gaming','tvs','vacuums','lighting','smart home')
     or v_category like '%electric%' or v_category like '%electronic%' then
    v_power := true;
  elsif public.policy_has_word(v_text, 'rechargeable') or public.policy_has_word(v_text, 'electric')
     or public.policy_has_word(v_text, 'electronic') or public.policy_has_word(v_text, 'cordless')
     or public.policy_has_word(v_text, 'battery powered') or public.policy_has_word(v_text, 'toothbrush')
     or public.policy_has_word(v_text, 'sonicare') or public.policy_has_word(v_text, 'bluetooth')
     or public.policy_has_word(v_text, 'vacuum') or public.policy_has_word(v_text, 'laptop')
     or v_charger is not null then
    v_power := true;
  else
    v_power := null;
  end if;

  for v_word in select jsonb_array_elements_text(coalesce(r->'blocked_keywords', '[]'::jsonb))
  loop
    if public.policy_has_word(v_text, v_word) then
      return query select 'block'::text, v_label || ': blocked  -  keyword "' || v_word || '"', 'rules'::text;
      return;
    end if;
  end loop;

  for v_cat in select lower(btrim(x)) from jsonb_array_elements_text(coalesce(r->'blocked_categories', '[]'::jsonb)) x
  loop
    if v_category <> '' and v_category = v_cat then
      return query select 'block'::text, v_label || ': blocked  -  category ' || coalesce(u.category, v_cat), 'rules'::text;
      return;
    end if;
  end loop;

  if coalesce((r->>'block_chargers_cables')::boolean, false) and v_charger is not null then
    return query select 'block'::text,
      v_label || ': blocked  -  chargers/cables/tech accessories (' || v_charger || ')', 'rules'::text;
    return;
  end if;

  if coalesce((r->>'block_requires_power')::boolean, false) then
    if v_power is true then
      if coalesce((r->>'allow_cameras')::boolean, false) and v_is_camera and v_charger is null then
        null;
      else
        return query select 'block'::text,
          v_label || ': blocked  -  rechargeable/powered electronics', 'rules'::text;
        return;
      end if;
    elsif v_power is null and coalesce((r->>'review_if_power_unknown')::boolean, true) then
      if not (coalesce((r->>'allow_cameras')::boolean, false) and v_is_camera) then
        return query select 'review'::text,
          v_label || ': needs review  -  power/electrical status unknown', 'rules'::text;
        return;
      end if;
    end if;
  end if;

  if (coalesce((r->>'require_own_photos')::boolean, false) or coalesce((r->>'block_stock_photos')::boolean, false))
     and u.has_stock_photos then
    return query select 'block'::text, v_label || ': blocked  -  stock photos not allowed', 'rules'::text;
    return;
  end if;

  if coalesce((r->>'block_ai_images')::boolean, false) and u.has_ai_images then
    return query select 'block'::text, v_label || ': blocked  -  AI-generated images not allowed', 'rules'::text;
    return;
  end if;

  if coalesce((r->>'block_manufacturer_photos')::boolean, false) and u.has_manufacturer_photos then
    return query select 'block'::text, v_label || ': blocked  -  manufacturer/retailer photos not allowed', 'rules'::text;
    return;
  end if;

  for v_word in select jsonb_array_elements_text(coalesce(r->'prohibited_keywords', '[]'::jsonb))
  loop
    if public.policy_has_word(v_text, v_word) then
      return query select 'block'::text, v_label || ': blocked  -  prohibited ("' || v_word || '")', 'rules'::text;
      return;
    end if;
  end loop;

  if jsonb_typeof(r->'allowed_categories_only') = 'array' and jsonb_array_length(r->'allowed_categories_only') > 0 then
    if v_category = '' or not exists (
      select 1 from jsonb_array_elements_text(r->'allowed_categories_only') x
      where lower(btrim(x)) = v_category
    ) then
      return query select 'block'::text, v_label || ': blocked  -  category not in allow-list', 'rules'::text;
      return;
    end if;
  end if;

  return query select 'allow'::text, v_label || ': eligible'::text, 'rules'::text;
end $$;


ALTER FUNCTION "public"."evaluate_marketplace_eligibility_core"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extend_reservation"("p_id" "uuid", "p_seconds" integer DEFAULT 600) RETURNS timestamp with time zone
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_exp timestamptz;
begin
  perform public.assert_staff_or_service();
  update public.reservations
     set expires_at = greatest(expires_at, now()) + make_interval(secs => greatest(30, least(coalesce(p_seconds, 600), 1800)))
   where id = p_id
     and released_at is null
     and finalized_at is null
     and store_id is not distinct from public.current_store_id()
  returning expires_at into v_exp;
  if v_exp is null then raise exception 'reservation_expired' using errcode = 'P0001'; end if;
  return v_exp;
end;
$$;


ALTER FUNCTION "public"."extend_reservation"("p_id" "uuid", "p_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_register_charge"("p_charge_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_charge public.card_charges;
  v_summary jsonb;
  v_ticket uuid;
  v_err text;
  v_failed boolean := false;
  v_pay text;
  v_expected int;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;

  select * into v_charge
    from public.card_charges
   where id = p_charge_id and store_id = v_store
   for update;
  if not found then
    raise exception 'charge_not_found' using errcode = 'P0001';
  end if;

  if v_charge.status = 'finalized' and v_charge.ticket_id is not null then
    return public.ticket_summary(v_store, v_charge.ticket_id);
  end if;

  if v_charge.status is distinct from 'captured' or v_charge.payment_id is null then
    raise exception 'charge_not_captured' using errcode = 'P0001';
  end if;
  if v_charge.lines is null or jsonb_typeof(v_charge.lines) <> 'array' then
    raise exception 'charge_missing_lines' using errcode = 'P0001';
  end if;

  v_ticket := coalesce(v_charge.ticket_id, gen_random_uuid());
  v_pay := lower(btrim(coalesce(v_charge.payment_method, 'card')));
  if v_pay not in ('cash', 'card', 'split', 'other') then
    v_pay := 'card';
  end if;

  begin
    v_summary := public.finalize_ticket(
      v_ticket,
      v_charge.lines,
      v_pay,
      v_charge.payment_id,
      null,
      'floor',
      coalesce(v_charge.discount_bps, 0),
      v_charge.discount_approval_id,
      v_charge.customer_id,
      coalesce(v_charge.redeem_points, 0),
      v_charge.cash_cents,
      v_charge.card_cents,
      v_charge.note
    );
    -- The card must have been charged exactly what finalize recorded.
    if v_pay = 'card' then
      v_expected := (v_summary->>'total_cents')::int;
    else
      v_expected := coalesce((v_summary->>'card_cents')::int, 0);
    end if;
    if v_expected is distinct from v_charge.amount_cents then
      raise exception using
        errcode = 'P0001',
        message = format('charge_amount_mismatch expected %s charged %s', v_expected, v_charge.amount_cents);
    end if;
  exception
    when others then
      v_err := SQLERRM;
      v_failed := true;
  end;

  if v_failed then
    update public.card_charges
       set status = 'finalize_failed',
           error = left(v_err, 500),
           updated_at = now()
     where id = p_charge_id;
    return jsonb_build_object(
      'ok', false,
      'error', v_err,
      'charge_id', p_charge_id,
      'payment_id', v_charge.payment_id,
      'amount_cents', v_charge.amount_cents,
      'needs_refund', true
    );
  end if;

  update public.sales
     set card_brand = v_charge.card_brand,
         card_last4 = v_charge.card_last4
   where store_id = v_store
     and ticket_id = v_ticket
     and voided_at is null;

  update public.card_charges
     set status = 'finalized',
         ticket_id = v_ticket,
         error = null,
         updated_at = now()
   where id = p_charge_id;

  return coalesce(public.ticket_summary(v_store, v_ticket), v_summary);
end;
$$;


ALTER FUNCTION "public"."finalize_register_charge"("p_charge_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_sale"("p_sku" "text", "p_channel" "text", "p_price_cents" integer, "p_payment_method" "text" DEFAULT NULL::"text", "p_payment_id" "text" DEFAULT NULL::"text", "p_customer_name" "text" DEFAULT NULL::"text", "p_customer_phone" "text" DEFAULT NULL::"text", "p_customer_email" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_tax_cents" integer DEFAULT 0, "p_approval_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."sales"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_sale public.sales; v_receipt text; v_seq int; v_store uuid := public.current_store_id(); v_floor int; v_fee int := 0;
begin
  perform public.assert_staff_or_service();
  perform public.release_expired_reservations();
  if v_store is null then select store_id into v_store from public.units where sku = p_sku limit 1; end if;
  if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if;
  if p_price_cents is null or p_price_cents < 0 then raise exception 'invalid_price' using errcode = '22023'; end if;
  if p_channel is null or btrim(p_channel) = '' then raise exception 'invalid_channel' using errcode = '22023'; end if;
  -- Manual phone card sales collect the configured fee on merchandise plus tax.
  -- Website checkout has its own quoted charge and must keep its existing total.
  if lower(btrim(coalesce(p_payment_method,'')))='card' and btrim(p_channel)<>'website' then
    v_fee:=round(((p_price_cents + coalesce(p_tax_cents,0))::numeric
      * greatest(public.store_setting_int(v_store,'card_fee_bps',250),0)) / 10000.0,0)::int;
  end if;
  select floor_cents into v_floor from public.units where sku = p_sku and store_id = v_store;
  if v_floor is not null and p_price_cents < v_floor then
    if p_approval_id is null or not exists (
      select 1 from public.approvals a where a.id = p_approval_id and a.store_id = v_store and a.action = 'below_floor' and a.sku = p_sku and a.consumed_at is null and a.created_at > now() - interval '10 minutes'
    ) then raise exception 'below_floor' using errcode = 'P0001'; end if;
    update public.approvals set consumed_at = now() where id = p_approval_id;
  end if;
  if p_reservation_id is not null then
    update public.reservations set payment_id = coalesce(p_payment_id, payment_id)
     where id = p_reservation_id and sku = p_sku and store_id = v_store and released_at is null and finalized_at is null and expires_at > now();
    if not found then raise exception 'reservation_expired' using errcode = 'P0001'; end if;
  end if;
  update public.units set state = 'sold', updated_at = now()
   where sku = p_sku and store_id = v_store and state in ('available', 'reserved');
  if not found then
    insert into public.incidents (store_id, kind, sku, detail) values (v_store, 'double_sell', p_sku, jsonb_build_object('channel', p_channel, 'payment_id', p_payment_id));
    perform public.enqueue_double_sell_alert(v_store, p_sku, jsonb_build_object('channel', p_channel, 'payment_id', p_payment_id));
    raise exception 'unit_not_sellable' using errcode = 'P0001';
  end if;
  insert into public.store_settings (store_id, key, value) values (v_store, 'receipt_seq', '0'::jsonb) on conflict (store_id, key) do nothing;
  update public.store_settings set value = to_jsonb(coalesce((value #>> '{}')::int, 0) + 1) where store_id = v_store and key = 'receipt_seq' returning (value #>> '{}')::int into v_seq;
  v_receipt := 'R-' || lpad(v_seq::text, greatest(5, public.sku_digits()), '0');
  begin
    insert into public.sales (store_id, sku, price_cents, tax_cents, card_fee_cents, channel, payment_method, payment_id, customer_name, customer_phone, customer_email, note, sold_at, receipt_no, actor_id)
    values (v_store, p_sku, p_price_cents, coalesce(p_tax_cents, 0), v_fee, btrim(p_channel), p_payment_method, p_payment_id, p_customer_name, p_customer_phone, p_customer_email, p_note, now(), v_receipt, auth.uid())
    returning * into v_sale;
  exception when unique_violation then
    insert into public.incidents (store_id, kind, sku, detail) values (v_store, 'double_sell', p_sku, jsonb_build_object('channel', p_channel, 'payment_id', p_payment_id));
    perform public.enqueue_double_sell_alert(v_store, p_sku, jsonb_build_object('channel', p_channel, 'payment_id', p_payment_id));
    raise;
  end;
  update public.sku_ledger set fate = 'sold' where sku = p_sku and store_id is not distinct from v_store;
  if p_reservation_id is not null then
    update public.reservations set finalized_at = now(), sale_id = v_sale.id, payment_id = coalesce(p_payment_id, payment_id) where id = p_reservation_id;
  else
    update public.reservations set released_at = now() where store_id = v_store and sku = p_sku and released_at is null and finalized_at is null;
  end if;
  insert into public.events (store_id, sku, kind, new_value, actor, actor_id, note)
  values (v_store, p_sku, 'sold', p_price_cents::text, coalesce((select display_name from public.staff where user_id = auth.uid()), 'service'), auth.uid(), btrim(p_channel) || ' ' || v_receipt);
  perform public.steal_open_web_orders(v_store, p_sku, v_sale);
  perform public.open_delist_tasks(v_sale);
  perform public.enqueue_sale_alerts(v_sale);
  if btrim(p_channel) = 'website' then
    insert into public.alert_outbox (store_id, kind, sku, payload)
    select o.store_id, 'web_order', o.sku, jsonb_build_object('order_id', o.id, 'buyer_name', o.buyer_name, 'buyer_email', o.buyer_email, 'buyer_phone', o.buyer_phone, 'ship_line1', o.ship_line1, 'ship_city', o.ship_city, 'ship_region', o.ship_region, 'ship_postal', o.ship_postal, 'item_cents', o.item_cents, 'shipping_cents', o.shipping_cents, 'total_cents', o.total_cents, 'receipt_no', v_sale.receipt_no)
    from public.web_orders o where o.sale_id = v_sale.id limit 1;
  end if;
  return v_sale;
end;
$$;


ALTER FUNCTION "public"."finalize_sale"("p_sku" "text", "p_channel" "text", "p_price_cents" integer, "p_payment_method" "text", "p_payment_id" "text", "p_customer_name" "text", "p_customer_phone" "text", "p_customer_email" "text", "p_note" "text", "p_reservation_id" "uuid", "p_tax_cents" integer, "p_approval_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_ticket"("p_ticket_id" "uuid", "p_lines" "jsonb", "p_payment_method" "text", "p_payment_id" "text" DEFAULT NULL::"text", "p_amount_tendered_cents" integer DEFAULT NULL::integer, "p_channel" "text" DEFAULT 'floor'::"text", "p_discount_bps" integer DEFAULT 0, "p_discount_approval_id" "uuid" DEFAULT NULL::"uuid", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_redeem_points" integer DEFAULT 0, "p_cash_cents" integer DEFAULT NULL::integer, "p_card_cents" integer DEFAULT NULL::integer, "p_note" "text" DEFAULT NULL::"text", "p_sold_by_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_bps int;
  v_existing jsonb;
  v_n int;
  v_skus text[] := '{}';
  v_unit_prices int[] := '{}';
  v_qtys int[] := '{}';
  v_raw_prices int[] := '{}';
  v_disc_shares int[];
  v_net_prices int[] := '{}';
  v_fee_shares int[] := '{}';
  v_taxes int[];
  v_line jsonb;
  v_sku text;
  v_unit_price int;
  v_qty int;
  v_price int;
  v_ask int;
  v_floor int;
  v_state text;
  v_qty_on_hand int;
  v_approval uuid;
  v_reason text;
  v_list int;
  v_tax int;
  v_receipt text;
  v_seq int;
  v_sale public.sales;
  v_actor text;
  v_sale_actor_id uuid;
  v_code text := nullif(btrim(coalesce(p_sold_by_code, '')), '');
  v_channel text := coalesce(nullif(btrim(p_channel), ''), 'floor');
  v_pay text := lower(btrim(coalesce(p_payment_method, '')));
  i int;
  v_seen text[];
  v_raw_sub bigint := 0;
  v_discount_bps int := coalesce(p_discount_bps, 0);
  v_clerk_max int;
  v_discount_cents int := 0;
  v_signup_bps int;
  v_signup_cents int := 0;
  v_point_value int;
  v_points_per_dollar int;
  v_redeem_points int := coalesce(p_redeem_points, 0);
  v_redeem_cents int := 0;
  v_remaining int;
  v_total_disc int;
  v_net_sub int := 0;
  v_tax_total int := 0;
  v_prefee int;
  v_fee_bps int;
  v_card_base int := 0;
  v_card_fee int := 0;
  v_total int;
  v_cash int;
  v_card int;
  v_rewards_enabled boolean;
  v_rewards_channel boolean;
  v_cust public.customers;
  v_bal int;
  v_earn int := 0;
  v_new_bal int;
  v_receipt_snap jsonb;
  v_discount_by uuid := null;
  v_first_sku text;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if p_ticket_id is null then
    raise exception 'ticket_required' using errcode = '22023';
  end if;
  if v_pay is null or v_pay = '' or v_pay not in ('cash', 'card', 'split', 'other') then
    raise exception 'invalid_payment' using errcode = '22023';
  end if;
  if v_discount_bps < 0 or v_discount_bps > 10000 then
    raise exception 'invalid_discount_bps' using errcode = '22023';
  end if;
  if v_redeem_points < 0 then
    raise exception 'invalid_redeem_points' using errcode = '22023';
  end if;

  v_existing := public.ticket_summary(v_store, p_ticket_id);
  if v_existing is not null then
    return v_existing;
  end if;

  v_bps := public.store_tax_rate_bps();
  if v_bps is null then
    raise exception 'tax_rate_required' using errcode = 'P0001';
  end if;

  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) < 1 then
    raise exception 'empty_ticket' using errcode = '22023';
  end if;

  v_n := jsonb_array_length(p_lines);
  v_seen := '{}';

  for i in 0..v_n - 1 loop
    v_line := p_lines->i;
    v_sku := btrim(coalesce(v_line->>'sku', ''));
    if v_sku = '' then
      raise exception 'invalid_sku' using errcode = '22023';
    end if;
    if v_sku = any (v_seen) then
      raise exception using errcode = 'P0001', message = format('duplicate_sku %s', v_sku);
    end if;
    v_seen := v_seen || v_sku;
    v_unit_price := (v_line->>'price_cents')::int;
    if v_unit_price is null or v_unit_price < 0 then
      raise exception using errcode = '22023', message = format('invalid_price %s', v_sku);
    end if;
    v_qty := coalesce(nullif(v_line->>'qty', '')::int, 1);
    if v_qty is null or v_qty < 1 then
      raise exception using errcode = '22023', message = format('invalid_qty %s', v_sku);
    end if;
    v_skus := v_skus || v_sku;
    v_unit_prices := v_unit_prices || v_unit_price;
    v_qtys := v_qtys || v_qty;
    v_price := v_unit_price * v_qty;
    v_raw_prices := v_raw_prices || v_price;
    v_raw_sub := v_raw_sub + v_price;
  end loop;

  v_first_sku := v_skus[1];

  perform public.release_expired_reservations();

  perform 1
    from public.units u
   where u.store_id = v_store
     and u.sku = any (v_skus)
   order by u.sku
     for update;

  for i in 1..v_n loop
    v_sku := v_skus[i];
    select u.ask_cents, u.floor_cents, u.state, u.qty_on_hand
      into v_ask, v_floor, v_state, v_qty_on_hand
      from public.units u
     where u.store_id = v_store and u.sku = v_sku;
    if not found then
      raise exception using errcode = 'P0001', message = format('sku_not_in_store %s', v_sku);
    end if;
    if v_state is distinct from 'available' and v_state is distinct from 'reserved' then
      insert into public.incidents (store_id, kind, sku, detail)
      values (v_store, 'double_sell', v_sku, jsonb_build_object('ticket_id', p_ticket_id, 'state', v_state));
      raise exception using errcode = 'P0001', message = format('unit_not_sellable %s', v_sku);
    end if;
    if v_qty_on_hand < v_qtys[i] then
      raise exception using errcode = 'P0001', message = format('insufficient_qty %s', v_sku);
    end if;
  end loop;

  v_clerk_max := public.store_setting_int(v_store, 'clerk_max_discount_bps', 1000);
  if v_discount_bps > v_clerk_max then
    if not public.is_manager() and auth.role() <> 'service_role' then
      if p_discount_approval_id is null or not exists (
        select 1 from public.approvals a
         where a.id = p_discount_approval_id
           and a.store_id = v_store
           and a.action = 'ticket_discount'
           and (a.sku = '*' or a.sku = v_first_sku)
           and a.consumed_at is null
           and a.created_at > now() - interval '10 minutes'
      ) then
        raise exception 'discount_approval_required' using errcode = 'P0001';
      end if;
      update public.approvals set consumed_at = now() where id = p_discount_approval_id;
    end if;
  end if;

  v_discount_cents := round((v_raw_sub::numeric * v_discount_bps::numeric) / 10000.0, 0)::int;
  if v_discount_bps > 0 then
    v_discount_by := auth.uid();
  end if;
  v_remaining := (v_raw_sub - v_discount_cents)::int;

  v_rewards_enabled := coalesce(
    (public.store_setting(v_store, 'rewards_enabled', 'true'::jsonb) #>> '{}')::boolean,
    true
  );
  v_rewards_channel := v_channel in ('floor', 'website');

  if p_customer_id is not null and v_rewards_channel and v_rewards_enabled then
    select * into v_cust from public.customers
     where id = p_customer_id and store_id = v_store
     for update;
    if not found then
      raise exception 'customer_not_found' using errcode = 'P0001';
    end if;

    if not v_cust.first_purchase_discount_used then
      v_signup_bps := public.store_setting_int(v_store, 'rewards_signup_discount_bps', 500);
      v_signup_cents := round((v_remaining::numeric * v_signup_bps::numeric) / 10000.0, 0)::int;
      v_remaining := v_remaining - v_signup_cents;
      update public.customers
         set first_purchase_discount_used = true
       where id = v_cust.id;
    end if;

    if v_redeem_points > 0 then
      v_bal := public.customer_points_balance_internal(v_store, v_cust.id);
      if v_redeem_points > v_bal then
        raise exception 'insufficient_points' using errcode = 'P0001';
      end if;
      v_point_value := public.store_setting_int(v_store, 'rewards_point_value_cents', 1);
      v_redeem_cents := v_redeem_points * v_point_value;
      if v_redeem_cents > v_remaining then
        raise exception 'redeem_exceeds_subtotal' using errcode = 'P0001';
      end if;
      v_remaining := v_remaining - v_redeem_cents;
      v_new_bal := v_bal - v_redeem_points;
      insert into public.customer_points_ledger (
        store_id, customer_id, delta, balance_after, reason, ticket_id, actor_id
      ) values (
        v_store, v_cust.id, -v_redeem_points, v_new_bal, 'redeem_sale', p_ticket_id, auth.uid()
      );
    end if;
  elsif p_customer_id is not null and not v_rewards_channel then
    null;
  elsif v_redeem_points > 0 then
    raise exception 'customer_required_for_redeem' using errcode = 'P0001';
  end if;

  v_total_disc := v_discount_cents + v_signup_cents + v_redeem_cents;
  v_disc_shares := public.prorate_cents(v_raw_prices, v_total_disc);
  for i in 1..v_n loop
    v_net_prices := v_net_prices || greatest(v_raw_prices[i] - v_disc_shares[i], 0);
    v_net_sub := v_net_sub + greatest(v_raw_prices[i] - v_disc_shares[i], 0);
  end loop;

  v_taxes := public.allocate_line_taxes(v_net_prices, v_bps);
  for i in 1..v_n loop
    v_tax_total := v_tax_total + v_taxes[i];
  end loop;

  v_prefee := v_net_sub + v_tax_total;
  v_fee_bps := greatest(public.store_setting_int(v_store, 'card_fee_bps', 250), 0);

  if v_pay = 'split' then
    v_cash := coalesce(p_cash_cents, -1);
    v_card_base := coalesce(p_card_cents, -1);
    if v_cash < 0 or v_card_base < 0 then
      raise exception 'split_amounts_required' using errcode = '22023';
    end if;
    if v_cash + v_card_base is distinct from v_prefee then
      raise exception 'split_mismatch' using errcode = 'P0001';
    end if;
  elsif v_pay = 'card' then
    v_cash := coalesce(p_cash_cents, 0);
    v_card_base := v_prefee;
  elsif v_pay = 'cash' then
    v_cash := coalesce(p_cash_cents, v_prefee);
    v_card_base := coalesce(p_card_cents, 0);
  else
    v_cash := coalesce(p_cash_cents, 0);
    v_card_base := coalesce(p_card_cents, 0);
  end if;

  v_card_fee := round((v_card_base::numeric * v_fee_bps::numeric) / 10000.0, 0)::int;
  v_card := v_card_base + v_card_fee;
  v_total := v_prefee + v_card_fee;

  if v_pay in ('card', 'split') and v_card_base > 0
     and (p_payment_id is null or btrim(p_payment_id) = '') then
    raise exception 'payment_id_required' using errcode = '22023';
  end if;

  if p_customer_id is not null and v_rewards_channel and v_rewards_enabled and v_net_sub > 0 then
    v_points_per_dollar := public.store_setting_int(v_store, 'rewards_points_per_dollar', 1);
    v_earn := floor((v_net_sub::numeric * v_points_per_dollar::numeric) / 100.0)::int;
    if v_earn > 0 then
      v_bal := public.customer_points_balance_internal(v_store, p_customer_id);
      v_new_bal := v_bal + v_earn;
      insert into public.customer_points_ledger (
        store_id, customer_id, delta, balance_after, reason, ticket_id, actor_id
      ) values (
        v_store, p_customer_id, v_earn, v_new_bal, 'earn_sale', p_ticket_id, auth.uid()
      );
    end if;
  end if;

  v_fee_shares := public.prorate_cents(v_net_prices, v_card_fee);
  v_receipt_snap := public.store_setting(v_store, 'receipt_branding', '{}'::jsonb);

  if v_code is not null then
    select s.user_id, s.display_name into v_sale_actor_id, v_actor
      from public.staff s
     where s.store_id = v_store
       and s.deactivated_at is null
       and s.login_code = v_code;
    if v_sale_actor_id is null then
      raise exception using errcode = 'P0001', message = 'unknown_employee_id';
    end if;
  else
    v_sale_actor_id := auth.uid();
    v_actor := coalesce((select display_name from public.staff where user_id = auth.uid()), 'service');
  end if;

  insert into public.ticket_extras (
    ticket_id, store_id, discount_bps, discount_cents, discount_by, discount_approval_id,
    customer_id, points_redeemed, points_earned, signup_discount_cents,
    cash_cents, card_cents, amount_tendered_cents, note, receipt_settings,
    card_fee_bps, card_fee_cents
  ) values (
    p_ticket_id, v_store, v_discount_bps, v_discount_cents, v_discount_by, p_discount_approval_id,
    case when p_customer_id is not null and v_rewards_channel then p_customer_id else null end,
    case when v_redeem_cents > 0 then v_redeem_points else 0 end,
    v_earn, v_signup_cents,
    v_cash, v_card, p_amount_tendered_cents,
    nullif(btrim(coalesce(p_note, '')), ''),
    v_receipt_snap,
    v_fee_bps, v_card_fee
  );

  for i in 1..v_n loop
    v_sku := v_skus[i];
    v_price := v_net_prices[i];
    v_tax := v_taxes[i];
    v_qty := v_qtys[i];
    v_unit_price := v_unit_prices[i];
    v_line := p_lines->(i - 1);
    v_approval := nullif(v_line->>'approval_id', '')::uuid;
    v_reason := nullif(btrim(coalesce(v_line->>'override_reason', '')), '');

    select u.ask_cents, u.floor_cents into v_ask, v_floor
      from public.units u where u.store_id = v_store and u.sku = v_sku;
    v_list := v_ask;

    if v_floor is not null and v_unit_price < v_floor then
      if v_approval is null or not exists (
        select 1 from public.approvals a
         where a.id = v_approval
           and a.store_id = v_store
           and a.action = 'below_floor'
           and a.sku = v_sku
           and a.consumed_at is null
           and a.created_at > now() - interval '10 minutes'
      ) then
        raise exception using errcode = 'P0001', message = format('below_floor %s', v_sku);
      end if;
      update public.approvals set consumed_at = now() where id = v_approval;
    end if;

    if v_list is not null and v_unit_price is distinct from v_list then
      if v_reason is null then
        raise exception using errcode = 'P0001', message = format('override_reason_required %s', v_sku);
      end if;
    else
      v_reason := null;
    end if;

    update public.units
       set qty_on_hand = qty_on_hand - v_qty,
           state = case when qty_on_hand - v_qty <= 0 then 'sold' else 'available' end,
           updated_at = now()
     where store_id = v_store and sku = v_sku and state in ('available', 'reserved')
       and qty_on_hand >= v_qty;
    if not found then
      raise exception using errcode = 'P0001', message = format('unit_not_sellable %s', v_sku);
    end if;

    insert into public.store_settings (store_id, key, value)
    values (v_store, 'receipt_seq', '0'::jsonb)
    on conflict (store_id, key) do nothing;
    update public.store_settings
       set value = to_jsonb(coalesce((value #>> '{}')::int, 0) + 1)
     where store_id = v_store and key = 'receipt_seq'
    returning (value #>> '{}')::int into v_seq;
    v_receipt := 'R-' || lpad(v_seq::text, greatest(5, public.sku_digits()), '0');

    insert into public.sales (
      store_id, sku, price_cents, tax_cents, card_fee_cents, channel, payment_method, payment_id,
      note, sold_at, receipt_no, actor_id, ticket_id, list_price_cents,
      override_reason, override_by, qty, override_price_cents
    ) values (
      v_store, v_sku, v_price, v_tax, coalesce(v_fee_shares[i], 0), v_channel, v_pay, p_payment_id,
      p_note,
      now(), v_receipt, v_sale_actor_id, p_ticket_id,
      case when v_list is not null then v_list * v_qty else null end,
      v_reason,
      case when v_reason is not null then auth.uid() else null end,
      v_qty,
      case when v_reason is not null then v_unit_price * v_qty else null end
    )
    returning * into v_sale;

    if (select qty_on_hand from public.units where store_id = v_store and sku = v_sku) <= 0 then
      update public.sku_ledger set fate = 'sold'
       where sku = v_sku and store_id is not distinct from v_store;
    end if;

    update public.reservations
       set released_at = now()
     where store_id = v_store and sku = v_sku
       and released_at is null and finalized_at is null;

    insert into public.events (store_id, sku, kind, new_value, actor, actor_id, note)
    values (
      v_store, v_sku, 'sold', v_price::text, v_actor, v_sale_actor_id,
      v_channel || ' ' || v_receipt || ' ticket=' || p_ticket_id::text
    );

    perform public.open_delist_tasks(v_sale);
    perform public.enqueue_sale_alerts(v_sale);
  end loop;

  return public.ticket_summary(v_store, p_ticket_id);
end;
$$;


ALTER FUNCTION "public"."finalize_ticket"("p_ticket_id" "uuid", "p_lines" "jsonb", "p_payment_method" "text", "p_payment_id" "text", "p_amount_tendered_cents" integer, "p_channel" "text", "p_discount_bps" integer, "p_discount_approval_id" "uuid", "p_customer_id" "uuid", "p_redeem_points" integer, "p_cash_cents" integer, "p_card_cents" integer, "p_note" "text", "p_sold_by_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_email_outbox"("p_id" bigint, "p_ok" boolean, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ begin perform public.assert_service(); if p_ok then update public.email_outbox set status = 'sent', sent_at = now(), error = null where id = p_id; else update public.email_outbox set status = 'error', error = left(coalesce(p_error, 'send_failed'), 500) where id = p_id; end if; end; $$;


ALTER FUNCTION "public"."finish_email_outbox"("p_id" bigint, "p_ok" boolean, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finish_web_order_refund"("p_store" "uuid", "p_order" "uuid", "p_refund" "text") RETURNS "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare o public.web_orders;
begin
  perform public.assert_service();
  perform set_config('floor.store_id', p_store::text, true);
  select * into o from public.web_orders where id = p_order and store_id = p_store for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0001'; end if;
  if o.status = 'refunded' then return o; end if;
  if o.status <> 'paid' or o.refund_requested_at is null or nullif(p_refund,'') is null then
    raise exception 'refund_not_requested' using errcode = 'P0001';
  end if;
  -- Voids the sale (reports/payouts drop it), restores the unit, reverses points, relists.
  perform public.void_ticket(o.reservation_id,
    'Online order ' || coalesce(o.order_no, o.id::text) || ' refunded: ' || coalesce(o.cancel_reason, o.cancel_source), null);
  update public.web_orders set status = 'refunded', refund_id = p_refund, canceled_at = now(), updated_at = now()
   where id = o.id returning * into o;
  insert into public.events (store_id, sku, kind, actor, note)
  values (p_store, o.sku, 'web_order_refunded', 'website', coalesce(o.order_no,'') || ' ' || coalesce(o.cancel_source,''));
  return o;
end $$;


ALTER FUNCTION "public"."finish_web_order_refund"("p_store" "uuid", "p_order" "uuid", "p_refund" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_begin_push"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtext(p_store::text));
  perform public.floor_bundle_push_gate(p_store,p_sku,p_channel);
  insert into public.floor_listing_push_intents(store_id,sku,channel,expires_at)
    values(p_store,p_sku,lower(btrim(p_channel)),now()+interval '30 minutes')
    on conflict(store_id,sku,channel) do update set expires_at=excluded.expires_at;
end $$;


