    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.active then
    update public.unit_channel_categories set enabled=false,updated_at=now()
      where store_id=new.store_id and sku=new.sku and channel='amazon';
  end if;
  return new;
end $$;


