end $$;


ALTER FUNCTION "public"."floor_bundle_listing_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_push_gate"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_unit public.units; v_channel text:=lower(btrim(coalesce(p_channel,'')));
begin
  select * into v_unit from public.units where store_id=p_store and sku=p_sku;
  if not found then raise exception 'unknown_sku'; end if;
  if exists(select 1 from public.floor_bundle_components c
      join public.floor_bundles b on b.store_id=c.store_id and b.sku=c.bundle_sku and b.active
      where c.store_id=p_store and c.component_sku=p_sku) then
    raise exception 'bundled_component_not_listable';
  end if;
  if exists(select 1 from public.floor_bundles where store_id=p_store and sku=p_sku and active)
      and v_channel not in ('ebay','tiktok','website') then
    raise exception 'bundle_channel_blocked';
  end if;
  if v_channel='depop' and (
    coalesce(v_unit.category,'') ~* '(electronic|computer|tablet|phone|camera|audio|video game|appliance)'
    or coalesce(v_unit.title,'') ~* '(electric|rechargeable|powered)\s+toothbrush'
  ) then raise exception 'depop_electronics_blocked'; end if;
end $$;


ALTER FUNCTION "public"."floor_bundle_push_gate"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_refresh"("p_store" "uuid", "p_bundle" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  b public.floor_bundles;
  v_available int;
  v_cost int;
  v_price int;
  v_main_price int;
  v_extra_price int;
  v_description text;
  v_main_title text;
  v_extra_titles text;
begin
  select * into b from public.floor_bundles
    where store_id=p_store and sku=p_bundle and active for update;
  if not found then return; end if;
  select min(case when u.state in ('available','reserved') then u.qty_on_hand / c.quantity else 0 end),
         sum(coalesce(u.acquisition_cost_cents,0)*c.quantity),
         max(u.ask_cents) filter(where c.is_main),
         coalesce(sum(u.ask_cents*c.quantity) filter(where not c.is_main),0),
         string_agg(c.quantity::text || ' × ' || coalesce(nullif(u.title,''),u.sku), ', ' order by c.is_main desc,c.component_sku),
         max(coalesce(nullif(u.title,''),u.sku)) filter(where c.is_main),
         string_agg(c.quantity::text || ' × ' || coalesce(nullif(u.title,''),u.sku), ', ' order by c.component_sku) filter(where not c.is_main)
    into v_available,v_cost,v_main_price,v_extra_price,v_description,v_main_title,v_extra_titles
    from public.floor_bundle_components c join public.units u on u.sku=c.component_sku and u.store_id=c.store_id
    where c.store_id=p_store and c.bundle_sku=p_bundle;
  if v_available is null or v_main_price is null then raise exception 'bundle_components_invalid'; end if;
  v_price:=coalesce(b.price_override_cents,v_main_price+round(v_extra_price/2.0)::int);
  update public.units set qty_on_hand=v_available,
      state=case when v_available<1 then 'sold'
        when exists(select 1 from public.reservations r where r.store_id=p_store and r.sku=p_bundle
          and r.released_at is null and r.finalized_at is null and r.expires_at>now()) then 'reserved'
        else 'available' end,
      ask_cents=v_price, acquisition_cost_cents=v_cost,
      title='Bundle: '||case when length(v_main_title)>38 then left(v_main_title,35)||'…'
        else v_main_title end||' + '||left(v_extra_titles,160),
      listing_body='Includes: '||v_description||'.', updated_at=now()
    where store_id=p_store and sku=p_bundle;
end $$;


ALTER FUNCTION "public"."floor_bundle_refresh"("p_store" "uuid", "p_bundle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_reservation_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if exists(select 1 from public.floor_bundles b where b.store_id=new.store_id and b.sku=new.sku and b.active) then
    perform public.floor_bundle_refresh(new.store_id,new.sku);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."floor_bundle_reservation_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_return_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_part record;
begin
  if old.voided_at is null and new.voided_at is not null then
    if current_setting('floor.bundle_restock', true)='false' then return new; end if;
    for v_part in select bc.component_sku,bc.quantity from public.floor_bundle_components bc
      where bc.store_id=new.store_id and bc.bundle_sku=new.sku order by bc.component_sku loop
      update public.units set qty_on_hand=qty_on_hand+v_part.quantity*coalesce(new.qty,1),
        state='available',updated_at=now()
      where store_id=new.store_id and sku=v_part.component_sku;
    end loop;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."floor_bundle_return_stock"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_bundle_sale_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_part record;
begin
  if exists(select 1 from public.floor_bundle_components bc join public.floor_bundles b
    on b.store_id=bc.store_id and b.sku=bc.bundle_sku and b.active
    where bc.store_id=new.store_id and bc.component_sku=new.sku) then
    raise exception 'bundled_component_not_sellable: %',new.sku;
  end if;
  if exists(select 1 from public.floor_bundles b where b.store_id=new.store_id and b.sku=new.sku and b.active) then
    if exists(select 1 from public.reservations r where r.store_id=new.store_id and r.sku=new.sku
      and r.released_at is null and r.finalized_at is null and r.expires_at>now()
      and r.channel<>new.channel) then raise exception 'bundle_reserved_for_another_channel'; end if;
    for v_part in select bc.component_sku,bc.quantity from public.floor_bundle_components bc
      where bc.store_id=new.store_id and bc.bundle_sku=new.sku order by bc.component_sku loop
      update public.units set qty_on_hand=qty_on_hand-v_part.quantity*coalesce(new.qty,1),
        state=case when qty_on_hand-v_part.quantity*coalesce(new.qty,1)>0 then 'available' else 'sold' end,
        updated_at=now()
      where store_id=new.store_id and sku=v_part.component_sku and state in ('available','reserved')
        and qty_on_hand>=v_part.quantity*coalesce(new.qty,1);
      if not found then raise exception 'bundle_component_out_of_stock: %',v_part.component_sku; end if;
    end loop;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."floor_bundle_sale_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_demote_sku"("p_store" "uuid", "p_sku" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_count int;
begin
  update public.units u set listing_specs=jsonb_set(coalesce(u.listing_specs,'{}'::jsonb),'{ready_to_list}','false'::jsonb,true)
  where u.store_id=p_store and u.sku=p_sku
    and coalesce((u.listing_specs->>'ready_to_list')::boolean,false)
    and not exists(select 1 from public.listings l where l.store_id=u.store_id and l.sku=u.sku and l.status='listed')
    and not exists(select 1 from public.amazon_list_items a where a.store_id=u.store_id and a.sku=u.sku and a.status='live')
    and not exists(select 1 from public.tiktok_list_items t where t.store_id=u.store_id and t.sku=u.sku and t.status='live')
    and jsonb_array_length(public.floor_category_gaps(u.store_id,u.sku))>0;
  get diagnostics v_count=row_count;
  return v_count>0;
end $$;


ALTER FUNCTION "public"."floor_category_demote_sku"("p_store" "uuid", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_gaps"("p_store" "uuid", "p_sku" "text", "p_channel" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object('channel',i.channel,'issue',i.issue,'field',i.field)
    order by i.channel,i.field),'[]'::jsonb)
  from public.floor_category_issue_rows(p_store,p_sku,p_channel,p_channel) i
$$;


ALTER FUNCTION "public"."floor_category_gaps"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_issue_rows"("p_store" "uuid", "p_sku" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT NULL::"text", "p_push_channel" "text" DEFAULT NULL::"text") RETURNS TABLE("sku" "text", "channel" "text", "issue" "text", "field" "text")
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select x.sku, x.channel, x.issue, x.field from (
    select c.sku, c.channel,
      case when c.review_reason is not null then c.review_reason
        when c.category_id is null then 'missing category'
        when c.channel='depop' and (d.category_id is null or not d.active) then 'retired category'
        when c.channel<>'depop' and (t.category_id is null or not t.active or not t.leaf) then 'retired category'
        when c.channel<>'depop' and t.fields_fetched_at is null then 'category fields not synced'
        -- category-sync refreshes each channel every 3 days; 7 days tolerates one failed run.
        when c.channel<>'depop' and (t.fetched_at < now()-interval '7 days'
          or t.fields_fetched_at < now()-interval '7 days') then 'category taxonomy stale'
        when c.channel<>'depop' and c.validated_version is distinct from
          (coalesce(t.fingerprint,'')||':'||coalesce(t.fields_version,'')) then 'category changed; recheck'
        when c.channel='amazon'
          and (p_push_channel = 'amazon' or public.floor_unit_headed_to_amazon(c.store_id, c.sku))
          and (c.validation_version is distinct from t.fields_version
          or c.validation_attributes is distinct from c.attributes
          or c.validation_unit is distinct from jsonb_build_object('condition',u.condition,'ask_cents',u.ask_cents,
            'qty_on_hand',u.qty_on_hand,'asin',u.listing_specs->>'asin')) then 'Amazon schema validation pending'
        when f.value->>'issue' is not null then f.value->>'issue'
        when f.value->>'kind'='unsupported_document' then 'channel document required'
        when f.value is not null then 'missing required field'
        else null end issue,
      f.value->>'name' field
    from public.unit_channel_categories c
    join public.units u on u.store_id=c.store_id and u.sku=c.sku
    left join public.channel_taxonomy t on t.channel=c.channel and t.category_id=c.category_id
    left join public.store_depop_categories d on c.channel='depop' and d.store_id=c.store_id and d.category_id=c.category_id
    left join lateral (
      select elem.value from jsonb_array_elements(case when c.channel='depop' then coalesce(d.required_fields,'[]'::jsonb)
        else coalesce(t.required_fields,'[]'::jsonb) end) elem
      where coalesce(elem.value->>'required','true')='true'
        and (elem.value->>'kind'='unsupported_document'
          or nullif(btrim(coalesce(c.attributes->>(elem.value->>'name'),'')),'') is null
          or (jsonb_typeof(elem.value->'allowed')='array'
            and jsonb_array_length(elem.value->'allowed')>0
            and not ((elem.value->'allowed') ? (c.attributes->>(elem.value->>'name')))))
      union all select elem.value from jsonb_array_elements(c.validation_errors) elem where c.channel='amazon'
    ) f on true
    where c.store_id=p_store and c.enabled
      and (p_sku is null or c.sku=p_sku)
      and (p_channel is null or c.channel=p_channel)
  ) x where x.issue is not null
$$;


ALTER FUNCTION "public"."floor_category_issue_rows"("p_store" "uuid", "p_sku" "text", "p_channel" "text", "p_push_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_pre_push"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_gaps jsonb;
begin
  if p_channel not in ('ebay','amazon','tiktok','depop') then
    raise exception 'unknown_channel' using errcode='22023'; end if;
  if not exists(select 1 from public.units where store_id=p_store and sku=p_sku) then
    raise exception 'unit_not_found' using errcode='22023'; end if;
  if not exists(select 1 from public.unit_channel_categories
    where store_id=p_store and sku=p_sku and channel=p_channel and enabled) then
    raise exception 'category_channel_disabled: %',p_channel using errcode='22023'; end if;
  v_gaps:=public.floor_category_gaps(p_store,p_sku,p_channel);
  if jsonb_array_length(v_gaps)>0 then
    raise exception 'category_not_ready: %',v_gaps using errcode='22023'; end if;
end $$;


ALTER FUNCTION "public"."floor_category_pre_push"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_ready_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if coalesce((new.listing_specs->>'ready_to_list')::boolean,false)
    and not exists(select 1 from public.listings l where l.store_id=new.store_id and l.sku=new.sku and l.status='listed')
    and not exists(select 1 from public.amazon_list_items a where a.store_id=new.store_id and a.sku=new.sku and a.status='live')
    and not exists(select 1 from public.tiktok_list_items t where t.store_id=new.store_id and t.sku=new.sku and t.status='live')
    and jsonb_array_length(public.floor_category_gaps(new.store_id,new.sku))>0 then
    update public.units set listing_specs=jsonb_set(coalesce(new.listing_specs,'{}'::jsonb),'{ready_to_list}','false'::jsonb,true)
      where store_id=new.store_id and sku=new.sku;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."floor_category_ready_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_row_guard"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.category_id is not null and new.channel='depop'
    and not exists(select 1 from public.store_depop_categories d where d.store_id=new.store_id
      and d.category_id=new.category_id and d.active) then
    raise exception 'category_not_active_leaf: depop' using errcode='22023'; end if;
  return new;
end $$;


ALTER FUNCTION "public"."floor_category_row_guard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_taxonomy_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r record;
begin
  for r in select store_id,sku from public.unit_channel_categories
    where channel=new.channel and category_id=new.category_id and enabled loop
    perform public.floor_category_demote_sku(r.store_id,r.sku);
  end loop;
  return new;
end $$;


ALTER FUNCTION "public"."floor_category_taxonomy_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_category_unit_changed"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.floor_category_demote_sku(new.store_id,new.sku);
  return new;
end $$;


ALTER FUNCTION "public"."floor_category_unit_changed"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_store_listing_channels"("p_store" "uuid") RETURNS "text"[]
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select coalesce(array_agg(x order by x), '{}'::text[])
  from jsonb_array_elements_text(public.store_setting(p_store, 'listing_channels', '["ebay"]'::jsonb)) x
  where x in ('ebay', 'amazon', 'tiktok', 'depop');
$$;


ALTER FUNCTION "public"."floor_store_listing_channels"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."floor_unit_headed_to_amazon"("p_store" "uuid", "p_sku" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists(select 1 from public.amazon_list_items a
    where a.store_id = p_store and a.sku = p_sku
      and a.status in ('queued', 'ready', 'needs_review', 'listing', 'live', 'error'));
$$;


ALTER FUNCTION "public"."floor_unit_headed_to_amazon"("p_store" "uuid", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_online_checkout_hold"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.channel is distinct from 'website' and (
    exists(select 1 from public.reservations r
            where r.store_id = new.store_id and r.sku = new.sku and r.channel = 'website'
              and r.released_at is null and r.finalized_at is null and r.expires_at > now())
    or exists(select 1 from public.web_orders o
            where o.store_id = new.store_id and o.sku = new.sku and o.status = 'claimed'
              and o.payment_started_at > now() - interval '30 minutes')
  ) then
    raise exception using errcode = 'P0001', message = format('held_by_online_order %s', new.sku);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."guard_online_checkout_hold"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."heartbeat_pos_device"("p_device_id" "uuid", "p_square_authorized" boolean DEFAULT NULL::boolean, "p_square_location_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_staff_or_service();
  update public.pos_devices
     set last_seen = now(),
         square_authorized = coalesce(p_square_authorized, square_authorized),
         square_location_id = case
           when p_square_authorized is null then square_location_id
           when p_square_authorized then nullif(btrim(coalesce(p_square_location_id, '')), '')
           else null
         end
   where id = p_device_id
     and store_id = public.current_store_id();
end;
$$;


ALTER FUNCTION "public"."heartbeat_pos_device"("p_device_id" "uuid", "p_square_authorized" boolean, "p_square_location_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ingest_channel_return"("p_store" "uuid", "p_channel" "text", "p_payload" "jsonb") RETURNS "public"."returns"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_channel text := lower(btrim(coalesce(p_channel, '')));
  v_ext text := nullif(btrim(coalesce(p_payload->>'external_return_id', p_payload->>'amazon_rma_id', p_payload->>'return_id', '')), '');
  v_order text := nullif(btrim(coalesce(p_payload->>'external_order_id', p_payload->>'order_id', '')), '');
  v_sku text := nullif(btrim(coalesce(p_payload->>'sku', p_payload->>'merchant_sku', '')), '');
  v_wo public.web_orders;
  v_sale public.sales;
  v_settings jsonb;
  v_hours int;
  v_row public.returns;
  v_item int;
  v_label int := greatest(0, coalesce((p_payload->>'return_label_cents')::int, 0));
  v_refund int := greatest(0, coalesce((p_payload->>'refund_cents')::int, 0));
  v_status text := lower(btrim(coalesce(p_payload->>'status', 'requested')));
  v_needs boolean := coalesce((p_payload->>'needs_decision')::boolean, true);
  v_supplier public.suppliers;
  v_route text := 'garage';
begin
  perform public.assert_service();
  if p_store is null or v_channel = '' then
    raise exception 'store_and_channel_required' using errcode = '22023';
  end if;

  if v_ext is not null then
    select * into v_row from public.returns
     where store_id = p_store and channel = v_channel and external_return_id = v_ext;
    if found then
      update public.returns set
        raw = coalesce(raw, '{}'::jsonb) || coalesce(p_payload, '{}'::jsonb),
        refund_cents = case when v_refund > 0 then v_refund else refund_cents end,
        return_label_cents = case when v_label > 0 then v_label else return_label_cents end,
        tracking_number = coalesce(nullif(p_payload->>'tracking_number',''), tracking_number),
        carrier = coalesce(nullif(p_payload->>'carrier',''), carrier),
        updated_at = now()
      where id = v_row.id
      returning * into v_row;
      return v_row;
    end if;
  end if;

  if v_order is not null then
    select * into v_wo from public.web_orders
     where store_id = p_store and channel = v_channel and order_no = v_order
     order by created_at desc limit 1;
  end if;

  if v_sku is null and v_wo.id is not null then v_sku := v_wo.sku; end if;

  if v_wo.sale_id is not null then
    select * into v_sale from public.sales where id = v_wo.sale_id;
  elsif v_sku is not null then
    select * into v_sale from public.sales
     where store_id = p_store and sku = v_sku and voided_at is null
     order by sold_at desc limit 1;
  end if;

  if v_sku is null then v_sku := 'UNMATCHED'; end if;

  v_item := coalesce(v_wo.item_cents, v_sale.price_cents, (p_payload->>'order_amount_cents')::int, 0);
  if v_refund <= 0 then v_refund := v_item; end if;

  if v_sku <> 'UNMATCHED' then
    select s.* into v_supplier
      from public.units u
      join public.suppliers s on s.id = u.supplier_id
     where u.store_id = p_store and u.sku = v_sku;
    if found then
      if v_supplier.accepts_returns and v_supplier.has_us_return_address then
        v_route := 'supplier';
      elsif public.returns_should_refund_no_return(p_store, v_item, v_label) then
        v_route := 'buyer_keeps';
        v_status := 'refunded_no_return';
        v_needs := false;
      end if;
    end if;
  end if;

  if v_route = 'garage' and public.returns_should_refund_no_return(p_store, v_item, v_label)
     and coalesce((p_payload->>'force_physical_return')::boolean, false) is not true then
    v_route := 'buyer_keeps';
    v_status := 'refunded_no_return';
    v_needs := false;
  end if;

  if v_status not in (
    'requested','approved','in_transit','received','inspected','dispositioned',
    'closed','refunded_no_return','denied','canceled'
  ) then
    v_status := 'requested';
  end if;

  v_settings := public.return_settings(p_store);
  v_hours := coalesce(
    (v_settings #>> array['decision_hours', v_channel])::int,
    (v_settings #>> array['decision_hours', 'default'])::int,
    72
  );

  insert into public.returns (
    store_id, sku, sale_id, web_order_id, channel, external_order_id, external_return_id,
    reason, fault, status, refund_cents, return_label_cents, label_paid_by,
    unrecovered_fees_cents, decision_deadline_at, needs_decision, route_to, supplier_id,
    tracking_number, carrier, condition_before, raw
  ) values (
    p_store, v_sku, v_sale.id, v_wo.id, v_channel, v_order, v_ext,
    public.map_return_reason(coalesce(p_payload->>'reason', p_payload->>'return_reason', '')),
    case
      when lower(coalesce(p_payload->>'fault','')) in ('seller','buyer','carrier') then lower(p_payload->>'fault')
      when public.map_return_reason(coalesce(p_payload->>'reason','')) in ('defective','not_as_described','wrong_item') then 'seller'
      when public.map_return_reason(coalesce(p_payload->>'reason','')) = 'buyer_remorse' then 'buyer'
      else 'unknown'
    end,
    v_status, v_refund, v_label,
    case lower(coalesce(p_payload->>'label_paid_by', p_payload->>'label_to_be_paid_by', ''))
      when 'seller' then 'seller' when 'buyer' then 'buyer' when 'customer' then 'buyer'
      when 'amazon' then 'channel' when 'channel' then 'channel' else 'unknown'
    end,
    greatest(0, coalesce((p_payload->>'unrecovered_fees_cents')::int, 0)),
    case when v_needs then now() + make_interval(hours => greatest(v_hours, 1)) else null end,
    v_needs, v_route, v_supplier.id,
    nullif(p_payload->>'tracking_number',''), nullif(p_payload->>'carrier',''),
    (select condition from public.units where store_id = p_store and sku = v_sku),
    coalesce(p_payload, '{}'::jsonb)
  ) returning * into v_row;

  if v_row.needs_decision then
    perform public.enqueue_return_decision_alert(v_row);
  end if;

  if v_row.status = 'refunded_no_return' then
    perform public.return_apply_commission_clawbacks(v_row.id);
    perform public.return_reverse_sale(p_store, v_row.sale_id, 'Refund without return', false);
    if v_row.web_order_id is not null then
      update public.web_orders
         set status = case when status = 'paid' then 'refunded' else status end,
             canceled_at = coalesce(canceled_at, now()),
             cancel_source = coalesce(cancel_source, 'return'),
             cancel_reason = coalesce(cancel_reason, 'refunded_no_return'),
             updated_at = now()
       where id = v_row.web_order_id and store_id = p_store;
    end if;
    update public.returns set
      refunded_at = now(), closed_at = now(), disposition = 'keep_buyer', updated_at = now()
     where id = v_row.id
     returning * into v_row;
    perform public.return_post_ledger(v_row.id);
  end if;

  if exists (select 1 from public.sku_ledger where store_id = p_store and sku = v_row.sku) then
    insert into public.events (store_id, sku, kind, actor, note)
    values (p_store, v_row.sku, 'return_opened', 'channel:' || v_channel,
            coalesce(v_row.external_return_id, v_row.id::text) || ' ' || v_row.status);
  end if;

  return v_row;
end $$;


ALTER FUNCTION "public"."ingest_channel_return"("p_store" "uuid", "p_channel" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."initialize_unit_categories"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_ebay text; v_on text[] := public.floor_store_listing_channels(new.store_id);
begin
  v_ebay:=coalesce(nullif(btrim(new.listing_specs->>'ebay_category_id'),''),
    case when new.ebay_category ~ '^[0-9]+$' then new.ebay_category end);
  insert into public.unit_channel_categories(store_id,sku,channel,category_id,enabled,source)
  values (new.store_id,new.sku,'ebay',v_ebay,'ebay' = any(v_on),'existing'),
    (new.store_id,new.sku,'amazon',null,'amazon' = any(v_on),'existing'),
    (new.store_id,new.sku,'tiktok',null,'tiktok' = any(v_on),'existing'),
    (new.store_id,new.sku,'depop',null,'depop' = any(v_on),'existing')
  on conflict do nothing;
  return new;
end $_$;


ALTER FUNCTION "public"."initialize_unit_categories"() OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."staff_invites" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "store_id" "uuid" NOT NULL,
    "email" "text" NOT NULL,
    "role" "text" NOT NULL,
    "token" "text" DEFAULT "encode"("extensions"."gen_random_bytes"(24), 'hex'::"text") NOT NULL,
    "invited_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "accepted_at" timestamp with time zone,
    CONSTRAINT "staff_invites_role_check" CHECK (("role" = ANY (ARRAY['manager'::"text", 'staff'::"text"])))
);


ALTER TABLE "public"."staff_invites" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_staff"("p_email" "text", "p_role" "text") RETURNS "public"."staff_invites"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row public.staff_invites;
  v_role text := lower(btrim(p_role));
begin
  perform public.assert_manager();
  if v_role = 'owner' then
    raise exception 'cannot_invite_owner' using errcode = '22023';
  end if;
  if v_role = 'manager' then
    perform public.assert_owner();
  end if;
  if v_role not in ('manager', 'staff') then
    raise exception 'invalid_role' using errcode = '22023';
  end if;

  insert into public.staff_invites (store_id, email, role, invited_by)
  values (public.current_store_id(), lower(btrim(p_email)), v_role, auth.uid())
  returning * into v_row;
  return v_row;
end;
$$;


