CREATE OR REPLACE FUNCTION "public"."list_customers"("p_q" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_store uuid := public.current_store_id(); v_lim int := greatest(1, least(coalesce(p_limit, 200), 500)); v_q text := nullif(btrim(coalesce(p_q, '')), ''); v_rows jsonb; v_point int; begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_point := greatest(public.store_setting_int(v_store, 'rewards_point_value_cents', 1), 0); select coalesce(jsonb_agg(row_to_json(x)::jsonb order by x.last_visit desc nulls last, x.created_at desc), '[]'::jsonb) into v_rows from ( select c.id, c.phone, c.name, c.email, c.marketing_opt_in, (c.unsubscribed_at is not null) as unsubscribed, c.first_purchase_discount_used, c.signup_code, c.created_at, public.customer_points_balance_internal(v_store, c.id) as points, public.customer_points_balance_internal(v_store, c.id) * v_point as credit_cents, coalesce((select sum(s.price_cents)::bigint from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and te.store_id = v_store and s.voided_at is null and s.channel in ('floor', 'website')), 0) as spend_cents, (select max(s.sold_at) from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and te.store_id = v_store and s.voided_at is null and s.channel in ('floor', 'website')) as last_visit from public.customers c where c.store_id = v_store and (v_q is null or (regexp_replace(v_q, '\D', '', 'g') <> '' and c.phone like '%' || regexp_replace(v_q, '\D', '', 'g') || '%') or c.name ilike '%' || v_q || '%' or c.email ilike '%' || v_q || '%') order by last_visit desc nulls last, c.created_at desc limit v_lim) x; return v_rows; end; $$;


ALTER FUNCTION "public"."list_customers"("p_q" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."list_stolen_web_orders"() RETURNS SETOF "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ begin if auth.role() <> 'service_role' then raise exception 'not_service' using errcode = '42501'; end if; return query select * from public.web_orders where status = 'stolen' and payment_id is not null and refund_id is null; end; $$;


ALTER FUNCTION "public"."list_stolen_web_orders"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."listing_check_floor"("p_store" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_service();
  return coalesce((select jsonb_agg(jsonb_build_object('sku', u.sku,
      'title', coalesce(nullif(btrim(u.title),''), concat_ws(' ', u.brand, u.model)),
      'state', u.state,
      'in_view', exists(select 1 from public.storefront_items s where s.store_id = u.store_id and s.sku = u.sku),
      'reason', case
        when exists(select 1 from public.sales s where s.store_id = u.store_id and s.sku = u.sku and s.voided_at is null)
          then 'Has an un-voided sale but the unit is still marked available'
        when exists(select 1 from public.reservations r where r.store_id = u.store_id and r.sku = u.sku
          and r.released_at is null and r.finalized_at is null and r.expires_at > now())
          then 'Held by an active checkout/reservation'
        when u.state = 'reserved' then 'Stuck in reserved state after its hold expired'
        when not exists(select 1 from public.photos p join storage.objects o on o.bucket_id = 'unit-photos' and o.name = p.path
          where p.store_id = u.store_id and p.sku = u.sku) then 'Photo record exists but the photo file is missing'
        when not u.show_on_website and exists(select 1 from public.events e where e.store_id = u.store_id and e.sku = u.sku
          and e.kind = 'edit' and e.field = 'show_on_website' and e.new_value in ('false','0')) then 'List online is turned off for this unit'
        when exists(select 1 from public.listings l where l.store_id = u.store_id and l.sku = u.sku
          and l.channel = 'website' and l.status in ('delisted','pending_delist')) then 'Website listing is marked delisted'
        else null end) order by u.sku)
    from public.units u
    where u.store_id = p_store and coalesce(u.ask_cents,0) > 0
      and (u.state = 'available' or (u.state = 'reserved' and not exists(select 1 from public.reservations r
        where r.store_id = u.store_id and r.sku = u.sku and r.released_at is null and r.finalized_at is null and r.expires_at > now())))
      and exists(select 1 from public.photos p where p.store_id = u.store_id and p.sku = u.sku)), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."listing_check_floor"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."listings_sync_unit_listed_on"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid;
  v_sku text;
  v_channels text[];
begin
  if tg_op = 'DELETE' then
    v_store := old.store_id;
    v_sku := old.sku;
  else
    v_store := new.store_id;
    v_sku := new.sku;
  end if;

  select coalesce(array_agg(distinct l.channel order by l.channel), '{}'::text[])
    into v_channels
  from public.listings l
  where l.store_id = v_store and l.sku = v_sku and l.status = 'listed';

  update public.units u
  set listed_on = (
      select coalesce(array_agg(distinct c order by c), '{}'::text[])
      from (
        select unnest(v_channels) as c
        union
        select c
        from unnest(coalesce(u.listed_on, '{}'::text[])) c
        where not exists (
          select 1 from public.listings l
          where l.store_id = u.store_id and l.sku = u.sku and l.channel = c
        )
      ) x
    ),
    updated_at = now()
  where u.store_id = v_store and u.sku = v_sku;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;


ALTER FUNCTION "public"."listings_sync_unit_listed_on"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."log_sale_price_override"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.override_price_cents is not null and new.list_price_cents is distinct from new.override_price_cents then
    insert into public.events(store_id,sku,kind,field,old_value,new_value,actor,actor_id,note)
    values(new.store_id,new.sku,'edit','sale_price_override',new.list_price_cents::text,
      new.override_price_cents::text,
      coalesce((select display_name from public.staff where store_id=new.store_id and user_id=new.override_by),'staff'),
      new.override_by,coalesce(new.override_reason,'') || ' · ' || new.receipt_no);
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."log_sale_price_override"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."lookup_customer_by_phone"("p_phone" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_store uuid := public.current_store_id(); v_phone text; r public.customers; begin perform public.assert_staff_or_service(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_phone := public.normalize_phone(p_phone); if v_phone is null then raise exception 'invalid_phone' using errcode = '22023'; end if; select * into r from public.customers where store_id = v_store and phone = v_phone; if not found then return null; end if; return public.customer_card(v_store, r); end; $$;


ALTER FUNCTION "public"."lookup_customer_by_phone"("p_phone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."map_return_reason"("p_raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when lower(coalesce(p_raw,'')) ~ 'defect|broken|not.?working|malfunction' then 'defective'
    when lower(coalesce(p_raw,'')) ~ 'not.?as.?descri|misrepresent|condition' then 'not_as_described'
    when lower(coalesce(p_raw,'')) ~ 'wrong.?item|incorrect' then 'wrong_item'
    when lower(coalesce(p_raw,'')) ~ 'damag|transit|shipping|crush' then 'damaged_in_transit'
    when lower(coalesce(p_raw,'')) ~ 'remorse|changed.?mind|no.?longer' then 'buyer_remorse'
    else 'other'
  end;
$$;


ALTER FUNCTION "public"."map_return_reason"("p_raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_alert_sent"("p_id" bigint, "p_error" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'not_service' using errcode = '42501';
  end if;
  update public.alert_outbox
     set sent_at = case when p_error is null then now() else sent_at end,
         error = p_error
   where id = p_id;
end;
$$;


ALTER FUNCTION "public"."mark_alert_sent"("p_id" bigint, "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_listed"("p_sku" "text", "p_channel" "text", "p_listing_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
begin
  perform public.assert_staff_or_service();
  insert into public.listings (store_id, sku, channel, status, listing_id, listed_at)
  values (v_store, p_sku, btrim(p_channel), 'listed', p_listing_id, now())
  on conflict (store_id, sku, channel) do update
    set status = 'listed',
        listing_id = coalesce(excluded.listing_id, public.listings.listing_id),
        listed_at = now(),
        store_id = v_store,
        delisted_at = null;
end;
$$;


ALTER FUNCTION "public"."mark_listed"("p_sku" "text", "p_channel" "text", "p_listing_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_pickup_complete"("p_order" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.pickup_orders_store();
  v_who text := coalesce((select display_name from public.staff where user_id = auth.uid()),
                         (select email from auth.users where id = auth.uid()), 'staff');
  o public.web_orders;
begin
  if v_store is null then raise exception 'not_staff' using errcode = '42501'; end if;
  update public.web_orders set picked_up_at = now(), picked_up_by = v_who, updated_at = now()
   where id = p_order and store_id = v_store and fulfillment = 'pickup' and status = 'paid'
     and picked_up_at is null and refund_requested_at is null
  returning * into o;
  if not found then raise exception 'pickup_not_open' using errcode = 'P0001'; end if;
  insert into public.events (store_id, sku, kind, actor, actor_id, note)
  values (v_store, o.sku, 'picked_up', v_who, auth.uid(), o.order_no);
  return jsonb_build_object('id', o.id, 'order_no', o.order_no, 'picked_up_at', o.picked_up_at, 'picked_up_by', o.picked_up_by);
end $$;


ALTER FUNCTION "public"."mark_pickup_complete"("p_order" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mark_web_order_boxed"("p_id" "uuid") RETURNS "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.web_orders; begin perform public.assert_staff_or_service(); update public.web_orders set boxed_at = coalesce(boxed_at, now()), updated_at = now() where id = p_id and store_id = public.current_store_id() and status = 'paid' and boxed_at is null returning * into v_row; if not found then raise exception 'not_boxable' using errcode = 'P0001'; end if; return v_row; end; $$;


