CREATE OR REPLACE FUNCTION "public"."mark_web_order_shipped"("p_id" "uuid", "p_tracking" "text") RETURNS "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_row public.web_orders; begin perform public.assert_staff_or_service(); if p_tracking is null or btrim(p_tracking) = '' then raise exception 'tracking_required' using errcode = '22023'; end if; update public.web_orders set shipped_at = coalesce(shipped_at, now()), tracking_number = btrim(p_tracking), updated_at = now() where id = p_id and store_id = public.current_store_id() and status = 'paid' and boxed_at is not null returning * into v_row; if not found then raise exception 'not_shippable' using errcode = 'P0001'; end if; insert into public.alert_outbox (store_id, kind, sku, payload) values (v_row.store_id, 'web_shipped', v_row.sku, jsonb_build_object('order_id', v_row.id, 'buyer_email', v_row.buyer_email, 'buyer_name', v_row.buyer_name, 'tracking', v_row.tracking_number)); return v_row; end; $$;


