CREATE OR REPLACE FUNCTION "public"."match_listing_sku_by_photo"("p_store" "uuid", "p_channel" "text", "p_photo_ids" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sku text;
  v_n int;
begin
  if p_store is null or coalesce(cardinality(p_photo_ids), 0) = 0 then
    return null;
  end if;
  select count(distinct l.sku), min(l.sku)
    into v_n, v_sku
  from public.listings l
  join public.units u on u.store_id = l.store_id and u.sku = l.sku
  where l.store_id = p_store
    and l.channel = lower(btrim(p_channel))
    and l.status = 'listed'
    and u.state = 'available'
    and l.photo_ids && p_photo_ids;
  if v_n = 1 then
    return v_sku;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."match_listing_sku_by_photo"("p_store" "uuid", "p_channel" "text", "p_photo_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_vendoo_sold_sku_by_photo"("p_store" "uuid", "p_channel" "text", "p_photo_ids" "text"[]) RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sku text;
  v_n int;
begin
  if p_store is null or coalesce(cardinality(p_photo_ids), 0) = 0 then
    return null;
  end if;
  select count(distinct s.sku), min(s.sku)
    into v_n, v_sku
  from public.vendoo_sold_records s
  join public.units u on u.store_id = s.store_id and u.sku = s.sku
  where s.store_id = p_store
    and s.channel = lower(btrim(p_channel))
    and u.state = 'available'
    and s.photo_ids && p_photo_ids
    and s.sold_at >= now() - interval '14 days';
  if v_n = 1 then
    return v_sku;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "public"."match_vendoo_sold_sku_by_photo"("p_store" "uuid", "p_channel" "text", "p_photo_ids" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."missing_ebay_aspect_names"("p_defs" "jsonb", "p_aspects" "jsonb", "p_specs" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select nullif(string_agg(name, ', ' order by name), '')
  from (
    select distinct btrim(def->>'name') as name
    from jsonb_array_elements(case when jsonb_typeof(p_defs) = 'array' then p_defs else '[]'::jsonb end) def
    where lower(coalesce(def->>'required', '')) in ('true', 't')
      and btrim(coalesce(def->>'name', '')) !~* '^(brand|upc|mpn)$'
      and nullif(btrim(coalesce(
        case when jsonb_typeof(p_aspects->(def->>'name')) = 'array' then p_aspects->(def->>'name')->>0 else p_aspects->>(def->>'name') end,
        case when jsonb_typeof(coalesce(p_specs, '{}'::jsonb)->'ebay_aspects'->(def->>'name')) = 'array'
          then coalesce(p_specs, '{}'::jsonb)->'ebay_aspects'->(def->>'name')->>0
          else coalesce(p_specs, '{}'::jsonb)#>>array['ebay_aspects', def->>'name'] end
      )), '') is null
  ) q
  where name <> '';
$_$;


ALTER FUNCTION "public"."missing_ebay_aspect_names"("p_defs" "jsonb", "p_aspects" "jsonb", "p_specs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."move_unit_photos_to_store_layout"("p_store" "uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'storage'
    AS $$
declare
  n int := 0;
  r record;
  v_new text;
begin
  if auth.role() <> 'service_role' and public.current_store_id() is distinct from p_store then
    raise exception 'not_staff' using errcode = '42501';
  end if;
  for r in
    select p.id, p.sku, p.path
      from public.photos p
     where p.store_id = p_store
       and p.path is not null
       and p.path not like (p_store::text || '/%')
  loop
    if r.path like (r.sku || '/%') then
      v_new := p_store::text || '/' || r.path;
    elsif position('/' in r.path) = 0 then
      v_new := p_store::text || '/' || r.sku || '/' || r.path;
    else
      v_new := p_store::text || '/' || r.sku || '/' || regexp_replace(r.path, '^.*/', '');
    end if;

    update storage.objects
       set name = v_new
     where bucket_id = 'unit-photos'
       and name = r.path;
    if not found then
      if not exists (
        select 1 from storage.objects o
         where o.bucket_id = 'unit-photos' and o.name = v_new
      ) then
        raise exception 'photo_missing: %', r.path using errcode = 'P0001';
      end if;
    end if;

    update public.photos
       set path = v_new
     where id = r.id;

    n := n + 1;
  end loop;
  return n;
end;
$$;


ALTER FUNCTION "public"."move_unit_photos_to_store_layout"("p_store" "uuid") OWNER TO "postgres";


