CREATE OR REPLACE FUNCTION "public"."normalize_unit_condition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.condition is null then
    return new;
  end if;
  new.condition := case lower(btrim(replace(new.condition, '_', ' ')))
    when 'open box' then 'Open box'
    when 'new' then 'New'
    when 'excellent' then 'Excellent'
    when 'good' then 'Good'
    when 'fair' then 'Fair'
    when 'for parts' then 'For parts'
    else new.condition
  end;
  return new;
end $$;


ALTER FUNCTION "public"."normalize_unit_condition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_delist_tasks"("p_sale" "public"."sales") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.delist_tasks (store_id, sku, channel, sale_id, nag_after)
  select p_sale.store_id, p_sale.sku, l.channel, p_sale.id,
         now() + make_interval(
           mins => coalesce(
             (public.store_setting(p_sale.store_id, 'delistNagMinutes', '15'::jsonb) #>> '{}')::int,
             15
           )
         )
    from public.listings l
   where l.store_id is not distinct from p_sale.store_id
     and l.sku = p_sale.sku
     and l.status = 'listed'
     and l.channel is distinct from p_sale.channel;
end;
$$;


