CREATE OR REPLACE FUNCTION "public"."portal_add_cash_movement"("p_kind" "text", "p_amount_cents" integer, "p_moved_on" "date" DEFAULT NULL::"date", "p_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_id uuid;
  v_kind text := lower(btrim(coalesce(p_kind, '')));
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_kind not in ('owner_take', 'owner_put', 'adjustment') then
    raise exception 'kind_invalid' using errcode = '22023';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'amount_required' using errcode = '22023';
  end if;
  insert into public.store_cash_movements (store_id, kind, amount_cents, moved_on, note, created_by)
  values (
    v_store,
    v_kind,
    p_amount_cents,
    coalesce(p_moved_on, (now() at time zone 'America/Los_Angeles')::date),
    coalesce(btrim(p_note), ''),
    auth.uid()
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."portal_add_cash_movement"("p_kind" "text", "p_amount_cents" integer, "p_moved_on" "date", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_add_expense"("p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer, "p_needs_reimbursement" boolean DEFAULT true, "p_employee" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_emp uuid; v_id uuid;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'amount_required' using errcode = '22023'; end if;
  v_emp := coalesce(p_employee, public.portal_owner_employee());
  if coalesce(p_needs_reimbursement, true) and (v_emp is null
     or not exists(select 1 from public.staff s where s.user_id = v_emp and s.store_id = v_store and s.deactivated_at is null)) then
    raise exception 'reimbursement_recipient_required' using errcode = '22023';
  end if;
  insert into public.portal_expenses(store_id, spent_on, description, category, amount_cents, needs_reimbursement, employee_id, created_by)
  values (v_store, coalesce(p_spent_on, (now() at time zone 'America/Los_Angeles')::date), btrim(p_description),
          coalesce(nullif(btrim(p_category),''),'Other'), p_amount_cents, coalesce(p_needs_reimbursement,true),
          case when coalesce(p_needs_reimbursement,true) then v_emp end, auth.uid())
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."portal_add_expense"("p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer, "p_needs_reimbursement" boolean, "p_employee" "uuid") OWNER TO "postgres";


