CREATE OR REPLACE FUNCTION "public"."portal_add_platform_withdrawal"("p_platform" "text", "p_amount_cents" integer, "p_withdrawn_on" "date" DEFAULT NULL::"date", "p_note" "text" DEFAULT ''::"text", "p_reduce_available" boolean DEFAULT true) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_id uuid;
  v_plat text := lower(btrim(coalesce(p_platform, '')));
  v_prev int;
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_plat not in ('square', 'ebay', 'depop', 'amazon', 'tiktok') then
    raise exception 'platform_invalid' using errcode = '22023';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'amount_required' using errcode = '22023';
  end if;
  insert into public.platform_withdrawals (store_id, platform, amount_cents, withdrawn_on, note, created_by)
  values (
    v_store,
    v_plat,
    p_amount_cents,
    coalesce(p_withdrawn_on, (now() at time zone 'America/Los_Angeles')::date),
    coalesce(btrim(p_note), ''),
    auth.uid()
  )
  returning id into v_id;

  if coalesce(p_reduce_available, true) then
    select available_cents into v_prev
    from public.platform_balance_snapshots
    where store_id = v_store and platform = v_plat
    order by created_at desc
    limit 1;
    if v_prev is not null then
      insert into public.platform_balance_snapshots (store_id, platform, available_cents, noted_on, note, created_by)
      values (
        v_store,
        v_plat,
        greatest(0, v_prev - p_amount_cents),
        coalesce(p_withdrawn_on, (now() at time zone 'America/Los_Angeles')::date),
        'auto after withdrawal',
        auth.uid()
      );
    end if;
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "public"."portal_add_platform_withdrawal"("p_platform" "text", "p_amount_cents" integer, "p_withdrawn_on" "date", "p_note" "text", "p_reduce_available" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_add_return_photo"("p_return" "uuid", "p_path" "text", "p_kind" "text" DEFAULT 'inspection'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  r public.returns;
  v_path text := btrim(coalesce(p_path, ''));
  v_kind text := coalesce(nullif(btrim(p_kind), ''), 'inspection');
  v_photo public.return_photos;
  v_sort int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_path = '' then raise exception 'path_required' using errcode = '22023'; end if;
  select * into r from public.returns where id = p_return and store_id = v_store;
  if not found then raise exception 'return_not_found' using errcode = 'P0001'; end if;

  select coalesce(max(sort_order), -1) + 1 into v_sort from public.return_photos where return_id = r.id;
  insert into public.return_photos (store_id, return_id, path, kind, sort_order, created_by)
  values (v_store, r.id, v_path, v_kind, v_sort, auth.uid())
  returning * into v_photo;

  -- Also attach to the unit so catalog/channels see the new condition photos.
  perform public.portal_add_unit_photo(r.sku, v_path);

  return to_jsonb(v_photo);
end $$;


ALTER FUNCTION "public"."portal_add_return_photo"("p_return" "uuid", "p_path" "text", "p_kind" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_add_unit_photo"("p_sku" "text", "p_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_actor text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if not exists(select 1 from public.units where store_id=v_store and sku=p_sku)
     or p_path not like v_store::text || '/' || p_sku || '/%' then
    raise exception 'bad_photo_path' using errcode = '22023';
  end if;
  select coalesce(st.display_name,split_part(au.email,'@',1),'admin') into v_actor
    from auth.users au left join public.staff st on st.user_id=au.id and st.store_id=v_store
    where au.id=auth.uid();
  insert into public.photos(store_id,sku,path,original_path,created_at,is_primary)
    values(v_store,p_sku,p_path,p_path,now(),not exists(select 1 from public.photos
      where store_id=v_store and sku=p_sku));
  insert into public.events(store_id,sku,kind,actor,actor_id)
    values(v_store,p_sku,'photo',v_actor,auth.uid());
end $$;


ALTER FUNCTION "public"."portal_add_unit_photo"("p_sku" "text", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_amazon_list"() RETURNS TABLE("id" "uuid", "sku" "text", "note" "text", "created_at" timestamp with time zone, "title" "text", "condition" "text", "ask_cents" integer, "photo_path" "text", "upc" "text", "flags" "text"[], "status" "text", "asin" "text", "matched_title" "text", "amazon_price_cents" integer, "fee_estimate_cents" integer, "condition_code" "text", "condition_note" "text", "last_error" "text", "listed_at" timestamp with time zone, "retail_cents" integer, "cost_cents" integer, "needs_review_reason" "text", "acquisition_cost_cents" integer, "brand" "text", "model" "text", "state" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if not public.portal_is_admin() then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return query
  select a.id, a.sku, a.note, a.created_at,
    coalesce(nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), nullif(u.title, ''), 'Item')::text,
    u.condition::text, u.ask_cents,
    (select p.path from public.photos p where p.store_id = a.store_id and p.sku = a.sku
      order by p.is_primary desc nulls last, p.sort_order nulls last, p.created_at limit 1) as photo_path,
    u.upc,
    array_remove(array[
      case when not exists (select 1 from public.photos p where p.store_id = a.store_id and p.sku = a.sku) then 'no_photo' end,
      case when nullif(btrim(coalesce(u.upc, '')), '') is null
        and nullif(btrim(coalesce(u.listing_specs->>'asin', '')), '') is null
        and nullif(btrim(coalesce(a.asin, '')), '') is null then 'no_upc_asin' end,
      case when coalesce((u.listing_specs->>'amazon_skip')::boolean, false) then 'skip_list' end,
      case when u.state is distinct from 'available' then 'not_available' end,
      case when a.sku = '11284' then 'never_list' end,
      case when coalesce(u.ask_cents, 0) <= 0 then 'no_price' end
    ], null)::text[] as flags,
    a.status, a.asin, a.matched_title, a.amazon_price_cents, a.fee_estimate_cents,
    a.condition_code, a.condition_note, a.last_error, a.listed_at, a.retail_cents, a.cost_cents,
    a.needs_review_reason, u.acquisition_cost_cents, u.brand::text, u.model::text, u.state::text
  from public.amazon_list_items a
  left join public.units u on u.store_id = a.store_id and u.sku = a.sku
  where a.store_id = v_store and a.status is distinct from 'removed'
  order by a.created_at desc;
end $$;


ALTER FUNCTION "public"."portal_amazon_list"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_amazon_list_add"("p_skus" "text"[], "p_note" "text" DEFAULT ''::"text") RETURNS TABLE("sku" "text", "ok" boolean, "reason" "text", "matched_by" "text", "input" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
#variable_conflict use_column
declare
  v_store uuid := public.portal_store_id();
  v_code text;
  v_note text := coalesce(p_note, '');
  v_norm text;
  v_digits text;
  v_unit public.units%rowtype;
  v_matched text;
  v_found boolean;
begin
  if v_store is null or not public.portal_is_admin() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if p_skus is null or cardinality(p_skus) = 0 then return; end if;
  if cardinality(p_skus) > 500 then raise exception 'too_many_skus' using errcode = '22023'; end if;

  foreach v_code in array p_skus loop
    v_norm := nullif(btrim(v_code), '');
    if v_norm is null then continue; end if;
    v_norm := regexp_replace(v_norm, '[^0-9A-Za-z\-]+', '', 'g');
    if v_norm = '' then continue; end if;
    v_digits := regexp_replace(v_norm, '[^0-9]', '', 'g');
    v_matched := null;
    v_found := false;

    -- 1) Exact Floor SKU
    select * into v_unit
    from public.units u
    where u.store_id = v_store and u.sku = v_norm;
    if found then
      v_found := true;
      v_matched := 'sku';
    end if;

    -- 2) UPC / GTIN → prefer oldest available; else any match (may be sold)
    if not v_found and length(v_digits) between 8 and 14 then
      select * into v_unit
      from public.units u
      where u.store_id = v_store
        and u.state = 'available'
        and (
          regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g') = v_digits
          or right(regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g'), 12)
               = right(v_digits, 12)
          or nullif(ltrim(regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g'), '0'), '')
               = nullif(ltrim(v_digits, '0'), '')
        )
      order by u.received_at asc nulls last, u.sku asc
      limit 1;
      if found then
        v_found := true;
        v_matched := 'upc';
      else
        select * into v_unit
        from public.units u
        where u.store_id = v_store
          and (
            regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g') = v_digits
            or right(regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g'), 12)
                 = right(v_digits, 12)
            or nullif(ltrim(regexp_replace(coalesce(u.upc, ''), '[^0-9]', '', 'g'), '0'), '')
                 = nullif(ltrim(v_digits, '0'), '')
          )
        order by u.received_at desc nulls last, u.sku asc
        limit 1;
        if found then
          v_found := true;
          v_matched := 'upc';
        end if;
      end if;
    end if;

    if not v_found then
      sku := v_norm; ok := false;
      reason := case when length(v_digits) between 8 and 14 then 'unknown_upc' else 'unknown_sku' end;
      matched_by := null; input := v_norm; return next; continue;
    end if;

    -- Only skip sold / not available
    if v_unit.state is distinct from 'available' then
      sku := v_unit.sku; ok := false; reason := 'already_sold';
      matched_by := v_matched; input := v_norm; return next; continue;
    end if;

    insert into public.amazon_list_items (store_id, sku, note, status, created_by, updated_at)
    values (v_store, v_unit.sku, v_note, 'queued', auth.uid(), now())
    on conflict on constraint amazon_list_items_store_id_sku_key do update
      set note = case when excluded.note <> '' then excluded.note else public.amazon_list_items.note end,
          status = case when public.amazon_list_items.status = 'removed' then 'queued' else public.amazon_list_items.status end,
          updated_at = now();

    sku := v_unit.sku;
    ok := true;
    reason := case when v_matched = 'upc' then 'added_via_upc' else 'added' end;
    matched_by := v_matched;
    input := v_norm;
    return next;
  end loop;
end
$$;


