ALTER FUNCTION "public"."portal_amazon_list_set_note"("p_sku" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_amazon_set_upc"("p_sku" "text", "p_upc" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_sku text := nullif(btrim(coalesce(p_sku, '')), '');
  v_upc text := nullif(regexp_replace(coalesce(p_upc, ''), '[^0-9]', '', 'g'), '');
  v_old text;
begin
  if v_store is null or not public.portal_is_admin() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_sku is null then
    raise exception 'sku_required' using errcode = '22023';
  end if;
  if v_upc is null then
    raise exception 'upc_required' using errcode = '22023';
  end if;
  if not public.valid_gtin(v_upc) then
    raise exception 'invalid_upc' using errcode = '22023';
  end if;

  select upc into v_old
  from public.units
  where store_id = v_store and sku = v_sku
  for update;
  if not found then
    raise exception 'unit_not_found' using errcode = 'P0001';
  end if;

  update public.units
     set upc = v_upc,
         upc_rejected = null,
         updated_at = now()
   where store_id = v_store and sku = v_sku;

  update public.amazon_list_items
     set last_error = null,
         updated_at = now()
   where store_id = v_store and sku = v_sku and status is distinct from 'removed';

  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (
    v_store, v_sku, 'edit', 'upc', left(v_old, 200), left(v_upc, 200),
    coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid()
  );
end
$$;


ALTER FUNCTION "public"."portal_amazon_set_upc"("p_sku" "text", "p_upc" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_approve_match"("p_suggestion" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id(); v_sku text;
begin
  if v_store is null then raise exception 'Admin access required'; end if;
  select s.sku into v_sku from public.photo_enrichment_suggestions s
    join public.photo_enrichment_assets a on a.id=s.asset_id and a.store_id=s.store_id
    where s.id=p_suggestion and s.store_id=v_store and s.status='review'
      and a.status='published' and jsonb_array_length(a.public_paths)>0;
  if v_sku is null then raise exception 'Match is not ready to publish'; end if;
  update public.photo_enrichment_suggestions set status='rejected',decided_at=now(),decided_by=auth.uid()
    where store_id=v_store and sku=v_sku and status='review' and id<>p_suggestion;
  update public.photo_enrichment_suggestions set status='approved',decided_at=now(),decided_by=auth.uid()
    where id=p_suggestion and store_id=v_store;
  update public.photo_enrichment_queue set status='matched',checked_at=now(),error=null
    where store_id=v_store and sku=v_sku;
end $$;


ALTER FUNCTION "public"."portal_approve_match"("p_suggestion" "uuid") OWNER TO "postgres";


