CREATE OR REPLACE FUNCTION "public"."portal_bulk_set_unit_text"("p_skus" "text"[], "p_field" "text", "p_value" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_sku text; v_updated int := 0;
begin
  if public.portal_store_id() is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_skus is null or cardinality(p_skus) > 200 then raise exception 'bulk_limit' using errcode = '22023'; end if;
  foreach v_sku in array p_skus loop
    if nullif(btrim(coalesce(v_sku, '')), '') is null then continue; end if;
    perform public.portal_set_unit_text(v_sku, p_field, p_value);
    v_updated := v_updated + 1;
  end loop;
  return jsonb_build_object('updated', v_updated);
end $$;


ALTER FUNCTION "public"."portal_bulk_set_unit_text"("p_skus" "text"[], "p_field" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_bundle_for_sku"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.current_store_id(); v_bundle text; v_parts jsonb;
begin
  if v_store is null or not public.is_store_staff(v_store) then
    raise exception 'portal_access_denied' using errcode='42501';
  end if;
  select b.sku into v_bundle from public.floor_bundles b
    where b.store_id=v_store and b.active and (b.sku=p_sku or exists
      (select 1 from public.floor_bundle_components c where c.store_id=b.store_id
       and c.bundle_sku=b.sku and c.component_sku=p_sku)) limit 1;
  if v_bundle is null then return null; end if;
  select coalesce(jsonb_agg(jsonb_build_object('sku',c.component_sku,'title',u.title,
      'quantity',c.quantity,'isMain',c.is_main) order by c.is_main desc,c.component_sku),'[]'::jsonb)
    into v_parts from public.floor_bundle_components c
    join public.units u on u.store_id=c.store_id and u.sku=c.component_sku
    where c.store_id=v_store and c.bundle_sku=v_bundle;
  return jsonb_build_object('sku',v_bundle,'components',v_parts);
end $$;


ALTER FUNCTION "public"."portal_bundle_for_sku"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_cash_movements"("p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(row_to_json(r)::jsonb order by r.moved_on desc, r.created_at desc)
    from (
      select id, kind, amount_cents, moved_on, note, created_at, voided_at
      from public.store_cash_movements
      where store_id = v_store
      order by moved_on desc, created_at desc
      limit greatest(1, least(coalesce(p_limit, 100), 500))
    ) r
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."portal_cash_movements"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_category_attributes"("p_skus" "text"[], "p_channel" "text", "p_attributes" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id()); v_count int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  if cardinality(p_skus) not between 1 and 100 or p_channel not in ('ebay','amazon','tiktok','depop')
    or jsonb_typeof(p_attributes)<>'object' then raise exception 'invalid_category_attributes' using errcode='22023'; end if;
  if (select count(*) from public.units where store_id=v_store and sku=any(p_skus))<>cardinality(p_skus) then
    raise exception 'unit_not_found' using errcode='22023'; end if;
  update public.unit_channel_categories c set attributes=p_attributes,review_reason=null,
    validated_version=case when p_channel='depop' then null else
      (select coalesce(t.fingerprint,'')||':'||coalesce(t.fields_version,'')
        from public.channel_taxonomy t where t.channel=p_channel and t.category_id=c.category_id) end,
    updated_at=now()
    where c.store_id=v_store and c.sku=any(p_skus) and c.channel=p_channel;
  get diagnostics v_count=row_count;
  return v_count;
end $$;


ALTER FUNCTION "public"."portal_category_attributes"("p_skus" "text"[], "p_channel" "text", "p_attributes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_category_gaps"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id());
begin
  if v_store is null or not exists(select 1 from public.units where store_id=v_store and sku=p_sku) then
    raise exception 'unit_not_found_or_access_denied' using errcode='42501'; end if;
  return public.floor_category_gaps(v_store,p_sku);
end $$;


ALTER FUNCTION "public"."portal_category_gaps"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_category_queue"("p_limit" integer DEFAULT 50, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id());
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.received_at desc) from (
    select u.sku,u.title,u.upc,u.internal_category,u.received_at,g.gaps,
      (select jsonb_object_agg(c.channel,jsonb_build_object('category_id',c.category_id,
        'enabled',c.enabled,'attributes',c.attributes))
        from public.unit_channel_categories c where c.store_id=u.store_id and c.sku=u.sku) channels,
      exists(select 1 from public.listings l where l.store_id=u.store_id
        and l.sku=u.sku and l.status='listed') live
    from (
      select i.sku, jsonb_agg(jsonb_build_object('channel',i.channel,'issue',i.issue,'field',i.field)
        order by i.channel,i.field) gaps
      from public.floor_category_issue_rows(v_store) i group by i.sku
    ) g
    join public.units u on u.store_id=v_store and u.sku=g.sku
    where u.state in ('available','reserved','repair')
    order by u.received_at desc limit greatest(1,least(coalesce(p_limit,50),100))
      offset greatest(0,coalesce(p_offset,0))
  ) x),'[]'::jsonb);
end $$;


