CREATE OR REPLACE FUNCTION "public"."portal_connection_status"() RETURNS TABLE("provider" "text", "status" "text", "account_label" "text", "last_error" "text", "connected_at" timestamp with time zone, "updated_at" timestamp with time zone, "scopes" "text"[], "has_finances" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_is_admin() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  return query
    select
      c.provider,
      c.status,
      c.account_label,
      c.last_error,
      c.connected_at,
      c.updated_at,
      c.scopes,
      (
        c.provider = 'ebay'
        and c.scopes is not null
        and exists (
          select 1
          from unnest(c.scopes) s(scope)
          where s.scope like '%sell.finances%'
        )
      ) as has_finances
    from public.connections c
    where c.store_id = v_store
      and c.provider in ('ebay', 'amazon', 'square')
    order by c.provider;
end;
$$;


