CREATE OR REPLACE FUNCTION "public"."portal_depop_category_save"("p_id" "text", "p_path" "text", "p_required" "jsonb" DEFAULT '[]'::"jsonb", "p_active" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id());
begin
  if v_store is null or not public.is_staff() then raise exception 'portal_access_denied' using errcode='42501'; end if;
  if nullif(btrim(p_id),'') is null or nullif(btrim(p_path),'') is null
    or jsonb_typeof(p_required)<>'array' then raise exception 'invalid_category' using errcode='22023'; end if;
  insert into public.store_depop_categories(store_id,category_id,path,required_fields,active)
  values(v_store,btrim(p_id),btrim(p_path),p_required,p_active)
  on conflict(store_id,category_id) do update set path=excluded.path,required_fields=excluded.required_fields,
    active=excluded.active,updated_at=now();
end $$;


ALTER FUNCTION "public"."portal_depop_category_save"("p_id" "text", "p_path" "text", "p_required" "jsonb", "p_active" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_disconnect_provider"("p_provider" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_is_admin() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if p_provider is null or p_provider not in ('ebay', 'amazon', 'square') then
    raise exception 'unknown_provider' using errcode = '22023';
  end if;

  update public.connections
     set status = 'disconnected',
         token_ciphertext = null,
         refresh_ciphertext = null,
         last_error = null,
         updated_at = now()
   where store_id = v_store
     and provider = p_provider;
end;
$$;


ALTER FUNCTION "public"."portal_disconnect_provider"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_disposition_return"("p_return" "uuid", "p_disposition" "text", "p_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  r public.returns;
  v_disp text := lower(btrim(coalesce(p_disposition, '')));
  v_settings jsonb;
  v_ch text;
  v_photos int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_disp not in ('relist', 'downgrade_channel', 'bundle_lot', 'write_off') then
    raise exception 'invalid_disposition' using errcode = '22023';
  end if;

  select * into r from public.returns where id = p_return and store_id = v_store for update;
  if not found then raise exception 'return_not_found' using errcode = 'P0001'; end if;
  if r.status not in ('inspected', 'received', 'dispositioned') then
    raise exception 'inspect_before_disposition' using errcode = 'P0001';
  end if;

  select count(*)::int into v_photos from public.return_photos where return_id = r.id;
  if v_photos < 1 then
    raise exception 'inspection_photos_required' using errcode = 'P0001';
  end if;

  v_settings := public.return_settings(v_store);

  update public.returns set
    refund_cents = coalesce((p_patch->>'refund_cents')::int, refund_cents),
    return_label_cents = coalesce((p_patch->>'return_label_cents')::int, return_label_cents),
    unrecovered_fees_cents = coalesce((p_patch->>'unrecovered_fees_cents')::int, unrecovered_fees_cents),
    regrade_loss_cents = coalesce((p_patch->>'regrade_loss_cents')::int, regrade_loss_cents),
    label_paid_by = coalesce(nullif(p_patch->>'label_paid_by',''), label_paid_by),
    updated_at = now()
  where id = r.id
  returning * into r;

  perform public.return_apply_commission_clawbacks(r.id);

  if r.sale_id is not null then
    perform public.return_reverse_sale(
      v_store, r.sale_id,
      'Return disposition: ' || v_disp,
      v_disp <> 'write_off' or coalesce((p_patch->>'restock')::boolean, false)
    );
  else
    if v_disp in ('relist', 'downgrade_channel', 'bundle_lot') then
      update public.units set state = 'available', updated_at = now()
       where store_id = v_store and sku = r.sku and state in ('sold', 'reserved');
      update public.sku_ledger set fate = 'issued'
       where store_id = v_store and sku = r.sku;
    elsif v_disp = 'write_off' then
      update public.units set state = 'scrapped', updated_at = now()
       where store_id = v_store and sku = r.sku;
      update public.sku_ledger set fate = 'retired'
       where store_id = v_store and sku = r.sku;
    end if;
  end if;

  if v_disp = 'downgrade_channel' then
    for v_ch in
      select lower(btrim(x)) from jsonb_array_elements_text(
        coalesce(v_settings->'downgrade_block_channels', '["amazon","tiktok"]'::jsonb)
      ) x
    loop
      insert into public.unit_marketplace_overrides(store_id, sku, channel, decision, note, actor_id, actor_name)
      values (
        v_store, r.sku, v_ch, 'block',
        'Return downgrade — pulled from forced-return channels',
        auth.uid(),
        coalesce((select display_name from public.staff where user_id = auth.uid()), 'portal')
      )
      on conflict (store_id, sku, channel) do update set
        decision = 'block', note = excluded.note, updated_at = now(),
        actor_id = excluded.actor_id, actor_name = excluded.actor_name;
    end loop;
  end if;

  if v_disp = 'bundle_lot' then
    update public.units set
      listing_body = trim(both from coalesce(listing_body, '') || E'\n[RETURN → bundle lot]'),
      updated_at = now()
     where store_id = v_store and sku = r.sku;
    insert into public.unit_marketplace_overrides(store_id, sku, channel, decision, note, actor_id, actor_name)
    select v_store, r.sku, c, 'block', 'Return → bundle lot only', auth.uid(), 'portal'
      from unnest(array['amazon','tiktok']) c
    on conflict (store_id, sku, channel) do update set
      decision = 'block', note = excluded.note, updated_at = now();
  end if;

  if v_disp = 'write_off' then
    insert into public.unit_marketplace_overrides(store_id, sku, channel, decision, note, actor_id, actor_name)
    select v_store, r.sku, c, 'block', 'Return write-off', auth.uid(), 'portal'
      from unnest(array['ebay','depop','amazon','tiktok','website']) c
    on conflict (store_id, sku, channel) do update set
      decision = 'block', note = excluded.note, updated_at = now();
  end if;

  if v_disp = 'relist' and coalesce((p_patch->>'clear_channel_blocks')::boolean, false) then
    delete from public.unit_marketplace_overrides
     where store_id = v_store and sku = r.sku
       and channel in ('amazon', 'tiktok')
       and note like 'Return%';
  end if;

  update public.returns set
    status = 'dispositioned',
    disposition = v_disp,
    dispositioned_at = coalesce(dispositioned_at, now()),
    refunded_at = coalesce(refunded_at, case when coalesce((p_patch->>'mark_refunded')::boolean, true) then now() else null end),
    updated_at = now()
  where id = r.id
  returning * into r;

  perform public.return_post_ledger(r.id);

  if coalesce((p_patch->>'close')::boolean, true) then
    update public.returns set status = 'closed', closed_at = coalesce(closed_at, now()), closed_by = auth.uid(), updated_at = now()
     where id = r.id returning * into r;
  end if;

  if exists (select 1 from public.sku_ledger where store_id = v_store and sku = r.sku) then
    insert into public.events (store_id, sku, kind, actor, note)
    values (v_store, r.sku, 'return_dispositioned',
            coalesce((select display_name from public.staff where user_id = auth.uid()), 'portal'),
            v_disp);
  end if;

  return to_jsonb(r);
end $$;


ALTER FUNCTION "public"."portal_disposition_return"("p_return" "uuid", "p_disposition" "text", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_eligibility_review_queue"() RETURNS TABLE("id" bigint, "sku" "text", "channel" "text", "reason" "text", "status" "text", "created_at" timestamp with time zone, "title" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return query
  select r.id, r.sku, r.channel, r.reason, r.status, r.created_at, u.title
  from public.marketplace_eligibility_review r
  left join public.units u on u.store_id = r.store_id and u.sku = r.sku
  where r.store_id = v_store and r.status = 'pending'
  order by r.created_at desc
  limit 300;
end $$;


ALTER FUNCTION "public"."portal_eligibility_review_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_enrich_received_unit"("p_sku" "text", "p_specs" "jsonb" DEFAULT NULL::"jsonb", "p_msrp_cents" integer DEFAULT NULL::integer, "p_show" boolean DEFAULT NULL::boolean, "p_brand" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_unit public.units;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_specs is not null and jsonb_typeof(p_specs) <> 'object' then
    raise exception 'specs_must_be_object' using errcode = '22023';
  end if;
  if p_msrp_cents is not null and p_msrp_cents < 0 then
    raise exception 'msrp_must_be_non_negative' using errcode = '22023';
  end if;

  select * into v_unit from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;

  update public.units set
    listing_specs = case
      when p_specs is null then listing_specs
      else coalesce(listing_specs, '{}'::jsonb) || jsonb_strip_nulls(p_specs)
    end,
    msrp_cents = coalesce(msrp_cents, p_msrp_cents),
    brand = case when nullif(btrim(coalesce(brand, '')), '') is null then coalesce(nullif(btrim(coalesce(p_brand, '')), ''), brand) else brand end,
    model = case when nullif(btrim(coalesce(model, '')), '') is null then coalesce(nullif(btrim(coalesce(p_model, '')), ''), model) else model end,
    title = case when nullif(btrim(coalesce(title, '')), '') is null then coalesce(nullif(btrim(coalesce(p_title, '')), ''), title) else title end,
    listing_body = case when nullif(btrim(coalesce(listing_body, '')), '') is null then coalesce(nullif(btrim(coalesce(p_description, '')), ''), listing_body) else listing_body end,
    show_on_website = coalesce(p_show, show_on_website),
    updated_at = now()
  where store_id = v_store and sku = p_sku
  returning * into v_unit;

  return jsonb_build_object(
    'sku', v_unit.sku,
    'show_on_website', v_unit.show_on_website,
    'listing_specs', v_unit.listing_specs
  );
end $$;


ALTER FUNCTION "public"."portal_enrich_received_unit"("p_sku" "text", "p_specs" "jsonb", "p_msrp_cents" integer, "p_show" boolean, "p_brand" "text", "p_model" "text", "p_title" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_financial_access"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.is_manager()
      or exists (
        select 1
        from public.portal_admins a
        where a.user_id = auth.uid()
      );
$$;


ALTER FUNCTION "public"."portal_financial_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_find_sale_costs"("p_query" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_q text := lower(btrim(coalesce(p_query, '')));
  v_row record;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_q = '' then raise exception 'query_required'; end if;

  select
    l.id, l.sku, l.channel,
    coalesce(nullif(trim(concat_ws(' ', l.brand, l.model)), ''), l.sku) as title,
    l.price_cents, l.channel_fee_cents, l.fee_source,
    l.ship_cost_cents, l.ship_cost_source,
    l.processing_fee_cents, l.processing_fee_source,
    l.profit_cents, l.web_order_no, l.payment_id, l.sold_at
  into v_row
  from public.sale_ledger l
  where l.store_id = v_store
    and l.voided_at is null
    and (
      lower(l.sku) = v_q
      or lower(coalesce(l.web_order_no, '')) = v_q
      or lower(coalesce(l.payment_id, '')) = v_q
      or lower(coalesce(l.payment_id, '')) like '%:' || v_q
      or lower(coalesce(split_part(l.payment_id, ':', 2), '')) = v_q
    )
  order by l.sold_at desc
  limit 1;

  if not found then
    return jsonb_build_object('found', false);
  end if;

  return jsonb_build_object(
    'found', true,
    'sale_id', v_row.id,
    'sku', v_row.sku,
    'channel', v_row.channel,
    'title', v_row.title,
    'price_cents', v_row.price_cents,
    'channel_fee_cents', v_row.channel_fee_cents,
    'fee_source', v_row.fee_source,
    'ship_cost_cents', v_row.ship_cost_cents,
    'ship_cost_source', v_row.ship_cost_source,
    'processing_fee_cents', v_row.processing_fee_cents,
    'processing_fee_source', v_row.processing_fee_source,
    'profit_cents', v_row.profit_cents,
    'order_no', v_row.web_order_no,
    'payment_id', v_row.payment_id,
    'sold_at', v_row.sold_at
  );
end $$;


ALTER FUNCTION "public"."portal_find_sale_costs"("p_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_floor_cancel_order"("p_order" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  o public.web_orders;
  v_reason text;
  v_now timestamptz := now();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_reason := nullif(btrim(coalesce(p_reason, '')), '');
  if v_reason is null then
    v_reason := 'Canceled in Floor (marketplace / Square not canceled)';
  end if;

  select * into o from public.web_orders where id = p_order and store_id = v_store for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0001'; end if;
  if o.status in ('canceled', 'refunded') then return; end if;
  if o.status <> 'paid' then raise exception 'order_not_cancelable' using errcode = 'P0001'; end if;

  -- Floor-local only: reverse the Floor sale and put the unit back. No marketplace API, no Square refund.
  if o.sale_id is not null then
    update public.sales
      set voided_at = coalesce(voided_at, v_now),
          void_reason = coalesce(nullif(btrim(coalesce(void_reason, '')), ''), v_reason)
    where id = o.sale_id and store_id = v_store and voided_at is null;

    update public.units
      set state = 'available', updated_at = v_now
    where store_id = v_store and sku = o.sku;

    update public.sku_ledger
      set fate = 'issued'
    where store_id = v_store and sku = o.sku;
  end if;

  update public.portal_expenses
    set voided_at = coalesce(voided_at, v_now),
        void_reason = coalesce(nullif(btrim(coalesce(void_reason, '')), ''), v_reason)
  where store_id = v_store and order_id = o.id and voided_at is null;

  update public.web_orders
  set status = 'canceled',
      canceled_at = coalesce(canceled_at, v_now),
      cancel_source = 'floor_app',
      cancel_reason = v_reason,
      updated_at = v_now
  where id = o.id and store_id = v_store;

  insert into public.events (store_id, sku, kind, field, new_value, actor, note)
  values (
    v_store,
    o.sku,
    'edit',
    'web_order_floor_cancel',
    jsonb_build_object('order_no', o.order_no, 'channel', o.channel, 'source', 'floor_app')::text,
    'portal',
    v_reason
  );
end $$;


ALTER FUNCTION "public"."portal_floor_cancel_order"("p_order" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_floor_product_upsert"("p_product" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid;
  v_gtin text := nullif(btrim(coalesce(p_product->>'gtin14', '')), '');
  v_row public.floor_products;
begin
  select store_id into v_store from public.staff
  where user_id = auth.uid() and deactivated_at is null limit 1;
  if v_store is null then
    raise exception 'not_authorized';
  end if;
  if v_gtin is null or v_gtin !~ '^[0-9]{14}$' then
    raise exception 'gtin14_required';
  end if;
  insert into public.floor_products as fp (
    gtin14, upc_a, ean13, brand, model, title, category, description,
    aspects, features,
    package_length_in, package_width_in, package_height_in, package_weight_lb,
    dim_sources, asin, images, photo_path, source, updated_at, updated_by
  ) values (
    v_gtin,
    nullif(btrim(coalesce(p_product->>'upc_a', '')), ''),
    nullif(btrim(coalesce(p_product->>'ean13', '')), ''),
    nullif(btrim(coalesce(p_product->>'brand', '')), ''),
    nullif(btrim(coalesce(p_product->>'model', '')), ''),
    nullif(btrim(coalesce(p_product->>'title', '')), ''),
    nullif(btrim(coalesce(p_product->>'category', '')), ''),
    nullif(btrim(coalesce(p_product->>'description', '')), ''),
    coalesce(p_product->'aspects', '{}'::jsonb),
    coalesce(p_product->'features', '[]'::jsonb),
    nullif(p_product->>'package_length_in', '')::numeric,
    nullif(p_product->>'package_width_in', '')::numeric,
    nullif(p_product->>'package_height_in', '')::numeric,
    nullif(p_product->>'package_weight_lb', '')::numeric,
    coalesce(p_product->'dim_sources', '{}'::jsonb),
    nullif(btrim(coalesce(p_product->>'asin', '')), ''),
    coalesce(p_product->'images', '[]'::jsonb),
    nullif(btrim(coalesce(p_product->>'photo_path', '')), ''),
    coalesce(nullif(btrim(coalesce(p_product->>'source', '')), ''), 'manual'),
    now(),
    auth.uid()
  )
  on conflict (gtin14) do update set
    upc_a = coalesce(excluded.upc_a, fp.upc_a),
    ean13 = coalesce(excluded.ean13, fp.ean13),
    brand = coalesce(excluded.brand, fp.brand),
    model = coalesce(excluded.model, fp.model),
    title = coalesce(excluded.title, fp.title),
    category = coalesce(excluded.category, fp.category),
    description = coalesce(excluded.description, fp.description),
    aspects = case when excluded.aspects = '{}'::jsonb then fp.aspects else excluded.aspects end,
    features = case when excluded.features = '[]'::jsonb then fp.features else excluded.features end,
    package_length_in = coalesce(excluded.package_length_in, fp.package_length_in),
    package_width_in = coalesce(excluded.package_width_in, fp.package_width_in),
    package_height_in = coalesce(excluded.package_height_in, fp.package_height_in),
    package_weight_lb = coalesce(excluded.package_weight_lb, fp.package_weight_lb),
    dim_sources = fp.dim_sources || coalesce(excluded.dim_sources, '{}'::jsonb),
    asin = coalesce(excluded.asin, fp.asin),
    images = case when excluded.images = '[]'::jsonb then fp.images else excluded.images end,
    photo_path = coalesce(excluded.photo_path, fp.photo_path),
    source = coalesce(excluded.source, fp.source),
    updated_at = now(),
    updated_by = auth.uid()
  returning * into v_row;
  return to_jsonb(v_row);
end;
$_$;


ALTER FUNCTION "public"."portal_floor_product_upsert"("p_product" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_floor_products_search"("p_q" "text" DEFAULT ''::"text", "p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid;
  v_q text := lower(btrim(coalesce(p_q, '')));
  v_lim int := greatest(1, least(coalesce(p_limit, 50), 100));
begin
  select store_id into v_store from public.staff
  where user_id = auth.uid() and deactivated_at is null limit 1;
  if v_store is null then
    raise exception 'not_authorized';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(r) order by r.updated_at desc)
    from (
      select gtin14, upc_a, ean13, brand, model, title, category, description,
             package_length_in, package_width_in, package_height_in, package_weight_lb,
             dim_sources, asin, source, updated_at
      from public.floor_products
      where v_q = ''
         or gtin14 like '%' || regexp_replace(v_q, '\D', '', 'g') || '%'
         or lower(coalesce(brand, '')) like '%' || v_q || '%'
         or lower(coalesce(model, '')) like '%' || v_q || '%'
         or lower(coalesce(title, '')) like '%' || v_q || '%'
      order by updated_at desc
      limit v_lim
    ) r
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."portal_floor_products_search"("p_q" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_identical_category_skus"("p_sku" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id()); v_upc text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  select nullif(btrim(upc),'') into v_upc from public.units where store_id=v_store and sku=p_sku;
  if v_upc is null then return array[p_sku]; end if;
  return coalesce((select array_agg(sku order by sku) from (
    select u.sku from public.units u where u.store_id=v_store and u.upc=v_upc
      and u.state in ('available','reserved','repair')
      and not exists(select 1 from public.listings l where l.store_id=v_store and l.sku=u.sku and l.status='listed')
      and not exists(select 1 from public.amazon_list_items a where a.store_id=v_store and a.sku=u.sku and a.status='live')
      and not exists(select 1 from public.tiktok_list_items t where t.store_id=v_store and t.sku=u.sku and t.status='live')
      order by u.sku limit 100
  ) x),array[p_sku]);
end $$;


