CREATE OR REPLACE FUNCTION "public"."portal_insights"("p_period" "text" DEFAULT 'month'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_period not in ('week','month','quarter') then
    raise exception 'period_invalid' using errcode = '22023'; end if;
  return jsonb_build_object(
    'first_sale_on',(select min((sold_at at time zone 'America/Los_Angeles')::date)
      from public.sales where store_id=v_store and voided_at is null),
    'periods',coalesce((select jsonb_agg(to_jsonb(t) order by t.period_start,t.channel)
      from (
        select date_trunc(p_period,l.sold_at at time zone 'America/Los_Angeles')::date period_start,
          lower(l.channel) channel,
          coalesce(sum(l.price_cents+coalesce(l.shipping_cents,0)),0)::bigint sales_cents,
          coalesce(sum(l.profit_cents),0)::bigint profit_cents,
          count(*)::int units_sold
        from public.sale_ledger l
        where l.store_id=v_store and l.voided_at is null
          and l.sold_at>=now()-interval '2 years'
        group by 1,2
      ) t),'[]'::jsonb),
    'categories',coalesce((select jsonb_agg(to_jsonb(c) order by c.sold_units desc,c.category)
      from (
        select coalesce(nullif(btrim(u.internal_category),''),'Uncategorized') category,
          count(*)::int received_units,
          coalesce(sum(u.qty_on_hand),0)::int stock_units,
          coalesce(sum(s.qty),0)::int sold_units,
          coalesce(sum(s.sales_cents),0)::bigint revenue_cents,
          coalesce(sum(s.profit_cents),0)::bigint profit_cents,
          round(avg(s.days_to_sell)::numeric,1) avg_days_to_sell
        from public.units u
        left join lateral (
          select sum(l.qty)::int qty,
            sum(l.price_cents+coalesce(l.shipping_cents,0))::bigint sales_cents,
            sum(l.profit_cents)::bigint profit_cents,
            avg(extract(epoch from (l.sold_at-u.received_at))/86400) days_to_sell
          from public.sale_ledger l where l.store_id=u.store_id and l.sku=u.sku
            and l.voided_at is null
        ) s on true
        where u.store_id=v_store and u.state<>'voided'
        group by 1
      ) c),'[]'::jsonb),
    'aging',coalesce((select jsonb_build_object(
      'days_30',count(*) filter(where now()-u.received_at>=interval '30 days'
        and now()-u.received_at<interval '60 days'),
      'days_60',count(*) filter(where now()-u.received_at>=interval '60 days'
        and now()-u.received_at<interval '90 days'),
      'days_90_plus',count(*) filter(where now()-u.received_at>=interval '90 days')
    ) from public.units u where u.store_id=v_store
      and u.state in ('available','reserved','repair') and u.qty_on_hand>0),'{}'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."portal_insights"("p_period" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inspect_return"("p_return" "uuid", "p_condition" "text", "p_notes" "text" DEFAULT NULL::"text", "p_regrade_loss_cents" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  r public.returns;
  v_cond text := btrim(coalesce(p_condition, ''));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_cond = '' then raise exception 'condition_required' using errcode = '22023'; end if;
  select * into r from public.returns where id = p_return and store_id = v_store for update;
  if not found then raise exception 'return_not_found' using errcode = 'P0001'; end if;
  if r.status not in ('received', 'inspected', 'in_transit', 'approved') then
    raise exception 'return_not_inspectable' using errcode = 'P0001';
  end if;

  update public.units set condition = v_cond, updated_at = now()
   where store_id = v_store and sku = r.sku;

  update public.returns set
    status = 'inspected',
    condition_after = v_cond,
    inspection_notes = coalesce(nullif(btrim(p_notes), ''), inspection_notes),
    regrade_loss_cents = greatest(0, coalesce(p_regrade_loss_cents, regrade_loss_cents, 0)),
    inspected_at = coalesce(inspected_at, now()),
    received_at = coalesce(received_at, now()),
    updated_at = now()
  where id = r.id
  returning * into r;

  return to_jsonb(r);
end $$;


ALTER FUNCTION "public"."portal_inspect_return"("p_return" "uuid", "p_condition" "text", "p_notes" "text", "p_regrade_loss_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_counts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  v_all int;
  v_unfinished int;
  v_available int;
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  select count(*)::int,
    count(*) filter (where not public.unit_not_for_sale(u.listing_specs)
      and public.unit_is_unfinished(public.unit_listing_gaps(u)))::int,
    count(*) filter (where u.state = 'available')::int
  into v_all, v_unfinished, v_available
  from public.units u
  where u.store_id = sid and u.state in ('available','reserved','repair');
  return jsonb_build_object('live', v_all, 'unfinished', v_unfinished, 'available', v_available);
end $$;


ALTER FUNCTION "public"."portal_inventory_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_detail"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_admin boolean := public.portal_is_admin();
  v_result jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  select jsonb_build_object(
    'unit', case when v_admin or u.state in ('available','reserved','repair') then to_jsonb(u)
      else (select jsonb_object_agg(e.key, e.value) from jsonb_each(to_jsonb(u)) e
        where e.key !~ '(_cents$|price|cost)' and e.key <> 'listing_specs') end,
    'photos', coalesce((select jsonb_agg(to_jsonb(p) order by p.is_primary desc,p.id)
      from public.photos p where p.store_id=u.store_id and p.sku=u.sku),'[]'::jsonb),
    'listings', coalesce((select jsonb_agg(case when v_admin or u.state in ('available','reserved','repair')
        then to_jsonb(l) else (select jsonb_object_agg(e.key, e.value) from jsonb_each(to_jsonb(l)) e
          where e.key !~ '_cents$') end order by l.channel)
      from public.listings l where l.store_id=u.store_id and l.sku=u.sku),'[]'::jsonb),
    'sales', coalesce((select jsonb_agg(case when v_admin
        then to_jsonb(s) || jsonb_build_object('actor_name',coalesce(st.display_name,'Unknown'))
        else jsonb_build_object('sold_at', s.sold_at, 'receipt_no', s.receipt_no, 'channel', s.channel,
          'actor_name', coalesce(st.display_name,'Unknown')) end order by s.sold_at desc)
      from public.sales s left join public.staff st
        on st.store_id=s.store_id and st.user_id=s.actor_id
      where s.store_id=u.store_id and s.sku=u.sku and s.voided_at is null),'[]'::jsonb)
  ) into v_result from public.units u where u.store_id=v_store and u.sku=p_sku;
  return v_result;
end $_$;


ALTER FUNCTION "public"."portal_inventory_detail"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_get"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  u public.units;
  photos jsonb;
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  select * into u from public.units where store_id = sid and sku = btrim(p_sku);
  if not found then raise exception 'unit_not_found'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', p.id, 'path', p.path, 'is_primary', p.is_primary
  ) order by p.is_primary desc nulls last, p.created_at), '[]'::jsonb)
  into photos
  from public.photos p
  where p.store_id = sid and p.sku = u.sku;
  return jsonb_build_object(
    'sku', u.sku,
    'title', u.title,
    'brand', u.brand,
    'model', u.model,
    'category', u.category,
    'condition', u.condition,
    'test_status', u.test_status,
    'location', u.location,
    'ask_cents', u.ask_cents,
    'acquisition_cost_cents', u.acquisition_cost_cents,
    'floor_cents', u.floor_cents,
    'msrp_cents', u.msrp_cents,
    'upc', u.upc,
    'lot', u.lot,
    'mfr_serial', u.mfr_serial,
    'defect_notes', u.defect_notes,
    'state', u.state,
    'show_on_website', u.show_on_website,
    'received_at', u.received_at,
    'updated_at', u.updated_at,
    'photos', photos,
    'has_photo', jsonb_array_length(photos) > 0,
    'unfinished', u.ask_cents is null or jsonb_array_length(photos) = 0
  );
end;
$$;


ALTER FUNCTION "public"."portal_inventory_get"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_list"("p_q" "text" DEFAULT NULL::"text", "p_unfinished" boolean DEFAULT false, "p_limit" integer DEFAULT 200, "p_offset" integer DEFAULT 0) RETURNS TABLE("sku" "text", "title" "text", "brand" "text", "model" "text", "category" "text", "condition" "text", "ask_cents" integer, "acquisition_cost_cents" integer, "floor_cents" integer, "state" "text", "has_photo" boolean, "unfinished" boolean, "received_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  q text := nullif(btrim(coalesce(p_q, '')), '');
  lim int := greatest(1, least(coalesce(p_limit, 200), 500));
  off int := greatest(0, coalesce(p_offset, 0));
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  return query
  select
    u.sku,
    coalesce(nullif(btrim(u.title), ''), nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), u.sku)::text,
    u.brand,
    u.model,
    u.category,
    u.condition,
    u.ask_cents,
    u.acquisition_cost_cents,
    u.floor_cents,
    u.state,
    exists (select 1 from public.photos p where p.store_id = u.store_id and p.sku = u.sku) as has_photo,
    (
      u.ask_cents is null
      or not exists (select 1 from public.photos p where p.store_id = u.store_id and p.sku = u.sku)
    ) as unfinished,
    u.received_at,
    u.updated_at
  from public.units u
  where u.store_id = sid
    and u.state in ('available','reserved','repair')
    and (
      not coalesce(p_unfinished, false)
      or u.ask_cents is null
      or not exists (select 1 from public.photos p where p.store_id = u.store_id and p.sku = u.sku)
    )
    and (
      q is null
      or u.sku ilike '%' || q || '%'
      or coalesce(u.title, '') ilike '%' || q || '%'
      or coalesce(u.brand, '') ilike '%' || q || '%'
      or coalesce(u.model, '') ilike '%' || q || '%'
    )
  order by u.sku desc
  limit lim offset off;
end;
$$;


ALTER FUNCTION "public"."portal_inventory_list"("p_q" "text", "p_unfinished" boolean, "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_list"("p_query" "text" DEFAULT ''::"text", "p_status" "text" DEFAULT 'in_stock'::"text", "p_unfinished" boolean DEFAULT false, "p_sort" "text" DEFAULT 'sku'::"text", "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_admin boolean := public.portal_is_admin();
  v_result jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_offset < 0 or p_limit < 1 or p_limit > 100 or p_sort not in ('sku','price','date') then
    raise exception 'invalid_inventory_options' using errcode = '22023';
  end if;
  with base as (
    select u.sku, u.brand, u.model, u.title, u.condition, u.state, u.received_at, u.package_weight_lb,
      u.ask_cents, u.acquisition_cost_cents, u.listing_specs,
      public.unit_is_defective(u.listing_specs, u.condition) as defective,
      public.unit_not_for_sale(u.listing_specs) as not_for_sale,
      ph.photo_path, ph.photo_count,
      case when p_unfinished then public.unit_listing_gaps(u) end as gaps,
      sl.sold_at, sl.sold_price_cents
    from public.units u
    cross join lateral (
      select count(*)::int photo_count,
        (array_agg(p.path order by p.is_primary desc, p.id))[1] photo_path
      from public.photos p where p.store_id = u.store_id and p.sku = u.sku
    ) ph
    left join lateral (
      select max(s.sold_at) sold_at, sum(s.price_cents)::int sold_price_cents
      from public.sales s
      where u.state = 'sold' and s.store_id = u.store_id and s.sku = u.sku and s.voided_at is null
    ) sl on true
    where u.store_id = v_store
      and (nullif(btrim(p_query),'') is null or u.sku ilike '%' || btrim(p_query) || '%'
        or u.brand ilike '%' || btrim(p_query) || '%'
        or u.model ilike '%' || btrim(p_query) || '%'
        or u.title ilike '%' || btrim(p_query) || '%')
  ), filtered as (
    select b.sku, b.brand, b.model, b.title, b.condition, b.state, b.received_at, b.package_weight_lb,
      b.photo_path, b.photo_count, b.defective, b.not_for_sale,
      coalesce(b.gaps, '{}') as missing,
      case when v_admin or b.state in ('available','reserved','repair') then b.ask_cents end as ask_cents,
      case when v_admin then b.acquisition_cost_cents end as acquisition_cost_cents,
      b.sold_at,
      case when v_admin then b.sold_price_cents end as sold_price_cents
    from base b
    where (p_status = 'all'
        or (p_status = 'in_stock' and b.state in ('available','reserved','repair') and not b.defective)
        or (p_status = 'defective' and b.state in ('available','reserved','repair') and b.defective)
        or (p_status = 'listed' and b.state in ('available','reserved','repair') and not b.defective
          and exists (
            select 1 from public.listings l
            where l.store_id = v_store and l.sku = b.sku and l.status = 'listed'
          ))
        or (p_status = 'delisted' and exists (select 1 from public.listings l
          where l.store_id = v_store and l.sku = b.sku and l.status = 'delisted'))
        or b.state = p_status)
      and (not p_unfinished or (b.state in ('available','reserved','repair')
        and not b.not_for_sale and public.unit_is_unfinished(b.gaps)))
  ), page as (
    select row_number() over (order by
        case when p_sort = 'sku' then sku::numeric end desc nulls last,
        case when p_sort = 'price' then coalesce(sold_price_cents, ask_cents) end asc nulls last,
        case when p_sort = 'date' then coalesce(sold_at, received_at) end desc nulls last,
        sku desc) as sort_order,
      sku,brand,model,title,condition,ask_cents,acquisition_cost_cents,
      state,received_at,package_weight_lb,photo_path,photo_count,
      defective,not_for_sale,missing,sold_at,sold_price_cents
    from filtered
    order by case when p_sort = 'sku' then sku::numeric end desc nulls last,
      case when p_sort = 'price' then coalesce(sold_price_cents, ask_cents) end asc nulls last,
      case when p_sort = 'date' then coalesce(sold_at, received_at) end desc nulls last, sku desc
    offset p_offset limit p_limit
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(p) - 'sort_order' order by p.sort_order)
      from page p), '[]'::jsonb),
    'totals', (select jsonb_build_object('unit_count',count(*),
      'retail_cents', case when v_admin then coalesce(sum(ask_cents),0) end,
      'cost_cents', case when v_admin then coalesce(sum(acquisition_cost_cents),0) end,
      'missing_cost', case when v_admin then count(*) filter (where acquisition_cost_cents is null) end)
      from filtered)
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "public"."portal_inventory_list"("p_query" "text", "p_status" "text", "p_unfinished" boolean, "p_sort" "text", "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_list_with_locations"("p_query" "text" DEFAULT ''::"text", "p_status" "text" DEFAULT 'in_stock'::"text", "p_unfinished" boolean DEFAULT false, "p_sort" "text" DEFAULT 'sku'::"text", "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 24, "p_location" "text" DEFAULT 'all'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_admin boolean := public.portal_is_admin();
  v_result jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_offset < 0 or p_limit < 1 or p_limit > 100 or p_sort not in ('sku','price','date') then
    raise exception 'invalid_inventory_options' using errcode = '22023';
  end if;
  with base as (
    select u.sku, u.brand, u.model, u.title, u.condition, u.state, u.received_at, u.package_weight_lb,
      u.ask_cents, u.acquisition_cost_cents, u.listing_specs, u.qty_on_hand, loc.locations, loc.assigned,
      public.unit_is_defective(u.listing_specs, u.condition) as defective,
      public.unit_not_for_sale(u.listing_specs) as not_for_sale,
      ph.photo_path, ph.photo_count,
      case when p_unfinished then public.unit_listing_gaps(u) end as gaps,
      sl.sold_at, sl.sold_price_cents
    from public.units u
    cross join lateral (
      select count(*)::int photo_count,
        (array_agg(p.path order by p.is_primary desc, p.id))[1] photo_path
      from public.photos p where p.store_id = u.store_id and p.sku = u.sku
    ) ph
    cross join lateral (
      select coalesce(string_agg(x.location_code || ' ×' || x.quantity,
        ', ' order by l.bay_no,l.row_no,l.bin_no nulls first),'') locations,
        coalesce(sum(x.quantity),0)::int assigned
      from public.unit_location_stock x join public.store_locations l
        on l.store_id=x.store_id and l.code=x.location_code
      where x.store_id=u.store_id and x.sku=u.sku
    ) loc
    left join lateral (
      select max(s.sold_at) sold_at, sum(s.price_cents)::int sold_price_cents
      from public.sales s
      where u.state = 'sold' and s.store_id = u.store_id and s.sku = u.sku and s.voided_at is null
    ) sl on true
    where u.store_id = v_store
      and (nullif(btrim(p_query),'') is null or u.sku ilike '%' || btrim(p_query) || '%'
        or u.brand ilike '%' || btrim(p_query) || '%'
        or u.model ilike '%' || btrim(p_query) || '%'
        or u.title ilike '%' || btrim(p_query) || '%')
  ), filtered as (
    select b.sku, b.brand, b.model, b.title, b.condition, b.state, b.received_at, b.package_weight_lb,
      b.photo_path, b.photo_count, b.defective, b.not_for_sale, b.locations, b.assigned,
      coalesce(b.gaps, '{}') as missing,
      case when v_admin or b.state in ('available','reserved','repair') then b.ask_cents end as ask_cents,
      case when v_admin then b.acquisition_cost_cents end as acquisition_cost_cents,
      b.sold_at,
      case when v_admin then b.sold_price_cents end as sold_price_cents
    from base b
    where (p_status = 'all'
        or (p_status = 'in_stock' and b.state in ('available','reserved','repair') and not b.defective)
        or (p_status = 'defective' and b.state in ('available','reserved','repair') and b.defective)
        or (p_status = 'listed' and b.state in ('available','reserved','repair') and not b.defective
          and exists (
            select 1 from public.listings l
            where l.store_id = v_store and l.sku = b.sku and l.status = 'listed'
          ))
        or (p_status = 'delisted' and exists (select 1 from public.listings l
          where l.store_id = v_store and l.sku = b.sku and l.status = 'delisted'))
        or b.state = p_status)
      and (not p_unfinished or (b.state in ('available','reserved','repair')
        and not b.not_for_sale and public.unit_is_unfinished(b.gaps)))
      and (p_location='all' or (p_location='unassigned' and
        b.state in ('available','reserved','repair') and b.assigned<b.qty_on_hand)
        or exists(select 1 from public.unit_location_stock x
          where x.store_id=v_store and x.sku=b.sku and x.location_code=p_location))
  ), page as (
    select row_number() over (order by
        case when p_sort = 'sku' then sku::numeric end desc nulls last,
        case when p_sort = 'price' then coalesce(sold_price_cents, ask_cents) end asc nulls last,
        case when p_sort = 'date' then coalesce(sold_at, received_at) end desc nulls last,
        sku desc) as sort_order,
      sku,brand,model,title,condition,ask_cents,acquisition_cost_cents,
      state,received_at,package_weight_lb,photo_path,photo_count,
      defective,not_for_sale,missing,sold_at,sold_price_cents,locations,assigned
    from filtered
    order by case when p_sort = 'sku' then sku::numeric end desc nulls last,
      case when p_sort = 'price' then coalesce(sold_price_cents, ask_cents) end asc nulls last,
      case when p_sort = 'date' then coalesce(sold_at, received_at) end desc nulls last, sku desc
    offset p_offset limit p_limit
  )
  select jsonb_build_object(
    'items', coalesce((select jsonb_agg(to_jsonb(p) - 'sort_order' order by p.sort_order)
      from page p), '[]'::jsonb),
    'totals', (select jsonb_build_object('unit_count',count(*),
      'retail_cents', case when v_admin then coalesce(sum(ask_cents),0) end,
      'cost_cents', case when v_admin then coalesce(sum(acquisition_cost_cents),0) end,
      'missing_cost', case when v_admin then count(*) filter (where acquisition_cost_cents is null) end)
      from filtered)
  ) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "public"."portal_inventory_list_with_locations"("p_query" "text", "p_status" "text", "p_unfinished" boolean, "p_sort" "text", "p_offset" integer, "p_limit" integer, "p_location" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_next_sku"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  sid uuid := public.portal_store_id();
  v text;
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  begin
    if public.current_store_id() is not null then
      select public.next_sku() into v;
      return v;
    end if;
  exception when others then
    null;
  end;
  select lpad((coalesce(max(sku::bigint), 11000) + 1)::text, 5, '0') into v
  from public.units
  where store_id = sid and sku ~ '^[0-9]+$';
  return v;
end;
$_$;


ALTER FUNCTION "public"."portal_inventory_next_sku"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_receive"("p_sku" "text", "p_brand" "text" DEFAULT ''::"text", "p_model" "text" DEFAULT ''::"text", "p_title" "text" DEFAULT ''::"text", "p_category" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_ask_cents" integer DEFAULT NULL::integer, "p_cost_cents" integer DEFAULT NULL::integer, "p_floor_cents" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  v_sku text := btrim(p_sku);
  v_row public.units;
  v_actor text;
  v_title text;
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  if v_sku is null or v_sku = '' then raise exception 'invalid_sku'; end if;

  v_title := coalesce(
    nullif(btrim(p_title), ''),
    nullif(btrim(concat_ws(' ', p_brand, p_model)), ''),
    v_sku
  );

  if exists (
    select 1 from public.staff s
    where s.user_id = auth.uid() and s.store_id = sid and s.deactivated_at is null
  ) and public.current_store_id() is not distinct from sid then
    v_row := public.receive_unit(
      v_sku, coalesce(p_brand,''), coalesce(p_model,''), v_title,
      p_category, p_condition, null, null,
      p_ask_cents, null, p_cost_cents, p_floor_cents, p_notes, null, null, null
    );
    return to_jsonb(v_row);
  end if;

  if exists (select 1 from public.units where store_id = sid and sku = v_sku) then
    raise exception 'SKU % is already in inventory.', v_sku;
  end if;

  v_actor := coalesce(
    (select display_name from public.staff where user_id = auth.uid() and store_id = sid),
    (select email from auth.users where id = auth.uid()),
    'portal'
  );

  insert into public.sku_ledger (store_id, sku, issued_at, label, fate)
  values (sid, v_sku, now(), v_title, 'issued');

  insert into public.units (
    store_id, sku, brand, model, title, category, condition,
    defect_notes, acquisition_cost_cents, ask_cents, floor_cents,
    state, show_on_website, received_at, updated_at
  ) values (
    sid, v_sku, coalesce(p_brand,''), coalesce(p_model,''), v_title,
    p_category, p_condition, p_notes, p_cost_cents, p_ask_cents, p_floor_cents,
    'available', true, now(), now()
  )
  returning * into v_row;

  insert into public.events (store_id, sku, kind, actor, actor_id, note)
  values (sid, v_sku, 'received', v_actor, auth.uid(), 'portal');

  return to_jsonb(v_row);
end;
$$;


ALTER FUNCTION "public"."portal_inventory_receive"("p_sku" "text", "p_brand" "text", "p_model" "text", "p_title" "text", "p_category" "text", "p_condition" "text", "p_ask_cents" integer, "p_cost_cents" integer, "p_floor_cents" integer, "p_notes" "text") OWNER TO "postgres";


