CREATE OR REPLACE FUNCTION "public"."portal_inventory_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_active int;
  v_sold int;
  v_ebay int;
  v_amazon int;
  v_depop int;
  v_tiktok int;
  v_do_not_list int;
begin
  if v_store is null then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;

  select
    count(*) filter (where u.state in ('available', 'reserved', 'repair'))::int,
    count(*) filter (where u.state = 'sold')::int,
    count(*) filter (
      where u.state in ('available', 'reserved', 'repair')
        and (
          coalesce((u.listing_specs->>'do_not_list')::boolean, false)
          or coalesce(u.listing_specs->>'hold_reason', '') = 'do_not_list'
        )
    )::int
  into v_active, v_sold, v_do_not_list
  from public.units u
  where u.store_id = v_store;

  select count(*)::int into v_ebay
  from public.listings l
  join public.units u on u.store_id = l.store_id and u.sku = l.sku
  where l.store_id = v_store
    and l.status = 'listed'
    and lower(l.channel) = 'ebay'
    and u.state in ('available', 'reserved', 'repair');

  select greatest(
    coalesce((
      select count(*)::int from public.listings l
      join public.units u on u.store_id = l.store_id and u.sku = l.sku
      where l.store_id = v_store and l.status = 'listed' and lower(l.channel) = 'amazon'
        and u.state in ('available', 'reserved', 'repair')
    ), 0),
    coalesce((
      select count(*)::int from public.amazon_list_items a
      join public.units u on u.store_id = a.store_id and u.sku = a.sku
      where a.store_id = v_store and a.status = 'live'
        and u.state in ('available', 'reserved', 'repair')
    ), 0)
  ) into v_amazon;

  select count(*)::int into v_depop
  from public.listings l
  join public.units u on u.store_id = l.store_id and u.sku = l.sku
  where l.store_id = v_store
    and l.status = 'listed'
    and lower(l.channel) = 'depop'
    and u.state in ('available', 'reserved', 'repair');

  select count(*)::int into v_tiktok
  from public.listings l
  join public.units u on u.store_id = l.store_id and u.sku = l.sku
  where l.store_id = v_store
    and l.status = 'listed'
    and lower(l.channel) = 'tiktok'
    and u.state in ('available', 'reserved', 'repair');

  return jsonb_build_object(
    'total_active_inventory', v_active,
    'sold_inventory', v_sold,
    'ebay', v_ebay,
    'amazon', v_amazon,
    'depop', v_depop,
    'tiktok', v_tiktok,
    'do_not_list', v_do_not_list
  );
end;
$$;


ALTER FUNCTION "public"."portal_inventory_stats"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_inventory_update_field"("p_sku" "text", "p_field" "text", "p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  sid uuid := public.portal_store_id();
  v_old text;
  v_actor text;
begin
  if sid is null then raise exception 'not a portal admin'; end if;
  if p_field not in (
    'brand','model','title','category','condition','test_status','location',
    'mfr_serial','defect_notes','upc','lot','acquisition_cost_cents','msrp_cents',
    'ask_cents','floor_cents'
  ) then
    raise exception 'invalid_field' using errcode = '22023';
  end if;

  if not exists (select 1 from public.units where sku = btrim(p_sku) and store_id = sid) then
    raise exception 'unit_not_found';
  end if;

  execute format('select %I::text from public.units where sku = $1 and store_id = $2', p_field)
    into v_old using btrim(p_sku), sid;

  if p_field like '%_cents' then
    execute format(
      'update public.units set %I = $1::int, updated_at = now() where sku = $2 and store_id = $3',
      p_field
    ) using nullif(p_value, ''), btrim(p_sku), sid;
  else
    execute format(
      'update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3',
      p_field
    ) using p_value, btrim(p_sku), sid;
  end if;

  v_actor := coalesce(
    (select display_name from public.staff where user_id = auth.uid() and store_id = sid),
    (select email from auth.users where id = auth.uid()),
    'portal'
  );

  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (sid, btrim(p_sku), 'edit', p_field, v_old, p_value, v_actor, auth.uid());
end;
$_$;


ALTER FUNCTION "public"."portal_inventory_update_field"("p_sku" "text", "p_field" "text", "p_value" "text") OWNER TO "postgres";


