CREATE OR REPLACE FUNCTION "public"."portal_listing_queue"() RETURNS TABLE("id" "uuid", "sku" "text", "reason" "text", "detail" "jsonb", "best_viable_price_cents" integer, "profit_cents" integer, "status" "text", "title" "text", "condition" "text", "ask_cents" integer, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
begin
  if sid is null then
    raise exception 'not a portal admin';
  end if;
  return query
  select
    q.id,
    q.sku,
    q.reason,
    q.detail,
    q.best_viable_price_cents,
    q.profit_cents,
    q.status,
    coalesce(u.title, trim(both from concat_ws(' ', u.brand, u.model)), q.sku) as title,
    u.condition,
    u.ask_cents,
    q.created_at
  from public.listing_review_queue q
  left join public.units u on u.store_id = q.store_id and u.sku = q.sku
  where q.store_id = sid
    and q.status = 'pending'
  order by q.created_at desc;
end;
$$;


ALTER FUNCTION "public"."portal_listing_queue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_listing_queue_decide"("p_id" "uuid", "p_action" "text", "p_price_cents" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  row public.listing_review_queue;
begin
  if sid is null then
    raise exception 'not a portal admin';
  end if;
  select * into row from public.listing_review_queue where id = p_id and store_id = sid;
  if not found then
    raise exception 'queue row not found';
  end if;
  if p_action = 'keep_instore' then
    update public.listing_review_queue
    set status = 'kept_instore', decided_at = now(), decided_by = auth.uid(), updated_at = now()
    where id = p_id;
  elsif p_action = 'dismiss' then
    update public.listing_review_queue
    set status = 'dismissed', decided_at = now(), decided_by = auth.uid(), updated_at = now()
    where id = p_id;
  elsif p_action = 'approve' then
    if p_price_cents is null or p_price_cents <= 0 then
      raise exception 'price required';
    end if;
    update public.listing_review_queue
    set status = 'approved',
        decided_price_cents = p_price_cents,
        decided_at = now(),
        decided_by = auth.uid(),
        updated_at = now()
    where id = p_id;
    update public.units u
    set listing_specs = coalesce(u.listing_specs, '{}'::jsonb)
      || jsonb_build_object(
        'marketplace_pricing',
        coalesce(u.listing_specs->'marketplace_pricing', '{}'::jsonb)
          || jsonb_build_object(
            'ebay_list_usd', (p_price_cents::numeric / 100),
            'approved_at', now(),
            'your_call', false
          )
      ),
      updated_at = now()
    where u.store_id = sid and u.sku = row.sku;
  else
    raise exception 'unknown action';
  end if;
end;
$$;


ALTER FUNCTION "public"."portal_listing_queue_decide"("p_id" "uuid", "p_action" "text", "p_price_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_listing_queue_decide_bulk"("p_action" "text", "p_ids" "uuid"[] DEFAULT NULL::"uuid"[], "p_reason" "text" DEFAULT NULL::"text", "p_price_cents" integer DEFAULT NULL::integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
  n integer := 0;
  r public.listing_review_queue;
  price integer;
begin
  if sid is null then
    raise exception 'not a portal admin';
  end if;
  if p_action not in ('keep_instore', 'dismiss', 'approve') then
    raise exception 'unknown action';
  end if;
  if (p_ids is null or cardinality(p_ids) = 0) and (p_reason is null or length(trim(p_reason)) = 0) then
    raise exception 'p_ids or p_reason required';
  end if;

  for r in
    select *
    from public.listing_review_queue q
    where q.store_id = sid
      and q.status = 'pending'
      and (
        (p_ids is not null and cardinality(p_ids) > 0 and q.id = any (p_ids))
        or (p_reason is not null and length(trim(p_reason)) > 0 and q.reason = p_reason)
      )
  loop
    if p_action = 'keep_instore' then
      update public.listing_review_queue
      set status = 'kept_instore', decided_at = now(), decided_by = auth.uid(), updated_at = now()
      where id = r.id;
      n := n + 1;
    elsif p_action = 'dismiss' then
      update public.listing_review_queue
      set status = 'dismissed', decided_at = now(), decided_by = auth.uid(), updated_at = now()
      where id = r.id;
      n := n + 1;
    elsif p_action = 'approve' then
      price := coalesce(p_price_cents, r.best_viable_price_cents);
      if price is null or price <= 0 then
        continue;
      end if;
      update public.listing_review_queue
      set status = 'approved',
          decided_price_cents = price,
          decided_at = now(),
          decided_by = auth.uid(),
          updated_at = now()
      where id = r.id;
      update public.units u
      set listing_specs = coalesce(u.listing_specs, '{}'::jsonb)
        || jsonb_build_object(
          'marketplace_pricing',
          coalesce(u.listing_specs->'marketplace_pricing', '{}'::jsonb)
            || jsonb_build_object(
              'ebay_list_usd', (price::numeric / 100),
              'approved_at', now(),
              'your_call', false
            )
        ),
        updated_at = now()
      where u.store_id = sid and u.sku = r.sku;
      n := n + 1;
    end if;
  end loop;

  return n;
end;
$$;


ALTER FUNCTION "public"."portal_listing_queue_decide_bulk"("p_action" "text", "p_ids" "uuid"[], "p_reason" "text", "p_price_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_listings_health"() RETURNS TABLE("marketplace" "text", "live_count" integer, "floor_count" integer, "vendoo_count" integer, "open_mismatches" integer, "captured_at" timestamp with time zone, "detail" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
begin
  if sid is null then
    raise exception 'not a portal admin';
  end if;
  return query
  with latest as (
    select distinct on (h.marketplace)
      h.marketplace,
      h.live_count,
      h.floor_count,
      h.vendoo_count,
      h.open_mismatches,
      h.captured_at,
      h.detail
    from public.listings_health h
    where h.store_id = sid
    order by h.marketplace, h.captured_at desc
  )
  select * from latest
  order by marketplace;
end;
$$;


ALTER FUNCTION "public"."portal_listings_health"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_listings_health_mismatches"("p_limit" integer DEFAULT 50) RETURNS TABLE("id" "uuid", "marketplace" "text", "sku" "text", "kind" "text", "detail" "jsonb", "captured_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  sid uuid := public.portal_store_id();
begin
  if sid is null then
    raise exception 'not a portal admin';
  end if;
  return query
  select m.id, m.marketplace, m.sku, m.kind, m.detail, m.captured_at
  from public.listings_health_mismatches m
  where m.store_id = sid
    and m.resolved_at is null
  order by m.captured_at desc
  limit greatest(1, least(coalesce(p_limit, 50), 200));
end;
$$;


ALTER FUNCTION "public"."portal_listings_health_mismatches"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_log_policy_strike"("p_channel" "text", "p_sku" "text", "p_reason" "text", "p_email_body" "text" DEFAULT NULL::"text", "p_struck_at" "date" DEFAULT NULL::"date") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_id bigint; v_channel text := lower(btrim(p_channel));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_channel = '' or coalesce(nullif(btrim(p_sku), ''), '') = '' or coalesce(nullif(btrim(p_reason), ''), '') = '' then
    raise exception 'channel_sku_reason_required' using errcode = '22023';
  end if;
  insert into public.marketplace_policy_strikes(store_id, channel, sku, struck_at, reason, email_body, created_by, created_by_name)
  values (v_store, v_channel, btrim(p_sku), coalesce(p_struck_at, (timezone('America/Los_Angeles', now()))::date),
    btrim(p_reason), p_email_body, auth.uid(),
    coalesce((select display_name from public.staff where user_id = auth.uid()), (select email from auth.users where id = auth.uid())))
  on conflict (store_id, sku, channel) do update
    set struck_at = excluded.struck_at, reason = excluded.reason, email_body = excluded.email_body
  returning id into v_id;
  delete from public.unit_marketplace_overrides where store_id = v_store and sku = btrim(p_sku) and channel = v_channel;
  return v_id;
end $$;


ALTER FUNCTION "public"."portal_log_policy_strike"("p_channel" "text", "p_sku" "text", "p_reason" "text", "p_email_body" "text", "p_struck_at" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_manifest_list"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return coalesce((select jsonb_agg(to_jsonb(m) || jsonb_build_object(
    'received_count', coalesce(stats.received_count,0),
    'sold_count', coalesce(stats.sold_count,0),
    'stock_count', coalesce(stats.stock_count,0),
    'revenue_cents', coalesce(stats.revenue_cents,0),
    'profit_cents', coalesce(stats.profit_cents,0)
  ) order by m.manifest_on desc, m.created_at desc)
  from public.store_manifests m
  left join lateral (
    select coalesce(sum(u.qty_on_hand + coalesce(sold.qty,0)),0)::int received_count,
      coalesce(sum(sold.qty),0)::int sold_count,
      coalesce(sum(u.qty_on_hand) filter (where u.state in ('available','reserved')),0)::int stock_count,
      coalesce(sum(sold.revenue_cents),0)::bigint revenue_cents,
      coalesce(sum(sold.profit_cents),0)::bigint profit_cents
    from public.units u
    left join lateral (
      select s.sku, sum(s.qty)::int qty, sum(s.price_cents)::bigint revenue_cents,
        coalesce(sum(l.profit_cents),0)::bigint profit_cents
      from public.sales s left join public.sale_ledger l
        on l.store_id=s.store_id and l.id=s.id and l.voided_at is null
      where s.store_id=u.store_id and s.sku=u.sku and s.voided_at is null
      group by s.sku
    ) sold on true
    where u.store_id=v_store and u.manifest_id=m.id
  ) stats on true
  where m.store_id=v_store), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_manifest_list"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_mark_order_delivered"("p_order" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  update public.web_orders
  set shipped_at = coalesce(shipped_at, now()),
      delivered_at = coalesce(delivered_at, now()),
      updated_at = now()
  where id = p_order and store_id = v_store and status = 'paid' and fulfillment = 'ship'
    and refund_requested_at is null;
  if not found then raise exception 'order_not_deliverable' using errcode = 'P0001'; end if;
end $$;


ALTER FUNCTION "public"."portal_mark_order_delivered"("p_order" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_mark_order_shipped"("p_order" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  o public.web_orders;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  select * into o from public.web_orders where id = p_order and store_id = v_store;
  if not found then raise exception 'order_not_shippable' using errcode = 'P0001'; end if;
  if o.status <> 'paid' or o.fulfillment <> 'ship' or o.refund_requested_at is not null then
    raise exception 'order_not_shippable' using errcode = 'P0001';
  end if;
  if lower(coalesce(o.channel, '')) in ('amazon', 'tiktok')
     and nullif(btrim(coalesce(o.pack_proof_photo_path, '')), '') is null then
    raise exception 'pack_proof_required' using errcode = 'P0001';
  end if;
  update public.web_orders
  set shipped_at = coalesce(shipped_at, now()), updated_at = now()
  where id = p_order and store_id = v_store;
end $$;


ALTER FUNCTION "public"."portal_mark_order_shipped"("p_order" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_mark_vendoo_listed"("p_items" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_item jsonb;
  v_sku text;
  v_channels text[];
  v_n int := 0;
  v_ch text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'items_array_required' using errcode = '22023';
  end if;

  for v_item in select value from jsonb_array_elements(p_items)
  loop
    v_sku := nullif(btrim(coalesce(v_item->>'sku', '')), '');
    if v_sku is null then continue; end if;
    if not exists (select 1 from public.units u where u.store_id = v_store and u.sku = v_sku) then
      continue;
    end if;

    select coalesce(array_agg(distinct lower(btrim(x)) order by lower(btrim(x))), array['vendoo']::text[])
      into v_channels
    from (
      select 'vendoo'::text as x
      union all
      select jsonb_array_elements_text(coalesce(v_item->'channels', '[]'::jsonb))
    ) s
    where btrim(x) <> '';

    foreach v_ch in array v_channels
    loop
      insert into public.listings(store_id, sku, channel, status, listed_at, delisted_at)
      values (v_store, v_sku, v_ch, 'listed', now(), null)
      on conflict (store_id, sku, channel) do update
        set status = 'listed',
            listed_at = coalesce(public.listings.listed_at, excluded.listed_at),
            delisted_at = null;
    end loop;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;


ALTER FUNCTION "public"."portal_mark_vendoo_listed"("p_items" "jsonb") OWNER TO "postgres";


