CREATE OR REPLACE FUNCTION "public"."portal_match_web_order"("p_order" "uuid", "p_sku" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_order public.web_orders;
  v_sale public.sales;
  v_payment_suffix text;
  v_unit_title text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  select * into v_order from public.web_orders where id = p_order and store_id = v_store for update;
  if not found then raise exception 'order_not_found' using errcode='P0002'; end if;
  if v_order.match_status = 'matched' and v_order.sale_id is not null then return; end if;
  if nullif(btrim(p_sku), '') is null then raise exception 'sku_required' using errcode='22023'; end if;
  if coalesce(v_order.item_cents, 0) <= 0 then
    raise exception 'sale_price_required' using errcode='22023';
  end if;

  select coalesce(nullif(btrim(title), ''), nullif(btrim(concat_ws(' ', brand, model)), ''), btrim(p_sku))
    into v_unit_title
  from public.units
  where store_id = v_store and sku = btrim(p_sku);

  v_sale := public.finalize_sale(
    p_sku => btrim(p_sku),
    p_channel => coalesce(nullif(v_order.channel,''), 'ebay'),
    p_price_cents => v_order.item_cents,
    p_payment_method => case when v_order.channel = 'ebay' then 'ebay' else 'marketplace' end,
    p_payment_id => coalesce(v_order.payment_id, 'manual:' || p_order::text),
    p_note => 'Matched marketplace order ' || coalesce(v_order.order_no, p_order::text),
    p_tax_cents => 0,
    p_approval_id => null
  );

  update public.web_orders
    set sku = btrim(p_sku),
        sale_id = v_sale.id,
        match_status = 'matched',
        marketplace_title = coalesce(v_unit_title, marketplace_title),
        updated_at = now()
  where id = p_order and store_id = v_store;

  update public.channel_orders
    set sku = btrim(p_sku), sale_id = v_sale.id
  where store_id = v_store
    and provider = v_order.channel
    and (
      order_id = v_order.order_no
      or (v_order.payment_id like 'marketplace:%' and order_id = split_part(v_order.payment_id, ':', 3))
      or (v_order.payment_id like 'ebay:%' and order_id = split_part(v_order.payment_id, ':', 2))
    );

  v_payment_suffix := case
    when v_order.payment_id like 'marketplace:%' then split_part(v_order.payment_id, ':', 3)
    else null
  end;
  if v_payment_suffix is not null then
    update public.marketplace_email_sales
      set state = 'matched',
          sale_id = v_sale.id,
          sku = btrim(p_sku),
          item_title = coalesce(v_unit_title, item_title),
          reason = null
    where store_id = v_store
      and sale_id is null
      and marketplace = v_order.channel
      and (
        order_number = v_payment_suffix
        or message_id = v_payment_suffix
        or ('msg:' || regexp_replace(coalesce(message_id,''), '[^A-Za-z0-9_-]', '', 'g')) = v_payment_suffix
        or left('msg:' || regexp_replace(coalesce(message_id,''), '[^A-Za-z0-9_-]', '', 'g'), 52) = v_payment_suffix
      );
  end if;

  update public.listings
    set status = 'delisted', delisted_at = coalesce(delisted_at, now())
  where store_id = v_store and sku = btrim(p_sku) and channel = v_order.channel;
end $$;


ALTER FUNCTION "public"."portal_match_web_order"("p_order" "uuid", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_move_location_stock"("p_sku" "text", "p_to" "text", "p_quantity" integer DEFAULT 1, "p_from" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := coalesce(public.portal_store_id(),public.current_store_id()); v_on_hand int; v_assigned int; v_from int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 100000 then
    raise exception 'quantity_invalid' using errcode = '22023'; end if;
  select qty_on_hand into v_on_hand from public.units
  where store_id=v_store and sku=p_sku for update;
  if v_on_hand is null then raise exception 'sku_not_found' using errcode = 'P0002'; end if;
  if not exists (select 1 from public.store_locations
    where store_id=v_store and code=p_to) then
    raise exception 'location_not_found' using errcode = 'P0002'; end if;
  if p_from is not null then
    select quantity into v_from from public.unit_location_stock
    where store_id=v_store and sku=p_sku and location_code=p_from for update;
    if coalesce(v_from,0) < p_quantity then
      raise exception 'not_enough_stock_at_source' using errcode = 'P0001'; end if;
    delete from public.unit_location_stock
    where store_id=v_store and sku=p_sku and location_code=p_from and quantity=p_quantity;
    if not found then
      update public.unit_location_stock set quantity=quantity-p_quantity,updated_at=now()
      where store_id=v_store and sku=p_sku and location_code=p_from;
    end if;
  else
    select coalesce(sum(quantity),0) into v_assigned from public.unit_location_stock
    where store_id=v_store and sku=p_sku;
    if v_assigned+p_quantity > v_on_hand then
      raise exception 'not_enough_unassigned_stock' using errcode = 'P0001'; end if;
  end if;
  insert into public.unit_location_stock(store_id,sku,location_code,quantity)
  values(v_store,p_sku,p_to,p_quantity)
  on conflict(store_id,sku,location_code) do update
    set quantity=public.unit_location_stock.quantity+excluded.quantity,updated_at=now();
end $$;


ALTER FUNCTION "public"."portal_move_location_stock"("p_sku" "text", "p_to" "text", "p_quantity" integer, "p_from" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_online_board"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_channels text[] := array['ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook'];
  v_msc_channels text[] := array['mercari', 'depop', 'whatnot'];
  v_inventory_total int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;

  select count(*)::int into v_inventory_total
  from public.units u
  where u.store_id = v_store and u.state = 'available';

  return (
    with lots as (
      select
        lot.id as lot_id,
        lot.key as lot_key,
        lot.title as lot_title,
        lot.primary_sku,
        lot.channel as lot_channel,
        lot.listing_id,
        (
          select count(*)::int
          from public.listing_lot_members m
          join public.units u on u.store_id = m.store_id and u.sku = m.sku
          where m.lot_id = lot.id and u.state = 'available'
        ) as qty_available,
        (
          select coalesce(array_agg(m.sku order by m.sku), '{}'::text[])
          from public.listing_lot_members m
          where m.lot_id = lot.id
        ) as member_skus
      from public.listing_lots lot
      where lot.store_id = v_store
    ),
    member_skus as (
      select distinct unnest(member_skus) as sku from lots
    ),
    units as (
      select
        u.sku,
        coalesce(nullif(btrim(u.title), ''), nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), 'Item') as title,
        u.brand,
        u.model,
        u.state,
        u.ask_cents,
        u.acquisition_cost_cents,
        coalesce(u.listed_on, '{}'::text[]) as listed_on,
        u.show_on_website,
        exists (
          select 1 from public.photos p where p.store_id = u.store_id and p.sku = u.sku
        ) as has_photo,
        (
          coalesce(u.package_weight_lb, 0) > 0
          and coalesce(u.package_length_in, 0) > 0
          and coalesce(u.package_width_in, 0) > 0
          and coalesce(u.package_height_in, 0) > 0
        ) as has_specs,
        public.unit_not_listable_reason(u.store_id, u.sku) as not_listable_reason,
        (select l.lot_id from lots l where u.sku = any (l.member_skus) limit 1) as lot_id
      from public.units u
      where u.store_id = v_store
        and (
          u.state in ('available', 'reserved', 'repair')
          or exists (
            select 1 from public.listings l
            where l.store_id = u.store_id and l.sku = u.sku and l.status = 'listed'
              and l.channel = any (v_channels)
          )
          or exists (select 1 from member_skus m where m.sku = u.sku)
        )
    ),
    amazon_live as (
      select a.sku from public.amazon_list_items a
      where a.store_id = v_store and a.status = 'live'
    ),
    listing_live as (
      select l.sku, l.channel
      from public.listings l
      where l.store_id = v_store
        and l.status = 'listed'
        and l.channel = any (v_channels)
    ),
    enriched as (
      select
        u.*,
        (
          select array_agg(distinct c order by c)
          from (
            select unnest(u.listed_on) as c
            union
            select ll.channel from listing_live ll where ll.sku = u.sku
            union
            select 'amazon'::text from amazon_live al where al.sku = u.sku
            union
            select lot.lot_channel
            from lots lot
            where lot.lot_id = u.lot_id and lot.qty_available > 0 and lot.listing_id is not null
          ) x
          where c = any (v_channels)
        ) as online_on
      from units u
    ),
    display_units as (
      select
        e.*,
        case when e.lot_id is not null then e.lot_id::text else e.sku end as display_key,
        case
          when e.lot_id is not null then (select lot.primary_sku from lots lot where lot.lot_id = e.lot_id)
          else e.sku
        end as display_sku,
        case
          when e.lot_id is not null then (select lot.lot_title from lots lot where lot.lot_id = e.lot_id)
          else e.title
        end as display_title,
        case
          when e.lot_id is not null then (select lot.qty_available from lots lot where lot.lot_id = e.lot_id)
          else 1
        end as qty,
        case when e.lot_id is not null then true else false end as is_lot,
        row_number() over (
          partition by case when e.lot_id is not null then e.lot_id::text else e.sku end
          order by
            case when e.state = 'available' then 0 else 1 end,
            case when e.sku = (select lot.primary_sku from lots lot where lot.lot_id = e.lot_id) then 0 else 1 end,
            e.sku
        ) as rn
      from enriched e
    ),
    scored as (
      select
        d.*,
        (select r.status from public.evaluate_marketplace_eligibility(v_store, d.display_sku, 'ebay') r) as ebay_status,
        (select r.reason from public.evaluate_marketplace_eligibility(v_store, d.display_sku, 'ebay') r) as ebay_reason
      from display_units d
      where d.rn = 1 and d.state = 'available'
        and (not d.is_lot or d.qty > 0)
    ),
    with_reasons as (
      select
        s.*,
        array_remove(array[
          case when not s.has_photo then 'Missing photo' end,
          case when s.ask_cents is null or s.ask_cents <= 0 then 'Missing price' end,
          case when s.acquisition_cost_cents is null then 'Missing cost' end,
          case when not s.has_specs then 'Missing package specs' end,
          case when not s.show_on_website then 'Hidden from website' end,
          case when s.ebay_status is distinct from 'allow' and s.ebay_reason is not null
            then 'eBay: ' || s.ebay_reason
          when s.ebay_status is distinct from 'allow'
            then 'Blocked for eBay'
          end
        ], null) as blockers
      from scored s
      where s.not_listable_reason is null
        and coalesce(cardinality(s.online_on), 0) = 0
    ),
    listed_rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'sku', d.display_sku,
          'title', d.display_title,
          'brand', d.brand,
          'model', d.model,
          'state', d.state,
          'ask_cents', d.ask_cents,
          'listed_on', to_jsonb(coalesce(d.online_on, '{}'::text[])),
          'qty', d.qty,
          'is_lot', d.is_lot
        )
        order by d.display_sku
      ), '[]'::jsonb) as rows
      from display_units d
      where d.rn = 1
        and d.state = 'available'
        and coalesce(cardinality(d.online_on), 0) > 0
        and (not d.is_lot or d.qty > 0)
    ),
    ready_rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'sku', w.display_sku,
          'title', w.display_title,
          'brand', w.brand,
          'model', w.model,
          'ask_cents', w.ask_cents,
          'listed_on', to_jsonb(coalesce(w.online_on, '{}'::text[])),
          'qty', w.qty,
          'is_lot', w.is_lot
        )
        order by w.display_sku
      ), '[]'::jsonb) as rows
      from with_reasons w
      where w.has_photo
        and w.ask_cents is not null and w.ask_cents > 0
        and w.acquisition_cost_cents is not null
        and w.has_specs
        and w.show_on_website
        and w.ebay_status = 'allow'
        and cardinality(w.blockers) = 0
    ),
    not_ready_rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'sku', w.display_sku,
          'title', w.display_title,
          'brand', w.brand,
          'model', w.model,
          'ask_cents', w.ask_cents,
          'listed_on', to_jsonb(coalesce(w.online_on, '{}'::text[])),
          'reasons', to_jsonb(w.blockers),
          'qty', w.qty,
          'is_lot', w.is_lot
        )
        order by w.display_sku
      ), '[]'::jsonb) as rows
      from with_reasons w
      where cardinality(w.blockers) > 0
    ),
    not_listable_rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'sku', d.display_sku,
          'title', d.display_title,
          'brand', d.brand,
          'model', d.model,
          'ask_cents', d.ask_cents,
          'listed_on', to_jsonb(coalesce(d.online_on, '{}'::text[])),
          'reasons', to_jsonb(array[d.not_listable_reason]),
          'qty', d.qty,
          'is_lot', d.is_lot
        )
        order by d.display_sku
      ), '[]'::jsonb) as rows
      from scored d
      where d.not_listable_reason is not null
        and coalesce(cardinality(d.online_on), 0) = 0
    ),
    msc_rows as (
      select coalesce(jsonb_agg(
        jsonb_build_object(
          'sku', d.display_sku,
          'title', d.display_title,
          'brand', d.brand,
          'model', d.model,
          'ask_cents', d.ask_cents,
          'listed_on', to_jsonb(coalesce(d.online_on, '{}'::text[])),
          'missing', (
            select coalesce(jsonb_agg(c), '[]'::jsonb)
            from unnest(v_msc_channels) c
            where not (c = any (coalesce(d.online_on, '{}'::text[])))
          ),
          'qty', d.qty,
          'is_lot', d.is_lot
        )
        order by d.display_sku
      ), '[]'::jsonb) as rows
      from display_units d
      where d.rn = 1
        and d.state = 'available'
        and 'ebay' = any (coalesce(d.online_on, '{}'::text[]))
        and (not d.is_lot or d.qty > 0)
        and exists (
          select 1 from unnest(v_msc_channels) c
          where not (c = any (coalesce(d.online_on, '{}'::text[])))
        )
    )
    select jsonb_build_object(
      'channels', to_jsonb(v_channels),
      'inventory_total', v_inventory_total,
      'listed', (select rows from listed_rows),
      'ready', (select rows from ready_rows),
      'not_ready', (select rows from not_ready_rows),
      'not_listable', (select rows from not_listable_rows),
      'facebook_only', (select rows from not_listable_rows),
      'msc', (select rows from msc_rows)
    )
  );
end
$$;


ALTER FUNCTION "public"."portal_online_board"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_online_channel_counts"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_channels text[] := array['ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook'];
  v_counts jsonb;
  v_unique int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;

  select coalesce(jsonb_object_agg(c.channel, c.n), '{}'::jsonb)
  into v_counts
  from (
    select ch.channel,
      case
        when ch.channel = 'amazon' then greatest(
          coalesce((
            select count(*)::int from public.listings l
            join public.units u on u.store_id = l.store_id and u.sku = l.sku
            where l.store_id = v_store and l.status = 'listed' and lower(l.channel) = 'amazon'
              and u.state in ('available', 'reserved', 'repair')
          ), 0),
          coalesce((
            select count(*)::int from public.amazon_list_items a
            join public.units u on u.store_id = a.store_id and u.sku = a.sku
            where a.store_id = v_store and a.status = 'live'
              and u.state in ('available', 'reserved', 'repair')
          ), 0)
        )
        else coalesce((
          select count(*)::int from public.listings l
          join public.units u on u.store_id = l.store_id and u.sku = l.sku
          where l.store_id = v_store
            and l.status = 'listed'
            and lower(l.channel) = ch.channel
            and u.state in ('available', 'reserved', 'repair')
        ), 0)
      end as n
    from unnest(v_channels) as ch(channel)
  ) c;

  select count(distinct l.sku)::int into v_unique
  from public.listings l
  join public.units u on u.store_id = l.store_id and u.sku = l.sku
  where l.store_id = v_store
    and l.status = 'listed'
    and lower(l.channel) = any (v_channels)
    and u.state in ('available', 'reserved', 'repair');

  v_unique := v_unique + coalesce((
    select count(*)::int from public.amazon_list_items a
    join public.units u on u.store_id = a.store_id and u.sku = a.sku
    where a.store_id = v_store and a.status = 'live'
      and u.state in ('available', 'reserved', 'repair')
      and not exists (
        select 1 from public.listings l
        where l.store_id = a.store_id and l.sku = a.sku and l.status = 'listed'
          and lower(l.channel) = any (v_channels)
      )
  ), 0);

  return v_counts || jsonb_build_object('listed_unique', v_unique);
end $$;


ALTER FUNCTION "public"."portal_online_channel_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_online_report"("p_year" integer DEFAULT NULL::integer, "p_month" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_tz text := 'America/Los_Angeles';
  v_month_start timestamptz;
  v_month_end timestamptz;
  v_all_time boolean := (p_year is null or p_month is null);
  v_label text;
  v_now timestamptz := now();
  v_is_future boolean := false;
  v_is_current_month boolean := false;
  v_channels text[] := array['ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook', 'website'];
  v_list_channels text[] := array['ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook'];
  v_online_sold text[] := array[
    'ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook',
    'website', 'web', 'vendoo', 'offerup', 'craigslist', 'etsy', 'poshmark'
  ];
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;

  if v_all_time then
    v_month_start := timestamptz '1970-01-01';
    v_month_end := timestamptz '2100-01-01';
    v_label := 'All time';
  else
    if p_month < 1 or p_month > 12 then
      raise exception 'invalid_month' using errcode = '22023';
    end if;
    v_month_start := make_timestamptz(p_year, p_month, 1, 0, 0, 0, v_tz);
    v_month_end := v_month_start + interval '1 month';
    v_label := to_char(v_month_start at time zone v_tz, 'FMMonth YYYY');
    v_is_future := v_month_start > v_now;
    v_is_current_month := v_now >= v_month_start and v_now < v_month_end;
  end if;

  return jsonb_build_object(
    'all_time', v_all_time,
    'year', p_year,
    'month', p_month,
    'month_start', v_month_start,
    'month_end', v_month_end,
    'month_label', v_label,
    'listed_mode', case
      when v_all_time then 'live_now'
      when v_is_future then 'future'
      when v_is_current_month then 'live_now'
      else 'put_up_in_period'
    end,
    'by_platform', coalesce((
      select jsonb_agg(jsonb_build_object(
        'channel', p.channel,
        'listed', p.listed,
        'sold', p.sold,
        'sold_cents', p.sold_cents
      ) order by p.channel)
      from (
        select ch.channel,
          case
            when ch.channel = 'website' then 0
            when v_is_future then 0
            when v_all_time or v_is_current_month then coalesce((
              select count(*)::int from public.listings l
              join public.units u on u.store_id = l.store_id and u.sku = l.sku
              where l.store_id = v_store and l.status = 'listed' and lower(l.channel) = ch.channel
                and u.state in ('available', 'reserved', 'repair')
            ), 0)
            else coalesce((
              -- Past month: listings first stamped in that month (0 if none yet / before tracker)
              select count(*)::int from public.listings l
              where l.store_id = v_store and lower(l.channel) = ch.channel
                and l.listed_at is not null
                and l.listed_at >= v_month_start and l.listed_at < v_month_end
            ), 0)
          end as listed,
          case when v_is_future then 0 else coalesce((
            select count(*)::int from public.sales s
            where s.store_id = v_store and s.voided_at is null
              and (
                lower(coalesce(nullif(btrim(s.channel), ''), '')) = ch.channel
                or (ch.channel = 'website' and lower(coalesce(nullif(btrim(s.channel), ''), '')) in ('website', 'web'))
              )
              and s.sold_at >= v_month_start and s.sold_at < v_month_end
          ), 0) end as sold,
          case when v_is_future then 0 else coalesce((
            select coalesce(sum(s.price_cents), 0)::bigint from public.sales s
            where s.store_id = v_store and s.voided_at is null
              and (
                lower(coalesce(nullif(btrim(s.channel), ''), '')) = ch.channel
                or (ch.channel = 'website' and lower(coalesce(nullif(btrim(s.channel), ''), '')) in ('website', 'web'))
              )
              and s.sold_at >= v_month_start and s.sold_at < v_month_end
          ), 0) end as sold_cents
        from unnest(v_channels) as ch(channel)
      ) p
    ), '[]'::jsonb),
    'sold_total_this_month', case when v_is_future then 0 else (
      select coalesce(sum(x.sold), 0)::int
      from (
        select coalesce((
          select count(*)::int from public.sales s
          where s.store_id = v_store and s.voided_at is null
            and (
              lower(coalesce(nullif(btrim(s.channel), ''), '')) = ch.channel
              or (ch.channel = 'website' and lower(coalesce(nullif(btrim(s.channel), ''), '')) in ('website', 'web'))
            )
            and s.sold_at >= v_month_start and s.sold_at < v_month_end
        ), 0) as sold
        from unnest(v_channels) as ch(channel)
      ) x
    ) end,
    'sold_cents_total', case when v_is_future then 0 else (
      select coalesce(sum(x.sold_cents), 0)::bigint
      from (
        select coalesce((
          select coalesce(sum(s.price_cents), 0)::bigint from public.sales s
          where s.store_id = v_store and s.voided_at is null
            and (
              lower(coalesce(nullif(btrim(s.channel), ''), '')) = ch.channel
              or (ch.channel = 'website' and lower(coalesce(nullif(btrim(s.channel), ''), '')) in ('website', 'web'))
            )
            and s.sold_at >= v_month_start and s.sold_at < v_month_end
        ), 0) as sold_cents
        from unnest(v_channels) as ch(channel)
      ) x
    ) end,
    'currently_listed_total', case
      when v_is_future then 0
      when v_all_time or v_is_current_month then (
        select count(*)::int from public.listings l
        join public.units u on u.store_id = l.store_id and u.sku = l.sku
        where l.store_id = v_store and l.status = 'listed'
          and lower(l.channel) = any (v_list_channels)
          and u.state in ('available', 'reserved', 'repair')
      )
      else (
        select count(*)::int from public.listings l
        where l.store_id = v_store
          and lower(l.channel) = any (v_list_channels)
          and l.listed_at is not null
          and l.listed_at >= v_month_start and l.listed_at < v_month_end
      )
    end,
    'available_years', coalesce((
      select jsonb_agg(y order by y desc)
      from (
        select distinct extract(year from s.sold_at at time zone v_tz)::int as y
        from public.sales s
        where s.store_id = v_store and s.voided_at is null
          and lower(coalesce(nullif(btrim(s.channel), ''), '')) = any (v_online_sold)
        union
        select distinct extract(year from l.listed_at at time zone v_tz)::int as y
        from public.listings l
        where l.store_id = v_store and l.listed_at is not null
        union
        select extract(year from now() at time zone v_tz)::int
        union
        select extract(year from now() at time zone v_tz)::int + 1
      ) yrs
      where y is not null
    ), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."portal_online_report"("p_year" integer, "p_month" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_online_settings"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id();
begin
 if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
 return jsonb_build_object(
  'ship_excluded_categories',public.store_setting(v_store,'ship_excluded_categories','[]'::jsonb),
  'ship_excluded_keywords',public.store_setting(v_store,'ship_excluded_keywords','[]'::jsonb),
  'ship_max_weight_lb',public.store_setting(v_store,'ship_max_weight_lb','70'::jsonb),
  'ship_max_length_in',public.store_setting(v_store,'ship_max_length_in','108'::jsonb),
  'ship_max_length_girth_in',public.store_setting(v_store,'ship_max_length_girth_in','130'::jsonb),
  'pickup_hold_hours',public.store_setting(v_store,'pickup_hold_hours','48'::jsonb),
  'order_notify_emails',public.store_setting(v_store,'order_notify_emails','[]'::jsonb),
  'categories',public.store_setting(v_store,'categories','[]'::jsonb),
  'store_tax_bps',public.store_setting(v_store,'taxRateBps','0'::jsonb),
  'tax_origin_state',public.store_setting(v_store,'tax_origin_state','"CA"'::jsonb),
  'tax_out_of_state_bps',public.store_setting(v_store,'tax_out_of_state_bps','0'::jsonb),
  'tax_in_state_ship_bps',public.store_setting(v_store,'tax_in_state_ship_bps','null'::jsonb),
  'tax_shipping',public.store_setting(v_store,'tax_shipping','false'::jsonb),
  'manual_shipping_tiers',public.store_setting(v_store,'manual_shipping_tiers','[]'::jsonb),
  'manual_oversize_cents',public.store_setting(v_store,'manual_oversize_cents','30175'::jsonb),
  'marketplace_channels',public.store_setting(v_store,'marketplace_channels','[]'::jsonb),
  'counts',(select jsonb_build_object('listed',count(*),'shippable',count(*) filter(where s.shippable),'pickup_only',count(*) filter(where not s.shippable),'missing_dims',count(*) filter(where s.ship_note='Missing package dimensions or weight'),'ready_when_shipping_on',count(*) filter(where s.shippable)) from public.storefront_items s where s.store_id=v_store),
  'pickup_only_units',coalesce((select jsonb_agg(jsonb_build_object('sku',s.sku,'title',coalesce(nullif(btrim(s.title),''),concat_ws(' ',s.brand,s.model)),'category',s.category,'reason',s.ship_note) order by s.sku) from public.storefront_items s where s.store_id=v_store and not s.shippable),'[]'::jsonb));
end $$;


ALTER FUNCTION "public"."portal_online_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_online_sold"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_online text[] := array[
    'ebay', 'depop', 'whatnot', 'mercari', 'amazon', 'tiktok', 'facebook',
    'website', 'web', 'vendoo', 'offerup', 'craigslist', 'etsy', 'poshmark'
  ];
  v_limit int := greatest(coalesce(p_limit, 500), 1);
begin
  if v_store is null then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(x order by x->>'sold_at' desc)
    from (
      select x
      from (
        select jsonb_build_object(
          'sku', u.sku,
          'title', coalesce(nullif(btrim(u.title), ''), nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), 'Item'),
          'brand', u.brand,
          'model', u.model,
          'state', u.state,
          'ask_cents', u.ask_cents,
          'listed_on', to_jsonb(coalesce(u.listed_on, '{}'::text[])),
          'sold_at', s.sold_at,
          'sold_channel', lower(coalesce(s.channel, 'unknown')),
          'sold_price_cents', s.price_cents,
          'qty', 1,
          'is_lot', false,
          'match_status', 'matched',
          'needs_sku', false
        ) as x
        from public.units u
        join lateral (
          select ss.sold_at, ss.channel, ss.price_cents
          from public.sales ss
          where ss.store_id = u.store_id and ss.sku = u.sku
            and ss.voided_at is null
          order by ss.sold_at desc nulls last
          limit 1
        ) s on true
        where u.store_id = v_store
          and u.state = 'sold'
          and lower(coalesce(nullif(btrim(s.channel), ''), '')) = any (v_online)

        union all

        select jsonb_build_object(
          'sku', o.sku,
          'title', coalesce(
            nullif(btrim(o.marketplace_title), ''),
            initcap(coalesce(o.channel, 'marketplace')) || ' sale'
          ),
          'brand', null,
          'model', null,
          'state', 'unmatched',
          'ask_cents', o.item_cents,
          'listed_on', '[]'::jsonb,
          'sold_at', coalesce(o.paid_at, o.created_at),
          'sold_channel', lower(coalesce(o.channel, 'unknown')),
          'sold_price_cents', o.item_cents,
          'qty', 1,
          'is_lot', false,
          'match_status', o.match_status,
          'needs_sku', true,
          'web_order_id', o.id,
          'order_no', o.order_no
        ) as x
        from public.web_orders o
        where o.store_id = v_store
          and o.sale_id is null
          and o.match_status in ('unmatched', 'already_sold')
          and (o.status = 'paid' or o.paid_at is not null)
          and coalesce(o.payment_env, 'production') <> 'sandbox'
          and lower(coalesce(o.order_no, '')) not like 'sandbox%'
          and lower(coalesce(o.channel, '')) = any (v_online)
      ) combined
      order by combined.x->>'sold_at' desc nulls last
      limit v_limit
    ) q
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."portal_online_sold"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_overhead_total"("p_start" "date", "p_end" "date") RETURNS bigint
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return coalesce((select sum(amount_cents) from public.portal_overhead
    where store_id = v_store and voided_at is null and spent_on >= p_start and spent_on < p_end), 0);
end $$;


