CREATE OR REPLACE FUNCTION "public"."portal_payout_sales"() RETURNS TABLE("id" bigint, "ticket_key" "text", "sku" "text", "title" "text", "qty" integer, "sold_at" timestamp with time zone, "price_cents" integer, "tax_cents" integer, "card_fee_cents" integer, "cost_cents" integer, "payment_method" "text", "cash_cents" integer, "card_cents" integer, "actor_id" "uuid", "actor_name" "text", "channel" "text", "receipt_no" "text", "ebay_fee_cents" integer, "baked_ship_cents" integer, "cost_source" "text", "channel_fee_cents" integer, "fee_source" "text", "ship_cost_cents" integer, "ship_cost_source" "text", "processing_fee_cents" integer, "processing_fee_source" "text", "tax_remitted_by" "text", "tax_collected_cents" integer, "tax_owed_cents" integer, "ask_cents" integer, "variance_cents" integer, "profit_cents" integer, "shipping_cents" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return query
    select l.id, coalesce(l.ticket_id::text, 'sale:' || l.id::text), l.sku,
      coalesce(nullif(btrim(concat_ws(' ', l.brand, l.model)), ''), 'Item')::text,
      l.qty, l.sold_at, l.price_cents, l.tax_cents, l.card_fee_cents,
      l.cost_cents, l.payment_method, l.cash_cents, l.card_cents,
      l.actor_id, coalesce(l.actor_name, 'Unknown')::text, l.channel, l.receipt_no,
      case when lower(l.channel) = 'ebay' then l.channel_fee_cents else 0 end,
      case when lower(l.channel) = 'ebay' then l.ship_cost_cents else 0 end,
      l.cost_source, l.channel_fee_cents, l.fee_source,
      l.ship_cost_cents, l.ship_cost_source,
      l.processing_fee_cents, l.processing_fee_source,
      l.tax_remitted_by, l.tax_collected_cents, l.tax_owed_cents,
      l.ask_cents, l.variance_cents, l.profit_cents,
      coalesce(l.shipping_cents, 0)
    from public.sale_ledger l
    where l.store_id = v_store and l.voided_at is null
    order by l.id;
end $$;


