CREATE OR REPLACE FUNCTION "public"."portal_receipts"("p_query" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
  v_limit int := greatest(1, least(coalesce(p_limit, 100), 500));
  v_offset int := greatest(0, coalesce(p_offset, 0));
  v_total int;
  v_rows jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;

  select count(*)::int into v_total
  from (
    select coalesce(s.ticket_id::text, 'sale:' || s.id::text) as ticket_key
    from public.sales s
    left join public.units u on u.store_id = s.store_id and u.sku = s.sku
    left join lateral (
      select w.order_no, w.buyer_name, w.buyer_email
      from public.web_orders w where w.sale_id = s.id order by w.created_at limit 1
    ) wo on true
    where s.store_id = v_store and s.voided_at is null
      and (
        v_q is null
        or s.receipt_no ilike '%' || v_q || '%'
        or s.sku = v_q
        or lower(s.channel) = lower(v_q)
        or u.brand ilike '%' || v_q || '%'
        or u.model ilike '%' || v_q || '%'
        or u.title ilike '%' || v_q || '%'
        or wo.order_no ilike '%' || v_q || '%'
        or wo.buyer_name ilike '%' || v_q || '%'
        or wo.buyer_email ilike '%' || v_q || '%'
      )
    group by 1

    union all

    select 'unmatched:' || o.id::text
    from public.web_orders o
    where o.store_id = v_store
      and o.sale_id is null
      and o.match_status in ('unmatched', 'already_sold')
      and (o.status = 'paid' or o.paid_at is not null)
      and coalesce(o.payment_env, 'production') <> 'sandbox'
      and lower(coalesce(o.order_no, '')) not like 'sandbox%'
      and (
        v_q is null
        or o.order_no ilike '%' || v_q || '%'
        or o.sku = v_q
        or lower(o.channel) = lower(v_q)
        or o.marketplace_title ilike '%' || v_q || '%'
        or o.buyer_name ilike '%' || v_q || '%'
        or o.buyer_email ilike '%' || v_q || '%'
      )
  ) t;

  select coalesce(jsonb_agg(to_jsonb(r) order by r.sold_at desc), '[]'::jsonb) into v_rows
  from (
    select * from (
      select
        coalesce(s.ticket_id::text, 'sale:' || s.id::text) as ticket_key,
        coalesce(max(s.receipt_no), max(wo.order_no), min(s.id)::text) as receipt_no,
        min(s.sold_at) as sold_at,
        lower(max(s.channel)) as channel,
        max(s.payment_method) as payment_method,
        max(s.card_brand) as card_brand,
        max(s.card_last4) as card_last4,
        max(te.cash_cents) as cash_cents,
        max(te.card_cents) as card_cents,
        coalesce(
          max(st.display_name),
          case when lower(max(s.channel)) = 'floor' then 'Unknown' else initcap(max(s.channel)) end
        ) as actor_name,
        max(wo.buyer_name) as buyer_name,
        max(wo.buyer_email) as buyer_email,
        max(wo.order_no) as order_no,
        coalesce(sum(s.price_cents), 0)::int as subtotal_cents,
        coalesce(sum(s.tax_cents), 0)::int as tax_cents,
        coalesce(sum(s.card_fee_cents), 0)::int as card_fee_cents,
        coalesce(sum(s.price_cents + coalesce(s.tax_cents, 0) + coalesce(s.card_fee_cents, 0)), 0)::int as total_cents,
        coalesce(sum(coalesce(l.shipping_cents, 0)), 0)::int as shipping_cents,
        coalesce(sum(coalesce(l.channel_fee_cents, 0)), 0)::int as fee_cents,
        coalesce(sum(coalesce(l.ship_cost_cents, 0)), 0)::int as label_cents,
        coalesce(sum(coalesce(l.processing_fee_cents, 0)), 0)::int as processing_cents,
        coalesce(sum(coalesce(l.cost_cents, 0)), 0)::int as cost_cents,
        coalesce(sum(coalesce(l.profit_cents, 0)), 0)::int as profit_cents,
        false as needs_sku,
        jsonb_agg(jsonb_build_object(
          'id', s.id,
          'sku', s.sku,
          'title', coalesce(nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), nullif(u.title, ''), 'Item'),
          'condition', u.condition,
          'qty', s.qty,
          'price_cents', s.price_cents,
          'tax_cents', coalesce(s.tax_cents, 0),
          'card_fee_cents', coalesce(s.card_fee_cents, 0),
          'list_price_cents', s.list_price_cents
        ) order by s.id) as lines
      from public.sales s
      left join public.sale_ledger l on l.id = s.id
      left join public.units u on u.store_id = s.store_id and u.sku = s.sku
      left join public.staff st on st.store_id = s.store_id and st.user_id = s.actor_id
      left join public.ticket_extras te on te.store_id = s.store_id and te.ticket_id = s.ticket_id
      left join lateral (
        select w.buyer_name, w.buyer_email, w.order_no
        from public.web_orders w where w.sale_id = s.id order by w.created_at limit 1
      ) wo on true
      where s.store_id = v_store and s.voided_at is null
        and (
          v_q is null
          or s.receipt_no ilike '%' || v_q || '%'
          or s.sku = v_q
          or lower(s.channel) = lower(v_q)
          or u.brand ilike '%' || v_q || '%'
          or u.model ilike '%' || v_q || '%'
          or u.title ilike '%' || v_q || '%'
          or wo.order_no ilike '%' || v_q || '%'
          or wo.buyer_name ilike '%' || v_q || '%'
          or wo.buyer_email ilike '%' || v_q || '%'
        )
      group by coalesce(s.ticket_id::text, 'sale:' || s.id::text)

      union all

      select
        'unmatched:' || o.id::text as ticket_key,
        coalesce(o.order_no, 'UNMATCHED') as receipt_no,
        coalesce(o.paid_at, o.created_at) as sold_at,
        lower(coalesce(o.channel, 'other')) as channel,
        'marketplace'::text as payment_method,
        null::text as card_brand,
        null::text as card_last4,
        null::int as cash_cents,
        null::int as card_cents,
        initcap(coalesce(o.channel, 'marketplace')) as actor_name,
        o.buyer_name,
        o.buyer_email,
        o.order_no,
        coalesce(o.item_cents, 0) as subtotal_cents,
        coalesce(o.tax_cents, 0) as tax_cents,
        0 as card_fee_cents,
        coalesce(o.total_cents, o.item_cents, 0) as total_cents,
        coalesce(o.shipping_cents, 0) as shipping_cents,
        coalesce(o.marketplace_fee_cents, 0) as fee_cents,
        coalesce(o.label_cost_cents, 0) as label_cents,
        0 as processing_cents,
        0 as cost_cents,
        null::int as profit_cents,
        true as needs_sku,
        jsonb_build_array(jsonb_build_object(
          'id', 0,
          'sku', o.sku,
          'title', coalesce(nullif(btrim(o.marketplace_title), ''), 'Unmatched marketplace sale'),
          'condition', null,
          'qty', 1,
          'price_cents', coalesce(o.item_cents, 0),
          'tax_cents', coalesce(o.tax_cents, 0),
          'card_fee_cents', 0,
          'list_price_cents', null
        )) as lines
      from public.web_orders o
      where o.store_id = v_store
        and o.sale_id is null
        and o.match_status in ('unmatched', 'already_sold')
        and (o.status = 'paid' or o.paid_at is not null)
        and coalesce(o.payment_env, 'production') <> 'sandbox'
        and lower(coalesce(o.order_no, '')) not like 'sandbox%'
        and (
          v_q is null
          or o.order_no ilike '%' || v_q || '%'
          or o.sku = v_q
          or lower(o.channel) = lower(v_q)
          or o.marketplace_title ilike '%' || v_q || '%'
          or o.buyer_name ilike '%' || v_q || '%'
          or o.buyer_email ilike '%' || v_q || '%'
        )
    ) all_rows
    order by sold_at desc
    limit v_limit offset v_offset
  ) r;

  return jsonb_build_object('total', v_total, 'rows', coalesce(v_rows, '[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."portal_receipts"("p_query" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_receive_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_start int;
  v_max bigint;
  v_next bigint;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if (public.store_setting(v_store, 'skuDigits', '5'::jsonb) #>> '{}')::int <> 5 then
    raise exception 'expected_five_digit_skus' using errcode = '22023';
  end if;
  v_start := coalesce((public.store_setting(v_store, 'skuStart', '10000'::jsonb) #>> '{}')::int, 10000);
  select coalesce(max(case when sku ~ '^[0-9]{5}$' and sku < '90000' then sku::bigint end), v_start - 1)
    into v_max
    from public.sku_ledger where store_id = v_store;
  v_next := greatest(v_max + 1, v_start);
  return jsonb_build_object(
    'next_sku', case when v_next <= 89999 then lpad(v_next::text, 5, '0') else null end,
    'categories', public.store_setting(v_store, 'categories', '["Uncategorized"]'::jsonb),
    'conditions', public.store_setting(v_store, 'conditions', '["New","Open box","Excellent","Good","Fair","For parts"]'::jsonb),
    'test_statuses', public.store_setting(v_store, 'testStatuses', '["untested","passed","failed","partial"]'::jsonb),
    'locations', public.store_setting(v_store, 'locations', '["Floor","Back room","Repair bench"]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."portal_receive_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_receive_unit"("p_quantity" integer DEFAULT 1, "p_brand" "text" DEFAULT ''::"text", "p_model" "text" DEFAULT ''::"text", "p_title" "text" DEFAULT ''::"text", "p_description" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_test_status" "text" DEFAULT NULL::"text", "p_ask_cents" integer DEFAULT NULL::integer, "p_cost_cents" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text", "p_upc" "text" DEFAULT NULL::"text", "p_shippable" "text" DEFAULT NULL::"text", "p_length" numeric DEFAULT NULL::numeric, "p_width" numeric DEFAULT NULL::numeric, "p_height" numeric DEFAULT NULL::numeric, "p_weight" numeric DEFAULT NULL::numeric, "p_category" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_start int;
  v_max bigint;
  v_sku text;
  v_skus text[] := array[]::text[];
  v_actor text;
  v_mode text := lower(btrim(coalesce(p_shippable, 'auto')));
  v_override text;
  v_ship boolean;
  v_dim numeric;
  v_upc text := nullif(btrim(coalesce(p_upc, '')), '');
  v_upc_rejected text := null;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if (public.store_setting(v_store, 'skuDigits', '5'::jsonb) #>> '{}')::int <> 5 then
    raise exception 'expected_five_digit_skus' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 100 then
    raise exception 'quantity_must_be_1_to_100' using errcode = '22023';
  end if;
  if coalesce(p_ask_cents, 0) < 0 or coalesce(p_cost_cents, 0) < 0 then
    raise exception 'negative_amount' using errcode = '22023';
  end if;
  foreach v_dim in array array[p_length, p_width, p_height, p_weight] loop
    if v_dim is not null and v_dim <= 0 then
      raise exception 'dims_must_be_positive' using errcode = '22023';
    end if;
  end loop;

  if v_upc is not null and not public.valid_gtin(v_upc) then
    v_upc_rejected := v_upc;
    v_upc := null;
  end if;

  if v_mode in ('', 'auto', 'automatic') then
    v_override := null;
    v_ship := true;
  elsif v_mode in ('yes', 'true', '1', 'ship', 'shippable') then
    v_override := 'ship';
    v_ship := true;
  elsif v_mode in ('no', 'false', '0', 'pickup', 'pickup_only') then
    v_override := 'pickup';
    v_ship := false;
  else
    raise exception 'invalid_shippable' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(687593, hashtext(v_store::text));
  v_start := coalesce((public.store_setting(v_store, 'skuStart', '10000'::jsonb) #>> '{}')::int, 10000);
  select coalesce(max(case when sku ~ '^[0-9]{5}$' and sku < '90000' then sku::bigint end), v_start - 1)
    into v_max
    from public.sku_ledger where store_id = v_store;
  v_max := greatest(v_max, v_start - 1);
  if v_max + p_quantity > 89999 then
    raise exception 'sku_exhausted' using errcode = '22023';
  end if;
  select coalesce(st.display_name, split_part(au.email, '@', 1), 'admin') into v_actor
    from auth.users au
    left join public.staff st on st.user_id = au.id and st.store_id = v_store
    where au.id = auth.uid();

  for i in 1..p_quantity loop
    v_sku := lpad((v_max + i)::text, 5, '0');
    insert into public.sku_ledger(store_id, sku, issued_at, label, fate)
      values (v_store, v_sku, now(), coalesce(p_title, ''), 'issued');
    insert into public.units(
      store_id, sku, brand, model, title, category, listing_body, condition, test_status,
      defect_notes, upc, upc_rejected, acquisition_cost_cents, ask_cents, state, show_on_website,
      shippable, fulfillment_override,
      package_length_in, package_width_in, package_height_in, package_weight_lb,
      dims_source, received_at, updated_at
    ) values (
      v_store, v_sku,
      coalesce(p_brand, ''), coalesce(p_model, ''), coalesce(p_title, ''),
      nullif(btrim(coalesce(p_category, '')), ''),
      nullif(btrim(coalesce(p_description, '')), ''),
      p_condition, p_test_status,
      nullif(btrim(coalesce(p_notes, '')), ''),
      v_upc, v_upc_rejected,
      p_cost_cents, p_ask_cents, 'available', true,
      v_ship, v_override,
      p_length, p_width, p_height, p_weight,
      case when p_length is not null or p_width is not null or p_height is not null or p_weight is not null
        then 'verified' else null end,
      now(), now()
    );
    insert into public.events(store_id, sku, kind, actor, actor_id)
      values (v_store, v_sku, 'received', v_actor, auth.uid());
    v_skus := array_append(v_skus, v_sku);
  end loop;
  return jsonb_build_object('skus', to_jsonb(v_skus));
end;
$_$;


ALTER FUNCTION "public"."portal_receive_unit"("p_quantity" integer, "p_brand" "text", "p_model" "text", "p_title" "text", "p_description" "text", "p_condition" "text", "p_test_status" "text", "p_ask_cents" integer, "p_cost_cents" integer, "p_notes" "text", "p_upc" "text", "p_shippable" "text", "p_length" numeric, "p_width" numeric, "p_height" numeric, "p_weight" numeric, "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_reject_match"("p_suggestion" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id(); v_sku text;
begin
  if v_store is null then raise exception 'Admin access required'; end if;
  update public.photo_enrichment_suggestions set status='rejected',decided_at=now(),decided_by=auth.uid()
    where id=p_suggestion and store_id=v_store and status='review' returning sku into v_sku;
  if v_sku is null then raise exception 'Review match not found'; end if;
  update public.photo_enrichment_queue set status='pending',next_attempt_at=now()
    where store_id=v_store and sku=v_sku;
end $$;


