    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return public.return_settings(v_store);
end $$;


ALTER FUNCTION "public"."portal_return_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_returns"("p_status" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 200) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_status text := nullif(lower(btrim(coalesce(p_status, ''))), '');
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return coalesce((
    select jsonb_agg(x order by
      case when x.needs_decision then 0 else 1 end,
      x.decision_deadline_at nulls last,
      x.created_at desc)
    from (
      select r.*,
        coalesce(nullif(btrim(u.title),''), nullif(btrim(concat_ws(' ', u.brand, u.model)),''), 'Item') as title,
        u.condition as unit_condition,
        u.ask_cents,
        u.state as unit_state,
        (select count(*)::int from public.return_photos p where p.return_id = r.id) as photo_count,
        s.name as supplier_name,
        extract(epoch from (r.decision_deadline_at - now())) as decision_seconds_left
      from public.returns r
      left join public.units u on u.store_id = r.store_id and u.sku = r.sku
      left join public.suppliers s on s.id = r.supplier_id
      where r.store_id = v_store
        and (v_status is null or r.status = v_status
             or (v_status = 'open' and r.status not in ('closed','canceled','denied','refunded_no_return'))
             or (v_status = 'needs_decision' and r.needs_decision and r.status = 'requested'))
      order by r.created_at desc
      limit greatest(1, least(coalesce(p_limit, 200), 500))
    ) x
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_returns"("p_status" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_review_matches"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id(); v_result jsonb;
begin
  if v_store is null then raise exception 'Admin access required'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',s.id,'sku',s.sku,'unit_name',concat_ws(' ',u.brand,coalesce(nullif(u.model,''),u.title)),
    'own_photo_path',s.own_photo_path,'candidate_paths',a.candidate_paths,
    'source_url',a.source_url,'source_title',a.source_title,
    'description',a.description,'specs',a.specs,
    'confidence',s.confidence,'visual_score',s.visual_score,'text_score',s.text_score,
    'reason',s.reason,'created_at',s.created_at
  ) order by s.created_at desc),'[]'::jsonb) into v_result
  from public.photo_enrichment_suggestions s
  join public.photo_enrichment_assets a on a.id=s.asset_id and a.store_id=s.store_id
  join public.units u on u.store_id=s.store_id and u.sku=s.sku
  where s.store_id=v_store and s.status='review';
  return v_result;
end $$;


ALTER FUNCTION "public"."portal_review_matches"() OWNER TO "postgres";


