CREATE OR REPLACE FUNCTION "public"."portal_sale_tax_rows"("p_start" "date", "p_end" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_from timestamptz;
  v_to timestamptz;
  v_pct numeric;
  v_comm numeric;
  v_remitted text[];
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_from := p_start::timestamp at time zone 'America/Los_Angeles';
  v_to := (p_end + 1)::timestamp at time zone 'America/Los_Angeles';
  v_pct := coalesce((public.store_setting(v_store, 'income_tax_pct', '25'::jsonb) #>> '{}')::numeric, 25);
  v_comm := coalesce((public.store_setting(v_store, 'income_tax_commission_pct', '30'::jsonb) #>> '{}')::numeric, 30);
  v_remitted := public.setting_text_array(v_store, 'tax_remitted_channels');

  return jsonb_build_object(
    'start', p_start,
    'end', p_end,
    'income_tax_pct', v_pct,
    'commission_pct', v_comm,
    'rows', coalesce((
      select jsonb_agg(r order by r.sold_at desc)
      from (
        select
          l.id,
          l.sold_at,
          lower(l.channel) as channel,
          l.sku,
          coalesce(
            nullif(btrim(concat_ws(' ', u.brand, u.model)), ''),
            nullif(btrim(u.title), ''),
            'SKU ' || l.sku
          ) as title,
          l.price_cents,
          coalesce(l.shipping_cents, 0) as shipping_cents,
          coalesce(l.cost_cents, 0) as cost_cents,
          coalesce(l.channel_fee_cents, 0) as fee_cents,
          coalesce(l.ship_cost_cents, 0) as label_cents,
          coalesce(l.processing_fee_cents, 0) as processing_cents,
          coalesce(l.profit_cents, 0) as profit_cents,
          greatest(0, round(greatest(coalesce(l.profit_cents, 0), 0) * v_comm / 100.0))::int as commission_cents,
          greatest(0, coalesce(l.profit_cents, 0)
            - greatest(0, round(greatest(coalesce(l.profit_cents, 0), 0) * v_comm / 100.0)))::int as owner_base_cents,
          coalesce(l.tax_cents, 0) as sales_tax_cents,
          case
            when lower(l.channel) = any (v_remitted)
              or coalesce(l.tax_remitted_by, '') = 'marketplace'
              then 'marketplace'
            when coalesce(l.tax_owed_cents, l.tax_cents, 0) > 0 then 'store'
            when coalesce(l.tax_cents, 0) = 0 then 'none'
            else 'store'
          end as sales_tax_who,
          case
            when lower(l.channel) = any (v_remitted)
              or coalesce(l.tax_remitted_by, '') = 'marketplace'
              then 0
            else coalesce(l.tax_owed_cents, l.tax_cents, 0)
          end as sales_tax_owed_cents,
          greatest(0, round(
            greatest(0, coalesce(l.profit_cents, 0)
              - greatest(0, round(greatest(coalesce(l.profit_cents, 0), 0) * v_comm / 100.0))
            ) * v_pct / 100.0
          ))::int as income_tax_cents
        from public.sale_ledger l
        left join public.units u on u.store_id = l.store_id and u.sku = l.sku
        where l.store_id = v_store
          and l.voided_at is null
          and l.sold_at >= v_from and l.sold_at < v_to
      ) r
    ), '[]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."portal_sale_tax_rows"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_sales"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("id" bigint, "ticket_key" "text", "sku" "text", "title" "text", "qty" integer, "sold_at" timestamp with time zone, "price_cents" integer, "tax_cents" integer, "card_fee_cents" integer, "cost_cents" integer, "payment_method" "text", "cash_cents" integer, "card_cents" integer, "actor_id" "uuid", "actor_name" "text", "channel" "text", "receipt_no" "text", "list_price_cents" integer, "override_price_cents" integer, "override_reason" "text", "override_by_name" "text", "ebay_fee_cents" integer, "baked_ship_cents" integer, "cost_source" "text", "channel_fee_cents" integer, "fee_source" "text", "ship_cost_cents" integer, "ship_cost_source" "text", "processing_fee_cents" integer, "processing_fee_source" "text", "tax_remitted_by" "text", "tax_collected_cents" integer, "tax_owed_cents" integer, "ask_cents" integer, "variance_cents" integer, "profit_cents" integer, "shipping_cents" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  perform public.portal_assert_admin();
  if p_from is null or p_to is null or p_to <= p_from or p_to > p_from + interval '93 days' then
    raise exception 'invalid_date_range' using errcode = '22023';
  end if;
  return query
    select s.id, coalesce(s.ticket_id::text, 'sale:' || s.id::text), s.sku,
      coalesce(nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), nullif(u.title, ''), 'Item')::text,
      s.qty, s.sold_at, s.price_cents, s.tax_cents, s.card_fee_cents,
      l.cost_cents, s.payment_method, x.cash_cents, x.card_cents,
      s.actor_id,
      case
        when lower(s.channel) is distinct from 'floor' then 'Online'
        when st.display_name is null or st.display_name in ('Admin', 'service') then 'Unassigned'
        else st.display_name
      end::text,
      s.channel, s.receipt_no,
      s.list_price_cents, s.override_price_cents, s.override_reason,
      coalesce(st_override.display_name, 'Unknown')::text,
      case when lower(s.channel) = 'ebay' then l.channel_fee_cents else 0 end,
      case when lower(s.channel) = 'ebay' then l.ship_cost_cents else 0 end,
      l.cost_source, l.channel_fee_cents, l.fee_source,
      l.ship_cost_cents, l.ship_cost_source,
      l.processing_fee_cents, l.processing_fee_source,
      l.tax_remitted_by, l.tax_collected_cents, l.tax_owed_cents,
      l.ask_cents, l.variance_cents, l.profit_cents,
      coalesce(l.shipping_cents, 0)
    from public.sales s
    join public.sale_ledger l on l.id = s.id
    left join public.units u on u.store_id = s.store_id and u.sku = s.sku
    left join public.staff st on st.store_id = s.store_id and st.user_id = s.actor_id
    left join public.staff st_override on st_override.store_id = s.store_id and st_override.user_id = s.override_by
    left join public.ticket_extras x on x.store_id = s.store_id and x.ticket_id = s.ticket_id
    where s.store_id = v_store and s.voided_at is null and s.sold_at >= p_from and s.sold_at < p_to
    order by s.sold_at desc, s.id desc;
end $$;


ALTER FUNCTION "public"."portal_sales"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_save_withdrawal"("p_id" "uuid", "p_source" "text", "p_amount_cents" integer, "p_on" "date", "p_reason" "text", "p_note" "text", "p_person" "uuid" DEFAULT NULL::"uuid", "p_performer" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_source text := lower(btrim(coalesce(p_source, '')));
  v_reason text := lower(btrim(coalesce(p_reason, '')));
  v_id uuid;
  v_payment uuid;
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_source not in ('safe','square','ebay','amazon','tiktok','depop') then
    raise exception 'source_invalid' using errcode = '22023';
  end if;
  if v_source = 'depop' and not exists (select 1 from jsonb_array_elements(
    public.store_setting(v_store,'marketplace_channels','[]'::jsonb)) x
    where x->>'key'='depop') then
    raise exception 'depop_disabled_for_store' using errcode = '22023';
  end if;
  if v_reason not in ('bank_deposit','person_payout','owner_draw','other') then
    raise exception 'reason_invalid' using errcode = '22023';
  end if;
  if p_amount_cents is null or p_amount_cents <= 0 or p_on is null then
    raise exception 'amount_and_date_required' using errcode = '22023';
  end if;
  if v_reason = 'person_payout' then
    if p_person is null or not exists (
      select 1 from public.staff where store_id = v_store
        and user_id = p_person and deactivated_at is null
    ) then raise exception 'active_person_required' using errcode = '22023'; end if;
  elsif p_person is not null then
    raise exception 'person_only_for_payout' using errcode = '22023';
  end if;
  if p_performer is not null and not exists (
    select 1 from public.staff where store_id=v_store and user_id=p_performer
  ) then raise exception 'performer_not_in_store' using errcode = '22023'; end if;
  if v_source = 'safe' then
    if p_id is null then
      insert into public.store_cash_movements
        (store_id, kind, amount_cents, moved_on, reason, note, person_id, performed_by, created_by)
      values (v_store, 'owner_take', p_amount_cents, p_on, v_reason,
        btrim(coalesce(p_note,'')), p_person, coalesce(p_performer,auth.uid()), auth.uid()) returning id into v_id;
    else
      update public.store_cash_movements set amount_cents = p_amount_cents,
        moved_on = p_on, reason = v_reason, note = btrim(coalesce(p_note,'')),
        person_id = p_person, performed_by = coalesce(p_performer,auth.uid()),
        updated_at = now(), updated_by = auth.uid()
      where id = p_id and store_id = v_store and kind = 'owner_take'
        and voided_at is null returning id into v_id;
    end if;
  else
    if p_id is null then
      insert into public.platform_withdrawals
        (store_id, platform, amount_cents, withdrawn_on, reason, note, person_id, performed_by, created_by)
      values (v_store, v_source, p_amount_cents, p_on, v_reason,
        btrim(coalesce(p_note,'')), p_person, coalesce(p_performer,auth.uid()), auth.uid()) returning id into v_id;
    else
      update public.platform_withdrawals set amount_cents = p_amount_cents,
        withdrawn_on = p_on, reason = v_reason, note = btrim(coalesce(p_note,'')),
        person_id = p_person, performed_by = coalesce(p_performer,auth.uid()),
        updated_at = now(), updated_by = auth.uid()
      where id = p_id and store_id = v_store and platform = v_source
        and voided_at is null returning id into v_id;
    end if;
  end if;
  if v_id is null then raise exception 'withdrawal_not_editable' using errcode = 'P0001'; end if;

  select id into v_payment from public.portal_payout_payments
  where store_id = v_store and withdrawal_source = v_source and withdrawal_id = v_id;
  if v_reason = 'person_payout' then
    if v_payment is null then
      insert into public.portal_payout_payments
        (store_id, employee_id, amount_cents, paid_at, paid_by, note,
         withdrawal_source, withdrawal_id)
      values (v_store, p_person, p_amount_cents, p_on::timestamp at time zone 'America/Los_Angeles',
        auth.uid(), nullif(btrim(coalesce(p_note,'')),''), v_source, v_id);
      -- portal_payment_stamp sets paid_at to now on insert; restore the
      -- withdrawal's actual date after its employee check has run.
      update public.portal_payout_payments
      set paid_at = p_on::timestamp at time zone 'America/Los_Angeles'
      where store_id = v_store and withdrawal_source = v_source and withdrawal_id = v_id;
    else
      update public.portal_payout_payments
      set employee_id = p_person, amount_cents = p_amount_cents,
        paid_at = p_on::timestamp at time zone 'America/Los_Angeles',
        note = nullif(btrim(coalesce(p_note,'')),''), voided_at = null
      where id = v_payment;
    end if;
  elsif v_payment is not null then
    update public.portal_payout_payments set voided_at = now() where id = v_payment;
  end if;
  return v_id;
end $$;


ALTER FUNCTION "public"."portal_save_withdrawal"("p_id" "uuid", "p_source" "text", "p_amount_cents" integer, "p_on" "date", "p_reason" "text", "p_note" "text", "p_person" "uuid", "p_performer" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_bay"("p_bay" integer, "p_rows" integer[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := coalesce(public.portal_store_id(),public.current_store_id()); v_row int; v_bin int; v_code text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if not public.is_manager() and public.portal_store_id() is null then
    raise exception 'manager_required' using errcode = '42501'; end if;
  if p_bay is null or p_bay < 1 or p_bay > 9999
    or coalesce(array_length(p_rows,1),0) not between 3 and 4 then
    raise exception 'bay_layout_invalid' using errcode = '22023';
  end if;
  foreach v_bin in array p_rows loop
    if v_bin not in (0,2,3) then
      raise exception 'row_needs_two_or_three_bins_or_none' using errcode = '22023';
    end if;
  end loop;
  insert into public.store_bays(store_id,bay_no,row_bins)
  values (v_store,p_bay,p_rows)
  on conflict (store_id,bay_no) do update
    set row_bins=excluded.row_bins,updated_at=now();
  for v_row in 1..array_length(p_rows,1) loop
    if p_rows[v_row] = 0 then
      v_code := p_bay::text || '-' || v_row::text;
      insert into public.store_locations(store_id,code,bay_no,row_no,bin_no)
      values(v_store,v_code,p_bay,v_row,null) on conflict do nothing;
    else
      for v_bin in 1..p_rows[v_row] loop
        v_code := p_bay::text || '-' || v_row::text || '-' || v_bin::text;
        insert into public.store_locations(store_id,code,bay_no,row_no,bin_no)
        values(v_store,v_code,p_bay,v_row,v_bin) on conflict do nothing;
      end loop;
    end if;
  end loop;
  -- A layout can shrink only if none of the removed slots still hold stock.
  if exists (
    select 1 from public.store_locations l join public.unit_location_stock x
      on x.store_id=l.store_id and x.location_code=l.code
    where l.store_id=v_store and l.bay_no=p_bay
      and (l.row_no>array_length(p_rows,1) or
        (p_rows[l.row_no]=0 and l.bin_no is not null) or
        (p_rows[l.row_no]>0 and (l.bin_no is null or l.bin_no>p_rows[l.row_no])))
  ) then raise exception 'move_stock_before_removing_location' using errcode = 'P0001'; end if;
  delete from public.store_locations l
  where l.store_id=v_store and l.bay_no=p_bay
    and (l.row_no>array_length(p_rows,1) or
      (p_rows[l.row_no]=0 and l.bin_no is not null) or
      (p_rows[l.row_no]>0 and (l.bin_no is null or l.bin_no>p_rows[l.row_no])));
end $$;


ALTER FUNCTION "public"."portal_set_bay"("p_bay" integer, "p_rows" integer[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_bundle_price"("p_bundle" "text", "p_override_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id();
begin
  if v_store is null or not public.is_manager() or not public.is_store_staff(v_store) then
    raise exception 'portal_access_denied' using errcode='42501';
  end if;
  if p_override_cents is not null and p_override_cents<0 then raise exception 'bundle_price_invalid'; end if;
  update public.floor_bundles set price_override_cents=p_override_cents
    where store_id=v_store and sku=p_bundle and active;
  if not found then raise exception 'bundle_not_found'; end if;
  perform public.floor_bundle_refresh(v_store,p_bundle);
end $$;


ALTER FUNCTION "public"."portal_set_bundle_price"("p_bundle" "text", "p_override_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_channel_categories"("p_skus" "text"[], "p_ebay" "text", "p_tiktok" "text", "p_amazon" "text", "p_depop" "text", "p_internal" "text", "p_enabled" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id());
  v_sku text; v_channel text; v_category text; v_count int:=0; v_on text[];
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  v_on:=public.floor_store_listing_channels(v_store);
  if p_skus is null or cardinality(p_skus) < 1 or cardinality(p_skus)>100 then
    raise exception 'invalid_batch' using errcode='22023'; end if;
  if (p_depop is not null or coalesce((p_enabled->>'depop')::boolean,false))
    and not exists(select 1 from jsonb_array_elements(
      public.store_setting(v_store,'marketplace_channels','[]'::jsonb)) x
      where x->>'key'='depop')
    and not exists(select 1 from public.listings l where l.store_id=v_store and l.channel='depop') then
    raise exception 'depop_disabled' using errcode='22023'; end if;
  for v_channel,v_category in select * from (values
    ('ebay',p_ebay),('tiktok',p_tiktok),('amazon',p_amazon),('depop',p_depop)) x(channel,id) loop
    if v_channel<>'depop' and v_category is not null and not exists(select 1 from public.channel_taxonomy t
      where t.channel=v_channel and t.category_id=v_category and t.leaf and t.active) then
      raise exception 'category_not_active_leaf: %',v_channel using errcode='22023'; end if;
  end loop;
  foreach v_sku in array p_skus loop
    if not exists(select 1 from public.units where store_id=v_store and sku=v_sku) then
      raise exception 'unit_not_found' using errcode='22023'; end if;
    if coalesce((p_enabled->>'amazon')::boolean,'amazon' = any(v_on))
      and exists(select 1 from public.floor_bundles b where b.store_id=v_store and b.sku=v_sku and b.active) then
      raise exception 'bundle_amazon_disabled' using errcode='22023'; end if;
    update public.units set internal_category=coalesce(nullif(btrim(p_internal),''),internal_category),
      ebay_category=coalesce(p_ebay,ebay_category), updated_at=now()
      where store_id=v_store and sku=v_sku;
    for v_channel,v_category in select * from (values
      ('ebay',p_ebay),('tiktok',p_tiktok),('amazon',p_amazon),('depop',p_depop)) x(channel,id) loop
      insert into public.unit_channel_categories(store_id,sku,channel,category_id,enabled,updated_at)
      values(v_store,v_sku,v_channel,v_category,coalesce((p_enabled->>v_channel)::boolean,v_channel = any(v_on)),now())
      on conflict(store_id,sku,channel) do update set category_id=excluded.category_id,
        enabled=excluded.enabled,updated_at=now(),source='manual';
    end loop;
    v_count:=v_count+1;
    if p_ebay is not null then
      insert into public.store_category_mappings(store_id,ebay_category_id,tiktok_category_id,
        amazon_product_type,depop_category_id,internal_category,updated_by)
      values(v_store,p_ebay,p_tiktok,p_amazon,p_depop,p_internal,auth.uid())
      on conflict(store_id,ebay_category_id) do update set
        tiktok_category_id=excluded.tiktok_category_id,
        amazon_product_type=excluded.amazon_product_type,
        depop_category_id=excluded.depop_category_id,
        internal_category=coalesce(excluded.internal_category,public.store_category_mappings.internal_category),
        updated_by=excluded.updated_by,updated_at=now();
    end if;
  end loop;
  return v_count;
end $$;


ALTER FUNCTION "public"."portal_set_channel_categories"("p_skus" "text"[], "p_ebay" "text", "p_tiktok" "text", "p_amazon" "text", "p_depop" "text", "p_internal" "text", "p_enabled" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_channel_fee_rate"("p_channel" "text", "p_pct" numeric, "p_fixed_cents" integer, "p_min_fee_cents" integer DEFAULT NULL::integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_store uuid := public.portal_store_id(); v_rates jsonb; v_key text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_key := lower(btrim(coalesce(p_channel, '')));
  if v_key !~ '^[a-z][a-z0-9_]{0,39}$' then raise exception 'invalid_channel'; end if;
  if p_pct is null or p_pct < 0 or p_pct >= 100 then raise exception 'percent_0_to_100_required' using errcode = '22023'; end if;
  v_rates := coalesce(public.store_setting(v_store, 'channel_fee_rates', '{}'::jsonb), '{}'::jsonb);
  v_rates := v_rates || jsonb_build_object(v_key, jsonb_strip_nulls(jsonb_build_object(
    'pct', p_pct, 'fixed_cents', coalesce(p_fixed_cents, 0), 'min_fee_cents', p_min_fee_cents)));
  insert into public.store_settings (store_id, key, value) values (v_store, 'channel_fee_rates', v_rates)
  on conflict (store_id, key) do update set value = excluded.value;
end $_$;


ALTER FUNCTION "public"."portal_set_channel_fee_rate"("p_channel" "text", "p_pct" numeric, "p_fixed_cents" integer, "p_min_fee_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_commission_override"("p_ticket_key" "text", "p_paul_pct" numeric, "p_jacob_pct" numeric, "p_action" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_uid uuid := auth.uid();
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_old public.portal_commission_overrides%rowtype;
  v_def record;
  v_old_paul numeric;
  v_old_jacob numeric;
  v_was_override boolean := false;
  v_new_paul numeric;
  v_new_jacob numeric;
begin
  if v_store is null or v_uid is null then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if p_ticket_key is null or btrim(p_ticket_key) = '' then
    raise exception 'ticket_key_required' using errcode = '22023';
  end if;
  if v_action not in ('set', 'flip', 'reset') then
    raise exception 'invalid_commission_action' using errcode = '22023';
  end if;
  if not public.portal_ticket_exists(v_store, btrim(p_ticket_key)) then
    raise exception 'invalid_payout_ticket' using errcode = '22023';
  end if;
  if v_reason is not null and char_length(v_reason) > 500 then
    raise exception 'reason_too_long' using errcode = '22023';
  end if;

  select * into v_old
  from public.portal_commission_overrides
  where store_id = v_store and ticket_key = btrim(p_ticket_key);

  if found then
    v_was_override := true;
    v_old_paul := v_old.paul_pct;
    v_old_jacob := v_old.jacob_pct;
  else
    select * into v_def from public.portal_default_commission_split(v_store, btrim(p_ticket_key));
    v_old_paul := v_def.paul_pct;
    v_old_jacob := v_def.jacob_pct;
  end if;

  if v_action = 'reset' then
    if not v_was_override then
      return jsonb_build_object(
        'ticket_key', btrim(p_ticket_key),
        'override', null,
        'unchanged', true
      );
    end if;
    delete from public.portal_commission_overrides
    where store_id = v_store and ticket_key = btrim(p_ticket_key);
    insert into public.portal_commission_override_log (
      store_id, ticket_key, changed_by, action,
      old_paul_pct, old_jacob_pct, new_paul_pct, new_jacob_pct,
      was_override, reason
    ) values (
      v_store, btrim(p_ticket_key), v_uid, 'reset',
      v_old_paul, v_old_jacob, null, null,
      true, v_reason
    );
    return jsonb_build_object(
      'ticket_key', btrim(p_ticket_key),
      'override', null,
      'action', 'reset'
    );
  end if;

  if v_action = 'flip' then
    v_new_paul := v_old_jacob;
    v_new_jacob := v_old_paul;
  else
    if p_paul_pct is null or p_jacob_pct is null then
      raise exception 'commission_pct_required' using errcode = '22023';
    end if;
    if p_paul_pct < 0 or p_jacob_pct < 0 then
      raise exception 'commission_pct_negative' using errcode = '22023';
    end if;
    if p_paul_pct > 1000 or p_jacob_pct > 1000 then
      raise exception 'commission_pct_too_large' using errcode = '22023';
    end if;
    v_new_paul := round(p_paul_pct::numeric, 2);
    v_new_jacob := round(p_jacob_pct::numeric, 2);
  end if;

  insert into public.portal_commission_overrides (
    store_id, ticket_key, paul_pct, jacob_pct, updated_at, updated_by
  ) values (
    v_store, btrim(p_ticket_key), v_new_paul, v_new_jacob, now(), v_uid
  )
  on conflict (store_id, ticket_key) do update set
    paul_pct = excluded.paul_pct,
    jacob_pct = excluded.jacob_pct,
    updated_at = now(),
    updated_by = excluded.updated_by;

  insert into public.portal_commission_override_log (
    store_id, ticket_key, changed_by, action,
    old_paul_pct, old_jacob_pct, new_paul_pct, new_jacob_pct,
    was_override, reason
  ) values (
    v_store, btrim(p_ticket_key), v_uid, v_action,
    v_old_paul, v_old_jacob, v_new_paul, v_new_jacob,
    v_was_override, v_reason
  );

  return jsonb_build_object(
    'ticket_key', btrim(p_ticket_key),
    'override', jsonb_build_object(
      'paul_pct', v_new_paul,
      'jacob_pct', v_new_jacob
    ),
    'action', v_action
  );
end;
$$;


ALTER FUNCTION "public"."portal_set_commission_override"("p_ticket_key" "text", "p_paul_pct" numeric, "p_jacob_pct" numeric, "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_cost_default"("p_category" "text", "p_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_store uuid := public.portal_store_id(); v_map jsonb; v_key text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_key := lower(btrim(coalesce(p_category, '')));
  if v_key !~ '^[a-z][a-z0-9_ ]{0,39}$' then raise exception 'invalid_category'; end if;
  if p_cents is null or p_cents < 0 then raise exception 'cost_must_not_be_negative' using errcode = '22023'; end if;
  v_map := coalesce(public.store_setting(v_store, 'cost_defaults', '{}'::jsonb), '{}'::jsonb) || jsonb_build_object(v_key, p_cents);
  insert into public.store_settings (store_id, key, value) values (v_store, 'cost_defaults', v_map)
  on conflict (store_id, key) do update set value = excluded.value;
end $_$;


ALTER FUNCTION "public"."portal_set_cost_default"("p_category" "text", "p_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_cost_defaults"("p_defaults" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_keys text[] := array['refrigerators','dishwashers','mattresses','other']; k text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if jsonb_typeof(p_defaults) <> 'object' then raise exception 'invalid_defaults' using errcode = '22023'; end if;
  foreach k in array v_keys loop
    if coalesce((p_defaults->>k)::int, -1) < 0 then raise exception 'invalid_defaults' using errcode = '22023'; end if;
  end loop;
  insert into public.store_settings (store_id, key, value)
  values (v_store, 'cost_defaults', jsonb_build_object(
    'refrigerators', (p_defaults->>'refrigerators')::int,
    'dishwashers', (p_defaults->>'dishwashers')::int,
    'mattresses', (p_defaults->>'mattresses')::int,
    'other', (p_defaults->>'other')::int
  ))
  on conflict (store_id, key) do update set value = excluded.value;
end $$;


ALTER FUNCTION "public"."portal_set_cost_defaults"("p_defaults" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_income_tax_pct"("p_pct" numeric) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_pct numeric := greatest(0, least(60, coalesce(p_pct, 25)));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  insert into public.store_settings (store_id, key, value)
  values (v_store, 'income_tax_pct', to_jsonb(v_pct))
  on conflict (store_id, key) do update set value = excluded.value;
  return v_pct;
end $$;


ALTER FUNCTION "public"."portal_set_income_tax_pct"("p_pct" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_listing_channels"("p_channels" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  if p_channels is null or exists(select 1 from unnest(p_channels) x where x not in ('ebay','amazon','tiktok','depop')) then
    raise exception 'invalid_channel' using errcode='22023'; end if;
  insert into public.store_settings(store_id,key,value)
  values(v_store,'listing_channels',to_jsonb(array(select distinct x from unnest(p_channels) x order by x)))
  on conflict(store_id,key) do update set value=excluded.value;
  return public.floor_store_listing_channels(v_store);
end $$;


ALTER FUNCTION "public"."portal_set_listing_channels"("p_channels" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_listing_photo_ids"("p_sku" "text", "p_channel" "text", "p_photo_ids" "text"[], "p_listing_id" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid;
  v_ids text[];
begin
  v_store := public.current_store_id();
  if v_store is null then
    raise exception 'store_missing';
  end if;
  select array_agg(distinct x order by x)
    into v_ids
  from unnest(coalesce(p_photo_ids, '{}'::text[])) as x
  where x ~ '^[0-9]{6,}$';

  insert into public.listings (store_id, sku, channel, status, listing_id, listed_at, photo_ids)
  values (
    v_store,
    btrim(p_sku),
    lower(btrim(p_channel)),
    'listed',
    nullif(btrim(coalesce(p_listing_id, '')), ''),
    now(),
    coalesce(v_ids, '{}'::text[])
  )
  on conflict (sku, channel) do update
    set photo_ids = (
          select coalesce(array_agg(distinct y order by y), '{}'::text[])
          from unnest(public.listings.photo_ids || coalesce(excluded.photo_ids, '{}'::text[])) as y
          where y ~ '^[0-9]{6,}$'
        ),
        listing_id = coalesce(excluded.listing_id, public.listings.listing_id),
        store_id = coalesce(public.listings.store_id, excluded.store_id),
        status = 'listed',
        listed_at = coalesce(public.listings.listed_at, now()),
        delisted_at = null;
end;
$_$;


ALTER FUNCTION "public"."portal_set_listing_photo_ids"("p_sku" "text", "p_channel" "text", "p_photo_ids" "text"[], "p_listing_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_manifest_count"("p_id" "uuid", "p_count" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_count is null or p_count < 0 then raise exception 'count_invalid' using errcode = '22023'; end if;
  update public.store_manifests set item_count = p_count, count_source = 'manual', updated_at = now()
  where id = p_id and store_id = v_store;
  if not found then raise exception 'manifest_not_found' using errcode = 'P0002'; end if;
end $$;


