CREATE OR REPLACE FUNCTION "public"."portal_set_marketplace_policy_rule"("p_channel" "text", "p_enabled" boolean, "p_rules" "jsonb", "p_notes" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_channel text := lower(btrim(coalesce(p_channel, '')));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_channel = '' then raise exception 'channel_required' using errcode = '22023'; end if;
  insert into public.marketplace_policy_rules(store_id, channel, enabled, rules, notes, updated_at, updated_by)
  values (v_store, v_channel, coalesce(p_enabled, true), coalesce(p_rules, '{}'::jsonb), p_notes, now(), auth.uid())
  on conflict (store_id, channel) do update
    set enabled = excluded.enabled, rules = excluded.rules, notes = excluded.notes,
        updated_at = now(), updated_by = auth.uid();
end $$;


ALTER FUNCTION "public"."portal_set_marketplace_policy_rule"("p_channel" "text", "p_enabled" boolean, "p_rules" "jsonb", "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_online_setting"("p_key" "text", "p_value" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_store uuid:=public.portal_store_id();
begin
 if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
 if p_key in ('ship_excluded_categories','ship_excluded_keywords') then
  if jsonb_typeof(p_value)<>'array' or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string') then raise exception 'list_of_text_required' using errcode='22023'; end if;
 elsif p_key='ship_carriers' then
  if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)=0 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string' or btrim(x#>>'{}')='') then raise exception 'at_least_one_carrier_required' using errcode='22023'; end if;
  p_value:=(select jsonb_agg(upper(btrim(x))) from jsonb_array_elements_text(p_value) x);
 elsif p_key='order_notify_emails' then
  if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)=0 or exists(select 1 from jsonb_array_elements_text(p_value) x where x !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') then raise exception 'valid_emails_required' using errcode='22023'; end if;
 elsif p_key in ('ship_max_weight_lb','ship_max_length_in','ship_max_length_girth_in','pickup_hold_hours') then
  if jsonb_typeof(p_value)<>'number' or (p_value#>>'{}')::numeric<=0 then raise exception 'positive_number_required' using errcode='22023'; end if;
 elsif p_key='manual_shipping_tiers' then
  if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)=0 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'object' or (x->>'max_lb') !~ '^([1-9]|[1-6][0-9]|70)$' or (x->>'cents') !~ '^[1-9][0-9]*$') then raise exception 'invalid_shipping_tiers' using errcode='22023'; end if;
 elsif p_key='marketplace_channels' then
  if jsonb_typeof(p_value)<>'array' or jsonb_array_length(p_value)=0 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'object' or coalesce(x->>'key','') !~ '^[a-z][a-z0-9_]{1,39}$' or nullif(btrim(x->>'label'),'') is null or jsonb_typeof(x->'aliases')<>'array') then raise exception 'invalid_marketplace_channels' using errcode='22023'; end if;
  if (select count(*)<>count(distinct x->>'key') from jsonb_array_elements(p_value) x) then raise exception 'duplicate_marketplace_key' using errcode='22023'; end if;
 elsif p_key='tax_origin_state' then
  if jsonb_typeof(p_value)<>'string' or upper(p_value#>>'{}') !~ '^[A-Z]{2}$' then raise exception 'two_letter_state_required' using errcode='22023'; end if; p_value:=to_jsonb(upper(p_value#>>'{}'));
 elsif p_key='tax_out_of_state_bps' then
  if jsonb_typeof(p_value)<>'number' or (p_value#>>'{}')::numeric<0 or (p_value#>>'{}')::numeric>2500 then raise exception 'rate_0_to_2500_bps_required' using errcode='22023'; end if;
 elsif p_key='tax_in_state_ship_bps' then
  if jsonb_typeof(p_value) not in ('number','null') or (jsonb_typeof(p_value)='number' and ((p_value#>>'{}')::numeric<0 or (p_value#>>'{}')::numeric>2500)) then raise exception 'rate_0_to_2500_bps_or_blank_required' using errcode='22023'; end if;
 elsif p_key='tax_shipping' then
  if jsonb_typeof(p_value)<>'boolean' then raise exception 'true_or_false_required' using errcode='22023'; end if;
 else raise exception 'setting_not_editable' using errcode='22023'; end if;
 insert into public.store_settings(store_id,key,value) values(v_store,p_key,p_value) on conflict(store_id,key) do update set value=excluded.value;
end $_$;


ALTER FUNCTION "public"."portal_set_online_setting"("p_key" "text", "p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_order_label_cost"("p_order" "uuid", "p_label_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_order public.web_orders%rowtype;
  v_prev uuid;
  v_owner text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_label_cents is null or p_label_cents < 0 or p_label_cents > 50000 then
    raise exception 'invalid_label_cost';
  end if;
  select * into v_order from public.web_orders where id = p_order and store_id = v_store;
  if not found then raise exception 'order_not_found'; end if;
  if v_order.status <> 'paid' or v_order.fulfillment <> 'ship' then
    raise exception 'order_not_shippable';
  end if;
  if v_order.label_purchased_at is null and coalesce(v_order.pack_condition, '') <> 'ok' then
    raise exception 'Confirm the item matches the listing before recording a label cost.';
  end if;
  update public.web_orders set
    label_cost_cents = p_label_cents,
    label_purchased_at = coalesce(label_purchased_at, now()),
    shipping_rate = case
      when shipping_rate is null or shipping_rate = '{}'::jsonb
        then jsonb_build_object('source', 'manual', 'service', 'Purchased externally')
      else shipping_rate || jsonb_build_object('source', coalesce(shipping_rate->>'source', 'manual'))
    end,
    updated_at = now()
  where id = p_order and store_id = v_store;
  if v_order.payment_id like '%:%' then
    update public.channel_orders set
      ship_label_cents = p_label_cents,
      ship_label_source = case
        when ship_label_source in ('ebay', 'marketplace', 'shippo') then ship_label_source
        else 'manual' end
    where store_id = v_store
      and (order_id = v_order.order_no or order_id = split_part(v_order.payment_id, ':', 2));
  end if;
  select nullif(value #>> '{}', '') into v_owner from public.store_settings
   where store_id = v_store and key = 'online_payout_employee_id';
  if v_owner is not null and v_owner !~* '^[0-9a-f-]{36}$' then v_owner := null; end if;
  select id into v_prev from public.portal_expenses
   where store_id = v_store and order_id = p_order and source = 'manual_label' and voided_at is null
   limit 1;
  if v_prev is not null then
    update public.portal_expenses set
      amount_cents = p_label_cents,
      description = 'Shipping label ' || coalesce(v_order.order_no, p_order::text),
      employee_id = v_owner::uuid,
      needs_reimbursement = (v_owner is not null)
    where id = v_prev;
  elsif p_label_cents > 0 then
    insert into public.portal_expenses(
      store_id, description, category, amount_cents, needs_reimbursement, employee_id, source, order_id)
    values (v_store, 'Shipping label ' || coalesce(v_order.order_no, p_order::text), 'Shipping', p_label_cents, v_owner is not null, v_owner::uuid, 'manual_label', p_order);
  end if;
end $_$;


ALTER FUNCTION "public"."portal_set_order_label_cost"("p_order" "uuid", "p_label_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_pack_condition"("p_order" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_order public.web_orders%rowtype;
  v_title text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_status not in ('ok', 'not_as_listed') then raise exception 'invalid_pack_condition'; end if;
  select * into v_order from public.web_orders where id = p_order and store_id = v_store;
  if not found then raise exception 'order_not_found'; end if;
  update public.web_orders
    set pack_condition = p_status, pack_condition_at = now(), updated_at = now()
    where id = p_order and store_id = v_store;
  if p_status = 'not_as_listed' then
    select title into v_title from public.units where store_id = v_store and sku = v_order.sku;
    insert into public.alert_outbox (store_id, kind, sku, payload)
    values (
      v_store, 'pack_condition', v_order.sku,
      jsonb_build_object('order_id', v_order.id, 'order_no', v_order.order_no, 'channel', v_order.channel, 'buyer_name', v_order.buyer_name, 'title', coalesce(v_title, v_order.sku))
    );
  end if;
end $$;


ALTER FUNCTION "public"."portal_set_pack_condition"("p_order" "uuid", "p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_pack_proof"("p_order" "uuid", "p_photo_path" "text", "p_serial" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_path text := btrim(coalesce(p_photo_path, ''));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_path = '' then raise exception 'photo_required' using errcode = '22023'; end if;
  update public.web_orders set
    pack_proof_photo_path = v_path,
    pack_proof_serial = nullif(btrim(coalesce(p_serial, '')), ''),
    pack_proof_at = now(),
    updated_at = now()
  where id = p_order and store_id = v_store and status = 'paid';
  if not found then raise exception 'order_not_found' using errcode = 'P0001'; end if;
end $$;


ALTER FUNCTION "public"."portal_set_pack_proof"("p_order" "uuid", "p_photo_path" "text", "p_serial" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_payout_config"("p_channels" "jsonb", "p_pct" numeric, "p_employee" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if jsonb_typeof(p_channels) <> 'array' or exists(select 1 from jsonb_array_elements(p_channels) x where jsonb_typeof(x) <> 'string') then
    raise exception 'channel_list_required' using errcode = '22023';
  end if;
  if p_pct is null or p_pct < 0 or p_pct > 100 then raise exception 'percent_0_to_100_required' using errcode = '22023'; end if;
  if p_employee is null or not exists(select 1 from public.staff s where s.user_id = p_employee and s.store_id = v_store and s.deactivated_at is null) then
    raise exception 'recipient_must_be_active_staff' using errcode = '22023';
  end if;
  insert into public.store_settings(store_id, key, value) values
    (v_store, 'online_channels', (select coalesce(jsonb_agg(lower(btrim(x))), '[]'::jsonb) from jsonb_array_elements_text(p_channels) x where btrim(x) <> '')),
    (v_store, 'online_payout_pct', to_jsonb(p_pct)),
    (v_store, 'online_payout_employee_id', to_jsonb(p_employee::text))
  on conflict (store_id, key) do update set value = excluded.value;
end $$;


ALTER FUNCTION "public"."portal_set_payout_config"("p_channels" "jsonb", "p_pct" numeric, "p_employee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_platform_available"("p_platform" "text", "p_available_cents" integer, "p_noted_on" "date" DEFAULT NULL::"date", "p_note" "text" DEFAULT ''::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_id uuid;
  v_plat text := lower(btrim(coalesce(p_platform, '')));
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_plat not in ('square', 'ebay', 'depop', 'amazon', 'tiktok') then
    raise exception 'platform_invalid' using errcode = '22023';
  end if;
  if p_available_cents is null or p_available_cents < 0 then
    raise exception 'amount_required' using errcode = '22023';
  end if;
  insert into public.platform_balance_snapshots (store_id, platform, available_cents, noted_on, note, created_by)
  values (
    v_store,
    v_plat,
    p_available_cents,
    coalesce(p_noted_on, (now() at time zone 'America/Los_Angeles')::date),
    coalesce(btrim(p_note), ''),
    auth.uid()
  )
  returning id into v_id;
  return v_id;
end;
$$;


ALTER FUNCTION "public"."portal_set_platform_available"("p_platform" "text", "p_available_cents" integer, "p_noted_on" "date", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_return_settings"("p_value" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_value is null or jsonb_typeof(p_value) <> 'object' then
    raise exception 'invalid_settings' using errcode = '22023';
  end if;
  v := public.default_return_settings() || p_value;
  insert into public.store_settings (store_id, key, value)
  values (v_store, 'return_settings', v)
  on conflict (store_id, key) do update set value = excluded.value;
  return v;
end $$;


ALTER FUNCTION "public"."portal_set_return_settings"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_return_status"("p_return" "uuid", "p_status" "text", "p_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  r public.returns;
  v_status text := lower(btrim(coalesce(p_status, '')));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  select * into r from public.returns where id = p_return and store_id = v_store for update;
  if not found then raise exception 'return_not_found' using errcode = 'P0001'; end if;
  if v_status not in (
    'requested','approved','in_transit','received','inspected','dispositioned',
    'closed','refunded_no_return','denied','canceled'
  ) then raise exception 'invalid_status' using errcode = '22023'; end if;

  update public.returns set
    status = v_status,
    needs_decision = case when v_status = 'requested' then needs_decision else false end,
    approved_at = case when v_status = 'approved' then coalesce(approved_at, now()) else approved_at end,
    in_transit_at = case when v_status = 'in_transit' then coalesce(in_transit_at, now()) else in_transit_at end,
    received_at = case when v_status = 'received' then coalesce(received_at, now()) else received_at end,
    inspected_at = case when v_status = 'inspected' then coalesce(inspected_at, now()) else inspected_at end,
    closed_at = case when v_status in ('closed','canceled','denied','refunded_no_return') then coalesce(closed_at, now()) else closed_at end,
    refund_cents = coalesce((p_patch->>'refund_cents')::int, refund_cents),
    return_label_cents = coalesce((p_patch->>'return_label_cents')::int, return_label_cents),
    label_paid_by = coalesce(nullif(p_patch->>'label_paid_by',''), label_paid_by),
    unrecovered_fees_cents = coalesce((p_patch->>'unrecovered_fees_cents')::int, unrecovered_fees_cents),
    tracking_number = coalesce(nullif(p_patch->>'tracking_number',''), tracking_number),
    carrier = coalesce(nullif(p_patch->>'carrier',''), carrier),
    inspection_notes = coalesce(nullif(p_patch->>'inspection_notes',''), inspection_notes),
    fault = coalesce(nullif(p_patch->>'fault',''), fault),
    reason = coalesce(nullif(p_patch->>'reason',''), reason),
    updated_at = now()
  where id = r.id
  returning * into r;

  if v_status = 'refunded_no_return' then
    perform public.return_apply_commission_clawbacks(r.id);
    perform public.return_reverse_sale(v_store, r.sale_id, 'Refund without return', false);
    update public.returns set disposition = 'keep_buyer', refunded_at = coalesce(refunded_at, now())
     where id = r.id returning * into r;
    perform public.return_post_ledger(r.id);
  end if;

  return to_jsonb(r);
end $$;


ALTER FUNCTION "public"."portal_set_return_status"("p_return" "uuid", "p_status" "text", "p_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_sale_channel_costs"("p_sale_id" bigint, "p_fee_cents" integer DEFAULT NULL::integer, "p_ship_cents" integer DEFAULT NULL::integer, "p_processing_cents" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_sale public.sales%rowtype;
  v_provider text;
  v_order_id text;
  v_wo_id uuid;
  v_owner text;
  v_prev uuid;
  v_ch text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_fee_cents is null and p_ship_cents is null and p_processing_cents is null then
    raise exception 'nothing_to_update';
  end if;
  if p_fee_cents is not null and (p_fee_cents < 0 or p_fee_cents > 500000) then
    raise exception 'invalid_fee';
  end if;
  if p_ship_cents is not null and (p_ship_cents < 0 or p_ship_cents > 50000) then
    raise exception 'invalid_ship_cost';
  end if;
  if p_processing_cents is not null and (p_processing_cents < 0 or p_processing_cents > 100000) then
    raise exception 'invalid_processing_fee';
  end if;

  select * into v_sale from public.sales where id = p_sale_id and store_id = v_store;
  if not found then raise exception 'sale_not_found'; end if;
  v_ch := lower(coalesce(v_sale.channel, ''));

  if p_processing_cents is not null then
    update public.sales
       set processing_fee_cents = p_processing_cents,
           processing_fee_source = 'actual'
     where id = p_sale_id and store_id = v_store;
  end if;

  if p_fee_cents is not null or p_ship_cents is not null then
    if v_sale.payment_id like '%:%' then
      v_provider := lower(split_part(v_sale.payment_id, ':', 1));
      v_order_id := split_part(v_sale.payment_id, ':', 2);
    else
      v_provider := case when v_ch in ('floor', 'website', '') then 'manual' else v_ch end;
      v_order_id := coalesce(nullif(v_sale.payment_id, ''), 'sale:' || p_sale_id::text);
    end if;

    insert into public.channel_orders as co (
      store_id, provider, order_id, sku, sale_id, item_cents,
      fee_cents, fee_source, ship_label_cents, ship_label_source
    ) values (
      v_store, v_provider, v_order_id, v_sale.sku, p_sale_id, v_sale.price_cents,
      p_fee_cents, case when p_fee_cents is not null then 'manual' else 'estimated' end,
      p_ship_cents, case when p_ship_cents is not null then 'manual' else null end
    )
    on conflict (store_id, provider, order_id) do update set
      sale_id = coalesce(co.sale_id, excluded.sale_id),
      sku = coalesce(co.sku, excluded.sku),
      item_cents = coalesce(co.item_cents, excluded.item_cents),
      fee_cents = case when p_fee_cents is not null then p_fee_cents else co.fee_cents end,
      fee_source = case when p_fee_cents is not null then 'manual' else co.fee_source end,
      ship_label_cents = case when p_ship_cents is not null then p_ship_cents else co.ship_label_cents end,
      ship_label_source = case when p_ship_cents is not null then 'manual' else co.ship_label_source end;

    update public.channel_orders
       set fee_cents = case when p_fee_cents is not null then p_fee_cents else fee_cents end,
           fee_source = case when p_fee_cents is not null then 'manual' else fee_source end,
           ship_label_cents = case when p_ship_cents is not null then p_ship_cents else ship_label_cents end,
           ship_label_source = case when p_ship_cents is not null then 'manual' else ship_label_source end
     where store_id = v_store and sale_id = p_sale_id
       and not (provider = v_provider and order_id = v_order_id);

    select id into v_wo_id from public.web_orders
     where store_id = v_store and sale_id = p_sale_id
     order by created_at limit 1;

    if v_wo_id is not null then
      update public.web_orders set
        marketplace_fee_cents = case when p_fee_cents is not null then p_fee_cents else marketplace_fee_cents end,
        label_cost_cents = case when p_ship_cents is not null then p_ship_cents else label_cost_cents end,
        label_purchased_at = case
          when p_ship_cents is not null then coalesce(label_purchased_at, now())
          else label_purchased_at end,
        shipping_rate = case
          when p_ship_cents is null then shipping_rate
          when shipping_rate is null or shipping_rate = '{}'::jsonb
            then jsonb_build_object('source', 'manual', 'service', 'Purchased externally')
          else shipping_rate || jsonb_build_object('source', 'manual')
        end,
        updated_at = now()
      where id = v_wo_id and store_id = v_store;

      if p_ship_cents is not null then
        select nullif(value #>> '{}', '') into v_owner from public.store_settings
         where store_id = v_store and key = 'online_payout_employee_id';
        if v_owner is not null and v_owner !~* '^[0-9a-f-]{36}$' then v_owner := null; end if;
        select id into v_prev from public.portal_expenses
         where store_id = v_store and order_id = v_wo_id and source = 'manual_label' and voided_at is null
         limit 1;
        if v_prev is not null then
          update public.portal_expenses set
            amount_cents = p_ship_cents,
            description = 'Shipping label (manual) sale ' || coalesce(v_sale.sku, p_sale_id::text),
            employee_id = v_owner::uuid,
            needs_reimbursement = (v_owner is not null)
          where id = v_prev;
        elsif p_ship_cents > 0 then
          insert into public.portal_expenses(
            store_id, description, category, amount_cents, needs_reimbursement, employee_id, source, order_id)
          values (
            v_store,
            'Shipping label (manual) sale ' || coalesce(v_sale.sku, p_sale_id::text),
            'Shipping', p_ship_cents,
            v_owner is not null, v_owner::uuid, 'manual_label', v_wo_id);
        end if;
      end if;
    end if;
  end if;

  return (
    select jsonb_build_object(
      'sale_id', l.id,
      'sku', l.sku,
      'channel', l.channel,
      'channel_fee_cents', l.channel_fee_cents,
      'fee_source', l.fee_source,
      'ship_cost_cents', l.ship_cost_cents,
      'ship_cost_source', l.ship_cost_source,
      'processing_fee_cents', l.processing_fee_cents,
      'processing_fee_source', l.processing_fee_source,
      'profit_cents', l.profit_cents
    )
    from public.sale_ledger l
    where l.id = p_sale_id and l.store_id = v_store
  );
end $_$;


ALTER FUNCTION "public"."portal_set_sale_channel_costs"("p_sale_id" bigint, "p_fee_cents" integer, "p_ship_cents" integer, "p_processing_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_tax_remitted"("p_channel" "text", "p_remitted" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_list jsonb; v_key text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_key := lower(btrim(coalesce(p_channel, '')));
  v_list := coalesce(public.store_setting(v_store, 'tax_remitted_channels', '[]'::jsonb), '[]'::jsonb);
  if p_remitted then
    if not exists (select 1 from jsonb_array_elements_text(v_list) x where x = v_key) then
      v_list := v_list || to_jsonb(v_key);
    end if;
  else
    v_list := coalesce((select jsonb_agg(x) from jsonb_array_elements_text(v_list) x where x <> v_key), '[]'::jsonb);
  end if;
  insert into public.store_settings (store_id, key, value) values (v_store, 'tax_remitted_channels', v_list)
  on conflict (store_id, key) do update set value = excluded.value;
end $$;


ALTER FUNCTION "public"."portal_set_tax_remitted"("p_channel" "text", "p_remitted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_ask"("p_sku" "text", "p_ask_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_old int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_ask_cents is null or p_ask_cents < 0 then
    raise exception 'ask_must_be_non_negative' using errcode = '22023';
  end if;
  select ask_cents into v_old from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  update public.units
    set ask_cents = p_ask_cents, updated_at = now()
  where store_id = v_store and sku = p_sku;
  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (
    v_store, p_sku, 'edit', 'ask_cents', v_old::text, p_ask_cents::text,
    coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid()
  );
end $$;


ALTER FUNCTION "public"."portal_set_unit_ask"("p_sku" "text", "p_ask_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_aspect"("p_sku" "text", "p_name" "text", "p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_name text := btrim(coalesce(p_name, ''));
  v_value text := nullif(btrim(coalesce(p_value, '')), '');
  v_specs jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_name = '' or v_value is null then raise exception 'value_required' using errcode = '22023'; end if;
  if v_name ~* '^(brand)$' and v_value ~* '^(generic|unknown|n/?a|does not apply)$' then
    raise exception 'brand_invalid' using errcode = '22023';
  end if;
  select listing_specs into v_specs from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  v_specs := jsonb_set(coalesce(v_specs, '{}'::jsonb), '{ebay_aspects}',
    coalesce(coalesce(v_specs, '{}'::jsonb)->'ebay_aspects', '{}'::jsonb) || jsonb_build_object(v_name, to_jsonb(v_value)), true);
  update public.units set listing_specs = v_specs,
    brand = case when v_name ~* '^brand$' then v_value else brand end, updated_at = now()
    where store_id = v_store and sku = p_sku;
end $_$;


ALTER FUNCTION "public"."portal_set_unit_aspect"("p_sku" "text", "p_name" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_channel"("p_sku" "text", "p_channel" "text", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=coalesce(public.portal_store_id(),public.current_store_id());
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode='42501'; end if;
  if p_channel not in ('ebay','amazon','tiktok','depop') or p_enabled is null then
    raise exception 'invalid_channel' using errcode='22023'; end if;
  if not exists(select 1 from public.units where store_id=v_store and sku=p_sku) then
    raise exception 'unit_not_found' using errcode='22023'; end if;
  if p_enabled and p_channel='amazon'
    and exists(select 1 from public.floor_bundles b where b.store_id=v_store and b.sku=p_sku and b.active) then
    raise exception 'bundle_amazon_disabled' using errcode='22023'; end if;
  insert into public.unit_channel_categories(store_id,sku,channel,enabled,source,updated_at)
  values(v_store,p_sku,p_channel,p_enabled,'manual',now())
  on conflict(store_id,sku,channel) do update set enabled=excluded.enabled,updated_at=now();
end $$;


ALTER FUNCTION "public"."portal_set_unit_channel"("p_sku" "text", "p_channel" "text", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_cost"("p_sku" "text", "p_cost_cents" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_old int;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_cost_cents is not null and p_cost_cents < 0 then raise exception 'cost_must_not_be_negative' using errcode = '22023'; end if;
  select acquisition_cost_cents into v_old from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  update public.units set acquisition_cost_cents = p_cost_cents, updated_at = now() where store_id = v_store and sku = p_sku;
  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (v_store, p_sku, 'edit', 'acquisition_cost_cents', v_old::text, p_cost_cents::text,
          coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid());
end $$;


ALTER FUNCTION "public"."portal_set_unit_cost"("p_sku" "text", "p_cost_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_eligibility_override"("p_sku" "text", "p_channel" "text", "p_decision" "text", "p_note" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_channel text := lower(btrim(p_channel));
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_decision is null then
    delete from public.unit_marketplace_overrides
     where store_id = v_store and sku = p_sku and channel = v_channel;
    return;
  end if;
  if p_decision not in ('allow', 'block') then raise exception 'decision_invalid' using errcode = '22023'; end if;
  if coalesce(nullif(btrim(p_note), ''), '') = '' then raise exception 'note_required' using errcode = '22023'; end if;
  if exists (select 1 from public.marketplace_policy_strikes where store_id = v_store and sku = p_sku and channel = v_channel) then
    raise exception 'Cannot override a policy strike. Remove the strike first if it was logged in error.' using errcode = 'P0001';
  end if;
  insert into public.unit_marketplace_overrides(store_id, sku, channel, decision, note, actor_id, actor_name, updated_at)
  values (v_store, p_sku, v_channel, p_decision, btrim(p_note), auth.uid(),
    coalesce((select display_name from public.staff where user_id = auth.uid()), (select email from auth.users where id = auth.uid())),
    now())
  on conflict (store_id, sku, channel) do update
    set decision = excluded.decision, note = excluded.note, actor_id = excluded.actor_id,
        actor_name = excluded.actor_name, updated_at = now();
  update public.marketplace_eligibility_review
     set status = 'resolved', resolved_at = now(), resolved_by = auth.uid(),
         resolution_note = 'Override: ' || p_decision || '  -  ' || btrim(p_note)
   where store_id = v_store and sku = p_sku and channel = v_channel and status = 'pending';
end $$;


ALTER FUNCTION "public"."portal_set_unit_eligibility_override"("p_sku" "text", "p_channel" "text", "p_decision" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_listed_on"("p_sku" "text", "p_channels" "text"[]) RETURNS "text"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_channels text[];
  v_allowed text[];
  v_prev text[];
  v_ch text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  select coalesce(array_agg(x->>'key'), '{}'::text[]) into v_allowed
    from jsonb_array_elements(public.store_setting(v_store, 'marketplace_channels', '[]'::jsonb)) x
   where x->>'key' not in ('vendoo', 'mercari');
  select coalesce(array_agg(distinct lower(btrim(x)) order by lower(btrim(x))), '{}'::text[]) into v_channels
    from unnest(coalesce(p_channels, '{}'::text[])) x
   where lower(btrim(x)) = any (v_allowed)
     and lower(btrim(x)) not in ('vendoo', 'mercari');

  select coalesce(listed_on, '{}'::text[]) into v_prev from public.units where store_id = v_store and sku = p_sku;
  if not found then raise exception 'unit_not_found' using errcode = 'P0002'; end if;

  foreach v_ch in array v_channels
  loop
    if not (v_ch = any (coalesce(v_prev, '{}'::text[]))) then
      if v_ch = 'depop' then
        if not exists (
          select 1 from public.listings l
           where l.store_id = v_store and l.sku = p_sku
             and l.channel = 'depop' and l.status = 'listed'
        ) then
          raise exception 'depop_requires_listing_row — use Marketplaces → Listing manager → Depop (Push to Depop), then paste the listing link'
            using errcode = 'P0001';
        end if;
      end if;
      perform public.assert_channel_eligible(v_store, p_sku, v_ch);
    end if;
  end loop;

  update public.units set listed_on = v_channels, updated_at = now() where store_id = v_store and sku = p_sku;
  update public.listings set status = 'delisted', delisted_at = now()
    where store_id = v_store and sku = p_sku and channel = any (v_allowed)
      and not (channel = any (v_channels)) and status = 'listed';
  insert into public.listings(store_id, sku, channel, status, listed_at, delisted_at)
    select v_store, p_sku, x, 'listed', now(), null from unnest(v_channels) x
    on conflict(store_id, sku, channel) do update
      set status = 'listed', listed_at = coalesce(public.listings.listed_at, now()), delisted_at = null;
  return v_channels;
end $$;


ALTER FUNCTION "public"."portal_set_unit_listed_on"("p_sku" "text", "p_channels" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_marketplace_markup"("p_sku" "text", "p_markup_cents" integer) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_old integer;
  v_specs jsonb;
  v_who text := (select email from auth.users where id = auth.uid());
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_markup_cents is not null and p_markup_cents < 0 then
    raise exception 'packing_markup_must_be_nonnegative' using errcode = '22023';
  end if;
  select listing_specs into v_specs from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0002'; end if;
  begin v_old := nullif(v_specs->>'marketplace_packing_markup_cents','')::integer;
  exception when others then v_old := null; end;
  if p_markup_cents is null then
    v_specs := coalesce(v_specs, '{}'::jsonb) - 'marketplace_packing_markup_cents';
    if v_specs = '{}'::jsonb then v_specs := null; end if;
  else
    v_specs := jsonb_set(coalesce(v_specs, '{}'::jsonb), '{marketplace_packing_markup_cents}', to_jsonb(p_markup_cents), true);
  end if;
  update public.units set listing_specs = v_specs, updated_at = now() where store_id = v_store and sku = p_sku;
  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (v_store, p_sku, 'edit', 'marketplace_packing_markup_cents', v_old::text,
    p_markup_cents::text, coalesce(v_who,'admin'), auth.uid());
  return p_markup_cents;
end $$;


ALTER FUNCTION "public"."portal_set_unit_marketplace_markup"("p_sku" "text", "p_markup_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_shipping"("p_sku" "text", "p_override" "text", "p_length" numeric, "p_width" numeric, "p_height" numeric, "p_weight" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_who text := (select email from auth.users where id = auth.uid());
  u public.units;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if nullif(p_override,'') is not null and p_override not in ('ship','pickup') then raise exception 'invalid_override' using errcode = '22023'; end if;
  if least(coalesce(p_length,1),coalesce(p_width,1),coalesce(p_height,1),coalesce(p_weight,1)) <= 0 then
    raise exception 'dimensions_must_be_positive' using errcode = '22023';
  end if;
  select * into u from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  update public.units set fulfillment_override = nullif(p_override,''),
    package_length_in = p_length, package_width_in = p_width, package_height_in = p_height, package_weight_lb = p_weight,
    dims_source = case when (p_length, p_width, p_height, p_weight) is distinct from
      (u.package_length_in, u.package_width_in, u.package_height_in, u.package_weight_lb)
      and p_weight is not null then 'verified' else dims_source end,
    updated_at = now()
   where store_id = v_store and sku = p_sku;
  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (v_store, p_sku, 'edit', 'shipping', jsonb_build_object('override',u.fulfillment_override,'l',u.package_length_in,
    'w',u.package_width_in,'h',u.package_height_in,'lb',u.package_weight_lb)::text,
    jsonb_build_object('override',nullif(p_override,''),'l',p_length,'w',p_width,'h',p_height,'lb',p_weight)::text,
    coalesce(v_who,'admin'), auth.uid());
  return public.portal_unit_shipping(p_sku);
end $$;


ALTER FUNCTION "public"."portal_set_unit_shipping"("p_sku" "text", "p_override" "text", "p_length" numeric, "p_width" numeric, "p_height" numeric, "p_weight" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_set_unit_text"("p_sku" "text", "p_field" "text", "p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.portal_store_id();
  v_field text := lower(btrim(coalesce(p_field, '')));
  v_value text := nullif(btrim(coalesce(p_value, '')), '');
  v_old text;
  v_column text;
  v_specs jsonb;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_field not in ('model', 'description', 'brand', 'category', 'condition', 'upc') then
    raise exception 'invalid_text_field' using errcode = '22023';
  end if;
  if v_value is null then
    raise exception 'value_required' using errcode = '22023';
  end if;
  if v_field = 'brand' and v_value ~* '^(generic|unknown|n/?a|does not apply)$' then
    raise exception 'brand_invalid' using errcode = '22023';
  end if;

  if v_field = 'upc' and v_value ~* '^(does not apply|n/?a)$' then
    select listing_specs, upc into v_specs, v_old
      from public.units where store_id = v_store and sku = p_sku for update;
    if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
    v_specs := jsonb_set(
      coalesce(v_specs, '{}'::jsonb),
      '{ebay_aspects}',
      coalesce(coalesce(v_specs, '{}'::jsonb)->'ebay_aspects', '{}'::jsonb)
        || jsonb_build_object('UPC', to_jsonb('Does not apply'::text)),
      true
    );
    v_specs := v_specs || jsonb_build_object('upc', 'Does not apply');
    update public.units
      set upc = null, listing_specs = v_specs, updated_at = now()
      where store_id = v_store and sku = p_sku;
    insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
    values (
      v_store, p_sku, 'edit', 'upc', left(coalesce(v_old, ''), 200), 'Does not apply',
      coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid()
    );
    return;
  end if;

  if v_field = 'upc' and v_value !~ '^[0-9]{8,14}$' then
    raise exception 'upc_must_be_8_to_14_digits' using errcode = '22023';
  end if;
  v_column := case v_field when 'description' then 'listing_body' else v_field end;
  execute format('select %I from public.units where store_id = $1 and sku = $2 for update', v_column)
    into v_old using v_store, p_sku;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  execute format('update public.units set %I = $1, updated_at = now() where store_id = $2 and sku = $3', v_column)
    using v_value, v_store, p_sku;
  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (
    v_store, p_sku, 'edit', v_column, left(v_old, 200), left(v_value, 200),
    coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid()
  );
end $_$;


ALTER FUNCTION "public"."portal_set_unit_text"("p_sku" "text", "p_field" "text", "p_value" "text") OWNER TO "postgres";


