ALTER FUNCTION "public"."portal_ship_carriers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_stamp"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  new.edited_at := now(); new.edited_by := auth.uid();
  if tg_op = 'INSERT' then new.created_by := auth.uid(); end if;
  if tg_op = 'UPDATE' then
    new.store_id := old.store_id; new.created_at := old.created_at;
    new.created_by := old.created_by; new.period_type := old.period_type;
    new.period_start := old.period_start; new.period_end := old.period_end;
    new.summary := old.summary;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."portal_stamp"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_start_oauth"("p_provider" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_nonce text;
  v_hop text := 'https://inventoryobi.netlify.app/oauth/go?n=';
begin
  if v_store is null or not public.portal_is_admin() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if p_provider is null or p_provider not in ('ebay', 'amazon', 'square') then
    raise exception 'unknown_provider' using errcode = '22023';
  end if;

  v_nonce := encode(extensions.gen_random_bytes(24), 'hex');
  insert into public.oauth_states (store_id, user_id, provider, nonce, return_to, expires_at)
  values (
    v_store,
    auth.uid(),
    p_provider,
    v_nonce,
    'https://admin.openboxindustries.com/?page=marketplaces',
    now() + interval '10 minutes'
  );

  return jsonb_build_object(
    'ok', true,
    'provider', p_provider,
    'url', v_hop || v_nonce
  );
end;
$$;


ALTER FUNCTION "public"."portal_start_oauth"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_store_id"() RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select case when public.portal_is_admin() then (
    select x.store_id from (
      select store_id from public.portal_admins where user_id = auth.uid()
      union all
      select s.store_id
      from public.staff s
      where s.user_id = auth.uid()
        and s.deactivated_at is null
        and s.role in ('owner', 'manager')
        and s.store_id is not null
    ) x
    limit 1
  ) end;
$$;


