CREATE OR REPLACE FUNCTION "public"."portal_units_missing_cost"("p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  return (
    with hit as (
      select u.* from public.units u
      where u.store_id = v_store and u.acquisition_cost_cents is null
        and (u.state = 'sold'
          or (u.state in ('available', 'reserved') and not public.unit_not_for_sale(u.listing_specs)))
    )
    select jsonb_build_object(
      'total', (select count(*) from hit),
      'sold', (select count(*) from hit where state = 'sold'),
      'rows', coalesce((select jsonb_agg(x) from (
        select h.sku, coalesce(nullif(btrim(h.title),''), nullif(btrim(concat_ws(' ', h.brand, h.model)),''), 'Item') as title,
               h.brand, h.model, h.state, h.ask_cents, h.received_at,
               (select max(s.sold_at) from public.sales s where s.store_id = h.store_id and s.sku = h.sku and s.voided_at is null) as sold_at,
               (select max(s.channel) from public.sales s where s.store_id = h.store_id and s.sku = h.sku and s.voided_at is null) as sold_channel,
               (select max(s.price_cents) from public.sales s where s.store_id = h.store_id and s.sku = h.sku and s.voided_at is null) as sold_price_cents
          from hit h
         order by (h.state = 'sold') desc, h.received_at desc
         limit greatest(p_limit,1) offset greatest(p_offset,0)) x), '[]'::jsonb)
    )
  );
end $$;


ALTER FUNCTION "public"."portal_units_missing_cost"("p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_units_missing_field"("p_kind" "text", "p_limit" integer DEFAULT 100, "p_offset" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_blocks text;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if v_kind not in ('photo', 'price', 'spec', 'model', 'description', 'brand', 'upc', 'condition', 'category', 'specifics') then
    raise exception 'invalid_missing_kind' using errcode = '22023';
  end if;
  v_blocks := case v_kind
    when 'brand' then 'eBay, Amazon, TikTok'
    when 'category' then 'eBay, TikTok'
    when 'specifics' then 'eBay'
    when 'spec' then 'eBay, Amazon, TikTok'
    when 'upc' then 'eBay, Amazon'
    when 'photo' then 'eBay, Amazon, TikTok'
    when 'price' then 'eBay, Amazon, TikTok, Depop'
    when 'condition' then 'eBay, Amazon, TikTok'
    else null
  end;
  return (
    with hit as (
      select u.*, g.gaps
      from public.units u
      cross join lateral (select public.unit_listing_gaps(u) as gaps) g
      where u.store_id = v_store
        and u.state in ('available', 'reserved', 'repair')
        and v_kind = any(g.gaps)
    )
    select jsonb_build_object(
      'kind', v_kind,
      'blocks', v_blocks,
      'total', (select count(*) from hit),
      'rows', coalesce((
        select jsonb_agg(x) from (
          select h.sku,
            coalesce(nullif(btrim(h.title), ''), nullif(btrim(concat_ws(' ', h.brand, h.model)), ''), 'Item') as title,
            h.brand, h.model, h.category, h.condition, h.upc, h.state, h.ask_cents, h.received_at,
            h.package_weight_lb, h.package_length_in, h.package_width_in, h.package_height_in,
            (select count(*)::int from public.photos p where p.store_id = h.store_id and p.sku = h.sku) as photo_count,
            v_blocks as blocks,
            (select public.missing_ebay_aspect_names(d.aspect_defs, d.aspects, h.listing_specs)
               from public.ebay_drafts d where d.store_id = h.store_id and d.sku = h.sku limit 1) as missing_aspects,
            public.unit_not_for_sale(h.listing_specs) as not_for_sale
          from hit h
          order by h.received_at desc nulls last, h.sku desc
          limit greatest(p_limit, 1) offset greatest(p_offset, 0)
        ) x
      ), '[]'::jsonb)
    )
  );
end $$;


ALTER FUNCTION "public"."portal_units_missing_field"("p_kind" "text", "p_limit" integer, "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_unmatched_orders"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
begin
  if v_store is null then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;

  return coalesce((
    select jsonb_agg(x order by x->>'at' desc)
    from (
      select jsonb_build_object(
        'id', o.id,
        'ticket_key', 'unmatched:' || o.id::text,
        'order_no', o.order_no,
        'sku', o.sku,
        'title', coalesce(
          nullif(btrim(o.marketplace_title), ''),
          nullif(btrim(u.title), ''),
          nullif(btrim(concat_ws(' ', u.brand, u.model)), ''),
          initcap(coalesce(o.channel, 'marketplace')) || ' sale'
        ),
        'channel', lower(coalesce(o.channel, 'other')),
        'at', coalesce(o.paid_at, o.created_at),
        'price_cents', coalesce(o.item_cents, 0),
        'tax_cents', coalesce(o.tax_cents, 0),
        'shipping_cents', coalesce(o.shipping_cents, 0),
        'total_cents', coalesce(o.total_cents, o.item_cents, 0),
        'buyer_name', o.buyer_name,
        'buyer_email', o.buyer_email,
        'match_status', o.match_status,
        'marketplace_url', case
          when lower(o.channel) = 'ebay' and o.order_no is not null
            then 'https://www.ebay.com/mesh/ord/details?orderid=' || o.order_no
          when lower(o.channel) = 'depop' and o.order_no is not null
            then 'https://www.depop.com/sellinghub/sold/'
          when lower(o.channel) = 'mercari' and o.order_no is not null
            then 'https://www.mercari.com/mypage/listings/sold/'
          else null
        end
      ) as x
      from public.web_orders o
      left join public.units u
        on u.store_id = o.store_id
       and u.sku = o.sku
       and o.sku <> 'UNMATCHED'
      where o.store_id = v_store
        and o.sale_id is null
        and o.match_status in ('unmatched', 'already_sold')
        and (o.status = 'paid' or o.paid_at is not null)
        and coalesce(o.payment_env, 'production') <> 'sandbox'
        and lower(coalesce(o.order_no, '')) not like 'sandbox%'
        and coalesce(o.paid_at, o.created_at) >= p_from
        and coalesce(o.paid_at, o.created_at) < p_to
    ) q
  ), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "public"."portal_unmatched_orders"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_update_expense"("p_id" "uuid", "p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer, "p_needs_reimbursement" boolean, "p_employee" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_emp uuid;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 then raise exception 'amount_required' using errcode = '22023'; end if;
  v_emp := coalesce(p_employee, public.portal_owner_employee());
  update public.portal_expenses set spent_on = coalesce(p_spent_on, spent_on), description = btrim(p_description),
    category = coalesce(nullif(btrim(p_category),''),'Other'), amount_cents = p_amount_cents,
    needs_reimbursement = coalesce(p_needs_reimbursement,true),
    employee_id = case when coalesce(p_needs_reimbursement,true) then v_emp end
   where id = p_id and store_id = v_store and source = 'manual' and voided_at is null;
  if not found then raise exception 'expense_not_editable' using errcode = 'P0001'; end if;
end $$;


ALTER FUNCTION "public"."portal_update_expense"("p_id" "uuid", "p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer, "p_needs_reimbursement" boolean, "p_employee" "uuid") OWNER TO "postgres";


