CREATE OR REPLACE FUNCTION "public"."portal_update_unit"("p_sku" "text", "p_upc" "text" DEFAULT NULL::"text", "p_brand" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text", "p_ask_cents" integer DEFAULT NULL::integer, "p_cost_cents" integer DEFAULT NULL::integer, "p_condition" "text" DEFAULT NULL::"text", "p_test_status" "text" DEFAULT NULL::"text", "p_shippable" "text" DEFAULT NULL::"text", "p_notes" "text" DEFAULT NULL::"text", "p_length" numeric DEFAULT NULL::numeric, "p_width" numeric DEFAULT NULL::numeric, "p_height" numeric DEFAULT NULL::numeric, "p_weight" numeric DEFAULT NULL::numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_mode text := lower(btrim(coalesce(p_shippable, 'auto')));
  v_override text;
  v_ship boolean;
  v_unit public.units;
  v_dim numeric;
  v_brand text := coalesce(nullif(btrim(coalesce(p_brand, '')), ''), '');
  v_model text := coalesce(nullif(btrim(coalesce(p_model, '')), ''), '');
  v_title text := nullif(btrim(coalesce(p_title, '')), '');
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if nullif(btrim(coalesce(p_sku, '')), '') is null then
    raise exception 'sku_required' using errcode = '22023';
  end if;
  if p_ask_cents is not null and p_ask_cents < 0 then
    raise exception 'ask_must_be_non_negative' using errcode = '22023';
  end if;
  if p_cost_cents is not null and p_cost_cents < 0 then
    raise exception 'cost_must_be_non_negative' using errcode = '22023';
  end if;
  foreach v_dim in array array[p_length, p_width, p_height, p_weight] loop
    if v_dim is not null and v_dim <= 0 then
      raise exception 'dims_must_be_positive' using errcode = '22023';
    end if;
  end loop;

  if v_mode in ('', 'auto', 'automatic') then
    v_override := null;
    v_ship := null;
  elsif v_mode in ('yes', 'true', '1', 'ship', 'shippable') then
    v_override := 'ship';
    v_ship := true;
  elsif v_mode in ('no', 'false', '0', 'pickup', 'pickup_only') then
    v_override := 'pickup';
    v_ship := false;
  else
    raise exception 'invalid_shippable' using errcode = '22023';
  end if;

  -- Title is NOT NULL. Prefer explicit title, then brand + model, then keep prior / SKU.
  if v_title is null then
    v_title := nullif(btrim(concat_ws(' ', nullif(v_brand, ''), nullif(v_model, ''))), '');
  end if;

  select * into v_unit from public.units where store_id = v_store and sku = p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;

  if v_title is null then
    v_title := coalesce(nullif(btrim(coalesce(v_unit.title, '')), ''), p_sku);
  end if;

  update public.units set
    upc = nullif(btrim(coalesce(p_upc, '')), ''),
    brand = v_brand,
    model = v_model,
    title = v_title,
    listing_body = nullif(btrim(coalesce(p_description, '')), ''),
    ask_cents = p_ask_cents,
    acquisition_cost_cents = p_cost_cents,
    condition = nullif(btrim(coalesce(p_condition, '')), ''),
    test_status = nullif(btrim(coalesce(p_test_status, '')), ''),
    defect_notes = nullif(btrim(coalesce(p_notes, '')), ''),
    package_length_in = p_length,
    package_width_in = p_width,
    package_height_in = p_height,
    package_weight_lb = p_weight,
    dims_source = case
      when p_length is not null or p_width is not null or p_height is not null or p_weight is not null
        then 'verified'
      else dims_source
    end,
    fulfillment_override = case
      when v_mode in ('', 'auto', 'automatic') then null
      else v_override
    end,
    shippable = coalesce(v_ship, shippable),
    updated_at = now()
  where store_id = v_store and sku = p_sku
  returning * into v_unit;

  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (
    v_store, p_sku, 'edit', 'portal_update_unit', null, 'saved',
    coalesce((select email from auth.users where id = auth.uid()), 'admin'), auth.uid()
  );

  return jsonb_build_object(
    'sku', v_unit.sku,
    'upc', v_unit.upc,
    'brand', v_unit.brand,
    'model', v_unit.model,
    'title', v_unit.title,
    'description', v_unit.listing_body,
    'ask_cents', v_unit.ask_cents,
    'cost_cents', v_unit.acquisition_cost_cents,
    'condition', v_unit.condition,
    'test_status', v_unit.test_status,
    'notes', v_unit.defect_notes,
    'package_length_in', v_unit.package_length_in,
    'package_width_in', v_unit.package_width_in,
    'package_height_in', v_unit.package_height_in,
    'package_weight_lb', v_unit.package_weight_lb,
    'fulfillment_override', v_unit.fulfillment_override,
    'shippable', v_unit.shippable
  );
end;
$$;


ALTER FUNCTION "public"."portal_update_unit"("p_sku" "text", "p_upc" "text", "p_brand" "text", "p_model" "text", "p_title" "text", "p_description" "text", "p_ask_cents" integer, "p_cost_cents" integer, "p_condition" "text", "p_test_status" "text", "p_shippable" "text", "p_notes" "text", "p_length" numeric, "p_width" numeric, "p_height" numeric, "p_weight" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_upsert_ebay_fee_expense"("p_store" "uuid", "p_external_id" "text", "p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
  v_ext text := nullif(btrim(coalesce(p_external_id, '')), '');
  v_desc text := btrim(coalesce(p_description, ''));
  v_cat text := coalesce(nullif(btrim(coalesce(p_category, '')), ''), 'Marketplace fees');
  v_day date := coalesce(p_spent_on, (now() at time zone 'America/Los_Angeles')::date);
begin
  if p_store is null then raise exception 'store_required' using errcode = '22023'; end if;
  if v_ext is null then raise exception 'external_id_required' using errcode = '22023'; end if;
  if p_amount_cents is null or p_amount_cents <= 0 then
    raise exception 'amount_required' using errcode = '22023';
  end if;
  if v_desc = '' then raise exception 'description_required' using errcode = '22023'; end if;

  select e.id into v_id
  from public.portal_expenses e
  where e.store_id = p_store
    and e.source = 'ebay'
    and e.external_id = v_ext
    and e.voided_at is null
  limit 1;

  if v_id is not null then
    update public.portal_expenses set
      spent_on = v_day,
      description = v_desc,
      category = v_cat,
      amount_cents = p_amount_cents
    where id = v_id;
    return v_id;
  end if;

  insert into public.portal_expenses(
    store_id, spent_on, description, category, amount_cents,
    needs_reimbursement, employee_id, source, external_id
  ) values (
    p_store, v_day, v_desc, v_cat, p_amount_cents,
    false, null, 'ebay', v_ext
  )
  returning id into v_id;

  return v_id;
end $$;


ALTER FUNCTION "public"."portal_upsert_ebay_fee_expense"("p_store" "uuid", "p_external_id" "text", "p_spent_on" "date", "p_description" "text", "p_category" "text", "p_amount_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_upsert_supplier"("p_payload" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_id uuid := nullif(p_payload->>'id', '')::uuid;
  s public.suppliers;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  if nullif(btrim(p_payload->>'name'), '') is null then
    raise exception 'name_required' using errcode = '22023';
  end if;
  if v_id is null then
    insert into public.suppliers (
      store_id, name, accepts_returns, has_us_return_address,
      return_address_line1, return_address_line2, return_address_city,
      return_address_region, return_address_postal, return_address_country,
      return_window_days, restocking_fee_pct, notes
    ) values (
      v_store,
      btrim(p_payload->>'name'),
      coalesce((p_payload->>'accepts_returns')::boolean, false),
      coalesce((p_payload->>'has_us_return_address')::boolean, false),
      nullif(p_payload->>'return_address_line1',''),
      nullif(p_payload->>'return_address_line2',''),
      nullif(p_payload->>'return_address_city',''),
      nullif(p_payload->>'return_address_region',''),
      nullif(p_payload->>'return_address_postal',''),
      coalesce(nullif(p_payload->>'return_address_country',''), 'US'),
      nullif(p_payload->>'return_window_days','')::int,
      coalesce((p_payload->>'restocking_fee_pct')::numeric, 0),
      nullif(p_payload->>'notes','')
    ) returning * into s;
  else
    update public.suppliers set
      name = btrim(p_payload->>'name'),
      accepts_returns = coalesce((p_payload->>'accepts_returns')::boolean, accepts_returns),
      has_us_return_address = coalesce((p_payload->>'has_us_return_address')::boolean, has_us_return_address),
      return_address_line1 = coalesce(nullif(p_payload->>'return_address_line1',''), return_address_line1),
      return_address_line2 = coalesce(nullif(p_payload->>'return_address_line2',''), return_address_line2),
      return_address_city = coalesce(nullif(p_payload->>'return_address_city',''), return_address_city),
      return_address_region = coalesce(nullif(p_payload->>'return_address_region',''), return_address_region),
      return_address_postal = coalesce(nullif(p_payload->>'return_address_postal',''), return_address_postal),
      return_address_country = coalesce(nullif(p_payload->>'return_address_country',''), return_address_country),
      return_window_days = coalesce(nullif(p_payload->>'return_window_days','')::int, return_window_days),
      restocking_fee_pct = coalesce((p_payload->>'restocking_fee_pct')::numeric, restocking_fee_pct),
      notes = coalesce(nullif(p_payload->>'notes',''), notes),
      updated_at = now()
    where id = v_id and store_id = v_store
    returning * into s;
    if not found then raise exception 'supplier_not_found' using errcode = 'P0001'; end if;
  end if;
  return to_jsonb(s);
end $$;


