CREATE OR REPLACE FUNCTION "public"."portal_void_withdrawal"("p_id" "uuid", "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id(); v_source text := lower(btrim(coalesce(p_source,'')));
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_source = 'safe' then
    update public.store_cash_movements set voided_at = now(), void_reason = 'deleted',
      updated_at = now(), updated_by = auth.uid()
    where id = p_id and store_id = v_store and kind = 'owner_take' and voided_at is null;
  elsif v_source in ('square','ebay','amazon','tiktok','depop') then
    update public.platform_withdrawals set voided_at = now(), void_reason = 'deleted',
      updated_at = now(), updated_by = auth.uid()
    where id = p_id and store_id = v_store and platform = v_source and voided_at is null;
  else raise exception 'source_invalid' using errcode = '22023';
  end if;
  if not found then raise exception 'withdrawal_not_editable' using errcode = 'P0001'; end if;
  update public.portal_payout_payments set voided_at = now()
  where store_id = v_store and withdrawal_source = v_source and withdrawal_id = p_id;
end $$;


ALTER FUNCTION "public"."portal_void_withdrawal"("p_id" "uuid", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_voided_sales"("p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS TABLE("id" bigint, "ticket_key" "text", "sku" "text", "title" "text", "qty" integer, "sold_at" timestamp with time zone, "voided_at" timestamp with time zone, "void_reason" "text", "price_cents" integer, "tax_cents" integer, "card_fee_cents" integer, "cost_cents" integer, "payment_method" "text", "cash_cents" integer, "card_cents" integer, "actor_id" "uuid", "actor_name" "text", "channel" "text", "receipt_no" "text", "channel_fee_cents" integer, "ship_cost_cents" integer, "processing_fee_cents" integer, "profit_cents" integer, "shipping_cents" integer, "order_no" "text", "buyer_name" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  perform public.portal_assert_admin();
  if p_from is null or p_to is null or p_to <= p_from or p_to > p_from + interval '93 days' then
    raise exception 'invalid_date_range' using errcode = '22023';
  end if;
  return query
    select s.id, coalesce(s.ticket_id::text, 'sale:' || s.id::text), s.sku,
      coalesce(nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), nullif(u.title, ''), 'Item')::text,
      s.qty, s.sold_at, s.voided_at,
      coalesce(nullif(btrim(s.void_reason), ''), wo.cancel_reason, wo.cancel_source, 'Refunded / voided')::text,
      s.price_cents, s.tax_cents, s.card_fee_cents,
      l.cost_cents, s.payment_method, x.cash_cents, x.card_cents,
      s.actor_id,
      coalesce(st.display_name, case when s.channel = 'website'
        then 'Website ' || coalesce((select o.order_no from public.web_orders o where o.sale_id = s.id limit 1), 'order')
        else 'Unknown' end)::text,
      s.channel, s.receipt_no,
      l.channel_fee_cents, l.ship_cost_cents,
      l.processing_fee_cents, l.profit_cents,
      coalesce(l.shipping_cents, 0),
      coalesce(wo.order_no, replace(s.payment_id, 'ebay:', ''), s.receipt_no)::text,
      wo.buyer_name::text
    from public.sales s
    join public.sale_ledger l on l.id = s.id
    left join public.units u on u.store_id = s.store_id and u.sku = s.sku
    left join public.staff st on st.store_id = s.store_id and st.user_id = s.actor_id
    left join public.ticket_extras x on x.store_id = s.store_id and x.ticket_id = s.ticket_id
    left join lateral (
      select w.order_no, w.buyer_name, w.cancel_reason, w.cancel_source
      from public.web_orders w where w.sale_id = s.id order by w.created_at limit 1
    ) wo on true
    where s.store_id = v_store and s.voided_at is not null
      and s.voided_at >= p_from and s.voided_at < p_to
    order by s.voided_at desc, s.id desc;
end $$;


ALTER FUNCTION "public"."portal_voided_sales"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_web_orders"("p_days" integer DEFAULT 90) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_income_pct numeric;
begin
  if v_store is null then raise exception 'portal_access_denied' using errcode = '42501'; end if;
  v_income_pct := coalesce(
    (public.store_setting(v_store, 'income_tax_pct', '25'::jsonb) #>> '{}')::numeric,
    25
  );
  return coalesce((select jsonb_agg(x order by x.created_at desc) from (
    select o.id, o.order_no, o.sku, o.status, o.fulfillment, o.channel,
      o.buyer_name, o.buyer_email, o.buyer_phone,
      o.ship_line1, o.ship_line2, o.ship_city, o.ship_region, o.ship_postal,
      o.item_cents, o.shipping_cents, o.tax_cents, o.total_cents,
      o.payment_id, o.refund_id, o.payment_env, o.created_at, o.paid_at,
      o.pickup_deadline, o.picked_up_at, o.picked_up_by,
      o.boxed_at, o.shipped_at, o.delivered_at,
      o.tracking_number, o.tracking_url, o.carrier, o.service, o.shipping_rate, o.label_url,
      o.label_purchased_at, o.label_cost_cents, o.refund_requested_at,
      o.cancel_source, o.cancel_reason, o.canceled_at, o.ship_by,
      o.pack_condition, o.pack_condition_at,
      o.pack_proof_photo_path, o.pack_proof_serial, o.pack_proof_at,
      o.match_status, o.marketplace_fee_cents, o.marketplace_title,
      o.sale_id,
      case when o.sale_id is not null
        then coalesce(sl.ticket_id::text, 'sale:' || o.sale_id::text)
        else null end as ticket_key,
      coalesce(nullif(btrim(o.marketplace_title), ''), nullif(btrim(u.title), ''),
        nullif(btrim(concat_ws(' ', u.brand, u.model)), ''), 'Item') as title,
      coalesce(u.listed_on, '{}'::text[]) as listed_on,
      coalesce(co.fee_cents, o.marketplace_fee_cents, sl.channel_fee_cents) as fee_cents,
      coalesce(
        co.fee_source,
        case
          when co.fee_cents is null and o.marketplace_fee_cents is null and sl.fee_source is not null
            then sl.fee_source
          when co.fee_cents is null and o.marketplace_fee_cents is not null then 'estimated'
          else null
        end
      ) as fee_source,
      sl.cost_cents,
      sl.profit_cents,
      case when sl.profit_cents is null then null
        else greatest(0, round(sl.profit_cents * v_income_pct / 100.0))::int end as income_tax_cents,
      sl.tax_remitted_by,
      coalesce(sl.tax_collected_cents, o.tax_cents, 0) as tax_collected_cents,
      coalesce(sl.tax_owed_cents, 0) as tax_owed_cents,
      case
        when lower(o.channel) = 'ebay' and o.order_no is not null
          then 'https://www.ebay.com/mesh/ord/details?orderid=' || o.order_no
        when lower(o.channel) = 'amazon' and o.order_no is not null
          then 'https://sellercentral.amazon.com/orders-v3/order/' || o.order_no
        when lower(o.channel) = 'tiktok' and o.order_no is not null
          then 'https://seller-us.tiktok.com/order/detail?order_no=' || o.order_no
        when lower(o.channel) = 'depop' and o.order_no is not null
          then 'https://www.depop.com/sellinghub/sold/'
        when lower(o.channel) = 'mercari' and o.order_no is not null
          then 'https://www.mercari.com/mypage/listings/completed/'
        when lower(o.channel) in ('website','web') and o.order_no is not null
          then 'https://openboxindustries.com/account/orders/' || o.order_no
        else null
      end as marketplace_url,
      jsonb_build_object(
        'length_in', u.package_length_in,
        'width_in', u.package_width_in,
        'height_in', u.package_height_in,
        'weight_lb', u.package_weight_lb
      ) as package
    from public.web_orders o
    left join public.units u on u.store_id = o.store_id and u.sku = o.sku
    left join public.channel_orders co
      on co.store_id = o.store_id and co.provider = o.channel and co.order_id = o.order_no
    left join public.sale_ledger sl on sl.id = o.sale_id
    where o.store_id = v_store
      and o.created_at > now() - make_interval(days => greatest(p_days, 1))
      and (o.status in ('paid', 'refunded', 'canceled') or o.paid_at is not null)
      and coalesce(o.payment_env, 'production') <> 'sandbox'
      and lower(coalesce(o.order_no, '')) not like 'sandbox%'
  ) x), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_web_orders"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_withdrawal_audit"("p_source" "text", "p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(to_jsonb(a) order by a.at desc)
    from public.withdrawal_audit a where a.store_id = v_store
      and a.source = lower(btrim(p_source)) and a.withdrawal_id = p_id), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_withdrawal_audit"("p_source" "text", "p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_withdrawal_entries"("p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  return coalesce((select jsonb_agg(to_jsonb(x) order by x.moved_on desc, x.created_at desc)
    from (
      select id, 'safe'::text source, amount_cents, moved_on, reason, note,
        person_id, performed_by, created_by, created_at, updated_by, updated_at, voided_at
      from public.store_cash_movements where store_id = v_store and kind = 'owner_take'
      union all
      select id, platform, amount_cents, withdrawn_on, reason, note,
        person_id, performed_by, created_by, created_at, updated_by, updated_at, voided_at
      from public.platform_withdrawals where store_id = v_store
      order by moved_on desc, created_at desc
      limit greatest(1, least(coalesce(p_limit,500), 2000))
    ) x), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_withdrawal_entries"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_withdrawal_reconciliation"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.portal_store_id();
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  return coalesce((
    with sources as (
      select x.source from unnest(array['safe','square','ebay','amazon','tiktok','depop']) x(source)
      where x.source <> 'depop' or exists (select 1 from jsonb_array_elements(
        public.store_setting(v_store,'marketplace_channels','[]'::jsonb)) c
        where c->>'key'='depop')
    ), inflow as (
      select 'safe'::text source,
        coalesce(sum(te.cash_cents),0)::bigint
          + coalesce((select sum(amount_cents) from public.store_cash_movements
            where store_id=v_store and kind='owner_put' and voided_at is null),0)::bigint cents
      from public.ticket_extras te
      where te.store_id = v_store and exists (
        select 1 from public.sales s where s.store_id = v_store
          and s.ticket_id = te.ticket_id and s.voided_at is null
      )
      union all
      select 'square',
        coalesce(sum(te.card_cents),0)::bigint
          - coalesce((select sum(l.processing_fee_cents) from public.sale_ledger l
            where l.store_id = v_store and lower(l.channel) in ('floor','store')
              and l.voided_at is null),0)::bigint
      from public.ticket_extras te
      where te.store_id = v_store and exists (
        select 1 from public.sales s where s.store_id = v_store
          and s.ticket_id = te.ticket_id and s.voided_at is null
      )
      union all
      select lower(l.channel),
        coalesce(sum(l.price_cents + coalesce(l.shipping_cents,0)
          + coalesce(l.tax_owed_cents,0)
          - coalesce(l.channel_fee_cents,0)
          - coalesce(l.processing_fee_cents,0)),0)::bigint
      from public.sale_ledger l where l.store_id = v_store and l.voided_at is null
        and lower(l.channel) in ('ebay','amazon','tiktok','depop')
      group by lower(l.channel)
    ), refunds as (
      select lower(r.channel) source, coalesce(sum(r.refund_cents),0)::bigint cents
      from public.returns r join public.sales s on s.id = r.sale_id
      where r.store_id = v_store and s.store_id = v_store and s.voided_at is null
        and r.refunded_at is not null and lower(r.channel) in ('ebay','amazon','tiktok','depop')
      group by lower(r.channel)
    ), taken as (
      select 'safe'::text source, coalesce(sum(amount_cents),0)::bigint cents
      from public.store_cash_movements
      where store_id = v_store and kind <> 'owner_put' and voided_at is null
      union all
      select platform, sum(amount_cents)::bigint from public.platform_withdrawals
      where store_id = v_store and voided_at is null group by platform
    )
    select jsonb_agg(jsonb_build_object(
      'source', s.source,
      'sales_less_fees_cents', coalesce(i.cents,0),
      'refund_cents', coalesce(r.cents,0),
      'withdrawn_cents', coalesce(t.cents,0),
      'expected_cents', coalesce(i.cents,0)-coalesce(r.cents,0)-coalesce(t.cents,0)
    ) order by array_position(array['safe','square','ebay','amazon','tiktok','depop'],s.source))
    from sources s left join inflow i on i.source=s.source
      left join refunds r on r.source=s.source
      left join taken t on t.source=s.source
  ), '[]'::jsonb);
end $$;


ALTER FUNCTION "public"."portal_withdrawal_reconciliation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."portal_withdrawals_summary"("p_start" "date" DEFAULT NULL::"date", "p_end" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.portal_store_id();
  v_start date := coalesce(p_start, date '2000-01-01');
  v_end date := coalesce(p_end, (now() at time zone 'America/Los_Angeles')::date);
  v_cash_in int := 0;
  v_cash_in_all int := 0;
  v_owner_take int := 0;
  v_owner_take_all int := 0;
  v_owner_put int := 0;
  v_owner_put_all int := 0;
  v_platforms jsonb := '[]'::jsonb;
begin
  if v_store is null or not public.portal_financial_access() then
    raise exception 'portal_access_denied' using errcode = '42501';
  end if;
  if v_end < v_start then
    raise exception 'date_range_invalid' using errcode = '22023';
  end if;

  select coalesce(sum(te.cash_cents), 0)::int into v_cash_in_all
  from public.ticket_extras te
  where te.store_id = v_store
    and te.cash_cents > 0
    and exists (
      select 1 from public.sales s
      where s.ticket_id = te.ticket_id
        and s.store_id = v_store
        and s.voided_at is null
    );

  select coalesce(sum(te.cash_cents), 0)::int into v_cash_in
  from public.ticket_extras te
  where te.store_id = v_store
    and te.cash_cents > 0
    and exists (
      select 1 from public.sales s
      where s.ticket_id = te.ticket_id
        and s.store_id = v_store
        and s.voided_at is null
        and (s.sold_at at time zone 'America/Los_Angeles')::date >= v_start
        and (s.sold_at at time zone 'America/Los_Angeles')::date <= v_end
    );

  select
    coalesce(sum(amount_cents) filter (where kind = 'owner_take'), 0)::int,
    coalesce(sum(amount_cents) filter (where kind = 'owner_put'), 0)::int
  into v_owner_take_all, v_owner_put_all
  from public.store_cash_movements
  where store_id = v_store and voided_at is null;

  select
    coalesce(sum(amount_cents) filter (where kind = 'owner_take'), 0)::int,
    coalesce(sum(amount_cents) filter (where kind = 'owner_put'), 0)::int
  into v_owner_take, v_owner_put
  from public.store_cash_movements
  where store_id = v_store
    and voided_at is null
    and moved_on >= v_start
    and moved_on <= v_end;

  select coalesce(jsonb_agg(row_to_json(p)::jsonb order by p.sort_order), '[]'::jsonb)
  into v_platforms
  from (
    select
      plat.platform,
      plat.label,
      plat.sort_order,
      coalesce((
        select s.available_cents
        from public.platform_balance_snapshots s
        where s.store_id = v_store and s.platform = plat.platform
        order by s.created_at desc
        limit 1
      ), 0) as available_cents,
      coalesce((
        select s.noted_on
        from public.platform_balance_snapshots s
        where s.store_id = v_store and s.platform = plat.platform
        order by s.created_at desc
        limit 1
      ), null) as available_noted_on,
      coalesce((
        select sum(w.amount_cents)::int
        from public.platform_withdrawals w
        where w.store_id = v_store
          and w.platform = plat.platform
          and w.voided_at is null
      ), 0) as withdrawn_cents,
      coalesce((
        select sum(w.amount_cents)::int
        from public.platform_withdrawals w
        where w.store_id = v_store
          and w.platform = plat.platform
          and w.voided_at is null
          and w.withdrawn_on >= v_start
          and w.withdrawn_on <= v_end
      ), 0) as withdrawn_range_cents
    from (
      values
        ('square', 'Square', 1),
        ('ebay', 'eBay', 2),
        ('depop', 'Depop', 3),
        ('amazon', 'Amazon', 4),
        ('tiktok', 'TikTok', 5)
    ) as plat(platform, label, sort_order)
  ) p;

  return jsonb_build_object(
    'start', v_start,
    'end', v_end,
    'cash_in_cents', v_cash_in,
    'cash_in_all_cents', v_cash_in_all,
    'owner_take_cents', v_owner_take,
    'owner_take_all_cents', v_owner_take_all,
    'owner_put_cents', v_owner_put,
    'owner_put_all_cents', v_owner_put_all,
    'cash_on_hand_cents', greatest(0, v_cash_in_all - v_owner_take_all + v_owner_put_all),
    'platforms', v_platforms
  );
end;
$$;


ALTER FUNCTION "public"."portal_withdrawals_summary"("p_start" "date", "p_end" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_shipping_payment"("p_store" "uuid", "p_order" "uuid", "p_reservation" "uuid", "p_sku" "text", "p_source" "text") RETURNS "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare o public.web_orders; r public.reservations;
begin
  perform public.assert_service();
  -- Match the unit-first lock order used by claim/finalize.
  perform 1 from public.units where store_id=p_store and sku=p_sku for update;
  select * into o from public.web_orders where id=p_order and store_id=p_store and sku=p_sku and reservation_id=p_reservation for update;
  if not found then raise exception 'order_not_found'; end if;
  if o.status='paid' then return o; end if;
  if o.status <> 'claimed' or o.checkout_quote is null then raise exception 'order_not_payable'; end if;
  select * into r from public.reservations where id=p_reservation for update;
  if o.payment_started_at is null and (r.released_at is not null or r.finalized_at is not null or r.expires_at <= now()) then raise exception 'reservation_expired'; end if;
  if nullif(btrim(p_source),'') is null then raise exception 'source_required'; end if;
  update public.web_orders set payment_source_id=coalesce(payment_source_id,p_source),
    payment_started_at=coalesce(payment_started_at,now()) where id=o.id returning * into o;
  return o;
end $$;


ALTER FUNCTION "public"."prepare_shipping_payment"("p_store" "uuid", "p_order" "uuid", "p_reservation" "uuid", "p_sku" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."project_cursor_package_measures"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
declare
  v_specs jsonb := coalesce(new.listing_specs, '{}'::jsonb);
  v_status text := v_specs->>'package_measure_status';
  v_weight numeric;
  v_length numeric;
  v_width numeric;
  v_height numeric;
begin
  if v_status not in ('sourced', 'estimated') then return new; end if;
  begin
    v_weight := nullif(v_specs->>'package_weight_lb', '')::numeric;
    v_length := nullif(v_specs->>'package_length_in', '')::numeric;
    v_width := nullif(v_specs->>'package_width_in', '')::numeric;
    v_height := nullif(v_specs->>'package_height_in', '')::numeric;
  exception when invalid_text_representation then return new;
  end;
  if coalesce(v_weight, 0) <= 0 or coalesce(v_length, 0) <= 0
     or coalesce(v_width, 0) <= 0 or coalesce(v_height, 0) <= 0 then return new; end if;
  new.package_weight_lb := v_weight;
  new.package_length_in := v_length;
  new.package_width_in := v_width;
  new.package_height_in := v_height;
  return new;
end $$;


ALTER FUNCTION "public"."project_cursor_package_measures"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prorate_cents"("p_prices" integer[], "p_total" integer) RETURNS integer[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'public'
    AS $$
declare
  n int := coalesce(array_length(p_prices, 1), 0);
  v_sum bigint := 0;
  v_out int[] := '{}';
  v_acc int := 0;
  v_line int;
  i int;
begin
  if n = 0 then
    return '{}'::int[];
  end if;
  if p_total is null or p_total < 0 then
    raise exception 'invalid_prorate' using errcode = '22023';
  end if;
  for i in 1..n loop
    v_sum := v_sum + coalesce(p_prices[i], 0);
  end loop;
  if v_sum <= 0 then
    for i in 1..n loop
      v_out := v_out || 0;
    end loop;
    return v_out;
  end if;
  for i in 1..n loop
    if i = n then
      v_line := p_total - v_acc;
    else
      v_line := floor((p_prices[i]::numeric * p_total::numeric) / v_sum::numeric)::int;
      v_acc := v_acc + v_line;
    end if;
    v_out := v_out || v_line;
  end loop;
  return v_out;
end;
$$;


ALTER FUNCTION "public"."prorate_cents"("p_prices" integer[], "p_total" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_google_shipping_settings"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.key in ('shipping_enabled','ship_max_weight_lb','ship_max_length_in','ship_max_length_girth_in','ship_excluded_categories','ship_excluded_keywords') then
    insert into public.google_sync_queue(store_id,sku,action)
    select u.store_id,u.sku,'upsert' from public.units u where u.store_id=new.store_id
    on conflict(store_id,sku) do update set action='upsert',attempts=0,last_error=null,queued_at=now();
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."queue_google_shipping_settings"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_google_unit"("p_store" "uuid", "p_sku" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_store is null or nullif(btrim(p_sku),'') is null then return; end if;
  insert into public.google_sync_queue(store_id,sku) values(p_store,btrim(p_sku))
  on conflict(store_id,sku) do update set action='upsert',attempts=0,last_error=null,queued_at=now();
end $$;


ALTER FUNCTION "public"."queue_google_unit"("p_store" "uuid", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_google_unit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.queue_google_unit(coalesce(new.store_id,old.store_id),coalesce(new.sku,old.sku));
  if tg_op='UPDATE' and (old.store_id,old.sku) is distinct from (new.store_id,new.sku) then
    perform public.queue_google_unit(old.store_id,old.sku);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end $$;


ALTER FUNCTION "public"."queue_google_unit_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_loyalty_campaign"("p_subject" "text", "p_body" "text", "p_min_spend_cents" integer DEFAULT 0, "p_days" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_store uuid := public.current_store_id(); v_id uuid := gen_random_uuid(); v_n int := 0; v_subject text := btrim(coalesce(p_subject, '')); v_body text := btrim(coalesce(p_body, '')); begin perform public.assert_manager(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; if v_subject = '' or v_body = '' then raise exception 'subject_and_body_required' using errcode = '22023'; end if; insert into public.email_campaigns (id, store_id, subject, body_text, filter, created_by) values (v_id, v_store, v_subject, v_body, jsonb_build_object('min_spend_cents', greatest(coalesce(p_min_spend_cents, 0), 0), 'days', p_days), auth.uid()); insert into public.email_outbox (store_id, customer_id, campaign_id, kind, to_email, subject, body_text) select v_store, c.id, v_id, 'campaign', c.email, v_subject, v_body from public.customers c where c.store_id = v_store and c.email is not null and c.marketing_opt_in and c.unsubscribed_at is null and (coalesce(p_min_spend_cents, 0) <= 0 or coalesce((select sum(s.price_cents) from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and s.voided_at is null and s.channel in ('floor', 'website')), 0) >= p_min_spend_cents) and (p_days is null or exists (select 1 from public.ticket_extras te join public.sales s on s.ticket_id = te.ticket_id and s.store_id = v_store where te.customer_id = c.id and s.voided_at is null and s.channel in ('floor', 'website') and s.sold_at >= now() - make_interval(days => p_days))); get diagnostics v_n = row_count; update public.email_campaigns set queued_count = v_n where id = v_id; return jsonb_build_object('campaign_id', v_id, 'queued', v_n); end; $$;


ALTER FUNCTION "public"."queue_loyalty_campaign"("p_subject" "text", "p_body" "text", "p_min_spend_cents" integer, "p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_model_enrichment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_brand text; v_model text; v_photo_model text; v_store uuid; v_sku text;
begin
  if tg_table_name='photos' then
    select u.brand,u.model,coalesce(u.listing_specs->>'matched_model',u.model),u.store_id,u.sku
      into v_brand,v_model,v_photo_model,v_store,v_sku
      from public.units u where u.store_id=new.store_id and u.sku=new.sku;
  else
    v_brand:=new.brand; v_model:=new.model; v_store:=new.store_id; v_sku:=new.sku;
    v_photo_model:=coalesce(new.listing_specs->>'matched_model',new.model);
  end if;
  if nullif(btrim(v_model),'') is not null
    and exists(select 1 from public.photos p where p.store_id=v_store and p.sku=v_sku)
    and not exists(select 1 from public.manufacturer_photos mp
      where lower(mp.brand)=lower(v_brand) and lower(mp.model)=lower(v_photo_model)) then
    insert into public.model_enrichment(brand_key,model_key,brand,model,status)
    values(lower(btrim(v_brand)),lower(btrim(v_model)),btrim(v_brand),btrim(v_model),
      case when v_model ~ '^[A-Za-z0-9/.-]{5,}$' and v_model ~ '[0-9]'
        then 'pending' else 'needs_model' end)
    on conflict (brand_key,model_key) do nothing;
  end if;
  return new;
end $_$;


ALTER FUNCTION "public"."queue_model_enrichment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_photo_enrichment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_unit public.units%rowtype; v_identity text;
begin
  if tg_table_name='photos' then
    select * into v_unit from public.units where store_id=new.store_id and sku=new.sku;
  else
    v_unit:=new;
  end if;
  if v_unit.store_id is null or lower(coalesce(v_unit.category,''))='refrigerator'
    or not exists(select 1 from public.photos p where p.store_id=v_unit.store_id and p.sku=v_unit.sku)
    or exists(select 1 from public.manufacturer_photos mp where lower(mp.brand)=lower(v_unit.brand)
      and lower(mp.model)=lower(coalesce(v_unit.listing_specs->>'matched_model',v_unit.model)))
    or exists(select 1 from public.photo_enrichment_suggestions s where s.store_id=v_unit.store_id
      and s.sku=v_unit.sku and s.status='approved') then
    return new;
  end if;
  v_identity:=public.photo_enrichment_identity(v_unit.brand,v_unit.model,v_unit.title);
  insert into public.photo_enrichment_queue(store_id,sku,identity_key)
    values(v_unit.store_id,v_unit.sku,v_identity)
    on conflict (store_id,sku) do update set identity_key=excluded.identity_key,
      status=case when public.photo_enrichment_queue.identity_key is distinct from excluded.identity_key
        then 'pending' else public.photo_enrichment_queue.status end,
      next_attempt_at=case when public.photo_enrichment_queue.identity_key is distinct from excluded.identity_key
        then now() else public.photo_enrichment_queue.next_attempt_at end;
  return new;
end $$;


ALTER FUNCTION "public"."queue_photo_enrichment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."queue_web_order_emails"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_title text;
begin
  select coalesce(nullif(title,''),concat_ws(' ',brand,model),new.sku) into v_title
  from public.units where store_id=new.store_id and sku=new.sku;
  if new.status='paid' and (tg_op='INSERT' or old.status is distinct from 'paid') then
    insert into public.web_order_emails(order_id,kind,payload)
      select new.id,k,to_jsonb(new)-'payment_source_id' || jsonb_build_object('title',v_title)
      from unnest(array['owner','confirmation']) k on conflict do nothing;
  end if;
  if new.shipped_at is not null
     and (tg_op='INSERT' or old.shipped_at is null)
     and nullif(btrim(coalesce(new.tracking_number,'')), '') is not null then
    insert into public.web_order_emails(order_id,kind,payload)
      values(new.id,'tracking',to_jsonb(new)-'payment_source_id' || jsonb_build_object('title',v_title))
      on conflict do nothing;
  end if;
  return new;
end $$;


ALTER FUNCTION "public"."queue_web_order_emails"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."quote_ticket_totals"("p_lines" "jsonb", "p_discount_bps" integer DEFAULT 0, "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_redeem_points" integer DEFAULT 0, "p_channel" "text" DEFAULT 'floor'::"text", "p_payment_method" "text" DEFAULT 'cash'::"text", "p_cash_cents" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_bps int;
  v_n int;
  v_i int;
  v_line jsonb;
  v_sku text;
  v_unit int;
  v_qty int;
  v_prices int[] := '{}';
  v_raw_sub bigint := 0;
  v_discount_bps int := coalesce(p_discount_bps, 0);
  v_discount_cents int := 0;
  v_signup_cents int := 0;
  v_redeem_cents int := 0;
  v_remaining int;
  v_total_disc int;
  v_shares int[];
  v_net int[] := '{}';
  v_net_sub int := 0;
  v_taxes int[];
  v_tax int := 0;
  v_channel text := coalesce(nullif(btrim(p_channel), ''), 'floor');
  v_rewards_enabled boolean;
  v_cust public.customers;
  v_signup_bps int;
  v_point_value int;
  v_bal int;
  v_redeem_points int := coalesce(p_redeem_points, 0);
  v_pay text := lower(btrim(coalesce(p_payment_method, 'cash')));
  v_prefee int;
  v_fee_bps int;
  v_card_base int := 0;
  v_fee int := 0;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  v_bps := public.store_tax_rate_bps();
  if v_bps is null then
    raise exception 'tax_rate_required' using errcode = 'P0001';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) < 1 then
    raise exception 'empty_ticket' using errcode = '22023';
  end if;
  if v_discount_bps < 0 or v_discount_bps > 10000 then
    raise exception 'invalid_discount_bps' using errcode = '22023';
  end if;

  v_n := jsonb_array_length(p_lines);
  for v_i in 0..v_n - 1 loop
    v_line := p_lines->v_i;
    v_sku := btrim(coalesce(v_line->>'sku', ''));
    v_unit := (v_line->>'price_cents')::int;
    v_qty := coalesce(nullif(v_line->>'qty', '')::int, 1);
    if v_sku = '' or v_unit is null or v_unit < 0 or v_qty is null or v_qty < 1 then
      raise exception 'invalid_line' using errcode = '22023';
    end if;
    v_prices := v_prices || (v_unit * v_qty);
    v_raw_sub := v_raw_sub + v_unit * v_qty;
  end loop;

  v_discount_cents := round((v_raw_sub::numeric * v_discount_bps::numeric) / 10000.0, 0)::int;
  v_remaining := (v_raw_sub - v_discount_cents)::int;

  v_rewards_enabled := coalesce(
    (public.store_setting(v_store, 'rewards_enabled', 'true'::jsonb) #>> '{}')::boolean,
    true
  );

  if p_customer_id is not null and v_channel in ('floor', 'website') and v_rewards_enabled then
    select * into v_cust from public.customers
     where id = p_customer_id and store_id = v_store;
    if found and not v_cust.first_purchase_discount_used then
      v_signup_bps := public.store_setting_int(v_store, 'rewards_signup_discount_bps', 500);
      v_signup_cents := round((v_remaining::numeric * v_signup_bps::numeric) / 10000.0, 0)::int;
      v_remaining := v_remaining - v_signup_cents;
    end if;
    if found and v_redeem_points > 0 then
      v_bal := public.customer_points_balance_internal(v_store, v_cust.id);
      v_point_value := public.store_setting_int(v_store, 'rewards_point_value_cents', 1);
      v_redeem_cents := least(v_redeem_points, v_bal) * v_point_value;
      v_redeem_cents := least(v_redeem_cents, v_remaining);
      v_remaining := v_remaining - v_redeem_cents;
    end if;
  end if;

  v_total_disc := v_discount_cents + v_signup_cents + v_redeem_cents;
  v_shares := public.prorate_cents(v_prices, v_total_disc);
  for v_i in 1..v_n loop
    v_net := v_net || greatest(v_prices[v_i] - v_shares[v_i], 0);
    v_net_sub := v_net_sub + greatest(v_prices[v_i] - v_shares[v_i], 0);
  end loop;
  v_taxes := public.allocate_line_taxes(v_net, v_bps);
  for v_i in 1..v_n loop
    v_tax := v_tax + v_taxes[v_i];
  end loop;

  v_prefee := v_net_sub + v_tax;
  v_fee_bps := greatest(public.store_setting_int(v_store, 'card_fee_bps', 250), 0);

  if v_pay = 'card' then
    v_card_base := v_prefee;
  elsif v_pay = 'split' then
    if p_cash_cents is null or p_cash_cents < 0 or p_cash_cents >= v_prefee then
      raise exception 'invalid_split' using errcode = '22023';
    end if;
    v_card_base := v_prefee - p_cash_cents;
  else
    v_card_base := 0;
  end if;
  v_fee := round((v_card_base::numeric * v_fee_bps::numeric) / 10000.0, 0)::int;

  return jsonb_build_object(
    'raw_subtotal_cents', v_raw_sub,
    'discount_bps', v_discount_bps,
    'discount_cents', v_discount_cents,
    'signup_discount_cents', v_signup_cents,
    'redeem_cents', v_redeem_cents,
    'subtotal_cents', v_net_sub,
    'tax_cents', v_tax,
    'pre_fee_total_cents', v_prefee,
    'card_fee_bps', v_fee_bps,
    'card_base_cents', v_card_base,
    'card_fee_cents', v_fee,
    'card_charge_cents', v_card_base + v_fee,
    'total_cents', v_prefee + v_fee
  );
end;
$$;


ALTER FUNCTION "public"."quote_ticket_totals"("p_lines" "jsonb", "p_discount_bps" integer, "p_customer_id" "uuid", "p_redeem_points" integer, "p_channel" "text", "p_payment_method" "text", "p_cash_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."valid_gtin"("p_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    AS $_$
declare v_code text := trim(coalesce(p_code,'')); v_sum int := 0; v_len int; v_i int;
begin
  if v_code = '' then return true; end if;
  v_len := length(v_code);
  if v_len not in (12,13,14) or v_code !~ '^[0-9]+$' then return false; end if;
  for v_i in 1..v_len-1 loop
    v_sum := v_sum + substr(v_code,v_i,1)::int *
      case when (v_len-v_i) % 2 = 1 then 3 else 1 end;
  end loop;
  return substr(v_code,v_len,1)::int = (10-v_sum%10)%10;
end $_$;


ALTER FUNCTION "public"."valid_gtin"("p_code" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."units" (
    "id" bigint NOT NULL,
    "sku" "text" NOT NULL,
    "brand" "text" DEFAULT ''::"text" NOT NULL,
    "model" "text" DEFAULT ''::"text" NOT NULL,
    "title" "text" DEFAULT ''::"text" NOT NULL,
    "category" "text",
    "condition" "text",
    "test_status" "text",
    "location" "text",
    "mfr_serial" "text",
    "defect_notes" "text",
    "upc" "text",
    "lot" "text",
    "acquisition_cost_cents" integer,
    "msrp_cents" integer,
    "ask_cents" integer,
    "floor_cents" integer,
    "state" "text" DEFAULT 'available'::"text" NOT NULL,
    "show_on_website" boolean DEFAULT false NOT NULL,
    "received_at" timestamp with time zone NOT NULL,
    "updated_at" timestamp with time zone NOT NULL,
    "store_id" "uuid",
    "listing_body" "text",
    "listing_specs" "jsonb",
    "qty_on_hand" integer DEFAULT 1 NOT NULL,
    "shippable" boolean DEFAULT false NOT NULL,
    "shipping_cents" integer,
    "ai_description" "text",
    "ebay_title" "text",
    "ebay_category" "text",
    "ebay_item_specifics" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "retail_price_sources" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "retail_source_name" "text",
    "retail_source_url" "text",
    "product_height_in" numeric(10,2),
    "product_width_in" numeric(10,2),
    "product_depth_in" numeric(10,2),
    "product_weight_lb" numeric(10,2),
    "package_length_in" numeric(10,2),
    "package_width_in" numeric(10,2),
    "package_height_in" numeric(10,2),
    "package_weight_lb" numeric(10,2),
    "dims_source" "text",
    "fulfillment_override" "text",
    "is_test" boolean DEFAULT false NOT NULL,
    "upc_rejected" "text",
    "listed_on" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "requires_power" boolean,
    "is_electrical" boolean,
    "is_camera" boolean,
    "has_stock_photos" boolean DEFAULT false NOT NULL,
    "has_ai_images" boolean DEFAULT false NOT NULL,
    "has_manufacturer_photos" boolean DEFAULT false NOT NULL,
    "is_collectible" boolean DEFAULT false NOT NULL,
    "supplier_id" "uuid",
    "ebay_never_list" boolean DEFAULT false NOT NULL,
    "manifest_id" "uuid",
    "internal_category" "text",
    CONSTRAINT "units_acquisition_cost_cents_check" CHECK ((("acquisition_cost_cents" IS NULL) OR ("acquisition_cost_cents" >= 0))),
    CONSTRAINT "units_ask_cents_check" CHECK ((("ask_cents" IS NULL) OR ("ask_cents" >= 0))),
    CONSTRAINT "units_dims_source_allowed" CHECK ((("dims_source" IS NULL) OR ("dims_source" = ANY (ARRAY['verified'::"text", 'estimated'::"text", 'measured'::"text"])))),
    CONSTRAINT "units_floor_cents_check" CHECK ((("floor_cents" IS NULL) OR ("floor_cents" >= 0))),
    CONSTRAINT "units_fulfillment_override_allowed" CHECK ((("fulfillment_override" IS NULL) OR ("fulfillment_override" = ANY (ARRAY['ship'::"text", 'pickup'::"text"])))),
    CONSTRAINT "units_msrp_cents_check" CHECK ((("msrp_cents" IS NULL) OR ("msrp_cents" >= 0))),
    CONSTRAINT "units_qty_on_hand_check" CHECK (("qty_on_hand" >= 0)),
    CONSTRAINT "units_shipping_cents_check" CHECK ((("shipping_cents" IS NULL) OR ("shipping_cents" >= 0))),
    CONSTRAINT "units_state_check" CHECK (("state" = ANY (ARRAY['available'::"text", 'reserved'::"text", 'repair'::"text", 'sold'::"text", 'voided'::"text", 'scrapped'::"text", 'lost'::"text"]))),
    CONSTRAINT "units_upc_valid_gtin" CHECK ("public"."valid_gtin"("upc"))
);


ALTER TABLE "public"."units" OWNER TO "postgres";


COMMENT ON COLUMN "public"."units"."listing_body" IS 'Original product description. Floor condition/test/defects stay on their own columns.';



COMMENT ON COLUMN "public"."units"."listing_specs" IS 'JSON: ebay aspects, market comps, marketplace_pricing (online prices). Never use ask_cents as marketplace price.';



COMMENT ON COLUMN "public"."units"."shipping_cents" IS 'Optional per-unit shipping override in cents. Null uses weight tiers. Zero is free shipping for this unit.';



COMMENT ON COLUMN "public"."units"."ebay_never_list" IS 'Never publish or republish this unit to eBay; unrelated channels remain eligible.';



CREATE OR REPLACE FUNCTION "public"."receive_unit"("p_sku" "text", "p_brand" "text" DEFAULT ''::"text", "p_model" "text" DEFAULT ''::"text", "p_title" "text" DEFAULT ''::"text", "p_category" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_test_status" "text" DEFAULT NULL::"text", "p_location" "text" DEFAULT NULL::"text", "p_ask_cents" integer DEFAULT NULL::integer, "p_msrp_cents" integer DEFAULT NULL::integer, "p_cost_cents" integer DEFAULT NULL::integer, "p_floor_cents" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text", "p_upc" "text" DEFAULT NULL::"text", "p_lot" "text" DEFAULT NULL::"text", "p_mfr_serial" "text" DEFAULT NULL::"text", "p_length" numeric DEFAULT NULL::numeric, "p_width" numeric DEFAULT NULL::numeric, "p_height" numeric DEFAULT NULL::numeric, "p_weight" numeric DEFAULT NULL::numeric) RETURNS "public"."units"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.current_store_id();
  v_sku text := btrim(p_sku);
  v_row public.units;
  v_cost int;
  v_floor int;
  v_status text;
  v_actor text;
  v_reuse boolean := false;
  v_upc text := nullif(btrim(coalesce(p_upc, '')), '');
  v_upc_rejected text := null;
  v_upc_dna boolean := false;
  v_specs jsonb := '{}'::jsonb;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if not public.is_sku(v_sku) then
    raise exception 'invalid_sku' using errcode = '22023';
  end if;

  if v_upc is not null and v_upc ~* '^(does not apply|n/?a)$' then
    v_upc_dna := true;
    v_upc := null;
    v_specs := jsonb_build_object(
      'upc', 'Does not apply',
      'ebay_aspects', jsonb_build_object('UPC', 'Does not apply')
    );
  elsif v_upc is not null and not public.valid_gtin(v_upc) then
    v_upc_rejected := v_upc;
    v_upc := null;
  end if;

  v_status := public.sku_status(v_sku) ->> 'status';
  if v_status = 'taken' then
    raise exception 'SKU % is already in inventory.', v_sku using errcode = 'P0001';
  end if;
  if v_status = 'locked' then
    raise exception 'SKU % was used before and can''t be reused.', v_sku using errcode = 'P0001';
  end if;
  if v_status = 'invalid' then
    raise exception 'invalid_sku' using errcode = '22023';
  end if;

  v_cost := case when public.is_manager() then p_cost_cents else null end;
  v_floor := case when public.is_manager() then p_floor_cents else null end;
  v_actor := coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff');

  if v_status = 'reusable' then
    v_reuse := true;
    update public.sku_ledger
       set fate = 'issued',
           label = coalesce(nullif(btrim(p_title), ''), label)
     where sku = v_sku and store_id is not distinct from v_store;
  else
    insert into public.sku_ledger (store_id, sku, issued_at, label, fate)
    values (v_store, v_sku, now(), coalesce(p_title, ''), 'issued');
  end if;

  insert into public.units (
    store_id, sku, brand, model, title, category, condition, test_status, location,
    mfr_serial, defect_notes, upc, upc_rejected, lot, acquisition_cost_cents, msrp_cents, ask_cents,
    floor_cents, state, show_on_website, received_at, updated_at,
    package_length_in, package_width_in, package_height_in, package_weight_lb, dims_source,
    listing_specs
  ) values (
    v_store, v_sku, coalesce(p_brand,''), coalesce(p_model,''), coalesce(p_title,''),
    p_category, p_condition, p_test_status, p_location, p_mfr_serial, p_notes, v_upc, v_upc_rejected, p_lot,
    v_cost, p_msrp_cents, p_ask_cents, v_floor, 'available', false, now(), now(),
    p_length, p_width, p_height, p_weight,
    case when p_length is not null or p_width is not null or p_height is not null or p_weight is not null
      then 'verified' else null end,
    case when v_upc_dna then v_specs else null end
  )
  returning * into v_row;

  if v_reuse then
    insert into public.events (store_id, sku, kind, actor, actor_id, note)
    values (v_store, v_sku, 'sku_reused', v_actor, auth.uid(), 'reused after delete with no sale');
  end if;

  insert into public.events (store_id, sku, kind, actor, actor_id, note)
  values (v_store, v_sku, 'received', v_actor, auth.uid(),
    case when v_upc_dna then 'UPC Does not apply' else null end);
  return v_row;
end $_$;


