CREATE OR REPLACE FUNCTION "public"."release_expired_reservations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  n int;
begin
  update public.web_orders o
     set status = 'expired', updated_at = now()
   where o.status = 'claimed'
     and exists (
       select 1 from public.reservations r
        where r.id = o.reservation_id
          and r.released_at is null
          and r.finalized_at is null
          and r.expires_at <= now()
     );
  update public.reservations
     set released_at = now()
   where released_at is null
     and finalized_at is null
     and expires_at <= now();
  get diagnostics n = row_count;
  update public.units u
     set state = 'available', updated_at = now()
   where u.state = 'reserved'
     and not exists (
       select 1 from public.reservations r
        where r.sku = u.sku
          and r.store_id is not distinct from u.store_id
          and r.released_at is null
          and r.finalized_at is null
     )
     and not exists (
       select 1 from public.sales s
        where s.sku = u.sku
          and s.store_id is not distinct from u.store_id
          and s.voided_at is null
     );
  return n;
end;
$$;


ALTER FUNCTION "public"."release_expired_reservations"() OWNER TO "postgres";


