CREATE OR REPLACE FUNCTION "public"."release_reservation"("p_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_sku text;
  v_store uuid;
begin
  perform public.assert_staff_or_service();

  update public.reservations
     set released_at = now()
   where id = p_id
     and released_at is null
     and finalized_at is null
     and (store_id = public.current_store_id() or auth.role() = 'service_role')
  returning sku, store_id into v_sku, v_store;
  if not found then
    return;
  end if;

  update public.units
     set state = 'available', updated_at = now()
   where sku = v_sku
     and store_id is not distinct from v_store
     and state = 'reserved'
     and not exists (
       select 1 from public.sales s
        where s.store_id is not distinct from v_store
          and s.sku = v_sku and s.voided_at is null
     );
end;
$$;


ALTER FUNCTION "public"."release_reservation"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_shipping_checkout"("p_store" "uuid", "p_reservation" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare o public.web_orders;
begin
  perform public.assert_service();
  perform 1 from public.units where store_id=p_store and sku=(select sku from public.web_orders where reservation_id=p_reservation and store_id=p_store limit 1) for update;
  select * into o from public.web_orders where store_id=p_store and reservation_id=p_reservation for update;
  if not found then return; end if;
  if o.payment_started_at is not null or o.status='paid' then raise exception 'payment_in_progress'; end if;
  perform public.web_release_reservation(p_store,p_reservation);
  update public.web_orders set status='canceled' where id=o.id and status='claimed';
end $$;


