CREATE OR REPLACE FUNCTION "public"."remove_category"("p_name" "text", "p_move_to" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_name text := btrim(coalesce(p_name, ''));
  v_move text := nullif(btrim(coalesce(p_move_to, '')), '');
  v_names text[];
  v_used int;
begin
  perform public.assert_manager();
  if v_name = '' then
    raise exception 'Enter a category name.' using errcode = '22023';
  end if;
  v_names := public.store_category_names(v_store);
  if array_position(v_names, v_name) is null then
    raise exception 'Category % is not on the list.', v_name using errcode = 'P0001';
  end if;
  if cardinality(v_names) = 1 then
    raise exception 'Keep at least one category.' using errcode = 'P0001';
  end if;

  select count(*) into v_used
    from public.units
   where store_id is not distinct from v_store
     and category = v_name;

  if v_used > 0 then
    if v_move is null then
      raise exception '% items use this, move them first', v_used using errcode = 'P0001';
    end if;
    if v_move = v_name then
      raise exception 'Pick a different category to move items to.' using errcode = 'P0001';
    end if;
    if array_position(v_names, v_move) is null then
      raise exception 'Category % is not on the list.', v_move using errcode = 'P0001';
    end if;
    update public.units
       set category = v_move, updated_at = now()
     where store_id is not distinct from v_store
       and category = v_name;
  end if;

  v_names := array_remove(v_names, v_name);
  perform public.save_store_categories(v_store, v_names);
  insert into public.events (store_id, sku, kind, old_value, new_value, actor, actor_id, note)
  values (
    v_store, null, 'category_remove', v_name, v_move,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'manager'),
    auth.uid(),
    case when v_used > 0 then format('moved %s items to %s', v_used, v_move) else 'unused' end
  );
end;
$$;


ALTER FUNCTION "public"."remove_category"("p_name" "text", "p_move_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rename_category"("p_from" "text", "p_to" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_from text := btrim(coalesce(p_from, ''));
  v_to text := btrim(coalesce(p_to, ''));
  v_names text[];
  i int;
begin
  perform public.assert_manager();
  if v_from = '' or v_to = '' then
    raise exception 'Enter a category name.' using errcode = '22023';
  end if;
  v_names := public.store_category_names(v_store);
  i := array_position(v_names, v_from);
  if i is null then
    raise exception 'Category % is not on the list.', v_from using errcode = 'P0001';
  end if;
  if v_from = v_to then
    return;
  end if;
  if v_to = any (v_names) then
    raise exception 'Category % already exists.', v_to using errcode = 'P0001';
  end if;
  v_names[i] := v_to;
  perform public.save_store_categories(v_store, v_names);
  update public.units
     set category = v_to, updated_at = now()
   where store_id is not distinct from v_store
     and category = v_from;
  insert into public.events (store_id, sku, kind, old_value, new_value, actor, actor_id)
  values (
    v_store, null, 'category_rename', v_from, v_to,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'manager'),
    auth.uid()
  );
end;
$$;


ALTER FUNCTION "public"."rename_category"("p_from" "text", "p_to" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_categories"("p_names" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_old text[];
  v_new text[];
begin
  perform public.assert_manager();
  v_old := public.store_category_names(v_store);
  select coalesce(array_agg(btrim(x)), array[]::text[])
    into v_new
  from unnest(coalesce(p_names, array[]::text[])) as x
  where btrim(x) <> '';
  if (select count(*) from unnest(v_new) t(x)) <> (select count(distinct x) from unnest(v_new) t(x)) then
    raise exception 'Category names must be unique.' using errcode = 'P0001';
  end if;
  if (select array_agg(x order by x) from unnest(v_old) t(x))
     is distinct from (select array_agg(x order by x) from unnest(v_new) t(x)) then
    raise exception 'Reorder has to keep the same categories.' using errcode = 'P0001';
  end if;
  perform public.save_store_categories(v_store, v_new);
  insert into public.events (store_id, sku, kind, actor, actor_id, note)
  values (
    v_store, null, 'category_reorder',
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'manager'),
    auth.uid(),
    'reordered'
  );
end;
$$;


ALTER FUNCTION "public"."reorder_categories"("p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reorder_unit_photos"("p_sku" "text", "p_ids" bigint[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.current_store_id(); v_count int;
begin
  perform public.assert_staff_or_service();
  select count(*) into v_count from public.photos where store_id=v_store and sku=p_sku;
  if v_count<>cardinality(p_ids) or
    (select count(distinct id) from unnest(p_ids) id)<>v_count or
    exists(select 1 from unnest(p_ids) id where not exists
      (select 1 from public.photos p where p.id=id and p.store_id=v_store and p.sku=p_sku)) then
    raise exception 'invalid_photo_order' using errcode='22023';
  end if;
  update public.photos p set sort_order=x.ordinality-1
  from unnest(p_ids) with ordinality x(id,ordinality)
  where p.id=x.id and p.store_id=v_store and p.sku=p_sku;
  insert into public.events(store_id,sku,kind,field,new_value,actor,actor_id)
  values(v_store,p_sku,'edit','photo_order',p_ids::text,
    coalesce((select display_name from public.staff where user_id=auth.uid()),'staff'),auth.uid());
end $$;


ALTER FUNCTION "public"."reorder_unit_photos"("p_sku" "text", "p_ids" bigint[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_web_order_refund"("p_store" "uuid", "p_order" "uuid", "p_source" "text", "p_reason" "text") RETURNS "public"."web_orders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare o public.web_orders;
begin
  perform public.assert_service();
  select * into o from public.web_orders where id = p_order and store_id = p_store for update;
  if not found then raise exception 'order_not_found' using errcode = 'P0001'; end if;
  if o.refund_requested_at is not null and o.status = 'paid' then return o; end if;
  if o.status <> 'paid' then raise exception 'order_not_cancellable' using errcode = 'P0001'; end if;
  if o.picked_up_at is not null then raise exception 'already_picked_up' using errcode = 'P0001'; end if;
  if o.shipped_at is not null then raise exception 'already_shipped' using errcode = 'P0001'; end if;
  if p_source = 'pickup_expired' and (o.fulfillment <> 'pickup' or o.pickup_deadline > now()) then
    raise exception 'pickup_not_expired' using errcode = 'P0001';
  end if;
  update public.web_orders set refund_requested_at = now(), cancel_source = p_source,
    cancel_reason = nullif(btrim(p_reason),''), updated_at = now() where id = o.id returning * into o;
  return o;
end $$;


ALTER FUNCTION "public"."request_web_order_refund"("p_store" "uuid", "p_order" "uuid", "p_source" "text", "p_reason" "text") OWNER TO "postgres";


