    AS $$
  select make_interval(
    secs => coalesce(
      (public.store_setting(public.current_store_id(), 'reservationTtlSeconds', '180'::jsonb) #>> '{}')::int,
      180
    )
  );
$$;


ALTER FUNCTION "public"."reservation_ttl"() OWNER TO "postgres";


