ALTER FUNCTION "public"."resolve_incident"("p_id" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_apply_commission_clawbacks"("p_return_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r public.returns;
  s public.sales;
  v_ticket text;
  v_emp uuid;
  v_full_comm int;
  v_reversal int;
  v_frac numeric;
  v_claw int;
  v_amt int;
  v_reason text;
  v_paid bigint;
  v_reimburse bigint;
  v_earned_prior bigint;
  v_covered bigint;
  v_rows jsonb := '[]'::jsonb;
  v_paul uuid;
  v_jacob uuid;
  v_online_emp uuid;
begin
  select * into r from public.returns where id = p_return_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'return_not_found'); end if;
  if r.sale_id is null then return jsonb_build_object('ok', true, 'adjustments', '[]'::jsonb, 'note', 'no_sale'); end if;

  select * into s from public.sales where id = r.sale_id and store_id = r.store_id;
  if not found then return jsonb_build_object('ok', true, 'adjustments', '[]'::jsonb, 'note', 'sale_missing'); end if;

  v_ticket := coalesce(s.ticket_id::text, 'sale:' || s.id::text);
  v_paul := public.payout_slot_employee(r.store_id, 'paul');
  v_jacob := public.payout_slot_employee(r.store_id, 'jacob');
  if coalesce(s.price_cents, 0) <= 0 then
    v_frac := 1;
  else
    v_frac := least(1, greatest(0, coalesce(r.refund_cents, s.price_cents)::numeric / s.price_cents::numeric));
  end if;

  begin
    v_online_emp := nullif(public.store_setting(r.store_id, 'online_payout_employee_id', 'null'::jsonb) #>> '{}', '')::uuid;
  exception when others then v_online_emp := null;
  end;

  for v_emp in
    select distinct x from unnest(array[
      v_paul, v_jacob, v_online_emp
    ] || array(select employee_id from public.portal_payout_rules where store_id = r.store_id)) as t(x)
    where x is not null
  loop
    v_full_comm := public.sale_commission_cents(r.store_id, r.sale_id, v_emp);
    if v_full_comm is null or v_full_comm <= 0 then continue; end if;
    v_reversal := round(v_full_comm * v_frac)::int;

    select coalesce(sum(amount_cents), 0) into v_paid
      from public.portal_payout_payments
     where store_id = r.store_id and employee_id = v_emp;

    v_claw := 0;
    if v_paid > 0 and v_reversal > 0 then
      select coalesce(sum(amount_cents), 0) into v_reimburse
        from public.portal_expenses
       where store_id = r.store_id and employee_id = v_emp
         and needs_reimbursement and voided_at is null;

      select coalesce(sum(cents), 0) into v_earned_prior from (
        select public.sale_commission_cents(r.store_id, ss.id, v_emp) as cents
          from public.sales ss
         where ss.store_id = r.store_id and ss.voided_at is null and ss.id <> r.sale_id
      ) x where cents is not null;

      v_earned_prior := v_earned_prior + coalesce((
        select sum(amount_cents) from public.portal_payout_adjustments
         where store_id = r.store_id and employee_id = v_emp
           and (return_id is null or return_id <> r.id)
      ), 0);

      v_covered := greatest(0, v_paid - v_reimburse - greatest(0, v_earned_prior));
      v_claw := least(v_reversal, v_covered::int);
    end if;

    -- Unpaid full refund: commission just drops with the void — no adjustment row.
    if v_claw <= 0 and v_frac >= 1 then continue; end if;

    if v_claw > 0 then
      -- Already paid (at least in part): negative clawback for the reversed share.
      -- Payouts UI add-backs sale_commission_cents so void+addback+claw net to −reversal.
      v_amt := -v_reversal;
      v_reason := format(
        'Return clawback SKU %s · %s · refund %s%% · return %s',
        r.sku, upper(r.channel), round(v_frac * 100)::text, r.id::text
      );
    else
      -- Unpaid partial refund: void drops full sale; retain the unrefunded commission share.
      v_amt := round(v_full_comm * (1.0 - v_frac))::int;
      if v_amt = 0 then continue; end if;
      v_reason := format(
        'Return partial retain SKU %s · %s · kept %s%% commission · return %s',
        r.sku, upper(r.channel), round((1 - v_frac) * 100)::text, r.id::text
      );
    end if;

    insert into public.portal_payout_adjustments (
      store_id, employee_id, amount_cents, reason, return_id, sale_id, ticket_key,
      sale_commission_cents, created_by
    ) values (
      r.store_id, v_emp, v_amt, v_reason,
      r.id, r.sale_id, v_ticket, v_full_comm, auth.uid()
    )
    on conflict (store_id, return_id, employee_id) do update set
      amount_cents = excluded.amount_cents,
      reason = excluded.reason,
      sale_commission_cents = excluded.sale_commission_cents,
      created_at = now();

    v_rows := v_rows || jsonb_build_array(jsonb_build_object(
      'employee_id', v_emp, 'adjustment_cents', v_amt,
      'clawback_cents', v_claw, 'sale_commission_cents', v_full_comm
    ));
  end loop;

  return jsonb_build_object('ok', true, 'adjustments', v_rows, 'refund_fraction', v_frac);
end $$;


ALTER FUNCTION "public"."return_apply_commission_clawbacks"("p_return_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_post_ledger"("p_return_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  r public.returns;
  v_extras int;
  v_desc text;
  v_sale_voided boolean := false;
begin
  select * into r from public.returns where id = p_return_id for update;
  if not found then return; end if;
  if r.ledger_posted_at is not null then return; end if;

  if r.sale_id is not null then
    select voided_at is not null into v_sale_voided
      from public.sales where id = r.sale_id;
  end if;
  -- Paths that reverse the sale always void; treat refund-no-return / dispositioned the same.
  if r.status in ('refunded_no_return', 'dispositioned', 'closed')
     or r.disposition is not null then
    v_sale_voided := true;
  end if;

  -- Extra costs only. Refund is represented by voiding the sale (revenue reversal).
  v_extras :=
    case when r.label_paid_by = 'seller' then coalesce(r.return_label_cents, 0) else 0 end
    + coalesce(r.unrecovered_fees_cents, 0)
    + coalesce(r.regrade_loss_cents, 0);

  -- Only if somehow a return posts without voiding the sale, include refund once.
  if not coalesce(v_sale_voided, false) then
    v_extras := v_extras + coalesce(r.refund_cents, 0);
  end if;

  if v_extras <= 0 then
    update public.returns set ledger_posted_at = now(), updated_at = now() where id = r.id;
    return;
  end if;

  v_desc := 'Return extras ' || upper(r.channel) || ' SKU ' || r.sku
    || coalesce(' order ' || r.external_order_id, '')
    || ' (label/fees/regrade; refund via voided sale)';

  -- Replace any prior double-counted return expense for this return.
  update public.portal_expenses set
    voided_at = coalesce(voided_at, now()),
    void_reason = coalesce(void_reason, 'returns_ledger_fix')
  where store_id = r.store_id and source = 'return' and external_id = r.id::text
    and voided_at is null;

  insert into public.portal_expenses(
    store_id, spent_on, description, category, amount_cents,
    needs_reimbursement, source, order_id, external_id
  ) values (
    r.store_id,
    (timezone('America/Los_Angeles', now()))::date,
    v_desc,
    'Returns',
    v_extras,
    false,
    'return',
    r.web_order_id,
    r.id::text
  );

  update public.returns set ledger_posted_at = now(), updated_at = now() where id = r.id;
end $$;


ALTER FUNCTION "public"."return_post_ledger"("p_return_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_reverse_sale"("p_store" "uuid", "p_sale_id" bigint, "p_reason" "text", "p_restock" boolean DEFAULT true) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r public.sales;
begin
  perform set_config('floor.store_id',p_store::text,true);
  if p_sale_id is null then return; end if;
  select * into r from public.sales
    where id=p_sale_id and store_id=p_store and voided_at is null for update;
  if not found then return; end if;
  perform set_config('floor.bundle_restock',case when p_restock then 'true' else 'false' end,true);
  update public.sales set voided_at=now(),void_reason=btrim(coalesce(p_reason,'return')) where id=r.id;
  perform set_config('floor.bundle_restock','true',true);
  update public.sku_ledger set fate=case when p_restock then 'issued' else 'retired' end
    where store_id=p_store and sku=r.sku;
  if p_restock then
    update public.units set state=case
      when exists(select 1 from public.floor_bundles b where b.store_id=p_store and b.sku=r.sku and not b.active)
        then 'voided'
      when qty_on_hand>0 then 'available' else 'sold' end,updated_at=now()
      where store_id=p_store and sku=r.sku;
    perform public.enqueue_sale_relist_alerts(r);
  else
    update public.units set state=case
      when exists(select 1 from public.floor_bundles b where b.store_id=p_store and b.sku=r.sku)
        and qty_on_hand>0 then 'available' else 'lost' end,updated_at=now()
      where store_id=p_store and sku=r.sku;
  end if;
  insert into public.events(store_id,sku,kind,actor,note)
    values(p_store,r.sku,'sale_void',
      coalesce((select display_name from public.staff where user_id=auth.uid()),'returns'),
      btrim(coalesce(p_reason,'return'))||case when p_restock then ' (restock)' else ' (no restock)' end);
end $$;


ALTER FUNCTION "public"."return_reverse_sale"("p_store" "uuid", "p_sale_id" bigint, "p_reason" "text", "p_restock" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_risk_channel_gate"("p_store" "uuid", "p_sku" "text", "p_channel" "text") RETURNS TABLE("status" "text", "reason" "text", "source" "text")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  u public.units;
  v_channel text := lower(btrim(coalesce(p_channel, '')));
  v_settings jsonb := public.return_settings(p_store);
  v_gate jsonb;
  v_cond text;
  v_blocked text;
  v_photo_count int;
  v_real_photos boolean;
begin
  if v_channel not in ('amazon', 'tiktok') then
    return query select 'allow'::text, 'n/a'::text, 'return_gate'::text;
    return;
  end if;

  select * into u from public.units where store_id = p_store and sku = p_sku;
  if not found then
    return query select 'block'::text, 'Unit not found'::text, 'return_gate'::text;
    return;
  end if;

  v_gate := coalesce(v_settings->'gate_amazon_tiktok', '{}'::jsonb);
  v_cond := lower(btrim(coalesce(u.condition, '')));

  for v_blocked in
    select lower(btrim(x)) from jsonb_array_elements_text(coalesce(v_gate->'block_conditions', '[]'::jsonb)) x
  loop
    if v_cond <> '' and (v_cond = v_blocked or v_cond like '%' || v_blocked || '%') then
      return query select 'block'::text,
        public.channel_display_name(v_channel) || ': blocked — condition "' || coalesce(u.condition, '') || '" not eligible for forced-return channels',
        'return_gate'::text;
      return;
    end if;
  end loop;

  if coalesce((v_gate->>'require_real_photos')::boolean, true) then
    select count(*)::int into v_photo_count
      from public.photos p where p.store_id = p_store and p.sku = p_sku;
    v_real_photos := v_photo_count > 0
      and coalesce(u.has_stock_photos, false) is not true
      and coalesce(u.has_ai_images, false) is not true;
    if not v_real_photos then
      return query select 'block'::text,
        public.channel_display_name(v_channel) || ': blocked — needs real unit photos before Amazon/TikTok listing',
        'return_gate'::text;
      return;
    end if;
  end if;

  return query select 'allow'::text, 'return risk ok'::text, 'return_gate'::text;
end $$;


ALTER FUNCTION "public"."return_risk_channel_gate"("p_store" "uuid", "p_sku" "text", "p_channel" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."return_settings"("p_store" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  d jsonb := public.default_return_settings();
  v jsonb;
begin
  select value into v from public.store_settings
   where store_id = p_store and key = 'return_settings';
  v := coalesce(v, '{}'::jsonb);
  return d || v
    || jsonb_build_object(
      'reserve_pct', coalesce(d->'reserve_pct', '{}'::jsonb) || coalesce(v->'reserve_pct', '{}'::jsonb),
      'decision_hours', coalesce(d->'decision_hours', '{}'::jsonb) || coalesce(v->'decision_hours', '{}'::jsonb),
      'gate_amazon_tiktok', coalesce(d->'gate_amazon_tiktok', '{}'::jsonb) || coalesce(v->'gate_amazon_tiktok', '{}'::jsonb)
    );
end $$;


ALTER FUNCTION "public"."return_settings"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."returns_should_refund_no_return"("p_store" "uuid", "p_item_cents" integer, "p_label_cents" integer) RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v jsonb := public.return_settings(p_store);
declare v_max int := coalesce((v->>'refund_no_return_max_item_cents')::int, 1500);
declare v_label_rule boolean := coalesce((v->>'refund_no_return_if_label_exceeds_item')::boolean, true);
begin
  if coalesce(p_item_cents, 0) > 0 and p_item_cents <= v_max then return true; end if;
  if v_label_rule and coalesce(p_label_cents, 0) > 0 and coalesce(p_item_cents, 0) > 0
     and p_label_cents >= p_item_cents then
    return true;
  end if;
  return false;
end $$;


ALTER FUNCTION "public"."returns_should_refund_no_return"("p_store" "uuid", "p_item_cents" integer, "p_label_cents" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sale_commission_cents"("p_store" "uuid", "p_sale_id" bigint, "p_employee" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s public.sales;
  v_cost int;
  v_base int;
  v_ticket text;
  v_channel text;
  v_online_channels jsonb;
  v_online_pct numeric;
  v_online_emp uuid;
  v_is_online boolean := false;
  v_ov record;
  v_rule record;
  v_rate numeric;
  v_paul uuid := public.payout_slot_employee(p_store, 'paul');
  v_jacob uuid := public.payout_slot_employee(p_store, 'jacob');
begin
  if exists(select 1 from public.sale_payout_lines where sale_id = p_sale_id and store_id = p_store) then
    return coalesce((select amount_cents from public.sale_commissions
      where sale_id = p_sale_id and employee_id = p_employee), 0);
  end if;

  select * into s from public.sales where id = p_sale_id and store_id = p_store;
  if not found then return 0; end if;

  select cost_cents,
    greatest(0, price_cents + coalesce(tax_collected_cents, 0) + coalesce(shipping_cents, 0) - coalesce(channel_fee_cents, 0)
      - coalesce(ship_cost_cents, 0) - coalesce(processing_fee_cents, 0)
      - coalesce(tax_collected_cents, 0) - cost_cents)
    into v_cost, v_base
  from public.sale_ledger where id = s.id;
  if v_cost is null then return null; end if;
  v_ticket := coalesce(s.ticket_id::text, 'sale:' || s.id::text);
  v_channel := lower(coalesce(s.channel, ''));

  select value into v_online_channels from public.store_settings
   where store_id = p_store and key = 'online_payout_channels';
  if v_online_channels is null then
    select value into v_online_channels from public.store_settings
     where store_id = p_store and key = 'online_channels';
  end if;
  v_online_pct := coalesce((public.store_setting(p_store, 'online_payout_pct', '0'::jsonb) #>> '{}')::numeric, 0);
  begin
    v_online_emp := nullif(public.store_setting(p_store, 'online_payout_employee_id', 'null'::jsonb) #>> '{}', '')::uuid;
  exception when others then v_online_emp := null;
  end;

  if v_online_channels is not null and jsonb_typeof(v_online_channels) = 'array' then
    select exists (
      select 1 from jsonb_array_elements_text(v_online_channels) x
      where lower(btrim(x)) = v_channel
    ) into v_is_online;
  end if;

  select * into v_ov from public.portal_commission_overrides
   where store_id = p_store and ticket_key = v_ticket;
  if found then
    if p_employee = v_paul then
      return round(v_base * coalesce(v_ov.paul_pct, 0) / 100.0)::int;
    elsif p_employee = v_jacob then
      return round(v_base * coalesce(v_ov.jacob_pct, 0) / 100.0)::int;
    else
      return 0;
    end if;
  end if;

  if v_is_online then
    if p_employee is distinct from v_online_emp then return 0; end if;
    return round(v_base * v_online_pct / 100.0)::int;
  end if;

  select * into v_rule from public.portal_payout_rules
   where store_id = p_store and employee_id = p_employee;
  if not found then return 0; end if;

  if v_rule.method = 'flat_ticket' then
    return round(v_rule.rate * 100)::int;
  end if;
  if v_rule.method = 'percent_profit' then
    v_rate := v_rule.rate;
    return round(v_base * v_rate / 100.0)::int;
  end if;
  return round(s.price_cents * v_rule.rate / 100.0)::int;
end $$;


ALTER FUNCTION "public"."sale_commission_cents"("p_store" "uuid", "p_sale_id" bigint, "p_employee" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sale_set_processing_fee"("p_store" "uuid", "p_sale" bigint, "p_fee_cents" integer, "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_service();
  if p_fee_cents is null or p_fee_cents < 0 then raise exception 'invalid_fee'; end if;
  if p_source not in ('actual','estimated') then raise exception 'invalid_source'; end if;
  update public.sales set processing_fee_cents = p_fee_cents, processing_fee_source = p_source
   where id = p_sale and store_id = p_store
     and (processing_fee_cents is null or processing_fee_source = 'estimated');
end $$;


ALTER FUNCTION "public"."sale_set_processing_fee"("p_store" "uuid", "p_sale" bigint, "p_fee_cents" integer, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_shipping_quote"("p_store" "uuid", "p_sku" "text", "p_postal" "text", "p_region" "text", "p_rates" "jsonb", "p_source" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_id uuid;
begin
  perform public.assert_service();
  if jsonb_typeof(p_rates) <> 'array' or jsonb_array_length(p_rates) = 0
     or exists(select 1 from jsonb_array_elements(p_rates) r where coalesce((r->>'amount_cents')::int,0) <= 0) then
    raise exception 'invalid_rates' using errcode = 'P0001';
  end if;
  delete from public.shipping_quotes where expires_at < now() - interval '1 day';
  insert into public.shipping_quotes(store_id, sku, postal, region, rates, source)
  values (p_store, p_sku, left(regexp_replace(p_postal,'\D','','g'),5), upper(btrim(p_region)), p_rates, p_source)
  returning id into v_id;
  return v_id;
end $$;


ALTER FUNCTION "public"."save_shipping_quote"("p_store" "uuid", "p_sku" "text", "p_postal" "text", "p_region" "text", "p_rates" "jsonb", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."save_store_categories"("p_store" "uuid", "p_names" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.store_settings (store_id, key, value)
  values (p_store, 'categories', to_jsonb(p_names))
  on conflict (store_id, key) do update set value = excluded.value;
end;
$$;


ALTER FUNCTION "public"."save_store_categories"("p_store" "uuid", "p_names" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_customers_by_phone"("p_phone" "text", "p_limit" integer DEFAULT 8) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_digits text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
  v_lim int := greatest(1, least(coalesce(p_limit, 8), 20));
  v_rows jsonb;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;
  if length(v_digits) < 3 then
    return '[]'::jsonb;
  end if;

  select coalesce(jsonb_agg(public.customer_card(v_store, q) order by q.phone), '[]'::jsonb)
    into v_rows
    from (
      select c.*
        from public.customers c
       where c.store_id = v_store
         and c.phone like v_digits || '%'
       order by c.phone
       limit v_lim
    ) q;

  return v_rows;
end;
$$;


ALTER FUNCTION "public"."search_customers_by_phone"("p_phone" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."seed_store_settings"("p_store" "uuid", "p_display_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  insert into public.store_settings (store_id, key, value) values
    (p_store, 'display_name', to_jsonb(coalesce(nullif(btrim(p_display_name), ''), 'Store'))),
    (p_store, 'skuStart', '10000'::jsonb),
    (p_store, 'skuDigits', '5'::jsonb),
    (p_store, 'taxPricing', '"added"'::jsonb),
    (p_store, 'currency', '"USD"'::jsonb),
    (p_store, 'reservationTtlSeconds', '180'::jsonb),
    (p_store, 'delistNagMinutes', '15'::jsonb),
    (p_store, 'card_payments_enabled', 'false'::jsonb),
    (p_store, 'pin_failed_count', '0'::jsonb),
    (p_store, 'receipt_seq', '0'::jsonb),
    (p_store, 'card_fee_bps', '250'::jsonb),
    (p_store, 'categories', '["Uncategorized"]'::jsonb),
    (p_store, 'conditions', '["New","Open box","Excellent","Good","Fair","For parts"]'::jsonb),
    (p_store, 'testStatuses', '["untested","passed","failed","partial"]'::jsonb),
    (p_store, 'locations', '["Floor","Back room","Repair bench"]'::jsonb),
    (p_store, 'channels', '["floor","ebay","facebook","offerup","amazon","tiktok","website","wholesale"]'::jsonb),
    (p_store, 'paymentMethods', '["cash","card","split","other"]'::jsonb),
    (p_store, 'clerk_max_discount_bps', '1000'::jsonb),
    (p_store, 'rewards_enabled', 'true'::jsonb),
    (p_store, 'rewards_points_per_dollar', '1'::jsonb),
    (p_store, 'rewards_point_value_cents', '1'::jsonb),
    (p_store, 'rewards_signup_discount_bps', '500'::jsonb),
    (p_store, 'receipt_branding', jsonb_build_object(
      'storeName', coalesce(nullif(btrim(p_display_name), ''), 'Store'),
      'address', '',
      'phone', '',
      'headerMessage', 'Thank you for shopping with us!',
      'footerMessage', 'Keep this receipt for your records.',
      'legal', '',
      'returnPolicy', 'Returns within 14 days with receipt.',
      'logoUrl', '',
      'showSku', true,
      'showCondition', true,
      'showClerk', true,
      'showPoints', true,
      'reviewUrl', '',
      'paperPreview', 'roll80'
    ))
  on conflict (store_id, key) do nothing;

  insert into public.channel_config (store_id, channel, mode) values
    (p_store, 'floor', 'manual'),
    (p_store, 'website', 'manual'),
    (p_store, 'ebay', 'off'),
    (p_store, 'amazon', 'off'),
    (p_store, 'facebook', 'off'),
    (p_store, 'tiktok', 'off')
  on conflict (store_id, channel) do nothing;
end;
$$;


ALTER FUNCTION "public"."seed_store_settings"("p_store" "uuid", "p_display_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_listing"("p_sku" "text", "p_channel" "text", "p_listed" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_sku text := btrim(coalesce(p_sku, ''));
  v_channel text := lower(btrim(coalesce(p_channel, '')));
begin
  perform public.assert_staff_or_service();
  if v_sku = '' or v_channel = '' or v_channel = 'floor' then
    raise exception 'Pick a listing channel.' using errcode = '22023';
  end if;
  if not exists (select 1 from public.units where sku = v_sku and store_id is not distinct from v_store) then
    raise exception 'No unit with SKU %.', v_sku using errcode = 'P0001';
  end if;

  if coalesce(p_listed, false) then
    perform public.assert_channel_eligible(v_store, v_sku, v_channel);
    insert into public.listings (store_id, sku, channel, status, listed_at, delisted_at)
    values (v_store, v_sku, v_channel, 'listed', now(), null)
    on conflict (store_id, sku, channel) do update
      set status = 'listed', listed_at = now(), delisted_at = null, store_id = v_store;
  else
    insert into public.listings (store_id, sku, channel, status, delisted_at)
    values (v_store, v_sku, v_channel, 'delisted', now())
    on conflict (store_id, sku, channel) do update
      set status = 'delisted', delisted_at = now(), store_id = v_store;
    update public.delist_tasks
       set completed_at = now(), completed_by = auth.uid()
     where store_id is not distinct from v_store and sku = v_sku and channel = v_channel and completed_at is null;
  end if;

  insert into public.events (store_id, sku, kind, field, new_value, actor, actor_id)
  values (
    v_store, v_sku, 'listing', v_channel,
    case when coalesce(p_listed, false) then 'listed' else 'delisted' end,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'),
    auth.uid()
  );
end $$;


ALTER FUNCTION "public"."set_listing"("p_sku" "text", "p_channel" "text", "p_listed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_listings"("p_skus" "text"[], "p_channel" "text", "p_listed" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_sku text;
begin
  perform public.assert_staff_or_service();
  foreach v_sku in array coalesce(p_skus, array[]::text[])
  loop
    perform public.set_listing(v_sku, p_channel, p_listed);
  end loop;
end $$;


ALTER FUNCTION "public"."set_listings"("p_skus" "text"[], "p_channel" "text", "p_listed" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_manager_pin"("p_pin" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_owner();
  if p_pin is null or char_length(p_pin) < 4 then
    raise exception 'pin_too_short' using errcode = '22023';
  end if;
  insert into public.store_settings (store_id, key, value)
  values (public.current_store_id(), 'manager_pin_hash', to_jsonb(crypt(p_pin, gen_salt('bf'))))
  on conflict (store_id, key) do update set value = excluded.value;
  insert into public.store_settings (store_id, key, value)
  values (public.current_store_id(), 'pin_failed_count', '0'::jsonb)
  on conflict (store_id, key) do update set value = '0'::jsonb;
  delete from public.store_settings
   where store_id = public.current_store_id() and key = 'pin_locked_until';
end;
$$;


