CREATE OR REPLACE FUNCTION "public"."sku_status"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_sku text := btrim(coalesce(p_sku, ''));
begin
  perform public.assert_staff_or_service();
  if v_sku = '' then
    return jsonb_build_object('status', 'empty', 'message', '');
  end if;
  if not public.is_sku(v_sku) then
    return jsonb_build_object('status', 'invalid', 'message', 'SKU must be digits.');
  end if;
  if exists (
    select 1 from public.units u
     where u.sku = v_sku and u.store_id is not distinct from v_store
  ) then
    return jsonb_build_object(
      'status', 'taken',
      'message', format('SKU %s is already in inventory.', v_sku)
    );
  end if;
  if exists (
    select 1 from public.sales s
     where s.sku = v_sku and s.store_id is not distinct from v_store
  ) or exists (
    select 1 from public.sku_ledger l
     where l.sku = v_sku and l.store_id is not distinct from v_store
       and l.fate in ('sold', 'voided', 'retired')
  ) then
    return jsonb_build_object(
      'status', 'locked',
      'message', format('SKU %s was used before and can''t be reused.', v_sku)
    );
  end if;
  if exists (
    select 1 from public.sku_ledger l
     where l.sku = v_sku and l.store_id is not distinct from v_store
  ) then
    return jsonb_build_object(
      'status', 'reusable',
      'message', format('SKU %s was deleted and never sold. You can reuse it.', v_sku)
    );
  end if;
  return jsonb_build_object('status', 'free', 'message', '');
end;
$$;


ALTER FUNCTION "public"."sku_status"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_add_unit_photo"("p_sku" "text", "p_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.current_store_id(); v_actor text;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id=auth.uid() and s.store_id=v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  if not exists(select 1 from public.units where store_id=v_store and sku=p_sku)
     or p_path not like v_store::text || '/' || p_sku || '/%' then
    raise exception 'bad_photo_path' using errcode = '22023';
  end if;
  select coalesce(display_name,split_part((select email from auth.users where id=auth.uid()),'@',1),'staff')
    into v_actor from public.staff where user_id=auth.uid() and store_id=v_store;
  insert into public.photos(store_id,sku,path,original_path,created_at,is_primary)
    values(v_store,p_sku,p_path,p_path,now(),not exists(select 1 from public.photos where store_id=v_store and sku=p_sku));
  insert into public.events(store_id,sku,kind,actor,actor_id) values(v_store,p_sku,'photo',v_actor,auth.uid());
end $$;


ALTER FUNCTION "public"."staff_add_unit_photo"("p_sku" "text", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_enrich_received_unit"("p_sku" "text", "p_specs" "jsonb" DEFAULT NULL::"jsonb", "p_msrp_cents" integer DEFAULT NULL::integer, "p_show" boolean DEFAULT NULL::boolean, "p_brand" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_title" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.current_store_id(); v_unit public.units;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id=auth.uid() and s.store_id=v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  if p_specs is not null and jsonb_typeof(p_specs) <> 'object' then
    raise exception 'specs_must_be_object' using errcode = '22023';
  end if;
  if p_msrp_cents is not null and p_msrp_cents < 0 then
    raise exception 'msrp_must_be_non_negative' using errcode = '22023';
  end if;
  if not exists(select 1 from public.events e where e.store_id=v_store and e.sku=p_sku
    and e.kind='received' and e.actor_id=auth.uid()) then
    raise exception 'received_unit_not_owned' using errcode = '42501';
  end if;
  select * into v_unit from public.units where store_id=v_store and sku=p_sku for update;
  if not found then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  update public.units set
    listing_specs=case when p_specs is null then listing_specs else coalesce(listing_specs,'{}'::jsonb) || jsonb_strip_nulls(p_specs) end,
    msrp_cents=coalesce(msrp_cents,p_msrp_cents),
    brand=case when nullif(btrim(coalesce(brand,'')),'') is null then coalesce(nullif(btrim(coalesce(p_brand,'')),''),brand) else brand end,
    model=case when nullif(btrim(coalesce(model,'')),'') is null then coalesce(nullif(btrim(coalesce(p_model,'')),''),model) else model end,
    title=case when nullif(btrim(coalesce(title,'')),'') is null then coalesce(nullif(btrim(coalesce(p_title,'')),''),title) else title end,
    listing_body=case when nullif(btrim(coalesce(listing_body,'')),'') is null then coalesce(nullif(btrim(coalesce(p_description,'')),''),listing_body) else listing_body end,
    show_on_website=coalesce(p_show,show_on_website),updated_at=now()
  where store_id=v_store and sku=p_sku returning * into v_unit;
  return jsonb_build_object('sku',v_unit.sku,'show_on_website',v_unit.show_on_website,'listing_specs',v_unit.listing_specs);
end $$;


ALTER FUNCTION "public"."staff_enrich_received_unit"("p_sku" "text", "p_specs" "jsonb", "p_msrp_cents" integer, "p_show" boolean, "p_brand" "text", "p_model" "text", "p_title" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_inventory_detail"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.current_store_id(); v_result jsonb;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id=auth.uid() and s.store_id=v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  select jsonb_build_object(
    'unit',jsonb_build_object('sku',u.sku,'brand',u.brand,'model',u.model,'title',u.title,'category',u.category,
      'condition',u.condition,'test_status',u.test_status,'location',u.location,'ask_cents',
      case when u.state in ('available','reserved','repair') then u.ask_cents end,
      'state',u.state,'show_on_website',u.show_on_website,'received_at',u.received_at,'updated_at',u.updated_at,
      'package_weight_lb',u.package_weight_lb,'package_length_in',u.package_length_in,
      'package_width_in',u.package_width_in,'package_height_in',u.package_height_in,'upc',u.upc),
    'photos',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'path',p.path,'is_primary',p.is_primary)
      order by p.is_primary desc,p.id) from public.photos p where p.store_id=u.store_id and p.sku=u.sku),'[]'::jsonb),
    'listings',coalesce((select jsonb_agg(jsonb_build_object('channel',l.channel,'status',l.status,'listing_id',l.listing_id)
      order by l.channel) from public.listings l where l.store_id=u.store_id and l.sku=u.sku),'[]'::jsonb)
  ) into v_result from public.units u where u.store_id=v_store and u.sku=p_sku;
  if v_result is null then raise exception 'unit_not_found' using errcode = 'P0001'; end if;
  return v_result;
end $$;


ALTER FUNCTION "public"."staff_inventory_detail"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_inventory_list"("p_query" "text" DEFAULT ''::"text", "p_status" "text" DEFAULT 'in_stock'::"text", "p_unfinished" boolean DEFAULT false, "p_sort" "text" DEFAULT 'sku'::"text", "p_offset" integer DEFAULT 0, "p_limit" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.current_store_id(); v_result jsonb;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id=auth.uid() and s.store_id=v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  if p_offset < 0 or p_limit < 1 or p_limit > 100 or p_sort not in ('sku','price','date') then
    raise exception 'invalid_inventory_options' using errcode = '22023';
  end if;
  with base as (
    select u.sku,u.brand,u.model,u.title,u.condition,u.state,u.received_at,u.package_weight_lb,u.ask_cents,u.listing_specs,
      public.unit_is_defective(u.listing_specs,u.condition) defective,
      public.unit_not_for_sale(u.listing_specs) not_for_sale,
      ph.photo_path,ph.photo_count,
      case when p_unfinished then public.unit_listing_gaps(u) end gaps
    from public.units u
    cross join lateral (select count(*)::int photo_count,
      (array_agg(p.path order by p.is_primary desc,p.id))[1] photo_path
      from public.photos p where p.store_id=u.store_id and p.sku=u.sku) ph
    where u.store_id=v_store and (nullif(btrim(p_query),'') is null or u.sku ilike '%'||btrim(p_query)||'%'
      or u.brand ilike '%'||btrim(p_query)||'%' or u.model ilike '%'||btrim(p_query)||'%' or u.title ilike '%'||btrim(p_query)||'%')
  ), filtered as (
    select b.sku,b.brand,b.model,b.title,b.condition,b.state,b.received_at,b.package_weight_lb,b.photo_path,b.photo_count,
      b.defective,b.not_for_sale,coalesce(b.gaps,'{}') missing,
      case when b.state in ('available','reserved','repair') then b.ask_cents end ask_cents,
      null::integer acquisition_cost_cents,null::timestamptz sold_at,null::integer sold_price_cents
    from base b where (p_status='all'
      or (p_status='in_stock' and b.state in ('available','reserved','repair') and not b.defective)
      or (p_status='defective' and b.state in ('available','reserved','repair') and b.defective)
      or (p_status='listed' and b.state in ('available','reserved','repair') and not b.defective and exists(
        select 1 from public.listings l where l.store_id=v_store and l.sku=b.sku and l.status='listed'))
      or (p_status='delisted' and exists(select 1 from public.listings l where l.store_id=v_store and l.sku=b.sku and l.status='delisted'))
      or b.state=p_status)
      and (not p_unfinished or (b.state in ('available','reserved','repair') and not b.not_for_sale
        and public.unit_is_unfinished(b.gaps)))
  ), page as (
    select row_number() over(order by
      case when p_sort='sku' then sku::numeric end desc nulls last,
      case when p_sort='price' then ask_cents end asc nulls last,
      case when p_sort='date' then received_at end desc nulls last,sku desc) sort_order,
      sku,brand,model,title,condition,ask_cents,acquisition_cost_cents,state,received_at,package_weight_lb,
      photo_path,photo_count,defective,not_for_sale,missing,sold_at,sold_price_cents
    from filtered order by case when p_sort='sku' then sku::numeric end desc nulls last,
      case when p_sort='price' then ask_cents end asc nulls last,
      case when p_sort='date' then received_at end desc nulls last,sku desc offset p_offset limit p_limit
  )
  select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(p)-'sort_order' order by p.sort_order) from page p),'[]'::jsonb),
    'totals',(select jsonb_build_object('unit_count',count(*)) from filtered)) into v_result;
  return v_result;
end $$;


ALTER FUNCTION "public"."staff_inventory_list"("p_query" "text", "p_status" "text", "p_unfinished" boolean, "p_sort" "text", "p_offset" integer, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_receive_options"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid := public.current_store_id(); v_start int; v_max bigint;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id = auth.uid() and s.store_id = v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  if (public.store_setting(v_store,'skuDigits','5'::jsonb) #>> '{}')::int <> 5 then
    raise exception 'expected_five_digit_skus' using errcode = '22023';
  end if;
  v_start := (public.store_setting(v_store,'skuStart','10000'::jsonb) #>> '{}')::int;
  select coalesce(max(sku::bigint),v_start-1) into v_max
    from public.sku_ledger where store_id=v_store;
  return jsonb_build_object(
    'next_sku',case when v_max < 99999 then lpad((v_max+1)::text,5,'0') else null end,
    'categories',public.store_setting(v_store,'categories','["Uncategorized"]'::jsonb),
    'conditions',public.store_setting(v_store,'conditions','["New","Open box","Excellent","Good","Fair","For parts"]'::jsonb),
    'test_statuses',public.store_setting(v_store,'testStatuses','["untested","passed","failed","partial"]'::jsonb),
    'locations',public.store_setting(v_store,'locations','["Floor","Back room","Repair bench"]'::jsonb)
  );
end $$;


ALTER FUNCTION "public"."staff_receive_options"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_receive_unit"("p_quantity" integer DEFAULT 1, "p_brand" "text" DEFAULT ''::"text", "p_model" "text" DEFAULT ''::"text", "p_title" "text" DEFAULT ''::"text", "p_description" "text" DEFAULT NULL::"text", "p_condition" "text" DEFAULT NULL::"text", "p_test_status" "text" DEFAULT NULL::"text", "p_ask_cents" integer DEFAULT NULL::integer, "p_cost_cents" integer DEFAULT NULL::integer, "p_notes" "text" DEFAULT NULL::"text", "p_upc" "text" DEFAULT NULL::"text", "p_shippable" "text" DEFAULT NULL::"text", "p_length" numeric DEFAULT NULL::numeric, "p_width" numeric DEFAULT NULL::numeric, "p_height" numeric DEFAULT NULL::numeric, "p_weight" numeric DEFAULT NULL::numeric, "p_category" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id(); v_start int; v_max bigint; v_sku text;
  v_skus text[] := array[]::text[]; v_actor text; v_mode text := lower(btrim(coalesce(p_shippable,'auto')));
  v_override text; v_ship boolean; v_dim numeric; v_upc text := nullif(btrim(coalesce(p_upc,'')), '');
  v_upc_rejected text := null;
begin
  if v_store is null or not exists (
    select 1 from public.staff s where s.user_id = auth.uid() and s.store_id = v_store and s.deactivated_at is null
  ) then raise exception 'staff_access_denied' using errcode = '42501'; end if;
  if (public.store_setting(v_store,'skuDigits','5'::jsonb) #>> '{}')::int <> 5 then
    raise exception 'expected_five_digit_skus' using errcode = '22023';
  end if;
  if p_quantity is null or p_quantity < 1 or p_quantity > 100 then
    raise exception 'quantity_must_be_1_to_100' using errcode = '22023';
  end if;
  if coalesce(p_ask_cents,0) < 0 then raise exception 'negative_amount' using errcode = '22023'; end if;
  foreach v_dim in array array[p_length,p_width,p_height,p_weight] loop
    if v_dim is not null and v_dim <= 0 then raise exception 'dims_must_be_positive' using errcode = '22023'; end if;
  end loop;
  -- Receiving accepts incomplete listing data; Unfinished tracks the remaining fields.
  if v_upc is not null and not public.valid_gtin(v_upc) then
    v_upc_rejected := v_upc;
    v_upc := null;
  end if;
  if v_mode in ('','auto','automatic') then v_override := null; v_ship := true;
  elsif v_mode in ('yes','true','1','ship','shippable') then v_override := 'ship'; v_ship := true;
  elsif v_mode in ('no','false','0','pickup','pickup_only') then v_override := 'pickup'; v_ship := false;
  else raise exception 'invalid_shippable' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(687593,hashtext(v_store::text));
  v_start := (public.store_setting(v_store,'skuStart','10000'::jsonb) #>> '{}')::int;
  select coalesce(max(sku::bigint),v_start-1) into v_max from public.sku_ledger where store_id=v_store;
  if v_max + p_quantity > 99999 then raise exception 'sku_exhausted' using errcode = '22023'; end if;
  select coalesce(st.display_name,split_part(au.email,'@',1),'staff') into v_actor
    from auth.users au left join public.staff st on st.user_id=au.id and st.store_id=v_store
    where au.id=auth.uid();
  for i in 1..p_quantity loop
    v_sku := lpad((v_max+i)::text,5,'0');
    insert into public.sku_ledger(store_id,sku,issued_at,label,fate)
      values(v_store,v_sku,now(),coalesce(p_title,''),'issued');
    insert into public.units(
      store_id,sku,brand,model,title,category,listing_body,condition,test_status,defect_notes,upc,upc_rejected,
      acquisition_cost_cents,ask_cents,state,show_on_website,shippable,fulfillment_override,
      package_length_in,package_width_in,package_height_in,package_weight_lb,dims_source,received_at,updated_at
    ) values (
      v_store,v_sku,coalesce(p_brand,''),coalesce(p_model,''),coalesce(p_title,''),
      nullif(btrim(coalesce(p_category,'')),''),nullif(btrim(coalesce(p_description,'')),''),
      p_condition,p_test_status,nullif(btrim(coalesce(p_notes,'')),''),v_upc,v_upc_rejected,
      null,p_ask_cents,'available',true,v_ship,v_override,p_length,p_width,p_height,p_weight,
      case when p_length is not null or p_width is not null or p_height is not null or p_weight is not null then 'verified' else null end,
      now(),now()
    );
    insert into public.events(store_id,sku,kind,actor,actor_id)
      values(v_store,v_sku,'received',v_actor,auth.uid());
    v_skus := array_append(v_skus,v_sku);
  end loop;
  return jsonb_build_object('skus',to_jsonb(v_skus));
end $$;


ALTER FUNCTION "public"."staff_receive_unit"("p_quantity" integer, "p_brand" "text", "p_model" "text", "p_title" "text", "p_description" "text", "p_condition" "text", "p_test_status" "text", "p_ask_cents" integer, "p_cost_cents" integer, "p_notes" "text", "p_upc" "text", "p_shippable" "text", "p_length" numeric, "p_width" numeric, "p_height" numeric, "p_weight" numeric, "p_category" "text") OWNER TO "postgres";


