    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select role from public.staff
   where user_id = auth.uid() and deactivated_at is null;
$$;


ALTER FUNCTION "public"."staff_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."steal_open_web_orders"("p_store" "uuid", "p_sku" "text", "p_sale" "public"."sales") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if p_sale.channel = 'website' then
    update public.web_orders set status = 'paid', sale_id = p_sale.id, updated_at = now()
     where store_id = p_store and sku = p_sku and status = 'claimed'
       and (p_sale.payment_id is null or payment_id is not distinct from p_sale.payment_id or payment_id is null);
    return;
  end if;
  insert into public.alert_outbox (store_id, kind, sku, payload)
  select o.store_id, 'web_apology', o.sku,
    jsonb_build_object('order_id', o.id, 'payment_id', o.payment_id, 'buyer_email', o.buyer_email, 'buyer_name', o.buyer_name, 'total_cents', o.total_cents, 'sale_channel', p_sale.channel)
  from public.web_orders o
  where o.store_id = p_store and o.sku = p_sku and o.status in ('claimed', 'paid') and o.sale_id is null;
  update public.web_orders set status = 'stolen', updated_at = now()
   where store_id = p_store and sku = p_sku and status in ('claimed', 'paid') and sale_id is null;
end;
$$;


ALTER FUNCTION "public"."steal_open_web_orders"("p_store" "uuid", "p_sku" "text", "p_sale" "public"."sales") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_category_names"("p_store" "uuid") RETURNS "text"[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v jsonb;
  v_names text[];
begin
  select value into v
    from public.store_settings
   where store_id = p_store and key = 'categories';
  if v is null or jsonb_typeof(v) <> 'array' then
    return array['Uncategorized']::text[];
  end if;
  select coalesce(array_agg(btrim(x) order by ord), array[]::text[])
    into v_names
  from jsonb_array_elements_text(v) with ordinality as t(x, ord)
  where btrim(x) <> '';
  if v_names is null or cardinality(v_names) = 0 then
    return array['Uncategorized']::text[];
  end if;
  return v_names;
end;
$$;


ALTER FUNCTION "public"."store_category_names"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_report"("p_from" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_to" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store uuid := public.current_store_id();
  v_from timestamptz := coalesce(p_from, '-infinity'::timestamptz);
  v_to timestamptz := coalesce(p_to, 'infinity'::timestamptz);
  v_totals jsonb;
  v_discounts jsonb;
  v_by_day jsonb;
  v_by_channel jsonb;
  v_by_payment jsonb;
  v_inventory jsonb;
begin
  perform public.assert_manager();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;

  with scoped as (
    select
      s.sku,
      s.qty,
      s.price_cents,
      coalesce(s.tax_cents, 0) as tax_cents,
      s.list_price_cents,
      s.channel,
      coalesce(nullif(btrim(s.payment_method), ''), 'other') as payment_method,
      (s.sold_at at time zone 'America/Los_Angeles')::date as sale_day,
      s.voided_at,
      coalesce(u.acquisition_cost_cents, 0) * s.qty as cost_cents,
      coalesce(
        (to_jsonb(s) ->> 'card_fee_cents')::int,
        (to_jsonb(s) ->> 'fee_cents')::int,
        0
      ) as card_fee_cents
    from public.sales s
    left join public.units u
      on u.store_id = s.store_id and u.sku = s.sku
    where s.store_id = v_store
      and s.sold_at >= v_from
      and s.sold_at < v_to
  )
  select jsonb_build_object(
    'sales', count(*) filter (where voided_at is null),
    'units_sold', coalesce(sum(qty) filter (where voided_at is null), 0),
    'merchandise_cents', coalesce(sum(price_cents) filter (where voided_at is null), 0),
    'tax_cents', coalesce(sum(tax_cents) filter (where voided_at is null), 0),
    'card_fee_cents', coalesce(sum(card_fee_cents) filter (where voided_at is null), 0),
    'collected_cents', coalesce(
      sum(price_cents + tax_cents + card_fee_cents) filter (where voided_at is null), 0),
    'markdown_cents', coalesce(
      sum(greatest(coalesce(list_price_cents, price_cents) - price_cents, 0))
        filter (where voided_at is null), 0),
    'gross_profit_cents', coalesce(
      sum(price_cents - cost_cents) filter (where voided_at is null), 0),
    'uncosted_sales', count(*) filter (
      where voided_at is null and cost_cents = 0
    ),
    'voided_sales', count(*) filter (where voided_at is not null),
    'voided_cents', coalesce(
      sum(price_cents + tax_cents) filter (where voided_at is not null), 0)
  ) into v_totals
  from scoped;

  select jsonb_build_object(
      'ticket_discount_cents', coalesce(sum(t.discount_cents), 0),
      'signup_discount_cents', coalesce(sum(t.signup_discount_cents), 0)
    )
    into v_discounts
    from public.ticket_extras t
   where t.store_id = v_store
     and t.created_at >= v_from
     and t.created_at < v_to;
  v_totals := v_totals || v_discounts;

  with scoped as (
    select
      (s.sold_at at time zone 'America/Los_Angeles')::date as sale_day,
      s.qty,
      s.price_cents,
      coalesce(s.tax_cents, 0) as tax_cents,
      coalesce(u.acquisition_cost_cents, 0) * s.qty as cost_cents
    from public.sales s
    left join public.units u
      on u.store_id = s.store_id and u.sku = s.sku
    where s.store_id = v_store
      and s.voided_at is null
      and s.sold_at >= v_from
      and s.sold_at < v_to
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'day', sale_day,
      'sales', n,
      'revenue_cents', revenue_cents,
      'tax_cents', tax_cents,
      'profit_cents', profit_cents
    ) order by sale_day desc), '[]'::jsonb)
    into v_by_day
    from (
      select
        sale_day,
        count(*)::int as n,
        sum(price_cents)::bigint as revenue_cents,
        sum(tax_cents)::bigint as tax_cents,
        sum(price_cents - cost_cents)::bigint as profit_cents
      from scoped
      group by sale_day
    ) d;

  select coalesce(jsonb_agg(jsonb_build_object(
      'channel', channel,
      'sales', n,
      'revenue_cents', revenue_cents,
      'profit_cents', profit_cents
    ) order by revenue_cents desc), '[]'::jsonb)
    into v_by_channel
    from (
      select
        s.channel,
        count(*)::int as n,
        sum(s.price_cents)::bigint as revenue_cents,
        sum(s.price_cents - coalesce(u.acquisition_cost_cents, 0) * s.qty)::bigint as profit_cents
      from public.sales s
      left join public.units u
        on u.store_id = s.store_id and u.sku = s.sku
      where s.store_id = v_store
        and s.voided_at is null
        and s.sold_at >= v_from
        and s.sold_at < v_to
      group by s.channel
    ) c;

  select coalesce(jsonb_agg(jsonb_build_object(
      'method', method,
      'sales', n,
      'collected_cents', collected_cents
    ) order by collected_cents desc), '[]'::jsonb)
    into v_by_payment
    from (
      select
        coalesce(nullif(btrim(s.payment_method), ''), 'other') as method,
        count(*)::int as n,
        sum(s.price_cents + coalesce(s.tax_cents, 0))::bigint as collected_cents
      from public.sales s
      where s.store_id = v_store
        and s.voided_at is null
        and s.sold_at >= v_from
        and s.sold_at < v_to
      group by 1
    ) p;

  select jsonb_build_object(
      'units_in_stock', count(*),
      'cost_cents', coalesce(sum(coalesce(u.acquisition_cost_cents, 0) * u.qty_on_hand), 0),
      'ask_cents', coalesce(sum(coalesce(u.ask_cents, 0) * u.qty_on_hand), 0),
      'unpriced', count(*) filter (where u.ask_cents is null),
      'missing_photos', count(*) filter (
        where not exists (
          select 1 from public.photos ph
           where ph.store_id = u.store_id and ph.sku = u.sku
        )
      )
    )
    into v_inventory
    from public.units u
   where u.store_id = v_store
     and u.state in ('available', 'reserved', 'repair');

  return jsonb_build_object(
    'from', v_from,
    'to', v_to,
    'generated_at', now(),
    'totals', v_totals,
    'by_day', v_by_day,
    'by_channel', v_by_channel,
    'by_payment', v_by_payment,
    'inventory', v_inventory
  );
end;
$$;


ALTER FUNCTION "public"."store_report"("p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_setting"("p_store" "uuid", "p_key" "text", "p_default" "jsonb" DEFAULT 'null'::"jsonb") RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    AS $$
  select coalesce(
    (select value from public.store_settings where store_id = p_store and key = p_key),
    p_default
  );
$$;


ALTER FUNCTION "public"."store_setting"("p_store" "uuid", "p_key" "text", "p_default" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_setting_int"("p_store" "uuid", "p_key" "text", "p_default" integer) RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_raw text;
  v_int int;
begin
  v_raw := public.store_setting(p_store, p_key, to_jsonb(p_default)) #>> '{}';
  if v_raw is null or v_raw = '' or v_raw = 'null' then
    return p_default;
  end if;
  begin
    v_int := v_raw::int;
  exception when others then
    return p_default;
  end;
  return v_int;
end;
$$;


ALTER FUNCTION "public"."store_setting_int"("p_store" "uuid", "p_key" "text", "p_default" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."store_tax_rate_bps"() RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.current_store_id();
  v_raw text;
  v_bps int;
  v_override text := nullif(current_setting('floor.tax_bps_override', true), '');
begin
  if v_store is null then return null; end if;
  if v_override is not null and auth.role() = 'service_role' and v_override ~ '^[0-9]{1,5}$' then
    return v_override::int;
  end if;
  v_raw := public.store_setting(v_store, 'taxRateBps', 'null'::jsonb) #>> '{}';
  if v_raw is null or v_raw = '' or v_raw = 'null' then return null; end if;
  begin v_bps := v_raw::int; exception when others then return null; end;
  if v_bps < 0 then return null; end if;
  return v_bps;
end;
$_$;


ALTER FUNCTION "public"."store_tax_rate_bps"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."supplier_return_policy_check"("p_store" "uuid", "p_supplier" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  s public.suppliers;
  v_reserve numeric;
  v_flag text := 'ok';
  v_note text := '';
begin
  select * into s from public.suppliers where id = p_supplier and store_id = p_store;
  if not found then
    return jsonb_build_object('ok', false, 'flag', 'missing_supplier', 'suggested_reserve_pct', 15,
      'note', 'Supplier not found');
  end if;
  v_reserve := public.channel_return_reserve_pct(p_store, 'amazon');
  if not s.accepts_returns or not s.has_us_return_address then
    v_flag := 'no_return_policy';
    v_note := 'Supplier has no US return path — raise reserve or skip Amazon/TikTok';
    v_reserve := greatest(v_reserve, 15);
  elsif coalesce(s.return_window_days, 0) < 30 then
    v_flag := 'short_window';
    v_note := 'Return window under 30 days — marketplace windows may exceed supplier policy';
    v_reserve := greatest(v_reserve, 12);
  end if;
  return jsonb_build_object(
    'ok', v_flag = 'ok',
    'flag', v_flag,
    'note', v_note,
    'suggested_reserve_pct', v_reserve,
    'accepts_returns', s.accepts_returns,
    'has_us_return_address', s.has_us_return_address,
    'return_window_days', s.return_window_days,
    'restocking_fee_pct', s.restocking_fee_pct
  );
end $$;


ALTER FUNCTION "public"."supplier_return_policy_check"("p_store" "uuid", "p_supplier" "uuid") OWNER TO "postgres";


