CREATE OR REPLACE FUNCTION "public"."ticket_summary"("p_store" "uuid", "p_ticket" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_lines jsonb := '[]'::jsonb;
  v_sub int := 0;
  v_tax int := 0;
  v_fee int := 0;
  v_shipping int := 0;
  r record;
  x public.ticket_extras;
  v_cust jsonb := null;
begin
  for r in
    select id, sku, receipt_no, price_cents, tax_cents, card_fee_cents, shipping_cents, list_price_cents,
           override_reason, payment_method, sold_at, card_brand, card_last4, qty
      from public.sales
     where store_id = p_store and ticket_id = p_ticket and voided_at is null
     order by id
  loop
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'sale_id', r.id,
      'sku', r.sku,
      'receipt_no', r.receipt_no,
      'price_cents', r.price_cents,
      'tax_cents', coalesce(r.tax_cents, 0),
      'card_fee_cents', coalesce(r.card_fee_cents, 0),
      'shipping_cents', r.shipping_cents,
      'list_price_cents', r.list_price_cents,
      'override_reason', r.override_reason,
      'payment_method', r.payment_method,
      'card_brand', r.card_brand,
      'card_last4', r.card_last4,
      'qty', r.qty
    ));
    v_shipping := v_shipping + r.shipping_cents;
    v_sub := v_sub + r.price_cents;
    v_tax := v_tax + coalesce(r.tax_cents, 0);
    v_fee := v_fee + coalesce(r.card_fee_cents, 0);
  end loop;
  if jsonb_array_length(v_lines) = 0 then
    return null;
  end if;

  select * into x from public.ticket_extras
   where ticket_id = p_ticket and store_id = p_store;

  if x.customer_id is not null then
    select jsonb_build_object(
      'id', c.id,
      'phone', c.phone,
      'name', c.name,
      'email', c.email,
      'points_balance', public.customer_points_balance_internal(p_store, c.id)
    ) into v_cust
      from public.customers c
     where c.id = x.customer_id;
  end if;

  return jsonb_build_object(
    'ticket_id', p_ticket,
    'lines', v_lines,
    'subtotal_cents', v_sub,
    'tax_cents', v_tax,
    'card_fee_bps', coalesce(x.card_fee_bps, 0),
    'card_fee_cents', coalesce(x.card_fee_cents, v_fee),
    'shipping_cents', v_shipping,
    'total_cents', v_sub + v_tax + v_shipping + coalesce(x.card_fee_cents, v_fee),
    'payment_method', v_lines->0->>'payment_method',
    'card_brand', v_lines->0->>'card_brand',
    'card_last4', v_lines->0->>'card_last4',
    'discount_bps', coalesce(x.discount_bps, 0),
    'discount_cents', coalesce(x.discount_cents, 0),
    'signup_discount_cents', coalesce(x.signup_discount_cents, 0),
    'points_redeemed', coalesce(x.points_redeemed, 0),
    'points_earned', coalesce(x.points_earned, 0),
    'points_balance', case when x.customer_id is not null then v_cust->'points_balance' else null end,
    'customer_id', x.customer_id,
    'customer', v_cust,
    'cash_cents', coalesce(x.cash_cents, 0),
    'card_cents', coalesce(x.card_cents, 0),
    'amount_tendered_cents', x.amount_tendered_cents,
    'note', x.note
  );
end;
$$;


ALTER FUNCTION "public"."ticket_summary"("p_store" "uuid", "p_ticket" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trim_location_stock_on_sale"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_remove int := old.qty_on_hand-new.qty_on_hand; x record; v_take int;
begin
  if v_remove <= 0 then return new; end if;
  for x in select a.location_code,a.quantity from public.unit_location_stock a
    join public.store_locations l on l.store_id=a.store_id and l.code=a.location_code
    where a.store_id=new.store_id and a.sku=new.sku
    order by l.bay_no,l.row_no,l.bin_no nulls first
    for update of a
  loop
    exit when v_remove <= 0;
    v_take := least(v_remove,x.quantity);
    if v_take = x.quantity then
      delete from public.unit_location_stock where store_id=new.store_id
        and sku=new.sku and location_code=x.location_code;
    else
      update public.unit_location_stock set quantity=quantity-v_take,updated_at=now()
      where store_id=new.store_id and sku=new.sku and location_code=x.location_code;
    end if;
    v_remove := v_remove-v_take;
  end loop;
  return new;
end $$;


ALTER FUNCTION "public"."trim_location_stock_on_sale"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."try_job_lock"("p_name" "text", "p_owner" "text", "p_ttl_seconds" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_got text;
begin
  insert into public.job_locks(name, owner, locked_until)
  values (p_name, p_owner, now() + make_interval(secs => greatest(p_ttl_seconds, 5)))
  on conflict (name) do update
    set owner = excluded.owner, locked_until = excluded.locked_until, updated_at = now()
    where public.job_locks.locked_until < now()
  returning owner into v_got;
  return v_got is not null;
end $$;


