CREATE OR REPLACE FUNCTION "public"."unit_ship_check"("u" "public"."units") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare r jsonb := public.unit_ship_rules(u);
begin
  if coalesce((r->>'ship')::boolean, false)
     and not coalesce((public.store_setting(u.store_id,'shipping_enabled','false'::jsonb) #>> '{}')::boolean, false) then
    return jsonb_build_object('ship', false, 'shipping_off', true,
      'reason', 'Shipping is turned off (store pickup only). Would ship once shipping is on.');
  end if;
  return r;
end $$;


ALTER FUNCTION "public"."unit_ship_check"("u" "public"."units") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_ship_rules"("u" "public"."units") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_dims numeric[];
  v_text text;
  k text;
  v_max_lb numeric := coalesce(nullif(public.store_setting(u.store_id,'ship_max_weight_lb','70'::jsonb) #>> '{}','')::numeric, 70);
  v_max_len numeric := coalesce(nullif(public.store_setting(u.store_id,'ship_max_length_in','108'::jsonb) #>> '{}','')::numeric, 108);
  v_max_lg numeric := coalesce(nullif(public.store_setting(u.store_id,'ship_max_length_girth_in','165'::jsonb) #>> '{}','')::numeric, 165);
begin
  if u.fulfillment_override = 'pickup' then
    return jsonb_build_object('ship', false, 'reason', 'Pickup only (set by staff)');
  end if;
  if coalesce(u.package_weight_lb,0) <= 0 or coalesce(u.package_length_in,0) <= 0
     or coalesce(u.package_width_in,0) <= 0 or coalesce(u.package_height_in,0) <= 0 then
    return jsonb_build_object('ship', false, 'missing_dims', true, 'reason', 'Missing package dimensions or weight');
  end if;
  if u.fulfillment_override = 'ship' then
    return jsonb_build_object('ship', true, 'reason', 'Shipping forced on by staff');
  end if;
  if lower(btrim(coalesce(u.category,''))) = any (public.setting_text_array(u.store_id,'ship_excluded_categories')) then
    return jsonb_build_object('ship', false, 'reason', format('%s is a pickup-only category', u.category));
  end if;
  v_text := lower(concat_ws(' ', u.title, u.brand, u.model, u.category));
  foreach k in array public.setting_text_array(u.store_id,'ship_excluded_keywords') loop
    if v_text ~ ('\m' || regexp_replace(k, '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\M') then
      return jsonb_build_object('ship', false, 'reason', format('Large item ("%s")', k));
    end if;
  end loop;
  v_dims := array(select x from unnest(array[u.package_length_in,u.package_width_in,u.package_height_in]) x order by x desc);
  if u.package_weight_lb > v_max_lb then
    return jsonb_build_object('ship', false, 'reason', format('Package %s lb is over the %s lb limit', u.package_weight_lb, v_max_lb));
  end if;
  if v_dims[1] > v_max_len then
    return jsonb_build_object('ship', false, 'reason', format('Longest side %s in is over the %s in limit', v_dims[1], v_max_len));
  end if;
  if v_dims[1] + 2 * (v_dims[2] + v_dims[3]) > v_max_lg then
    return jsonb_build_object('ship', false, 'reason', format('Length + girth %s in is over the %s in limit',
      v_dims[1] + 2 * (v_dims[2] + v_dims[3]), v_max_lg));
  end if;
  return jsonb_build_object('ship', true, 'reason', 'Ships');
end $_$;


ALTER FUNCTION "public"."unit_ship_rules"("u" "public"."units") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_ship_status"("p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare u public.units;
begin
  perform public.assert_staff_or_service();
  select * into u from public.units where store_id = public.current_store_id() and sku = p_sku;
  if not found then return null; end if;
  return public.unit_ship_check(u) || jsonb_build_object('override', u.fulfillment_override);
end $$;


ALTER FUNCTION "public"."unit_ship_status"("p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_shipping_cents"("p_store" "uuid", "p_override" integer, "p_specs" "jsonb", "p_ask" integer) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
  v_lb numeric;
  v_max numeric;
begin
  v_lb := public.unit_weight_lb(p_specs);
  v_max := coalesce(nullif(public.store_setting(p_store, 'ship_max_lb', '30'::jsonb) #>> '{}', '')::numeric, 30);
  if v_lb is null or v_lb > v_max then
    return null;
  end if;
  if p_override is not null then
    return p_override;
  end if;
  if v_lb <= 5 then
    return coalesce(nullif(public.store_setting(p_store, 'ship_tier_5_cents', '2000'::jsonb) #>> '{}', '')::int, 2000);
  end if;
  if v_lb <= 15 then
    return coalesce(nullif(public.store_setting(p_store, 'ship_tier_15_cents', '3200'::jsonb) #>> '{}', '')::int, 3200);
  end if;
  return coalesce(nullif(public.store_setting(p_store, 'ship_tier_30_cents', '5000'::jsonb) #>> '{}', '')::int, 5000);
end;
$$;


ALTER FUNCTION "public"."unit_shipping_cents"("p_store" "uuid", "p_override" integer, "p_specs" "jsonb", "p_ask" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_upc_does_not_apply"("p_specs" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select coalesce(
    nullif(btrim(coalesce(
      case when jsonb_typeof(p_specs->'ebay_aspects'->'UPC') = 'array'
        then p_specs->'ebay_aspects'->'UPC'->>0
        else p_specs#>>'{ebay_aspects,UPC}' end,
      p_specs->>'upc',
      ''
    )), ''),
    ''
  ) ~* '^(does not apply|n/?a)$';
$_$;


ALTER FUNCTION "public"."unit_upc_does_not_apply"("p_specs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_web_buyable"("p_store" "uuid", "p_shippable" boolean, "p_specs" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select coalesce(p_shippable, false)
     and public.unit_weight_lb(p_specs) is not null
     and public.unit_weight_lb(p_specs) <= coalesce(
       nullif(public.store_setting(p_store, 'ship_max_lb', '30'::jsonb) #>> '{}', '')::numeric,
       30
     );
$$;


ALTER FUNCTION "public"."unit_web_buyable"("p_store" "uuid", "p_shippable" boolean, "p_specs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unit_weight_lb"("p_specs" "jsonb") RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $_$
  select case
    when nullif(btrim(p_specs->>'weight_lb'), '') is null then null
    when (p_specs->>'weight_lb') ~ '^[0-9]+(\.[0-9]+)?$'
      and (p_specs->>'weight_lb')::numeric > 0
      then (p_specs->>'weight_lb')::numeric
    else null
  end;
$_$;


ALTER FUNCTION "public"."unit_weight_lb"("p_specs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unsubscribe_loyalty"("p_token" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare r public.customers; begin if p_token is null then raise exception 'token_required' using errcode = '22023'; end if; update public.customers set unsubscribed_at = coalesce(unsubscribed_at, now()), marketing_opt_in = false where unsub_token = p_token returning * into r; if not found then raise exception 'unknown_token' using errcode = 'P0001'; end if; return jsonb_build_object('ok', true, 'email', r.email); end; $$;


