CREATE OR REPLACE FUNCTION "public"."update_enriched_unit_field"("p_sku" "text", "p_field" "text", "p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare v_store uuid:=public.current_store_id(); v_old text;
begin
  perform public.assert_staff_or_service();
  if not public.is_manager() then raise exception 'not_manager' using errcode='42501'; end if;
  if p_field not in ('ai_description','ebay_title','ebay_category','ebay_item_specifics') then
    raise exception 'invalid_field' using errcode='22023';
  end if;
  execute format('select %I::text from public.units where sku=$1 and store_id=$2',p_field)
    into v_old using p_sku,v_store;
  if p_field='ebay_item_specifics' then
    if p_value is not null and jsonb_typeof(p_value::jsonb)<>'object' then
      raise exception 'invalid_specifics' using errcode='22023';
    end if;
    update public.units set ebay_item_specifics=coalesce(p_value::jsonb,'{}'::jsonb),
      listing_specs=jsonb_set(coalesce(listing_specs,'{}'::jsonb),'{ebay_aspects}',
        coalesce(p_value::jsonb,'{}'::jsonb),true),updated_at=now()
      where sku=p_sku and store_id=v_store;
  else
    execute format('update public.units set %I=$1,updated_at=now() where sku=$2 and store_id=$3',p_field)
      using nullif(p_value,''),p_sku,v_store;
  end if;
  insert into public.events(store_id,sku,kind,field,old_value,new_value,actor,actor_id)
  values(v_store,p_sku,'edit',p_field,v_old,p_value,
    coalesce((select display_name from public.staff where user_id=auth.uid()),'staff'),auth.uid());
end $_$;


ALTER FUNCTION "public"."update_enriched_unit_field"("p_sku" "text", "p_field" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_unit_field"("p_sku" "text", "p_field" "text", "p_value" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.current_store_id();
  v_old text;
  v_manager_fields text[] := array[
    'brand','model','title','category','mfr_serial','upc','lot',
    'acquisition_cost_cents','msrp_cents','floor_cents',
    'listing_body','listing_specs','show_on_website','shippable',
    'shipping_cents','fulfillment_override','dims_source',
    'requires_power','is_electrical','is_camera',
    'has_stock_photos','has_ai_images','has_manufacturer_photos','is_collectible',
    'package_length_in','package_width_in','package_height_in','package_weight_lb',
    'product_height_in','product_width_in','product_depth_in','product_weight_lb'
  ];
  v_staff_fields text[] := array[
    'condition','test_status','location','defect_notes','qty_on_hand','ask_cents'
  ];
  v_num_fields text[] := array[
    'package_length_in','package_width_in','package_height_in','package_weight_lb',
    'product_height_in','product_width_in','product_depth_in','product_weight_lb'
  ];
  v_bool_fields text[] := array[
    'show_on_website','shippable','requires_power','is_electrical','is_camera',
    'has_stock_photos','has_ai_images','has_manufacturer_photos','is_collectible'
  ];
  v_bool boolean;
  v_qty int;
begin
  perform public.assert_staff_or_service();
  if v_store is null then
    raise exception 'no_store' using errcode = 'P0001';
  end if;

  if p_field = any (v_manager_fields) and not public.is_manager() then
    raise exception 'not_manager' using errcode = '42501';
  end if;

  if p_field <> all (v_manager_fields || v_staff_fields) then
    raise exception 'invalid_field' using errcode = '22023';
  end if;

  if p_field = 'show_on_website' and lower(coalesce(p_value, '')) in ('true', '1', 't', 'yes', 'on') then
    perform public.assert_channel_eligible(v_store, p_sku, 'website');
  end if;

  execute format('select %I::text from public.units where sku = $1 and store_id = $2', p_field)
    into v_old using p_sku, v_store;

  if p_field = 'qty_on_hand' then
    if nullif(btrim(coalesce(p_value, '')), '') is null then
      raise exception 'qty_required' using errcode = '22023';
    end if;
    v_qty := p_value::int;
    if v_qty < 0 or v_qty > 9999 then
      raise exception 'qty_out_of_range' using errcode = '22023';
    end if;
    update public.units
       set qty_on_hand = v_qty,
           state = case when v_qty <= 0 then 'sold' else case when state = 'sold' then 'available' else state end end,
           updated_at = now()
     where sku = p_sku and store_id = v_store;
  elsif p_field like '%_cents' then
    execute format('update public.units set %I = $1::int, updated_at = now() where sku = $2 and store_id = $3', p_field)
      using nullif(p_value, ''), p_sku, v_store;
  elsif p_field = any (v_num_fields) then
    if nullif(p_value, '') is not null and p_value::numeric <= 0 then
      raise exception 'must_be_positive' using errcode = '22023';
    end if;
    execute format(
      'update public.units set %I = $1::numeric, dims_source = case when $1 is null then dims_source else ''verified'' end, updated_at = now() where sku = $2 and store_id = $3',
      p_field
    ) using nullif(p_value, ''), p_sku, v_store;
  elsif p_field = 'listing_specs' then
    update public.units set listing_specs = nullif(p_value, '')::jsonb, updated_at = now()
     where sku = p_sku and store_id = v_store;
  elsif p_field = any (v_bool_fields) then
    if nullif(btrim(coalesce(p_value, '')), '') is null and p_field in ('requires_power', 'is_electrical', 'is_camera') then
      v_bool := null;
    else
      v_bool := lower(coalesce(p_value, '')) in ('true', '1', 't', 'yes', 'on');
    end if;
    execute format('update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3', p_field)
      using v_bool, p_sku, v_store;
    if p_field = 'is_collectible' and v_bool is true then
      update public.units set acquisition_cost_cents = 0, updated_at = now()
       where sku = p_sku and store_id = v_store;
    end if;
  elsif p_field in ('fulfillment_override', 'dims_source') then
    execute format('update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3', p_field)
      using nullif(btrim(p_value), ''), p_sku, v_store;
  else
    execute format('update public.units set %I = $1, updated_at = now() where sku = $2 and store_id = $3', p_field)
      using p_value, p_sku, v_store;
  end if;

  insert into public.events (store_id, sku, kind, field, old_value, new_value, actor, actor_id)
  values (v_store, p_sku, 'edit', p_field, v_old, p_value,
    coalesce((select display_name from public.staff where user_id = auth.uid()), 'staff'), auth.uid());
end;
$_$;


ALTER FUNCTION "public"."update_unit_field"("p_sku" "text", "p_field" "text", "p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_customer"("p_phone" "text", "p_name" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_marketing_opt_in" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_store uuid := public.current_store_id(); v_phone text; r public.customers; begin perform public.assert_staff_or_service(); if v_store is null then raise exception 'no_store' using errcode = 'P0001'; end if; v_phone := public.normalize_phone(p_phone); if v_phone is null then raise exception 'invalid_phone' using errcode = '22023'; end if; insert into public.customers (store_id, phone, name, email, marketing_opt_in, signup_code) values (v_store, v_phone, nullif(btrim(coalesce(p_name, '')), ''), nullif(btrim(coalesce(p_email, '')), ''), coalesce(p_marketing_opt_in, false), public.new_signup_code()) on conflict (store_id, phone) do update set name = coalesce(excluded.name, public.customers.name), email = coalesce(excluded.email, public.customers.email), marketing_opt_in = public.customers.marketing_opt_in or excluded.marketing_opt_in returning * into r; return public.customer_card(v_store, r); end; $$;


ALTER FUNCTION "public"."upsert_customer"("p_phone" "text", "p_name" "text", "p_email" "text", "p_marketing_opt_in" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."verify_unit_photos"("p_store" "uuid") RETURNS TABLE("photo_id" bigint, "sku" "text", "path" "text", "storage_ok" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public', 'storage'
    AS $$
begin
  if auth.role() <> 'service_role' and public.current_store_id() is distinct from p_store then
    raise exception 'not_staff' using errcode = '42501';
  end if;
  return query
    select
      p.id,
      p.sku,
      p.path,
      exists (
        select 1 from storage.objects o
         where o.bucket_id = 'unit-photos' and o.name = p.path
      ) as storage_ok
    from public.photos p
    where p.store_id = p_store;
end;
$$;


ALTER FUNCTION "public"."verify_unit_photos"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."video_scan_attach_photo"("p_id" "uuid", "p_path" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.video_scan_store_id(); v_job public.video_scan_jobs; v_actor text;
begin
  select * into v_job from public.video_scan_jobs where id=p_id and store_id=v_store and created_by=auth.uid();
  if not found or v_job.status<>'saved' or v_job.sku is null or
     p_path not like v_store::text||'/'||v_job.sku||'/video-'||p_id::text||'-%' then
    raise exception 'invalid_video_still' using errcode='42501';
  end if;
  if exists(select 1 from public.photos where store_id=v_store and sku=v_job.sku and path=p_path) then return; end if;
  insert into public.photos(store_id,sku,path,source,is_primary)
    values(v_store,v_job.sku,p_path,'video_still',
      not exists(select 1 from public.photos where store_id=v_store and sku=v_job.sku));
  select coalesce(s.display_name,'staff') into v_actor from public.staff s where s.user_id=auth.uid();
  insert into public.events(store_id,sku,kind,actor,actor_id,note)
    values(v_store,v_job.sku,'photo',coalesce(v_actor,'admin'),auth.uid(),'video still');
end $$;


ALTER FUNCTION "public"."video_scan_attach_photo"("p_id" "uuid", "p_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."video_scan_budget"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.video_scan_store_id(); v_cap numeric; v_usage jsonb;
begin
  if v_store is null then raise exception 'scan_access_denied' using errcode='42501'; end if;
  select monthly_cap_usd into v_cap from public.video_scan_settings where store_id=v_store;
  v_usage:=public.video_scan_month_usage(v_store);
  return v_usage||jsonb_build_object('monthly_cap_usd',coalesce(v_cap,30));
end $$;


ALTER FUNCTION "public"."video_scan_budget"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."video_scan_create"("p_id" "uuid", "p_video_path" "text", "p_still_paths" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_store uuid:=public.video_scan_store_id(); v_cap numeric; v_used numeric; v_usage jsonb;
begin
  if v_store is null then raise exception 'scan_access_denied' using errcode='42501'; end if;
  if p_id is null or p_video_path not in (v_store::text||'/'||auth.uid()::text||'/'||p_id::text||'/video.mp4',
       v_store::text||'/'||auth.uid()::text||'/'||p_id::text||'/video.webm')
     or coalesce(array_length(p_still_paths,1),0)>4
     or exists(select 1 from unnest(coalesce(p_still_paths,'{}'::text[])) p
       where p not like v_store::text||'/'||auth.uid()::text||'/'||p_id::text||'/still-%.jpg') then
    raise exception 'invalid_scan_paths' using errcode='22023';
  end if;
  insert into public.video_scan_settings(store_id) values(v_store) on conflict do nothing;
  select monthly_cap_usd into v_cap from public.video_scan_settings where store_id=v_store for update;
  v_usage:=public.video_scan_month_usage(v_store);
  v_used:=(v_usage->>'spent_usd')::numeric+(v_usage->>'reserved_usd')::numeric;
  if v_used+1.00>v_cap then raise exception 'monthly_ai_cap_reached' using errcode='P0001'; end if;
  insert into public.video_scan_jobs(id,store_id,created_by,video_path,still_paths,reserved_usd)
    values(p_id,v_store,auth.uid(),p_video_path,coalesce(p_still_paths,'{}'::text[]),1.00);
  return jsonb_build_object('id',p_id,'monthly_cap_usd',v_cap,'month_spend_usd',v_used);
end $$;


ALTER FUNCTION "public"."video_scan_create"("p_id" "uuid", "p_video_path" "text", "p_still_paths" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."video_scan_month_usage"("p_store" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  with counts as (
    select coalesce(sum(input_tokens),0)::numeric inputs,
           coalesce(sum(output_tokens),0)::numeric outputs,
           coalesce(sum(search_queries),0)::numeric searches,
           coalesce(sum(reserved_usd),0)::numeric reserved
    from public.video_scan_jobs
    where store_id=p_store
      and created_at>=date_trunc('month',now() at time zone 'America/Los_Angeles') at time zone 'America/Los_Angeles'
      and created_at<(date_trunc('month',now() at time zone 'America/Los_Angeles')+interval '1 month') at time zone 'America/Los_Angeles'
  )
  select jsonb_build_object(
    'spent_usd',round(inputs*0.75/1000000+outputs*3.75/1000000+greatest(searches-5000,0)*0.014,5),
    'reserved_usd',reserved,'search_queries',searches,
    'free_search_queries_remaining',greatest(5000-searches,0))
  from counts;
$$;


ALTER FUNCTION "public"."video_scan_month_usage"("p_store" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."video_scan_receive"("p_id" "uuid", "p_draft" "jsonb", "p_ask_cents" integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_store uuid := public.video_scan_store_id();
  v_job public.video_scan_jobs;
  v_sku text;
  v_json jsonb;
  v_unit public.units;
  v_msrp int;
  v_title text;
  v_cost int;
  v_floor int;
  v_length numeric;
  v_width numeric;
  v_height numeric;
  v_weight numeric;
  v_num text;
begin
  if v_store is null then raise exception 'scan_access_denied' using errcode = '42501'; end if;
  if p_ask_cents is null or p_ask_cents <= 0 then raise exception 'selling_price_required' using errcode = '22023'; end if;
  select * into v_job from public.video_scan_jobs where id = p_id and store_id = v_store and created_by = auth.uid() for update;
  if not found then raise exception 'scan_not_found' using errcode = 'P0001'; end if;
  if v_job.status = 'saved' then return jsonb_build_object('sku', v_job.sku); end if;
  if v_job.status <> 'ready' then raise exception 'scan_not_ready' using errcode = 'P0001'; end if;
  if jsonb_typeof(p_draft) <> 'object' then raise exception 'invalid_draft' using errcode = '22023'; end if;
  v_title := left(coalesce(p_draft->>'title', ''), 240);
  v_msrp := nullif(p_draft->>'msrp_cents', '')::int;
  v_cost := nullif(p_draft->>'acquisition_cost_cents', '')::int;
  v_floor := nullif(p_draft->>'floor_cents', '')::int;
  if v_msrp < 0 or v_cost < 0 or v_floor < 0 then raise exception 'negative_amount' using errcode = '22023'; end if;
  v_num := coalesce(p_draft->>'package_length_in', p_draft->>'length_in', '');
  v_length := case when v_num ~ '^[0-9]+(\.[0-9]+)?$' then v_num::numeric else null end;
  v_num := coalesce(p_draft->>'package_width_in', p_draft->>'width_in', '');
  v_width := case when v_num ~ '^[0-9]+(\.[0-9]+)?$' then v_num::numeric else null end;
  v_num := coalesce(p_draft->>'package_height_in', p_draft->>'height_in', '');
  v_height := case when v_num ~ '^[0-9]+(\.[0-9]+)?$' then v_num::numeric else null end;
  v_num := coalesce(p_draft->>'package_weight_lb', p_draft->>'weight_lb', '');
  v_weight := case when v_num ~ '^[0-9]+(\.[0-9]+)?$' then v_num::numeric else null end;
  if public.portal_store_id() = v_store then
    v_json := public.portal_receive_unit(
      1,
      coalesce(p_draft->>'brand', ''),
      coalesce(p_draft->>'model', ''),
      v_title,
      p_draft->>'description',
      p_draft->>'condition',
      p_draft->>'test_status',
      p_ask_cents,
      v_cost,
      p_draft->>'condition_notes',
      p_draft->>'upc',
      'auto',
      v_length, v_width, v_height, v_weight,
      p_draft->>'category'
    );
    v_sku := v_json->'skus'->>0;
  else
    perform pg_advisory_xact_lock(687593, hashtext(v_store::text));
    v_sku := public.next_sku();
    v_unit := public.receive_unit(
      v_sku, coalesce(p_draft->>'brand', ''), coalesce(p_draft->>'model', ''), v_title,
      p_draft->>'category', p_draft->>'condition', p_draft->>'test_status', p_draft->>'location',
      p_ask_cents, v_msrp, v_cost, v_floor, p_draft->>'condition_notes', p_draft->>'upc', p_draft->>'lot', p_draft->>'mfr_serial',
      v_length, v_width, v_height, v_weight
    );
  end if;
  update public.units set ai_description = p_draft->>'description',
    ebay_title = left(coalesce(p_draft->>'ebay_title', ''), 80), ebay_category = p_draft->>'ebay_category',
    ebay_item_specifics = case when jsonb_typeof(p_draft->'ebay_item_specifics') = 'object' then p_draft->'ebay_item_specifics' else '{}'::jsonb end,
    retail_price_sources = case when jsonb_typeof(p_draft->'retail_prices') = 'array' then p_draft->'retail_prices' else '[]'::jsonb end,
    retail_source_name = p_draft->>'retail_source_name', retail_source_url = p_draft->>'retail_source_url',
    msrp_cents = coalesce(msrp_cents, v_msrp),
    floor_cents = coalesce(floor_cents, v_floor)
    where store_id = v_store and sku = v_sku;
  update public.video_scan_jobs set status = 'saved', sku = v_sku, updated_at = now() where id = p_id;
  return jsonb_build_object('sku', v_sku);
end $_$;


ALTER FUNCTION "public"."video_scan_receive"("p_id" "uuid", "p_draft" "jsonb", "p_ask_cents" integer) OWNER TO "postgres";


