CREATE OR REPLACE FUNCTION "public"."web_release_reservation"("p_store" "uuid", "p_reservation_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.assert_service();
  perform set_config('floor.store_id', p_store::text, true);
  update public.reservations
     set released_at = now()
   where id = p_reservation_id
     and store_id = p_store
     and released_at is null
     and finalized_at is null;
  update public.units u
     set state = 'available', updated_at = now()
   where u.store_id = p_store
     and u.state = 'reserved'
     and u.sku = (select sku from public.reservations where id = p_reservation_id)
     and not exists (
       select 1 from public.reservations r
        where r.store_id = p_store and r.sku = u.sku
          and r.released_at is null and r.finalized_at is null
          and r.expires_at > now()
     );
end;
$$;


ALTER FUNCTION "public"."web_release_reservation"("p_store" "uuid", "p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_reserve_unit"("p_store" "uuid", "p_sku" "text", "p_customer_id" "uuid" DEFAULT NULL::"uuid", "p_redeem_points" integer DEFAULT 0) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_res public.reservations;
  v_ask int;
  v_quote jsonb;
begin
  perform public.assert_service();
  if p_store is null then
    raise exception 'store_required' using errcode = '22023';
  end if;
  perform set_config('floor.store_id', p_store::text, true);

  select ask_cents into v_ask
    from public.units
   where store_id = p_store and sku = p_sku;
  if v_ask is null then
    raise exception 'unit_not_priced' using errcode = 'P0001';
  end if;

  v_res := public.reserve_unit(p_sku, 'website');
  v_quote := public.quote_ticket_totals(
    jsonb_build_array(jsonb_build_object('sku', p_sku, 'price_cents', v_ask, 'qty', 1)),
    0, p_customer_id, coalesce(p_redeem_points, 0), 'website', 'card', null
  );

  return jsonb_build_object(
    'reservation_id', v_res.id,
    'expires_at', v_res.expires_at,
    'price_cents', v_ask,
    'quote', v_quote
  );
end;
$$;


ALTER FUNCTION "public"."web_reserve_unit"("p_store" "uuid", "p_sku" "text", "p_customer_id" "uuid", "p_redeem_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_tax_decision"("p_store" "uuid", "p_fulfillment" "text", "p_region" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_store_bps int := coalesce(nullif(public.store_setting(p_store,'taxRateBps','0'::jsonb) #>> '{}','')::int, 0);
  v_origin text := upper(coalesce(nullif(btrim(public.store_setting(p_store,'tax_origin_state','"CA"'::jsonb) #>> '{}'),''),'CA'));
  v_out int := coalesce(nullif(public.store_setting(p_store,'tax_out_of_state_bps','0'::jsonb) #>> '{}',''),'0')::int;
  v_in_ship text := nullif(public.store_setting(p_store,'tax_in_state_ship_bps','null'::jsonb) #>> '{}','');
  v_ship_taxed boolean := coalesce((public.store_setting(p_store,'tax_shipping','false'::jsonb) #>> '{}')::boolean, false);
  v_region text := upper(btrim(coalesce(p_region,'')));
  v_bps int; v_rule text;
begin
  if p_fulfillment = 'pickup' then
    v_bps := v_store_bps; v_rule := 'pickup_store_rate';
  elsif v_region = v_origin then
    v_bps := coalesce(v_in_ship::int, v_store_bps); v_rule := 'ship_in_state';
  else
    v_bps := v_out; v_rule := 'ship_out_of_state';
  end if;
  return jsonb_build_object('bps', v_bps, 'rule', v_rule, 'tax_shipping', v_ship_taxed);
end $$;


ALTER FUNCTION "public"."web_tax_decision"("p_store" "uuid", "p_fulfillment" "text", "p_region" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."web_unit_fulfillment"("p_store" "uuid", "p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare u public.units;
begin
  perform public.assert_service();
  select * into u from public.units where store_id = p_store and sku = p_sku;
  if not found or not exists(select 1 from public.storefront_items s where s.store_id = p_store and s.sku = p_sku) then
    return jsonb_build_object('listed', false);
  end if;
  return public.unit_ship_check(u) || jsonb_build_object('listed', true, 'sku', u.sku,
    'title', coalesce(nullif(btrim(u.title),''), concat_ws(' ', u.brand, u.model)),
    'ask_cents', u.ask_cents, 'shipping_cents_override', u.shipping_cents,
    'package', jsonb_build_object('length_in', u.package_length_in, 'width_in', u.package_width_in,
      'height_in', u.package_height_in, 'weight_lb', u.package_weight_lb),
    'ship_from', public.store_setting(p_store, 'ship_from', '{}'::jsonb));
end $$;


