    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ declare v_phone text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g'); v_cust public.customers; begin perform public.assert_service(); if p_store is null or v_phone = '' then raise exception 'store_and_phone_required' using errcode = '22023'; end if; perform set_config('floor.store_id', p_store::text, true); insert into public.customers (store_id, phone, name, email, marketing_opt_in, signup_code) values (p_store, v_phone, nullif(btrim(coalesce(p_name, '')), ''), nullif(btrim(coalesce(p_email, '')), ''), coalesce(p_marketing_opt_in, false), public.new_signup_code()) on conflict (store_id, phone) do update set name = coalesce(excluded.name, public.customers.name), email = coalesce(excluded.email, public.customers.email), marketing_opt_in = public.customers.marketing_opt_in or excluded.marketing_opt_in returning * into v_cust; return public.customer_card(p_store, v_cust) || jsonb_build_object('first_purchase_discount_used', v_cust.first_purchase_discount_used, 'points_balance', public.customer_points_balance_internal(p_store, v_cust.id)); end; $$;


