CREATE OR REPLACE VIEW "public"."public_categories" WITH ("security_invoker"='false') AS
 SELECT "s"."store_id",
    "btrim"("x"."cat") AS "name",
    ("x"."ord")::integer AS "sort_index"
   FROM ("public"."store_settings" "s"
     CROSS JOIN LATERAL "jsonb_array_elements_text"("s"."value") WITH ORDINALITY "x"("cat", "ord"))
  WHERE (("s"."key" = 'categories'::"text") AND ("jsonb_typeof"("s"."value") = 'array'::"text") AND ("btrim"("x"."cat") <> ''::"text"));


ALTER VIEW "public"."public_categories" OWNER TO "postgres";


COMMENT ON VIEW "public"."public_categories" IS 'Public category names for the website, in store order. Same strings as units.category.';



CREATE OR REPLACE VIEW "public"."public_items" WITH ("security_invoker"='false') AS
 SELECT "sku",
    "brand",
    "model",
    "title",
    "category",
    "condition",
    "test_status",
    NULLIF(TRIM(BOTH FROM "concat_ws"('

'::"text", NULLIF("btrim"("listing_body"), ''::"text"), NULLIF("concat_ws"('
'::"text",
        CASE
            WHEN ("listing_specs" IS NOT NULL) THEN 'Specs'::"text"
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'configuration'::"text") IS NOT NULL) THEN ('Layout: '::"text" || ("listing_specs" ->> 'configuration'::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN ((("listing_specs" ->> 'width_in'::"text") IS NOT NULL) AND (("listing_specs" ->> 'height_in'::"text") IS NOT NULL) AND (("listing_specs" ->> 'depth_in'::"text") IS NOT NULL)) THEN (((((('Size: '::"text" || ("listing_specs" ->> 'width_in'::"text")) || ' W × '::"text") || ("listing_specs" ->> 'height_in'::"text")) || ' H × '::"text") || ("listing_specs" ->> 'depth_in'::"text")) || ' D'::"text")
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'capacity_cu_ft'::"text") IS NOT NULL) THEN ((('Capacity: '::"text" || ("listing_specs" ->> 'capacity_cu_ft'::"text")) || ' cu ft'::"text") || COALESCE(((' ('::"text" || NULLIF("concat_ws"(' / '::"text",
            CASE
                WHEN (("listing_specs" ->> 'fridge_cu_ft'::"text") IS NOT NULL) THEN (("listing_specs" ->> 'fridge_cu_ft'::"text") || ' fridge'::"text")
                ELSE NULL::"text"
            END,
            CASE
                WHEN (("listing_specs" ->> 'freezer_cu_ft'::"text") IS NOT NULL) THEN (("listing_specs" ->> 'freezer_cu_ft'::"text") || ' freezer'::"text")
                ELSE NULL::"text"
            END), ''::"text")) || ')'::"text"), ''::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'finish'::"text") IS NOT NULL) THEN ('Finish: '::"text" || ("listing_specs" ->> 'finish'::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'ice_maker'::"text") IS NOT NULL) THEN ('Ice: '::"text" || ("listing_specs" ->> 'ice_maker'::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'water_dispenser'::"text") IS NOT NULL) THEN ('Water: '::"text" || ("listing_specs" ->> 'water_dispenser'::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'energy'::"text") IS NOT NULL) THEN ('Energy: '::"text" || ("listing_specs" ->> 'energy'::"text"))
            ELSE NULL::"text"
        END,
        CASE
            WHEN (("listing_specs" ->> 'catalog_msrp'::"text") IS NOT NULL) THEN ('Typical new: '::"text" || ("listing_specs" ->> 'catalog_msrp'::"text"))
            ELSE NULL::"text"
        END), 'Specs'::"text"), ( SELECT "string_agg"(('• '::"text" || "f"."value"), '
'::"text") AS "string_agg"
           FROM "jsonb_array_elements_text"(COALESCE(("u"."listing_specs" -> 'features'::"text"), '[]'::"jsonb")) "f"("value")),
        CASE
            WHEN (NULLIF("btrim"("defect_notes"), ''::"text") IS NOT NULL) THEN ('On this unit: '::"text" || "btrim"("defect_notes"))
            ELSE NULL::"text"
        END)), ''::"text") AS "defect_notes",
    "ask_cents",
    "msrp_cents",
    COALESCE(("public"."store_setting"("store_id", 'currency'::"text", '"USD"'::"jsonb") #>> '{}'::"text"[]), 'USD'::"text") AS "currency",
    "received_at",
    "updated_at",
    ( SELECT "p"."path"
           FROM "public"."photos" "p"
          WHERE ((NOT ("p"."store_id" IS DISTINCT FROM "u"."store_id")) AND ("p"."sku" = "u"."sku"))
          ORDER BY "p"."is_primary" DESC, "p"."created_at"
         LIMIT 1) AS "primary_photo_path",
    COALESCE(( SELECT "json_agg"("p"."path" ORDER BY "p"."is_primary" DESC, "p"."created_at") AS "json_agg"
           FROM "public"."photos" "p"
          WHERE ((NOT ("p"."store_id" IS DISTINCT FROM "u"."store_id")) AND ("p"."sku" = "u"."sku"))), '[]'::json) AS "photo_paths",
    "store_id",
    "listing_body",
    "listing_specs",
    COALESCE(( SELECT "json_agg"("json_build_object"('id', "mp"."id", 'path', "mp"."path", 'source_url', "mp"."source_url", 'sort_order', "mp"."sort_order") ORDER BY "mp"."sort_order", "mp"."id") AS "json_agg"
           FROM "public"."manufacturer_photos" "mp"
          WHERE (("lower"("mp"."brand") = "lower"("u"."brand")) AND ("lower"("mp"."model") = "lower"(COALESCE(("u"."listing_specs" ->> 'matched_model'::"text"), "u"."model"))))), '[]'::json) AS "manufacturer_photos",
    "defect_notes" AS "unit_defect_notes",
    "state" AS "listing_state",
    ( SELECT "max"("s"."sold_at") AS "max"
           FROM "public"."sales" "s"
          WHERE (("s"."store_id" = "u"."store_id") AND ("s"."sku" = "u"."sku") AND ("s"."voided_at" IS NULL))) AS "sold_at",
    "shippable",
    "public"."unit_weight_lb"("listing_specs") AS "weight_lb",
    "public"."unit_web_buyable"("store_id", "shippable", "listing_specs") AS "web_buyable",
    "public"."unit_shipping_cents"("store_id", "shipping_cents", "listing_specs", "ask_cents") AS "shipping_cents"
   FROM "public"."units" "u"
  WHERE ("show_on_website" AND ("store_id" IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM "public"."photos" "p"
          WHERE ((NOT ("p"."store_id" IS DISTINCT FROM "u"."store_id")) AND ("p"."sku" = "u"."sku")))) AND ((("state" = ANY (ARRAY['available'::"text", 'reserved'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."sales" "s"
          WHERE (("s"."store_id" = "u"."store_id") AND ("s"."sku" = "u"."sku") AND ("s"."voided_at" IS NULL))))) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."reservations" "r"
          WHERE (("r"."store_id" = "u"."store_id") AND ("r"."sku" = "u"."sku") AND ("r"."released_at" IS NULL) AND ("r"."finalized_at" IS NULL) AND ("r"."expires_at" > "now"())))))) OR (("state" = 'sold'::"text") AND (EXISTS ( SELECT 1
           FROM "public"."sales" "s"
          WHERE (("s"."store_id" = "u"."store_id") AND ("s"."sku" = "u"."sku") AND ("s"."voided_at" IS NULL) AND ("s"."sold_at" > ("now"() - '48:00:00'::interval))))))));


