    "sku",
    "state",
    "condition",
    "ask_cents",
    "received_at",
    (GREATEST((0)::numeric, "floor"((EXTRACT(epoch FROM ("now"() - "received_at")) / (86400)::numeric))))::integer AS "age_days"
   FROM "public"."units"
  WHERE ("state" = ANY (ARRAY['available'::"text", 'reserved'::"text", 'repair'::"text"]));


