CREATE OR REPLACE VIEW "public"."report_sales_by_day" WITH ("security_invoker"='true') AS
 SELECT "store_id",
    (("sold_at" AT TIME ZONE 'America/Los_Angeles'::"text"))::"date" AS "sale_day",
    ("count"(*))::integer AS "line_count",
    "sum"("price_cents") AS "merchandise_cents",
    "sum"(COALESCE("tax_cents", 0)) AS "tax_cents",
    "sum"(("price_cents" + COALESCE("tax_cents", 0))) AS "total_cents"
   FROM "public"."sales"
  WHERE ("voided_at" IS NULL)
  GROUP BY "store_id", ((("sold_at" AT TIME ZONE 'America/Los_Angeles'::"text"))::"date");


