CREATE OR REPLACE VIEW "public"."units_pos" WITH ("security_invoker"='false') AS
 SELECT "u"."id",
    "u"."store_id",
    "u"."sku",
    "u"."brand",
    "u"."model",
    "u"."title",
    "u"."category",
    "u"."condition",
    "u"."test_status",
    "u"."location",
    "u"."mfr_serial",
    "u"."defect_notes",
    "u"."upc",
    "u"."lot",
        CASE
            WHEN ("a"."is_admin" OR ("u"."state" = ANY (ARRAY['available'::"text", 'reserved'::"text"]))) THEN "u"."msrp_cents"
            ELSE NULL::integer
        END AS "msrp_cents",
        CASE
            WHEN ("a"."is_admin" OR ("u"."state" = ANY (ARRAY['available'::"text", 'reserved'::"text"]))) THEN "u"."ask_cents"
            ELSE NULL::integer
        END AS "ask_cents",
    "u"."state",
    "u"."show_on_website",
    "u"."qty_on_hand",
    "u"."received_at",
    "u"."updated_at",
    "u"."shippable",
        CASE
            WHEN ("a"."is_admin" OR ("u"."state" = ANY (ARRAY['available'::"text", 'reserved'::"text"]))) THEN "u"."shipping_cents"
            ELSE NULL::integer
        END AS "shipping_cents",
    ( SELECT "r"."channel"
           FROM "public"."reservations" "r"
          WHERE (("r"."store_id" = "u"."store_id") AND ("r"."sku" = "u"."sku") AND ("r"."released_at" IS NULL) AND ("r"."finalized_at" IS NULL) AND ("r"."expires_at" > "now"()))
          ORDER BY "r"."expires_at" DESC
         LIMIT 1) AS "hold_channel"
   FROM ("public"."units" "u"
     CROSS JOIN ( SELECT "public"."portal_is_admin"() AS "is_admin") "a")
  WHERE ("u"."store_id" = "public"."current_store_id"());


ALTER VIEW "public"."units_pos" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."sale_receipts" WITH ("security_invoker"='false') AS
 SELECT "s"."id",
    "s"."store_id",
    "s"."sku",
    "s"."receipt_no",
    "s"."ticket_id",
    "s"."sold_at",
    "s"."price_cents",
    COALESCE("s"."tax_cents", 0) AS "tax_cents",
    COALESCE("s"."card_fee_cents", 0) AS "card_fee_cents",
    (("s"."price_cents" + COALESCE("s"."tax_cents", 0)) + COALESCE("s"."card_fee_cents", 0)) AS "total_cents",
    "s"."list_price_cents",
    "s"."override_reason",
    "s"."override_by",
    "s"."payment_method",
    "s"."payment_id",
    "s"."card_brand",
    "s"."card_last4",
    "s"."qty",
    "s"."channel",
    "s"."voided_at",
    "s"."void_reason",
    "s"."actor_id",
    "st"."display_name" AS "actor_name",
    COALESCE(NULLIF("btrim"("concat_ws"(' '::"text", "u"."brand", "u"."model")), ''::"text"), "u"."title", 'Item'::"text") AS "title",
    "u"."condition"
   FROM (("public"."sales" "s"
     LEFT JOIN "public"."staff" "st" ON ((("st"."user_id" = "s"."actor_id") AND ("st"."store_id" = "s"."store_id"))))
     LEFT JOIN "public"."units_pos" "u" ON ((("u"."sku" = "s"."sku") AND ("u"."store_id" = "s"."store_id"))))
  WHERE (("s"."store_id" IN ( SELECT "staff"."store_id"
           FROM "public"."staff"
          WHERE ("staff"."user_id" = "auth"."uid"()))) AND "public"."portal_is_admin"());


