CREATE OR REPLACE VIEW "public"."storefront_items" WITH ("security_invoker"='false', "security_barrier"='true') AS
 SELECT "u"."store_id",
    "u"."sku",
    "u"."brand",
    "u"."model",
    "u"."title",
    "u"."category",
    "u"."condition",
    "u"."test_status",
    "u"."defect_notes",
    "u"."defect_notes" AS "unit_defect_notes",
    "u"."ask_cents",
    "u"."msrp_cents",
    COALESCE(("public"."store_setting"("u"."store_id", 'currency'::"text", '"USD"'::"jsonb") #>> '{}'::"text"[]), 'USD'::"text") AS "currency",
    "u"."received_at",
    "u"."updated_at",
    "ph"."primary_photo_path",
    "ph"."photo_paths",
    COALESCE(("to_jsonb"("u".*) ->> 'listing_body'::"text"), ("to_jsonb"("i".*) ->> 'listing_body'::"text")) AS "listing_body",
        CASE
            WHEN ("spec"."raw" IS NULL) THEN NULL::"jsonb"
            ELSE "jsonb_strip_nulls"("jsonb_build_object"('matched_model', ("spec"."raw" -> 'matched_model'::"text"), 'height_in', ("spec"."raw" -> 'height_in'::"text"), 'width_in', ("spec"."raw" -> 'width_in'::"text"), 'depth_in', ("spec"."raw" -> 'depth_in'::"text"), 'depth_without_handles_in', ("spec"."raw" -> 'depth_without_handles_in'::"text"), 'depth_without_doors_in', ("spec"."raw" -> 'depth_without_doors_in'::"text"), 'capacity_cu_ft', ("spec"."raw" -> 'capacity_cu_ft'::"text"), 'fridge_cu_ft', ("spec"."raw" -> 'fridge_cu_ft'::"text"), 'freezer_cu_ft', ("spec"."raw" -> 'freezer_cu_ft'::"text"), 'configuration', ("spec"."raw" -> 'configuration'::"text"), 'finish', ("spec"."raw" -> 'finish'::"text"), 'ice_maker', ("spec"."raw" -> 'ice_maker'::"text"), 'water_dispenser', ("spec"."raw" -> 'water_dispenser'::"text"), 'energy', ("spec"."raw" -> 'energy'::"text"), 'features', ("spec"."raw" -> 'features'::"text"), 'catalog_msrp', ("spec"."raw" -> 'catalog_msrp'::"text"), 'weight_lb', ("spec"."raw" -> 'weight_lb'::"text")))
        END AS "listing_specs",
    (COALESCE(( SELECT "jsonb_agg"("jsonb_build_object"('id', "mp"."id", 'path', "mp"."path", 'source_url', "mp"."source_url", 'sort_order', "mp"."sort_order") ORDER BY "mp"."sort_order", "mp"."id") AS "jsonb_agg"
           FROM "public"."manufacturer_photos" "mp"
          WHERE (("lower"("mp"."brand") = "lower"("u"."brand")) AND ("lower"("mp"."model") = "lower"(COALESCE(("u"."listing_specs" ->> 'matched_model'::"text"), "u"."model"))))), '[]'::"jsonb") || COALESCE(( SELECT "jsonb_agg"("jsonb_build_object"('id', (1000000 + "path"."ordinality"), 'path', "path"."value", 'source_url', "asset"."source_url", 'sort_order', ("path"."ordinality" - 1)) ORDER BY "path"."ordinality") AS "jsonb_agg"
           FROM "jsonb_array_elements_text"(COALESCE("asset"."public_paths", '[]'::"jsonb")) WITH ORDINALITY "path"("value", "ordinality")), '[]'::"jsonb")) AS "manufacturer_photos",
    "u"."state" AS "listing_state",
    NULL::timestamp with time zone AS "sold_at",
    COALESCE((("ship"."v" ->> 'ship'::"text"))::boolean, false) AS "shippable",
    ("u"."package_weight_lb")::numeric AS "weight_lb",
    true AS "web_buyable",
    NULL::integer AS "shipping_cents",
    COALESCE("asset"."description", "m"."description") AS "model_description",
    COALESCE("asset"."specs", "m"."specs") AS "model_specs",
    COALESCE("asset"."source_url", "m"."source_url") AS "model_source_url",
    true AS "pickup_available",
    ("ship"."v" ->> 'reason'::"text") AS "ship_note"
   FROM ((((((("public"."units" "u"
     CROSS JOIN LATERAL ( SELECT ("count"(*))::integer AS "photo_count",
            ("array_agg"("p"."path" ORDER BY "p"."is_primary" DESC, "p"."sort_order", "p"."created_at", "p"."id"))[1] AS "primary_photo_path",
            COALESCE("jsonb_agg"("p"."path" ORDER BY "p"."is_primary" DESC, "p"."sort_order", "p"."created_at", "p"."id"), '[]'::"jsonb") AS "photo_paths"
           FROM ("public"."photos" "p"
             JOIN "storage"."objects" "o" ON ((("o"."bucket_id" = 'unit-photos'::"text") AND ("o"."name" = "p"."path"))))
          WHERE (("p"."store_id" = "u"."store_id") AND (("p"."sku" = "u"."sku") OR ((NOT (EXISTS ( SELECT 1
                   FROM "public"."photos" "own"
                  WHERE (("own"."store_id" = "u"."store_id") AND ("own"."sku" = "u"."sku"))))) AND ("p"."sku" = ( SELECT "b"."main_sku"
                   FROM "public"."floor_bundles" "b"
                  WHERE (("b"."store_id" = "u"."store_id") AND ("b"."sku" = "u"."sku") AND "b"."active"))))))) "ph")
     CROSS JOIN LATERAL ( SELECT "public"."unit_ship_check"("u".*) AS "v") "ship")
     LEFT JOIN "public"."public_items" "i" ON ((("i"."store_id" = "u"."store_id") AND ("i"."sku" = "u"."sku"))))
     LEFT JOIN "public"."model_enrichment" "m" ON ((("m"."brand_key" = "lower"("btrim"("u"."brand"))) AND ("m"."model_key" = "lower"("btrim"("u"."model"))))))
     LEFT JOIN "public"."photo_enrichment_suggestions" "approved" ON ((("approved"."store_id" = "u"."store_id") AND ("approved"."sku" = "u"."sku") AND ("approved"."status" = 'approved'::"text"))))
     LEFT JOIN "public"."photo_enrichment_assets" "asset" ON ((("asset"."id" = "approved"."asset_id") AND ("asset"."status" = 'published'::"text"))))
     CROSS JOIN LATERAL ( SELECT COALESCE(("to_jsonb"("u".*) -> 'listing_specs'::"text"), ("to_jsonb"("i".*) -> 'listing_specs'::"text")) AS "raw") "spec")
  WHERE (("u"."store_id" IS NOT NULL) AND ("u"."state" = 'available'::"text") AND ("u"."ask_cents" > 0) AND ("ph"."photo_count" > 0) AND ("u"."show_on_website" OR (NOT (EXISTS ( SELECT 1
           FROM "public"."events" "e"
          WHERE (("e"."store_id" = "u"."store_id") AND ("e"."sku" = "u"."sku") AND ("e"."kind" = 'edit'::"text") AND ("e"."field" = 'show_on_website'::"text") AND ("e"."new_value" = ANY (ARRAY['false'::"text", '0'::"text"]))))))) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."listings" "l"
          WHERE (("l"."store_id" = "u"."store_id") AND ("l"."sku" = "u"."sku") AND ("l"."channel" = 'website'::"text") AND ("l"."status" = ANY (ARRAY['delisted'::"text", 'pending_delist'::"text"])))))) AND ((EXISTS ( SELECT 1
           FROM "public"."floor_bundles" "b"
          WHERE (("b"."store_id" = "u"."store_id") AND ("b"."sku" = "u"."sku") AND "b"."active" AND ("u"."qty_on_hand" > 0)))) OR (NOT (EXISTS ( SELECT 1
           FROM "public"."sales" "s"
          WHERE (("s"."store_id" = "u"."store_id") AND ("s"."sku" = "u"."sku") AND ("s"."voided_at" IS NULL)))))) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."reservations" "r"
          WHERE (("r"."store_id" = "u"."store_id") AND ("r"."sku" = "u"."sku") AND ("r"."released_at" IS NULL) AND ("r"."finalized_at" IS NULL) AND ("r"."expires_at" > "now"()))))) AND (NOT (EXISTS ( SELECT 1
           FROM ("public"."floor_bundle_components" "c"
             JOIN "public"."floor_bundles" "b" ON ((("b"."store_id" = "c"."store_id") AND ("b"."sku" = "c"."bundle_sku") AND "b"."active")))
          WHERE (("c"."store_id" = "u"."store_id") AND ("c"."component_sku" = "u"."sku"))))));


ALTER VIEW "public"."storefront_items" OWNER TO "postgres";


COMMENT ON VIEW "public"."storefront_items" IS 'Live customer-facing Floor catalog. No cost, staff, or private unit fields.';



